insert into public.topics (id, subject_id, slug, name, description, sort_order) values
  ('top-matematika-sd-bilangan', 'sub-matematika-sd', 'bilangan', 'Bilangan', 'Memahami, mengaplikasikan, dan bernalar yang lebih tinggi untuk menyelesaikan permasalahan terkait bilangan rasional.', 0),
  ('top-matematika-sd-geometri-pengukuran', 'sub-matematika-sd', 'geometri-dan-pengukuran', 'Geometri dan Pengukuran', 'Memahami, mengaplikasikan, dan bernalar yang lebih tinggi untuk menyelesaikan permasalahan terkait objek geometri dan pengukuran.', 1),
  ('top-matematika-sd-data', 'sub-matematika-sd', 'data', 'Data', 'Memahami, mengaplikasikan, dan bernalar yang lebih tinggi untuk menyelesaikan permasalahan terkait penyajian dan penggunaan data.', 2)
insert into public.subtopics (id, topic_id, slug, name, description, sort_order) values
  ('st-matematika-sd-bilangan-rasional', 'top-matematika-sd-bilangan', 'bilangan-rasional', 'Bilangan Rasional', 'Pecahan senilai, perbandingan dan pengurutan pecahan, relasi pecahan-desimal-persen, operasi bilangan cacah, operasi bilangan pecahan, serta kelipatan, faktor, KPK, dan FPB.', 0),
  ('st-matematika-sd-objek-geometri', 'top-matematika-sd-geometri-pengukuran', 'objek-geometri', 'Objek Geometri', 'Bentuk bangun datar (segitiga, segiempat, segi banyak) serta konstruksi bangun ruang dan visualisasi spasial pada kubus, balok, dan gabungannya.', 0),
  ('st-matematika-sd-pengukuran', 'top-matematika-sd-geometri-pengukuran', 'pengukuran', 'Pengukuran', 'Panjang, volume, berat, dan waktu dengan satuan baku beserta hubungan antar-satuannya, laju perubahan, keliling dan luas bangun datar, volume bangun ruang, besar sudut, dan penaksiran ukuran.', 1),
  ('st-matematika-sd-penyajian-data', 'top-matematika-sd-data', 'penyajian-dan-penggunaan-data', 'Penyajian dan Penggunaan Data', 'Penyajian data dalam bentuk gambar, piktogram, diagram batang, dan tabel frekuensi, serta pengambilan informasi dan penggunaan data.', 0)
insert into public.concepts (id, subtopic_id, name, description, sort_order) values
  ('con-matematika-sd-pecahan-senilai', 'st-matematika-sd-bilangan-rasional', 'Pecahan senilai menggunakan gambar dan simbol matematika', 'Menentukan dan membuktikan pecahan senilai lewat gambar bagian yang diwarnai serta lewat perkalian dan pembagian pembilang dan penyebut dengan bilangan yang sama.', 1),
  ('con-matematika-sd-banding-urut-pecahan', 'st-matematika-sd-bilangan-rasional', 'Perbandingan dan pengurutan bilangan pecahan', 'Menentukan pecahan yang lebih besar atau lebih kecil dan menyusun beberapa pecahan menurut nilainya, termasuk pecahan yang penyebutnya berbeda.', 2),
  ('con-matematika-sd-relasi-bentuk-pecahan', 'st-matematika-sd-bilangan-rasional', 'Relasi berbagai bentuk pecahan (pecahan sederhana, desimal, persen)', 'Menyatakan satu besaran dalam bentuk pecahan sederhana, desimal, dan persen serta mengenali kesetaraan dan urutan antarbentuk.', 3),
  ('con-matematika-sd-operasi-bilangan-cacah', 'st-matematika-sd-bilangan-rasional', 'Operasi penjumlahan, pengurangan, perkalian, dan pembagian bilangan cacah', 'Menyelesaikan masalah yang memuat satu atau beberapa operasi hitung bilangan cacah, memilih operasi yang tepat, dan menafsirkan hasilnya termasuk sisa pembagian.', 4),
  ('con-matematika-sd-operasi-pecahan', 'st-matematika-sd-bilangan-rasional', 'Operasi penjumlahan dan pengurangan bilangan pecahan, serta operasi perkalian dan pembagian bilangan pecahan dengan bilangan asli', 'Menghitung penjumlahan dan pengurangan pecahan, termasuk yang penyebutnya berbeda, serta perkalian dan pembagian pecahan oleh bilangan asli pada konteks sehari-hari.', 5),
  ('con-matematika-sd-kpk-fpb', 'st-matematika-sd-bilangan-rasional', 'Kelipatan, faktor, KPK, dan FPB bilangan asli', 'Menentukan kelipatan, faktor, kelipatan persekutuan terkecil, dan faktor persekutuan terbesar, serta memakainya untuk menyelesaikan masalah jadwal dan pengelompokan.', 6),
  ('con-matematika-sd-bangun-datar', 'st-matematika-sd-objek-geometri', 'Bentuk bangun datar', 'Menggolongkan dan mengenali segitiga, segiempat, dan segi banyak berdasarkan panjang sisi, besar sudut, diagonal, dan sumbu simetri. Bangun datar mencakup segitiga, segiempat, dan segi banyak.', 7),
  ('con-matematika-sd-bangun-ruang-spasial', 'st-matematika-sd-objek-geometri', 'Konstruksi bangun ruang dan visualisasi spasial (bagian depan, atas, dan samping)', 'Mengenali unsur dan jaring-jaring kubus dan balok, menghitung kubus satuan penyusun bangun gabungan, serta menentukan pandangan depan, atas, dan samping. Bangun ruang mencakup kubus, balok, dan gabungannya.', 8),
  ('con-matematika-sd-panjang-satuan-baku', 'st-matematika-sd-pengukuran', 'Panjang benda menggunakan satuan baku', 'Mengukur dan menuliskan panjang benda dengan satuan baku mm, cm, m, dan km, termasuk membaca alat ukur dan memilih satuan yang paling sesuai.', 9),
  ('con-matematika-sd-konversi-panjang', 'st-matematika-sd-pengukuran', 'Hubungan antar-satuan baku panjang (mm, dm, cm, m, dam, hm, km)', 'Menentukan kesetaraan antarsatuan panjang pada tangga satuan dan memakainya untuk menjumlahkan, membandingkan, serta mengurutkan panjang.', 10),
  ('con-matematika-sd-volume-satuan-baku', 'st-matematika-sd-pengukuran', 'Volume benda menggunakan satuan baku', 'Mengukur dan menuliskan volume atau isi benda dengan satuan baku ml, cl, dl, l, dal, hl, dan kl, termasuk membaca alat ukur dan mengukur benda padat lewat kenaikan air.', 11),
  ('con-matematika-sd-konversi-volume', 'st-matematika-sd-pengukuran', 'Hubungan antar-satuan baku volume (ml, dl, cl, l, dal, hl, kl)', 'Menentukan kesetaraan antarsatuan volume pada tangga satuan dan memakainya untuk menjumlahkan, membandingkan, serta mengurutkan volume.', 12),
  ('con-matematika-sd-berat-satuan-baku', 'st-matematika-sd-pengukuran', 'Berat benda menggunakan satuan baku', 'Mengukur dan menuliskan berat benda dengan satuan baku mg, g, hg, dan kg, termasuk membaca timbangan serta menghitung berat bersih dari berat kotor dan tara.', 13),
  ('con-matematika-sd-konversi-berat', 'st-matematika-sd-pengukuran', 'Hubungan antar-satuan baku berat (mg, dg, cg, g, dag, hg, kg)', 'Menentukan kesetaraan antarsatuan berat pada tangga satuan dan memakainya untuk menjumlahkan, membandingkan, serta mengurutkan berat.', 14),
  ('con-matematika-sd-waktu', 'st-matematika-sd-pengukuran', 'Waktu', 'Membaca dan menuliskan waktu, menghitung lama kegiatan, menentukan waktu mulai atau selesai, serta memakai penanggalan pada masalah sehari-hari.', 15),
  ('con-matematika-sd-konversi-waktu', 'st-matematika-sd-pengukuran', 'Hubungan antar-satuan waktu (detik, menit, jam, hari, pekan, bulan, tahun)', 'Menentukan kesetaraan antarsatuan waktu dan memakainya untuk menjumlahkan, membandingkan, serta mengurutkan lama kegiatan.', 16),
  ('con-matematika-sd-kecepatan', 'st-matematika-sd-pengukuran', 'Laju perubahan (kecepatan)', 'Menentukan kecepatan, jarak, dan waktu tempuh pada masalah sehari-hari, serta menalar hubungan ketiganya termasuk kecepatan rata-rata perjalanan bertahap.', 17),
  ('con-matematika-sd-keliling-luas', 'st-matematika-sd-pengukuran', 'Keliling dan luas bangun datar (segitiga, segiempat, dan segi banyak)', 'Menentukan keliling dan luas segitiga, segiempat, dan segi banyak, termasuk bangun gabungan. Lingkaran tidak termasuk cakupan submateri ini.', 18),
  ('con-matematika-sd-volume-bangun-ruang', 'st-matematika-sd-pengukuran', 'Volume bangun ruang (kubus, balok, dan gabungannya)', 'Menentukan volume kubus, balok, dan gabungannya serta memakainya pada masalah pengisian wadah. Tabung, kerucut, dan bola tidak termasuk cakupan submateri ini.', 19),
  ('con-matematika-sd-besar-sudut', 'st-matematika-sd-pengukuran', 'Besar sudut', 'Mengukur besar sudut dengan busur derajat, menggolongkan jenis sudut, serta memakai hubungan sudut pelurus, penyiku, dan jumlah sudut dalam segitiga.', 20),
  ('con-matematika-sd-penaksiran', 'st-matematika-sd-pengukuran', 'Penaksiran ukuran', 'Menaksir hasil operasi hitung dan ukuran benda dengan pembulatan serta benda acuan, dan menilai kapan hasil taksiran memadai atau justru memerlukan hitungan tepat.', 21),
  ('con-matematika-sd-penyajian-data', 'st-matematika-sd-penyajian-data', 'Penyajian data (gambar, piktogram, diagram batang, dan tabel frekuensi)', 'Membaca, membandingkan, dan mengalihbentukkan penyajian data berupa gambar, piktogram, diagram batang, dan tabel frekuensi.', 22),
  ('con-matematika-sd-penggunaan-data', 'st-matematika-sd-penyajian-data', 'Pengambilan informasi dan penggunaan data', 'Membaca informasi dari data yang tersaji, memakainya untuk menghitung dan memutuskan, serta menilai sejauh mana suatu kesimpulan didukung datanya.', 23)
insert into public.misconceptions (id, label, description, insight) values
  ('mis-msd-senilai-001', 'Menambah bilangan yang sama pada pembilang dan penyebut', 'Siswa menganggap menambah bilangan yang sama pada pembilang dan penyebut menghasilkan pecahan senilai, misalnya 2/3 dianggap sama dengan 3/4.', 'Pecahan senilai diperoleh dengan mengalikan atau membagi pembilang dan penyebut dengan bilangan yang sama, bukan dengan menambah atau mengurangi.'),
  ('mis-msd-senilai-002', 'Mengalikan hanya pembilang atau hanya penyebut', 'Siswa mengalikan salah satu bagian pecahan saja, misalnya 3/5 dijadikan 6/5 atau 3/10, lalu menganggapnya senilai.', 'Kedua bagian pecahan harus dikalikan bilangan yang sama; mengubah satu bagian saja mengubah nilai pecahannya.'),
  ('mis-msd-senilai-003', 'Berhenti sebelum bentuk paling sederhana', 'Siswa membagi pembilang dan penyebut dengan faktor yang belum terbesar, sehingga hasilnya masih dapat disederhanakan lagi.', 'Periksa apakah pembilang dan penyebut masih punya faktor bersama sebelum menyatakan pecahan sudah paling sederhana.'),
  ('mis-msd-senilai-004', 'Potongan lebih banyak dianggap bagian lebih besar', 'Pada gambar, siswa menyimpulkan bagian berwarna lebih luas hanya karena benda itu dibagi menjadi lebih banyak potongan.', 'Semakin banyak potongan pada benda yang sama, setiap potongannya justru semakin kecil; yang dibandingkan adalah luas seluruh bagian berwarna.'),
  ('mis-msd-senilai-005', 'Menilai senilai dari selisih pembilang dan penyebut', 'Siswa menganggap dua pecahan senilai bila selisih pembilang dan penyebutnya sama, misalnya 3/4 dianggap sama dengan 4/5.', 'Yang menentukan nilai pecahan adalah perbandingan pembilang terhadap penyebut, bukan selisih keduanya.'),
  ('mis-msd-banding-001', 'Penyebut lebih besar dianggap pecahan lebih besar', 'Siswa membandingkan pecahan berpembilang sama dengan melihat penyebutnya saja, sehingga 2/7 dianggap lebih besar daripada 2/5.', 'Bila pembilangnya sama, penyebut yang lebih besar berarti potongannya lebih kecil, sehingga pecahannya justru lebih kecil.'),
  ('mis-msd-banding-002', 'Pembilang lebih besar dianggap pecahan lebih besar', 'Siswa hanya melihat pembilang tanpa memperhatikan penyebut, sehingga 3/10 dianggap lebih besar daripada 2/3.', 'Pembilang hanya menyatakan banyak potongan; besar setiap potongan ditentukan penyebutnya, jadi keduanya harus dipertimbangkan bersama.'),
  ('mis-msd-banding-003', 'Membandingkan lewat selisih pembilang dan penyebut', 'Siswa menyimpulkan pecahan dengan selisih pembilang dan penyebut lebih kecil pasti lebih besar, misalnya 3/5 dianggap lebih besar daripada 5/8.', 'Selisih pembilang dan penyebut bukan ukuran nilai pecahan; samakan penyebutnya lalu bandingkan pembilangnya.'),
  ('mis-msd-banding-004', 'Membandingkan pembilang dan penyebut secara terpisah', 'Siswa membandingkan pembilang dengan pembilang dan penyebut dengan penyebut, lalu menyimpulkan pecahan yang kedua angkanya lebih besar pasti lebih besar.', 'Pecahan adalah satu bilangan, bukan dua bilangan yang berdiri sendiri; ubah ke penyebut yang sama sebelum menyimpulkan.'),
  ('mis-msd-banding-005', 'Pecahan senilai dianggap berbeda besar', 'Siswa menganggap 5/8 dan 10/16 berbeda nilainya karena angkanya berbeda.', 'Sederhanakan dulu kedua pecahan; bila bentuk paling sederhananya sama, nilainya memang sama.'),
  ('mis-msd-relasi-001', 'Menyalin angka pecahan menjadi persen', 'Siswa menuliskan 3/4 sebagai 34% dengan menempelkan pembilang dan penyebut, tanpa menghitung nilai pecahannya.', 'Ubah pecahan menjadi penyebut 100 atau bagi pembilang dengan penyebut lebih dahulu, baru nyatakan sebagai persen.'),
  ('mis-msd-relasi-002', 'Desimal dianggap persen dengan menghapus koma', 'Siswa menuliskan 0,5 sebagai 5% karena hanya menghilangkan tanda koma, bukan mengalikan dengan 100.', 'Persen berarti per seratus, jadi desimal dikalikan 100 lebih dahulu: 0,5 × 100 = 50%.'),
  ('mis-msd-relasi-003', 'Nilai tempat desimal tertukar', 'Siswa menganggap 0,08 sama dengan 8/10 karena tidak membedakan tempat persepuluhan dan perseratusan.', 'Satu angka di belakang koma berarti persepuluhan, dua angka berarti perseratusan; 0,08 berarti 8/100.'),
  ('mis-msd-relasi-004', 'Membandingkan bentuk berbeda tanpa menyeragamkan', 'Siswa membandingkan pecahan, desimal, dan persen apa adanya tanpa mengubahnya ke satu bentuk yang sama.', 'Ubah semua besaran ke satu bentuk — biasanya desimal — sebelum diurutkan atau dibandingkan.'),
  ('mis-msd-relasi-005', 'Persen dianggap selalu lebih besar', 'Siswa menganggap bentuk persen pasti bernilai lebih besar daripada bentuk pecahan atau desimalnya karena angkanya tampak besar.', 'Bentuk penulisan tidak mengubah nilai; 40%, 0,4, dan 2/5 adalah bilangan yang sama.'),
  ('mis-msd-cacah-001', 'Mengerjakan operasi berurutan dari kiri', 'Siswa mengerjakan 18 + 6 × 4 dari kiri ke kanan menjadi 24 × 4, tanpa mendahulukan perkalian.', 'Perkalian dan pembagian dikerjakan lebih dahulu daripada penjumlahan dan pengurangan, kecuali ada tanda kurung.'),
  ('mis-msd-cacah-002', 'Sisa pembagian dibuang', 'Pada masalah yang menuntut semua benda atau orang terangkut, siswa membuang sisa pembagian sehingga jawabannya kurang satu.', 'Bila masih ada sisa yang harus ditampung, banyak wadah atau kendaraan dibulatkan ke atas.'),
  ('mis-msd-cacah-003', 'Keliru menyimpan atau meminjam', 'Siswa salah menyimpan pada penjumlahan atau salah meminjam pada pengurangan bersusun, sehingga hasilnya berbeda pada satu nilai tempat.', 'Periksa hasil pengurangan dengan menjumlahkannya kembali ke bilangan pengurang.'),
  ('mis-msd-cacah-004', 'Pengurangan dan pembagian dianggap dapat ditukar urutannya', 'Siswa menganggap sifat yang berlaku pada penjumlahan dan perkalian juga berlaku pada pengurangan dan pembagian, misalnya 120 : 6 : 2 dianggap sama dengan 120 : (6 : 2).', 'Pengurangan dan pembagian tidak dapat ditukar urutannya; kerjakan dari kiri ke kanan atau ikuti tanda kurung.'),
  ('mis-msd-cacah-005', 'Memilih operasi hanya dari kata kunci', 'Siswa memilih operasi karena menemukan kata seperti “seluruhnya” atau “sisa”, tanpa memeriksa hubungan bilangan pada ceritanya.', 'Baca ulang alur ceritanya dan tentukan apa yang dibagi, apa yang digabung, lalu pilih operasinya.'),
  ('mis-msd-oppec-001', 'Pembilang dan penyebut dijumlahkan bersamaan', 'Siswa menghitung 2/7 + 3/7 menjadi 5/14 karena penyebutnya ikut dijumlahkan.', 'Penyebut menyatakan besar potongan dan tidak berubah saat potongan digabung; yang dijumlahkan hanya pembilangnya.'),
  ('mis-msd-oppec-002', 'Penyebut belum disamakan', 'Siswa langsung menjumlahkan atau mengurangkan pembilang meski penyebutnya berbeda, misalnya 1/2 + 1/3 dianggap 2/5.', 'Pecahan hanya dapat dijumlahkan atau dikurangkan setelah penyebutnya sama, karena potongannya harus sama besar.'),
  ('mis-msd-oppec-003', 'Pembagian pecahan dikerjakan seperti perkalian', 'Siswa menghitung 2/3 : 4 dengan mengalikan pembilang dengan 4, sehingga hasilnya justru membesar.', 'Membagi pecahan dengan bilangan asli berarti memecahnya menjadi lebih banyak bagian, jadi penyebutnya yang dikalikan.'),
  ('mis-msd-oppec-004', 'Perkalian dengan bilangan asli dikenakan pada penyebut', 'Siswa menghitung 3/4 × 8 dengan mengalikan penyebutnya, sehingga hasilnya mengecil, bukan membesar.', 'Mengalikan pecahan dengan bilangan asli berarti menyalin pecahan itu sebanyak bilangan tersebut, jadi pembilangnya yang dikalikan.'),
  ('mis-msd-oppec-005', 'Penyebut disamakan tetapi pembilang tidak diubah', 'Siswa mengubah 5/6 − 1/4 menjadi 5/12 − 1/12 karena hanya penyebutnya disamakan tanpa mengalikan pembilangnya.', 'Setiap kali penyebut dikalikan, pembilangnya harus dikalikan dengan bilangan yang sama agar nilainya tetap.'),
  ('mis-msd-kpkfpb-001', 'KPK dan FPB tertukar', 'Siswa memakai FPB pada masalah kejadian berulang atau memakai KPK pada masalah pembagian rata.', 'Masalah “bertemu atau berulang bersama lagi” memakai KPK, sedangkan masalah “dibagi rata sebanyak mungkin kelompok” memakai FPB.'),
  ('mis-msd-kpkfpb-002', 'KPK dianggap selalu hasil kali kedua bilangan', 'Siswa langsung mengalikan kedua bilangan untuk mencari KPK, misalnya KPK 4 dan 6 dijawab 24.', 'Hasil kali dua bilangan memang kelipatan persekutuan, tetapi belum tentu yang terkecil; hasil kali sama dengan KPK hanya bila FPB-nya 1.'),
  ('mis-msd-kpkfpb-003', 'Daftar faktor tidak lengkap', 'Siswa melewatkan pasangan faktor, misalnya mendaftar faktor 24 tanpa menyertakan 8, karena tidak memeriksa secara berpasangan.', 'Daftar faktor secara berpasangan dari yang terkecil: 1 dan 24, 2 dan 12, 3 dan 8, 4 dan 6, sehingga tidak ada yang terlewat.'),
  ('mis-msd-kpkfpb-004', 'Aturan habis dibagi dibalik', 'Siswa menyimpulkan bahwa bilangan yang habis dibagi 3 pasti habis dibagi 9, membalik arah hubungan yang benar.', 'Setiap bilangan yang habis dibagi 9 pasti habis dibagi 3, tetapi tidak sebaliknya — 12 habis dibagi 3 namun tidak habis dibagi 9.'),
  ('mis-msd-kpkfpb-005', 'Kelipatan dan faktor tertukar', 'Siswa menyebut 45 sebagai kelipatan 6 atau menyebut 6 sebagai kelipatan 24, karena arah hubungan faktor dan kelipatan tertukar.', 'Faktor membagi habis bilangannya, sedangkan kelipatan adalah hasil mengalikan bilangan itu dengan bilangan asli.'),
  ('mis-msd-bangdat-001', 'Persegi dan persegi panjang dianggap saling terpisah', 'Siswa menganggap persegi bukan persegi panjang karena keduanya diberi nama berbeda, sehingga golongan bangun dianggap tidak dapat bertumpang.', 'Persegi memenuhi semua syarat persegi panjang dan menambahkan satu syarat lagi, yaitu keempat sisinya sama panjang.'),
  ('mis-msd-bangdat-002', 'Belah ketupat dianggap harus bersudut siku-siku', 'Siswa mencampur syarat belah ketupat dengan syarat persegi, sehingga bangun bersisi empat sama panjang tanpa sudut siku-siku tidak dikenali sebagai belah ketupat.', 'Belah ketupat hanya menuntut keempat sisi sama panjang; sudut siku-siku adalah syarat tambahan milik persegi.'),
  ('mis-msd-bangdat-003', 'Sumbu simetri persegi panjang dianggap empat', 'Siswa menyalin banyak sumbu simetri persegi ke persegi panjang, sehingga menghitung empat padahal hanya dua.', 'Lipatan sepanjang diagonal persegi panjang tidak menghasilkan dua bagian yang saling menutup, jadi diagonalnya bukan sumbu simetri.'),
  ('mis-msd-bangdat-004', 'Nama segi banyak ditentukan dari sudut yang tampak menonjol', 'Pada bangun gabungan, siswa hanya menghitung sudut yang menonjol ke luar dan melewatkan sudut yang menjorok ke dalam.', 'Nama segi banyak ditentukan oleh banyak sisinya; hitung sisi satu per satu mengikuti tepi bangun sampai kembali ke titik awal.'),
  ('mis-msd-bangdat-005', 'Trapesium dianggap punya dua pasang sisi sejajar', 'Siswa menyamakan trapesium dengan jajar genjang, sehingga menganggap kedua pasang sisi trapesium sejajar.', 'Trapesium hanya dijamin mempunyai satu pasang sisi sejajar; bila dua pasang sisinya sejajar, bangun itu sudah menjadi jajar genjang.'),
  ('mis-msd-ruang-001', 'Sisi, rusuk, dan titik sudut tertukar', 'Siswa menyebut banyak rusuk ketika yang diminta banyak sisi, atau sebaliknya, karena ketiga unsur itu belum terpisah jelas.', 'Sisi adalah bidang datarnya, rusuk adalah garis pertemuan dua sisi, dan titik sudut adalah pertemuan tiga rusuk.'),
  ('mis-msd-ruang-002', 'Pandangan atas dianggap memperlihatkan tinggi', 'Siswa menganggap pandangan atas dapat menunjukkan banyak lapisan tumpukan kubus, padahal tinggi tidak tampak dari atas.', 'Pandangan atas hanya memperlihatkan panjang dan lebar; tinggi tampak pada pandangan depan atau samping.'),
  ('mis-msd-ruang-003', 'Kubus tersembunyi tidak dihitung', 'Siswa hanya menghitung kubus satuan yang terlihat pada gambar, sehingga kubus di lapisan belakang atau di bagian dalam terlewat.', 'Hitung per lapisan: banyak kubus tiap lapisan dikalikan banyak lapisan, bukan sekadar yang tampak dari satu arah.'),
  ('mis-msd-ruang-004', 'Kubus dan balok dianggap terpisah sama sekali', 'Siswa menganggap kubus bukan balok, sehingga sifat yang berlaku pada balok dianggap tidak berlaku pada kubus.', 'Kubus adalah balok istimewa yang seluruh rusuknya sama panjang, jadi semua sifat balok tetap berlaku padanya.'),
  ('mis-msd-ruang-005', 'Bangun dianggap sama karena satu pandangannya sama', 'Siswa menyimpulkan dua bangun tersusun dari kubus sebanyak sama hanya karena pandangan depannya serupa.', 'Satu pandangan tidak menentukan bangunnya; perlu paling sedikit pandangan depan, atas, dan samping untuk memastikannya.'),
  ('mis-msd-panjang-001', 'Angka ujung dibaca sebagai panjang', 'Saat benda tidak diletakkan mulai dari angka 0, siswa langsung membaca angka di ujung benda tanpa mengurangi angka awalnya.', 'Panjang benda adalah selisih angka di kedua ujungnya, bukan angka di ujung akhir.'),
  ('mis-msd-panjang-002', 'Satuan dipilih tanpa memperhatikan ukuran benda', 'Siswa memilih satuan yang jauh terlalu besar atau terlalu kecil, misalnya menyatakan tebal uang logam dalam meter.', 'Pilih satuan yang membuat angka hasil ukur wajar dibaca: mm untuk benda sangat tipis, cm untuk benda seukuran tangan, m untuk ruangan, km untuk jarak antarkota.'),
  ('mis-msd-panjang-003', 'Angka hasil ukur dianggap mengubah panjang benda', 'Siswa menganggap benda menjadi lebih panjang ketika hasil ukurnya ditulis dalam satuan yang lebih kecil, misalnya 2 m ditulis 200 cm.', 'Panjang benda tetap; yang berubah hanya satuan dan angkanya, karena satuan yang lebih kecil dibutuhkan lebih banyak.'),
  ('mis-msd-panjang-004', 'Gabungan cm dan mm ditulis seperti bilangan desimal', 'Siswa menuliskan 4 cm 6 mm sebagai 4,6 mm atau 46 cm karena satuan gabungan tidak diurai lebih dahulu.', 'Ubah dahulu ke satu satuan: 4 cm = 40 mm, ditambah 6 mm menjadi 46 mm, atau 4,6 cm.'),
  ('mis-msd-panjang-005', 'Sisa pada pengukuran berulang tidak dijumlahkan', 'Saat benda diukur dengan alat yang lebih pendek secara berulang, siswa lupa menambahkan bagian sisa yang tidak sampai satu kali penuh.', 'Panjang seluruhnya adalah banyak pengulangan penuh dikalikan panjang alat, ditambah panjang sisanya.'),
  ('mis-msd-konvpanjang-001', 'Arah tangga satuan terbalik', 'Siswa mengalikan ketika seharusnya membagi, misalnya mengubah 2.500 cm ke meter dengan mengalikan 100.', 'Turun satu tangga satuan berarti dikali 10 dan naik satu tangga berarti dibagi 10; satuan yang lebih besar selalu memberi angka yang lebih kecil.'),
  ('mis-msd-konvpanjang-002', 'Tangga dam dan hm dilompati', 'Siswa melompati dam atau hm saat menghitung banyak tangga, sehingga pengalinya kurang atau lebih satu angka nol.', 'Urutan tangganya km, hm, dam, m, dm, cm, mm — hitung tangganya satu per satu tanpa melompat.'),
  ('mis-msd-konvpanjang-003', 'Setiap tangga dianggap berkelipatan 100', 'Siswa memakai pengali 100 untuk setiap tangga satuan panjang, seperti pada satuan luas.', 'Pada satuan panjang setiap tangga berkelipatan 10; pengali 100 baru muncul bila melewati dua tangga sekaligus.'),
  ('mis-msd-konvpanjang-004', 'Perpindahan koma keliru banyak angkanya', 'Pada bentuk desimal, siswa memindahkan koma lebih sedikit atau lebih banyak daripada banyak tangga yang dilewati.', 'Banyak angka perpindahan koma sama dengan banyak tangga yang dilewati, satu angka untuk satu tangga.'),
  ('mis-msd-konvpanjang-005', 'Membandingkan angka tanpa menyeragamkan satuan', 'Siswa langsung membandingkan angkanya, sehingga 450 m dianggap lebih panjang daripada 0,5 km.', 'Ubah semua besaran ke satu satuan yang sama lebih dahulu, baru bandingkan angkanya.'),
  ('mis-msd-volbenda-001', 'Tinggi permukaan air dianggap menentukan volume', 'Siswa menyimpulkan wadah yang permukaan airnya lebih tinggi pasti berisi air lebih banyak, tanpa memperhatikan luas dasar wadahnya.', 'Volume ditentukan oleh luas dasar dan tinggi bersama-sama; wadah sempit membuat air yang sama tampak jauh lebih tinggi.'),
  ('mis-msd-volbenda-002', 'Satuan volume dipilih tanpa memperhatikan besar wadah', 'Siswa menyatakan isi gelas dalam kiloliter atau isi tangki air dalam mililiter, sehingga angkanya menjadi tidak wajar.', 'Pilih ml untuk wadah kecil seperti gelas dan sendok obat, l untuk ember dan botol besar, serta kl untuk tangki dan kolam.'),
  ('mis-msd-volbenda-003', 'Skala gelas ukur dihitung per garis', 'Siswa menghitung banyak garis pada gelas ukur sebagai hasil pengukuran, tanpa memperhatikan nilai setiap garisnya.', 'Periksa dulu nilai satu garis dengan membagi selisih dua angka tercetak dengan banyak garis di antaranya.'),
  ('mis-msd-volbenda-004', 'Volume benda tenggelam dianggap tinggi air akhir', 'Saat benda dimasukkan ke gelas ukur, siswa membaca angka permukaan air terakhir sebagai volume bendanya.', 'Volume benda sama dengan selisih permukaan air sesudah dan sebelum benda dimasukkan.'),
  ('mis-msd-volbenda-005', 'Volume dianggap berubah saat dipindahkan', 'Siswa menganggap banyak air berubah ketika dituang ke wadah yang bentuknya berbeda.', 'Menuang hanya mengubah bentuk permukaan air, bukan banyaknya; volume air tetap selama tidak ada yang tercecer.'),
  ('mis-msd-konvvol-001', 'Arah tangga satuan volume terbalik', 'Siswa mengalikan ketika seharusnya membagi, misalnya mengubah 2.000 ml ke liter dengan mengalikan 1.000.', 'Satuan yang lebih besar selalu memberi angka yang lebih kecil, jadi ml ke l dibagi 1.000, bukan dikali.'),
  ('mis-msd-konvvol-002', 'Tangga cl, dl, atau dal dilompati', 'Siswa melompati satu tangga saat berpindah satuan, sehingga pengalinya kurang atau lebih satu angka nol.', 'Urutan tangganya kl, hl, dal, l, dl, cl, ml — hitung satu per satu tanpa melompat.'),
  ('mis-msd-konvvol-003', 'Sentiliter dianggap sama dengan mililiter', 'Siswa menganggap 1 cl sama dengan 1 ml karena keduanya satuan kecil yang jarang dipakai.', 'cl berada satu tangga di atas ml, jadi 1 cl sama dengan 10 ml.'),
  ('mis-msd-konvvol-004', 'Kiloliter dianggap 100 liter', 'Siswa memakai pengali 100 untuk kl ke l, padahal jaraknya tiga tangga.', 'kl ke l melewati hl dan dal, jadi pengalinya 1.000.'),
  ('mis-msd-konvvol-005', 'Membandingkan angka tanpa menyeragamkan satuan', 'Siswa langsung membandingkan angkanya, sehingga 750 l dianggap lebih banyak daripada 0,8 kl.', 'Ubah semua besaran ke satu satuan yang sama lebih dahulu, baru bandingkan angkanya.'),
  ('mis-msd-berat-001', 'Ukuran benda dianggap menentukan beratnya', 'Siswa menyimpulkan benda yang lebih besar pasti lebih berat, tanpa memperhitungkan bahan penyusunnya.', 'Besar dan berat adalah dua hal berbeda; satu kilogram kapas jauh lebih besar daripada satu kilogram besi meski beratnya sama.'),
  ('mis-msd-berat-002', 'Berat wadah tidak diperhitungkan', 'Pada masalah yang menyebutkan berat wadah, siswa hanya menghitung berat isinya sehingga batas beban terlampaui.', 'Bila batas beban meliputi wadahnya, kurangi dahulu berat wadah sebelum membagi dengan berat setiap barang.'),
  ('mis-msd-berat-003', 'Skala timbangan dihitung per garis', 'Siswa menghitung banyak garis pada timbangan sebagai hasil pengukuran, tanpa memeriksa nilai setiap garisnya.', 'Cari nilai satu garis dengan membagi selisih dua angka tercetak dengan banyak garis di antaranya.'),
  ('mis-msd-berat-004', 'Bruto, netto, dan tara tertukar', 'Siswa menjumlahkan tara ke berat kotor atau menganggap netto lebih besar daripada bruto.', 'Bruto adalah berat isi beserta wadahnya, tara adalah berat wadahnya, dan netto = bruto − tara.'),
  ('mis-msd-berat-005', 'Satuan berat dipilih tanpa memperhatikan benda', 'Siswa menyatakan berat gajah dalam gram atau berat vitamin dalam kilogram, sehingga angkanya menjadi tidak wajar.', 'Pilih mg untuk benda sangat ringan seperti obat, g untuk benda seukuran tangan, dan kg untuk benda berat seperti karung dan hewan besar.'),
  ('mis-msd-konvberat-001', 'Arah tangga satuan berat terbalik', 'Siswa mengalikan ketika seharusnya membagi, misalnya mengubah gram menjadi kilogram dengan mengalikan 1.000.', 'Satuan yang lebih besar memberi angka yang lebih kecil, jadi gram dibagi 1.000 untuk menjadi kilogram.'),
  ('mis-msd-konvberat-002', 'Tangga dag, hg, cg, atau dg dilompati', 'Siswa melompati satu tangga sehingga pengalinya kurang atau lebih satu angka nol, misalnya menganggap 1 hg sama dengan 1.000 g.', 'Urutan tangganya kg, hg, dag, g, dg, cg, mg — hitung satu per satu tanpa melompat.'),
  ('mis-msd-konvberat-003', 'Setiap tangga dianggap berkelipatan 1.000', 'Siswa memakai pengali 1.000 untuk setiap perpindahan satuan berat, karena hanya menghafal hubungan kg dan g.', 'Setiap tangga hanya berkelipatan 10; pengali 1.000 muncul karena kg dan g terpisah tiga tangga.'),
  ('mis-msd-konvberat-004', 'Perpindahan koma keliru banyak angkanya', 'Pada bentuk desimal, siswa memindahkan koma lebih sedikit atau lebih banyak daripada banyak tangga yang dilewati.', 'Banyak angka perpindahan koma sama dengan banyak tangga yang dilewati, satu angka untuk satu tangga.'),
  ('mis-msd-konvberat-005', 'Membandingkan angka tanpa menyeragamkan satuan', 'Siswa langsung membandingkan angkanya, sehingga 45.000 cg dianggap jauh lebih berat daripada 0,4 kg.', 'Ubah semua besaran ke satu satuan yang sama lebih dahulu, baru bandingkan angkanya.'),
  ('mis-msd-waktu-001', 'Menit dikurangkan seperti bilangan desimal', 'Siswa menghitung selisih waktu dengan mengurangkan angkanya langsung, misalnya 12.20 − 9.50 dianggap 2,70 sehingga ditulis 2 jam 70 menit.', 'Satu jam hanya memuat 60 menit, jadi bila menit pengurang lebih besar, pinjam 60 menit dari jamnya, bukan 100.'),
  ('mis-msd-waktu-002', 'Jarum pendek dan jarum panjang tertukar', 'Siswa membaca jarum panjang sebagai penunjuk jam dan jarum pendek sebagai penunjuk menit, sehingga pukul 07.15 terbaca 03.35.', 'Jarum pendek menunjuk jam dan jarum panjang menunjuk menit; setiap angka yang dilewati jarum panjang bernilai 5 menit.'),
  ('mis-msd-waktu-003', 'Penulisan 12 jam dan 24 jam tertukar', 'Siswa menuliskan pukul 24.15 untuk seperempat jam setelah tengah malam atau menuliskan tengah hari sebagai pukul 24.00.', 'Penulisan 24 jam berjalan dari 00.00 sampai 23.59; tengah malam ditulis 00.00 dan tengah hari ditulis 12.00.'),
  ('mis-msd-waktu-004', 'Banyak selang dianggap sama dengan banyak kejadian', 'Pada jadwal berulang, siswa mengalikan selang waktu dengan banyak keberangkatan, padahal keberangkatan pertama belum melewati satu selang.', 'Untuk kejadian ke-n, selang yang dilewati hanya n − 1, karena kejadian pertama terjadi pada waktu awal.'),
  ('mis-msd-waktu-005', 'Pergantian bulan tidak diperhitungkan', 'Saat menambah hari pada suatu tanggal, siswa menuliskan tanggal yang melebihi banyak hari dalam bulan itu, misalnya tanggal 37 Maret.', 'Bila hasil penjumlahan melebihi banyak hari dalam bulan itu, kurangi dengan banyak hari bulan tersebut dan pindah ke bulan berikutnya.'),
  ('mis-msd-konvwaktu-001', 'Satuan waktu dianggap berkelipatan 10 atau 100', 'Siswa memakai pengali 10 atau 100 untuk mengubah jam ke menit atau menit ke detik, seperti pada satuan panjang dan berat.', 'Satuan waktu tidak memakai tangga puluhan: 1 jam = 60 menit, 1 menit = 60 detik, 1 hari = 24 jam, dan 1 pekan = 7 hari.'),
  ('mis-msd-konvwaktu-002', 'Bentuk desimal jam dibaca sebagai menit', 'Siswa menafsirkan 1,5 jam sebagai 1 jam 5 menit atau 2,5 jam sebagai 2 jam 5 menit.', 'Angka di belakang koma adalah bagian dari jam: 0,5 jam berarti setengah jam, yaitu 30 menit.'),
  ('mis-msd-konvwaktu-003', 'Arah perubahan satuan waktu terbalik', 'Siswa membagi ketika seharusnya mengalikan, misalnya mengubah 3 jam ke menit dengan membagi 60.', 'Satuan yang lebih kecil dibutuhkan lebih banyak, jadi jam ke menit dikali 60 dan menit ke jam dibagi 60.'),
  ('mis-msd-konvwaktu-004', 'Sisa pembagian detik ditulis keliru', 'Saat mengubah detik ke menit, siswa menuliskan hasil bagi dan sisanya tertukar atau memakai sisa lebih dari 60.', 'Hasil bagi menjadi banyak menit dan sisanya menjadi detik; sisa harus selalu kurang dari 60.'),
  ('mis-msd-konvwaktu-005', 'Membandingkan angka tanpa menyeragamkan satuan', 'Siswa langsung membandingkan angkanya, sehingga 1.500 detik dianggap lebih lama daripada 0,6 jam.', 'Ubah semua lama waktu ke satu satuan yang sama, biasanya menit, sebelum dibandingkan.'),
  ('mis-msd-kecepatan-001', 'Jarak dan waktu tertukar', 'Siswa membagi waktu dengan jarak, atau mengalikan ketika seharusnya membagi, sehingga satuan hasilnya tidak masuk akal.', 'Kecepatan = jarak : waktu. Periksa satuannya: hasil km : jam memang km/jam, sedangkan jam : km bukan satuan kecepatan.'),
  ('mis-msd-kecepatan-002', 'Menit dipakai langsung sebagai jam', 'Siswa memasukkan 45 menit sebagai angka 45 ke dalam perhitungan berkecepatan km/jam, tanpa mengubahnya menjadi jam.', 'Bila kecepatannya km/jam, waktu harus dinyatakan dalam jam: 45 menit sama dengan 45 : 60 = 0,75 jam.'),
  ('mis-msd-kecepatan-003', 'Kecepatan rata-rata dianggap rata-rata kedua kecepatan', 'Pada perjalanan dua tahap, siswa menjumlahkan kedua kecepatan lalu membaginya dua, tanpa memperhatikan lama masing-masing tahap.', 'Kecepatan rata-rata = jarak seluruhnya : waktu seluruhnya, bukan rata-rata dari angka kecepatannya.'),
  ('mis-msd-kecepatan-004', 'Kecepatan dan waktu dianggap berubah searah', 'Siswa menganggap menggandakan kecepatan berarti waktu tempuhnya juga menjadi dua kali.', 'Untuk jarak yang tetap, kecepatan dan waktu berbanding berbalik: kecepatan dua kali membuat waktunya menjadi setengah.'),
  ('mis-msd-kecepatan-005', 'Satuan kecepatan diabaikan saat membandingkan', 'Siswa membandingkan 5 m/detik dengan 5 km/jam hanya dari angkanya, tanpa menyeragamkan satuannya.', 'Seragamkan satuannya lebih dahulu; 5 m/detik sama dengan 18 km/jam, jauh lebih cepat daripada 5 km/jam.'),
  ('mis-msd-luas-001', 'Keliling dan luas tertukar', 'Siswa menghitung luas ketika yang diminta keliling, atau sebaliknya, karena kedua besaran itu belum terpisah jelas.', 'Keliling mengukur panjang tepinya dan bersatuan cm, sedangkan luas mengukur daerah di dalamnya dan bersatuan cm².'),
  ('mis-msd-luas-002', 'Pembagian dua pada luas segitiga terlewat', 'Siswa menghitung luas segitiga sebagai alas kali tinggi tanpa membaginya dua.', 'Segitiga adalah setengah dari persegi panjang beralas dan bertinggi sama, jadi hasilnya harus dibagi dua.'),
  ('mis-msd-luas-003', 'Bagian yang dipotong tidak dikurangkan', 'Pada bangun gabungan, siswa menghitung luas persegi panjang utuhnya saja tanpa mengurangi bagian yang dipotong.', 'Luas bangun gabungan dihitung dengan menjumlahkan bagian-bagiannya atau mengurangi bagian yang hilang dari bangun utuhnya.'),
  ('mis-msd-luas-004', 'Keliling persegi panjang hanya panjang ditambah lebar', 'Siswa menjumlahkan panjang dan lebar sekali saja, sehingga kelilingnya hanya separuh dari yang seharusnya.', 'Persegi panjang mempunyai dua sisi panjang dan dua sisi lebar, jadi kelilingnya 2 × (panjang + lebar).'),
  ('mis-msd-luas-005', 'Luas dianggap berlipat sama dengan sisinya', 'Siswa menganggap menggandakan panjang dan lebar membuat luasnya menjadi dua kali, bukan empat kali.', 'Luas dipengaruhi dua ukuran sekaligus, jadi bila keduanya menjadi dua kali, luasnya menjadi 2 × 2 = 4 kali.'),
  ('mis-msd-volruang-001', 'Rusuk kubus hanya dikalikan tiga', 'Siswa menghitung volume kubus dengan mengalikan rusuknya dengan 3, misalnya kubus berusuk 5 cm dijawab 15 cm³.', 'Volume kubus adalah rusuk × rusuk × rusuk, karena panjang, lebar, dan tingginya sama.'),
  ('mis-msd-volruang-002', 'Volume dan luas tertukar', 'Siswa mengalikan hanya dua ukuran sehingga yang dihitung sebenarnya luas salah satu sisinya, bukan volumenya.', 'Volume memerlukan tiga ukuran sekaligus dan bersatuan cm³, sedangkan luas hanya dua ukuran dan bersatuan cm².'),
  ('mis-msd-volruang-003', 'Hubungan cm³ dan liter keliru', 'Siswa memakai pengali 100 atau 10.000 untuk mengubah cm³ ke liter, bukan 1.000.', '1 liter sama dengan 1.000 cm³, jadi banyak cm³ dibagi 1.000 untuk menjadi liter.'),
  ('mis-msd-volruang-004', 'Bagian bangun gabungan tidak dijumlahkan seluruhnya', 'Pada bangun gabungan, siswa hanya menghitung volume balok terbesarnya dan mengabaikan bagian lainnya.', 'Pecah bangun gabungan menjadi balok-balok yang jelas ukurannya, hitung volume masing-masing, lalu jumlahkan.'),
  ('mis-msd-volruang-005', 'Volume dianggap berlipat sama dengan rusuknya', 'Siswa menganggap menggandakan rusuk kubus membuat volumenya menjadi dua kali, bukan delapan kali.', 'Volume dipengaruhi tiga ukuran sekaligus, jadi bila ketiganya menjadi dua kali, volumenya menjadi 2 × 2 × 2 = 8 kali.'),
  ('mis-msd-sudut-001', 'Panjang kaki sudut dianggap menentukan besarnya', 'Siswa menyimpulkan sudut yang kakinya digambar lebih panjang pasti lebih besar daripada sudut berkaki pendek.', 'Besar sudut ditentukan oleh bukaan antara kedua kakinya; memperpanjang kaki tidak mengubah bukaan itu.'),
  ('mis-msd-sudut-002', 'Skala dalam dan luar busur derajat tertukar', 'Siswa membaca angka pada deretan skala yang salah, sehingga 65° terbaca 115° atau sebaliknya.', 'Mulai membaca dari angka 0 yang berimpit dengan salah satu kaki sudut, lalu ikuti deretan angka pada baris yang sama.'),
  ('mis-msd-sudut-003', 'Batas penggolongan jenis sudut keliru', 'Siswa menggolongkan sudut 95° sebagai lancip atau sudut 180° sebagai tumpul karena batasnya belum jelas.', 'Lancip kurang dari 90°, siku-siku tepat 90°, tumpul antara 90° dan 180°, dan lurus tepat 180°.'),
  ('mis-msd-sudut-004', 'Jumlah sudut segitiga dianggap 360°', 'Siswa memakai 360° sebagai jumlah sudut dalam segitiga, tertukar dengan jumlah sudut segi empat atau satu putaran penuh.', 'Jumlah sudut dalam segitiga selalu 180°; 360° adalah satu putaran penuh atau jumlah sudut segi empat.'),
  ('mis-msd-sudut-005', 'Pergerakan jarum jam pendek diabaikan', 'Saat menghitung sudut pada pukul setengah, siswa menganggap jarum pendek masih tepat di angka jamnya, padahal jarum itu sudah bergeser separuh selang.', 'Dalam 30 menit, jarum pendek bergeser setengah selang, yaitu 15°, sehingga posisinya tidak lagi tepat di angka jamnya.'),
  ('mis-msd-taksir-001', 'Pembulatan ke nilai tempat yang keliru', 'Siswa membulatkan ke ratusan padahal yang diminta puluhan, atau sebaliknya, sehingga taksirannya melenceng jauh.', 'Tentukan dulu nilai tempat yang diminta, lalu perhatikan satu angka di sebelah kanannya untuk memutuskan naik atau tetap.'),
  ('mis-msd-taksir-002', 'Angka tepat di tengah dibulatkan ke bawah', 'Siswa membulatkan 4.350 ke ratusan terdekat menjadi 4.300, padahal angka tepat di tengah dibulatkan ke atas.', 'Bila angka penentunya 5 atau lebih, pembulatan dilakukan ke atas — termasuk ketika nilainya tepat di tengah.'),
  ('mis-msd-taksir-003', 'Arah taksiran dianggap selalu ke bawah', 'Siswa menganggap hasil taksiran selalu lebih kecil daripada hasil sebenarnya, tanpa memeriksa arah pembulatannya.', 'Bila kedua faktor dibulatkan ke atas, taksirannya lebih besar daripada hasil sebenarnya; bila ke bawah, taksirannya lebih kecil.'),
  ('mis-msd-taksir-004', 'Penaksiran dipakai pada situasi yang menuntut hasil tepat', 'Siswa memakai taksiran untuk menghitung uang kembalian atau hasil ujian, padahal keduanya menuntut hitungan tepat.', 'Penaksiran hanya untuk memperkirakan dengan cepat; urusan uang dan pencatatan resmi tetap memerlukan hitungan tepat.'),
  ('mis-msd-taksir-005', 'Taksiran ukuran tidak dibandingkan dengan benda acuan', 'Siswa menaksir ukuran benda tanpa membandingkannya dengan benda yang sudah dikenal, sehingga hasilnya jauh dari wajar.', 'Pakai benda acuan yang dikenal — tinggi pintu sekitar 2 m, tebal buku sekitar 1 cm — lalu bandingkan benda yang ditaksir dengan acuan itu.'),
  ('mis-msd-sajidata-001', 'Banyak gambar piktogram dibaca sebagai banyak data', 'Siswa menjawab banyak gambar yang tampak, tanpa mengalikannya dengan nilai setiap gambar.', 'Pada piktogram, banyak data = banyak gambar × nilai satu gambar; keterangan nilai gambar harus dibaca lebih dahulu.'),
  ('mis-msd-sajidata-002', 'Setengah gambar diabaikan atau dihitung penuh', 'Siswa membaca 3 setengah gambar sebagai 3 gambar atau sebagai 4 gambar.', 'Setengah gambar bernilai setengah dari nilai satu gambar, jadi harus dihitung sebagai tambahan yang tepat.'),
  ('mis-msd-sajidata-003', 'Nilai data dan frekuensinya tertukar', 'Pada tabel frekuensi, siswa menjumlahkan nilai datanya, bukan frekuensinya, ketika mencari banyak seluruh data.', 'Banyak seluruh data adalah jumlah frekuensinya; kolom nilai hanya menyatakan kelompok datanya.'),
  ('mis-msd-sajidata-004', 'Skala diagram batang dihitung per garis', 'Siswa menghitung banyak garis pada sumbu diagram batang tanpa memeriksa nilai setiap garisnya.', 'Periksa dulu nilai satu garis pada sumbu, karena satu garis belum tentu bernilai satu.'),
  ('mis-msd-sajidata-005', 'Data dibandingkan tanpa memeriksa keterangan penyajiannya', 'Siswa langsung membandingkan tinggi batang atau banyak gambar meski skala atau nilai gambarnya tidak dinyatakan.', 'Penyajian data tanpa keterangan skala atau nilai gambar tidak dapat dibaca sebagai angka; keterangan itu bagian wajib penyajian.'),
  ('mis-msd-gunadata-001', 'Kesimpulan melampaui apa yang ditunjukkan data', 'Siswa menyimpulkan sebab atau kesukaan dari data yang sebenarnya hanya mencatat jumlah kejadian.', 'Periksa apa yang sesungguhnya dicatat oleh data itu; jumlah peminjaman belum tentu menunjukkan kesukaan, karena bisa jadi koleksinya memang sedikit.'),
  ('mis-msd-gunadata-002', 'Perkiraan dianggap kepastian', 'Siswa menyatakan kejadian berikutnya pasti mengikuti pola yang tampak pada data sebelumnya.', 'Pola pada data hanya mendasari perkiraan; keadaan berikutnya dapat berubah, jadi pakai kata “diperkirakan”, bukan “pasti”.'),
  ('mis-msd-gunadata-003', 'Frekuensi tertinggi dianggap berlaku bagi setiap orang', 'Siswa menyimpulkan bahwa pilihan terbanyak berarti semua orang menyukainya.', 'Frekuensi tertinggi hanya berarti paling banyak dipilih; masih ada anggota lain yang memilih hal yang berbeda.'),
  ('mis-msd-gunadata-004', 'Data kelompok kecil dianggap mewakili kelompok besar', 'Siswa memakai data satu kelas untuk menyimpulkan keadaan seluruh sekolah tanpa catatan apa pun.', 'Kesimpulan hanya berlaku untuk kelompok yang datanya benar-benar dikumpulkan, kecuali datanya diambil mewakili keseluruhan.'),
  ('mis-msd-gunadata-005', 'Jumlah dan selisih tertukar', 'Siswa menjumlahkan dua data ketika yang diminta selisihnya, atau sebaliknya.', 'Baca kembali kata kuncinya: “selisih” berarti mengurangkan, sedangkan “seluruhnya” atau “bersama-sama” berarti menjumlahkan.')
insert into public.questions (id, subject_id, topic_id, subtopic_id, concept_id, type, competency, difficulty, reasoning_type, content_format, stimulus, question_text, instruction, explanation, options, correct_answer, correct_answers, categories, statements, source_answer_key, requires_visual, visual_prompt, visual_type) values
  ('msd-senilai-001', 'sub-matematika-sd', 'top-matematika-sd-bilangan', 'st-matematika-sd-bilangan-rasional', 'con-matematika-sd-pecahan-senilai', 'single', 'Memahami pecahan senilai dari gambar bagian yang diwarnai', 'dasar', 'pemahaman', 'html', '<p>Dua pita kertas mempunyai panjang yang sama. Pita A dibagi menjadi 6 bagian sama besar dan 4 bagian di antaranya diwarnai. Pita B dibagi menjadi 9 bagian sama besar dan 6 bagian di antaranya diwarnai.</p>', '<p>Ternyata panjang bagian berwarna pada kedua pita sama. Bentuk paling sederhana dari pecahan bagian berwarna itu adalah ....</p>', 'Pilih satu jawaban.', '<p>Pita A: 4 dari 6 bagian, yaitu 4/6. Pita B: 6 dari 9 bagian, yaitu 6/9.</p><p>4/6 dibagi 2 pada pembilang dan penyebut menjadi 2/3. 6/9 dibagi 3 pada pembilang dan penyebut juga menjadi 2/3. Jadi keduanya senilai dengan 2/3.</p><p>Pilihan B memang bernilai sama, tetapi 4/6 belum bentuk paling sederhana karena 4 dan 6 masih dapat dibagi 2.</p>', '[{"key":"A","text":"<p>1/2</p>","misconceptionId":"mis-msd-senilai-004"},{"key":"B","text":"<p>4/6</p>","misconceptionId":"mis-msd-senilai-003"},{"key":"C","text":"<p>3/4</p>","misconceptionId":"mis-msd-senilai-005"},{"key":"D","text":"<p>2/3</p>"}]'::jsonb, 'D', null, null, null, 'D', true, 'Dua pita kertas mendatar sama panjang, ditumpuk atas-bawah dan disejajarkan ujungnya. Pita atas berlabel ''Pita A'' dibagi 6 kotak sama besar, 4 kotak paling kiri diwarnai biru. Pita bawah berlabel ''Pita B'' dibagi 9 kotak sama besar, 6 kotak paling kiri diwarnai biru. Garis pembagi tampak jelas, panjang total kedua pita persis sama.', 'svg'),
  ('msd-senilai-002', 'sub-matematika-sd', 'top-matematika-sd-bilangan', 'st-matematika-sd-bilangan-rasional', 'con-matematika-sd-pecahan-senilai', 'single', 'Memahami cara membuat pecahan senilai dengan simbol matematika', 'dasar', 'pemahaman', 'html', '<p>Sebuah resep memakai 3 dari 5 takaran gula yang tersedia. Bu Sari ingin menuliskan ulang bagian itu dengan penyebut 10 agar mudah dibaca pada gelas ukur bergaris sepuluh.</p>', '<p>Pecahan yang senilai dengan 3/5 adalah ....</p>', 'Pilih satu jawaban.', '<p>Agar penyebut 5 menjadi 10, penyebut dikalikan 2. Pembilang harus dikalikan 2 juga: 3 × 2 = 6.</p><p>Jadi 3/5 = 6/10.</p><p>Pilihan A didapat dengan menambah 2 pada pembilang dan penyebut — cara ini mengubah nilai pecahan. Pilihan C dan B hanya mengalikan satu bagian saja.</p>', '[{"key":"A","text":"<p>5/7</p>","misconceptionId":"mis-msd-senilai-001"},{"key":"B","text":"<p>6/5</p>","misconceptionId":"mis-msd-senilai-002"},{"key":"C","text":"<p>3/10</p>","misconceptionId":"mis-msd-senilai-002"},{"key":"D","text":"<p>6/10</p>"}]'::jsonb, 'D', null, null, null, 'D', false, null, null),
  ('msd-senilai-003', 'sub-matematika-sd', 'top-matematika-sd-bilangan', 'st-matematika-sd-bilangan-rasional', 'con-matematika-sd-pecahan-senilai', 'single', 'Mengaplikasikan pecahan senilai pada data dua kelompok', 'menengah', 'penerapan', 'html', '<p>Di Kelas A, 12 dari 20 siswa membawa bekal dari rumah. Di Kelas B, 15 dari 25 siswa membawa bekal. Setelah disederhanakan, kedua kelas ternyata mempunyai bagian pembawa bekal yang sama.</p>', '<p>Kelas C berisi 30 siswa dengan bagian pembawa bekal yang senilai dengan kedua kelas itu. Banyak siswa Kelas C yang membawa bekal adalah ....</p>', 'Pilih satu jawaban.', '<p>Kelas A: 12/20 = 3/5 (dibagi 4). Kelas B: 15/25 = 3/5 (dibagi 5). Bagian yang sama adalah 3/5.</p><p>Untuk 30 siswa, penyebut 5 dikalikan 6 menjadi 30, maka pembilang 3 dikalikan 6 menjadi 18.</p><p>Jadi 18 siswa membawa bekal.</p>', '[{"key":"A","text":"<p>15 siswa</p>","misconceptionId":"mis-msd-senilai-004"},{"key":"B","text":"<p>20 siswa</p>","misconceptionId":"mis-msd-senilai-005"},{"key":"C","text":"<p>18 siswa</p>"},{"key":"D","text":"<p>22 siswa</p>","misconceptionId":"mis-msd-senilai-001"}]'::jsonb, 'C', null, null, null, 'C', false, null, null),
  ('msd-senilai-004', 'sub-matematika-sd', 'top-matematika-sd-bilangan', 'st-matematika-sd-bilangan-rasional', 'con-matematika-sd-pecahan-senilai', 'single', 'Mengaplikasikan pecahan senilai pada pembagian petak', 'menengah', 'penerapan', 'html', '<p>Taman sekolah berbentuk persegi panjang dibagi menjadi 24 petak sama besar. Sebanyak 9 petak ditanami bunga, sisanya ditanami rumput.</p>', '<p>Taman di sekolah lain dibagi menjadi 40 petak sama besar dengan bagian bunga yang senilai. Banyak petak bunga di taman itu adalah ....</p>', 'Pilih satu jawaban.', '<p>Bagian bunga = 9/24. Pembilang dan penyebut dibagi 3 menjadi 3/8.</p><p>Untuk 40 petak: penyebut 8 dikalikan 5 menjadi 40, maka pembilang 3 dikalikan 5 menjadi 15.</p><p>Jadi 15 petak ditanami bunga. Periksa: 15/40 dibagi 5 menghasilkan 3/8, sama dengan 9/24.</p>', '[{"key":"A","text":"<p>12 petak</p>","misconceptionId":"mis-msd-senilai-002"},{"key":"B","text":"<p>25 petak</p>","misconceptionId":"mis-msd-senilai-001"},{"key":"C","text":"<p>16 petak</p>","misconceptionId":"mis-msd-senilai-004"},{"key":"D","text":"<p>15 petak</p>"}]'::jsonb, 'D', null, null, null, 'D', true, 'Persegi panjang mendatar berlabel ''Taman Sekolah'' dibagi menjadi kisi 4 baris × 6 kolom sehingga terbentuk 24 petak sama besar. Sembilan petak diwarnai hijau muda dan diberi ikon bunga kecil; petak lainnya dibiarkan putih. Garis kisi tipis berwarna abu-abu.', 'svg'),
  ('msd-senilai-005', 'sub-matematika-sd', 'top-matematika-sd-bilangan', 'st-matematika-sd-bilangan-rasional', 'con-matematika-sd-pecahan-senilai', 'single', 'Mengaplikasikan penyederhanaan pecahan pada data tempat duduk', 'menengah', 'penerapan', 'html', '<p>Pak Yusuf mencatat 35 dari 60 kursi aula sudah terisi. Ia ingin menuliskan catatan itu sebagai pecahan dalam bentuk paling sederhana.</p>', '<p>Penyebut pecahan setelah disederhanakan adalah ....</p>', 'Pilih satu jawaban.', '<p>Bagian kursi terisi = 35/60. Faktor bersama terbesar 35 dan 60 adalah 5.</p><p>35 : 5 = 7 dan 60 : 5 = 12, sehingga 35/60 = 7/12. Penyebutnya 12.</p><p>Pilihan B didapat bila hanya dibagi 4 (yang bukan faktor 35), dan pilihan D bila hanya dibagi 2 (yang bukan faktor 35). Keduanya tidak sah karena pembagi harus membagi habis kedua bagian.</p>', '[{"key":"A","text":"<p>5</p>","misconceptionId":"mis-msd-senilai-002"},{"key":"B","text":"<p>15</p>","misconceptionId":"mis-msd-senilai-003"},{"key":"C","text":"<p>12</p>"},{"key":"D","text":"<p>30</p>","misconceptionId":"mis-msd-senilai-003"}]'::jsonb, 'C', null, null, null, 'C', false, null, null),
  ('msd-senilai-006', 'sub-matematika-sd', 'top-matematika-sd-bilangan', 'st-matematika-sd-bilangan-rasional', 'con-matematika-sd-pecahan-senilai', 'single', 'Bernalar memilih pecahan yang tidak senilai dalam satu kumpulan', 'lanjut', 'penalaran', 'html', '<p>Empat kartu pecahan disusun di papan tulis:</p><ul><li>Kartu I: 4/6</li><li>Kartu II: 6/9</li><li>Kartu III: 8/12</li><li>Kartu IV: 10/14</li></ul><p>Guru berkata bahwa satu kartu tidak sekelompok dengan tiga kartu lainnya.</p>', '<p>Kartu yang tidak sekelompok adalah ....</p>', 'Pilih satu jawaban.', '<p>Sederhanakan setiap kartu:</p><ul><li>4/6 dibagi 2 menjadi 2/3</li><li>6/9 dibagi 3 menjadi 2/3</li><li>8/12 dibagi 4 menjadi 2/3</li><li>10/14 dibagi 2 menjadi 5/7</li></ul><p>Tiga kartu pertama senilai 2/3, sedangkan Kartu IV bernilai 5/7. Jadi Kartu IV yang tidak sekelompok.</p>', '[{"key":"A","text":"<p>Kartu I</p>","misconceptionId":"mis-msd-senilai-003"},{"key":"B","text":"<p>Kartu II</p>","misconceptionId":"mis-msd-senilai-005"},{"key":"C","text":"<p>Kartu III</p>","misconceptionId":"mis-msd-senilai-005"},{"key":"D","text":"<p>Kartu IV</p>"}]'::jsonb, 'D', null, null, null, 'D', false, null, null),
  ('msd-senilai-007', 'sub-matematika-sd', 'top-matematika-sd-bilangan', 'st-matematika-sd-bilangan-rasional', 'con-matematika-sd-pecahan-senilai', 'single', 'Bernalar menilai kesahihan cara membuat pecahan senilai', 'lanjut', 'penalaran', 'html', '<p>Dua siswa berbeda pendapat saat mengisi tabel pecahan senilai.</p><ul><li>Andi menulis 2/3 = 4/6 karena pembilang dan penyebut dikalikan 2.</li><li>Bima menulis 2/3 = 3/4 karena pembilang dan penyebut ditambah 1.</li></ul>', '<p>Penilaian yang tepat terhadap kedua pekerjaan itu adalah ....</p>', 'Pilih satu jawaban.', '<p>Mengalikan pembilang dan penyebut dengan bilangan yang sama berarti mengalikan pecahan dengan 2/2, yaitu dengan 1, sehingga nilainya tetap. Pekerjaan Andi benar.</p><p>Menambah 1 pada kedua bagian tidak sama dengan mengalikan 1. Buktinya, 2/3 = 8/12 sedangkan 3/4 = 9/12, jadi 3/4 lebih besar. Pekerjaan Bima salah.</p><p>Pecahan senilai boleh dibuat dengan mengalikan maupun membagi, jadi pilihan D juga tidak tepat.</p>', '[{"key":"A","text":"<p>Keduanya benar, karena Andi dan Bima sama-sama memperlakukan pembilang dan penyebut dengan cara yang sama.</p>","misconceptionId":"mis-msd-senilai-001"},{"key":"B","text":"<p>Hanya Bima yang benar, karena selisih pembilang dan penyebutnya tetap 1 sehingga nilainya tetap.</p>","misconceptionId":"mis-msd-senilai-005"},{"key":"C","text":"<p>Hanya Andi yang benar, karena mengalikan kedua bagian dengan bilangan yang sama tidak mengubah nilai.</p>"},{"key":"D","text":"<p>Keduanya salah, karena pecahan senilai hanya boleh dibuat dengan membagi, bukan dengan mengalikan.</p>","misconceptionId":"mis-msd-senilai-002"}]'::jsonb, 'C', null, null, null, 'C', false, null, null),
  ('msd-senilai-008', 'sub-matematika-sd', 'top-matematika-sd-bilangan', 'st-matematika-sd-bilangan-rasional', 'con-matematika-sd-pecahan-senilai', 'mcma', 'Mengaplikasikan penyederhanaan untuk menyaring pecahan senilai', 'menengah', 'penerapan', 'html', '<p>Panitia lomba menempel kartu-kartu pecahan di papan. Kartu yang senilai dengan 3/4 akan dikumpulkan menjadi satu kelompok.</p>', '<p>Kartu yang masuk kelompok itu adalah ....</p>', 'Pilih semua jawaban yang benar.', '<p>Sederhanakan tiap kartu:</p><ul><li>6/8 dibagi 2 menjadi 3/4 — senilai</li><li>4/5 sudah paling sederhana, bukan 3/4</li><li>9/12 dibagi 3 menjadi 3/4 — senilai</li><li>15/20 dibagi 5 menjadi 3/4 — senilai</li><li>12/15 dibagi 3 menjadi 4/5 — bukan 3/4</li></ul><p>Jadi kartu yang senilai dengan 3/4 adalah 6/8, 9/12, dan 15/20.</p>', '[{"key":"A","text":"<p>6/8</p>"},{"key":"B","text":"<p>4/5</p>","misconceptionId":"mis-msd-senilai-005"},{"key":"C","text":"<p>9/12</p>"},{"key":"D","text":"<p>15/20</p>"},{"key":"E","text":"<p>12/15</p>","misconceptionId":"mis-msd-senilai-002"}]'::jsonb, null, array['A', 'C', 'D'], null, null, 'A, C, D', false, null, null),
  ('msd-senilai-009', 'sub-matematika-sd', 'top-matematika-sd-bilangan', 'st-matematika-sd-bilangan-rasional', 'con-matematika-sd-pecahan-senilai', 'mcma', 'Bernalar tentang gambar dua pita yang pecahannya senilai', 'lanjut', 'penalaran', 'html', '<p>Pita A dan Pita B sama panjang. Pita A dibagi menjadi 4 bagian sama besar dengan 3 bagian diwarnai. Pita B dibagi menjadi 12 bagian sama besar dengan 9 bagian diwarnai.</p>', '<p>Pernyataan yang benar tentang kedua pita itu adalah ....</p>', 'Pilih semua jawaban yang benar.', '<p>9/12 dibagi 3 pada pembilang dan penyebut menghasilkan 3/4, jadi kedua pecahan senilai dan panjang bagian berwarnanya sama. Pernyataan A dan C benar.</p><p>Pita yang sama panjang dibagi 12 menghasilkan potongan yang lebih pendek daripada dibagi 4, jadi pernyataan D benar dan pernyataan B keliru: potongan lebih banyak berarti setiap potongan lebih kecil.</p><p>Pernyataan E salah karena 9/12 masih dapat dibagi 3.</p>', '[{"key":"A","text":"<p>Panjang bagian berwarna kedua pita sama.</p>"},{"key":"B","text":"<p>Bagian berwarna Pita B lebih panjang karena potongannya lebih banyak.</p>","misconceptionId":"mis-msd-senilai-004"},{"key":"C","text":"<p>3/4 dan 9/12 adalah pecahan senilai.</p>"},{"key":"D","text":"<p>Setiap potongan Pita B lebih pendek daripada setiap potongan Pita A.</p>"},{"key":"E","text":"<p>Pecahan pada Pita B tidak dapat disederhanakan.</p>","misconceptionId":"mis-msd-senilai-003"}]'::jsonb, null, array['A', 'C', 'D'], null, null, 'A, C, D', true, 'Dua pita kertas mendatar sama panjang disejajarkan atas-bawah. Pita atas berlabel ''Pita A'' dibagi 4 kotak besar sama lebar, 3 kotak paling kiri diwarnai oranye. Pita bawah berlabel ''Pita B'' dibagi 12 kotak kecil sama lebar, 9 kotak paling kiri diwarnai oranye. Perhatikan panjang total kedua pita harus digambar persis sama.', 'svg'),
  ('msd-senilai-010', 'sub-matematika-sd', 'top-matematika-sd-bilangan', 'st-matematika-sd-bilangan-rasional', 'con-matematika-sd-pecahan-senilai', 'category', 'Bernalar menilai kebenaran pernyataan tentang pecahan senilai', 'lanjut', 'penalaran', 'html', '<p>Kelompok belajar menyusun lima pernyataan tentang pecahan senilai untuk saling diperiksa.</p>', '<p>Tentukan benar atau salah setiap pernyataan berikut.</p>', 'Tentukan kategori setiap pernyataan.', '<p>P1 benar: 5/8 dikalikan 3 pada kedua bagian menjadi 15/24.</p><p>P2 salah: 1/2 menjadi 4/5, dan 1/2 = 5/10 sedangkan 4/5 = 8/10, jadi nilainya berubah.</p><p>P3 benar: 12/18 dibagi 6 menjadi 2/3, dan 8/12 dibagi 4 juga menjadi 2/3.</p><p>P4 benar: pecahan senilai 1/3 berbentuk k/(3 × k), sehingga penyebutnya selalu kelipatan 3, misalnya 2/6, 3/9, 5/15.</p><p>P5 salah: membagi kedua bagian dengan bilangan yang sama justru cara menyederhanakan tanpa mengubah nilai, misalnya 6/8 = 3/4.</p>', null, null, null, '[{"key":"B","label":"Benar"},{"key":"S","label":"Salah"}]'::jsonb, '[{"id":"p1","text":"<p>5/8 senilai dengan 15/24.</p>","correctCategoryKey":"B"},{"id":"p2","text":"<p>Menambah 3 pada pembilang dan penyebut 1/2 menghasilkan pecahan yang senilai.</p>","correctCategoryKey":"S","misconceptionId":"mis-msd-senilai-001"},{"id":"p3","text":"<p>12/18 dan 8/12 adalah dua pecahan yang senilai.</p>","correctCategoryKey":"B"},{"id":"p4","text":"<p>Setiap pecahan yang senilai dengan 1/3 mempunyai penyebut kelipatan 3.</p>","correctCategoryKey":"B"},{"id":"p5","text":"<p>Membagi pembilang dan penyebut dengan bilangan yang sama membuat nilai pecahan berubah.</p>","correctCategoryKey":"S","misconceptionId":"mis-msd-senilai-002"}]'::jsonb, 'p1: B; p2: S; p3: B; p4: B; p5: S', false, null, null),
  ('msd-banding-001', 'sub-matematika-sd', 'top-matematika-sd-bilangan', 'st-matematika-sd-bilangan-rasional', 'con-matematika-sd-banding-urut-pecahan', 'single', 'Memahami perbandingan pecahan berpembilang sama', 'dasar', 'pemahaman', 'html', '<p>Dua kue bolu berukuran sama dipotong untuk dibagikan. Bolu pertama dipotong menjadi 5 bagian sama besar, bolu kedua dipotong menjadi 7 bagian sama besar. Rina mengambil 2 potong dari bolu pertama dan Sila mengambil 2 potong dari bolu kedua.</p>', '<p>Bagian bolu yang lebih banyak diambil dinyatakan oleh pecahan ....</p>', 'Pilih satu jawaban.', '<p>Bolu yang sama besar dipotong 5 menghasilkan potongan yang lebih besar daripada dipotong 7. Dengan banyak potong yang sama, bagian Rina lebih banyak.</p><p>Dengan penyebut sama: 2/5 = 14/35 dan 2/7 = 10/35. Karena 14/35 lebih dari 10/35, maka 2/5 lebih besar daripada 2/7.</p>', '[{"key":"A","text":"<p>2/5, milik Rina</p>"},{"key":"B","text":"<p>2/7, milik Sila</p>","misconceptionId":"mis-msd-banding-001"},{"key":"C","text":"<p>keduanya sama karena banyak potongnya sama</p>","misconceptionId":"mis-msd-banding-002"},{"key":"D","text":"<p>tidak dapat dibandingkan karena penyebutnya berbeda</p>","misconceptionId":"mis-msd-banding-004"}]'::jsonb, 'A', null, null, null, 'A', false, null, null),
  ('msd-banding-002', 'sub-matematika-sd', 'top-matematika-sd-bilangan', 'st-matematika-sd-bilangan-rasional', 'con-matematika-sd-banding-urut-pecahan', 'single', 'Memahami pengurutan tiga pecahan berpenyebut berbeda', 'dasar', 'pemahaman', 'html', '<p>Tiga botol air minum berukuran sama terisi sebagian: botol Merah 1/2 bagian, botol Biru 3/4 bagian, dan botol Hijau 2/3 bagian.</p>', '<p>Urutan isi botol dari yang paling sedikit adalah ....</p>', 'Pilih satu jawaban.', '<p>Samakan penyebut dengan 12: 1/2 = 6/12, 3/4 = 9/12, dan 2/3 = 8/12.</p><p>Urutan pembilang dari kecil: 6, 8, 9. Jadi urutannya 1/2, 2/3, 3/4.</p>', '[{"key":"A","text":"<p>1/2, 2/3, 3/4</p>"},{"key":"B","text":"<p>1/2, 3/4, 2/3</p>","misconceptionId":"mis-msd-banding-002"},{"key":"C","text":"<p>2/3, 1/2, 3/4</p>","misconceptionId":"mis-msd-banding-004"},{"key":"D","text":"<p>3/4, 2/3, 1/2</p>","misconceptionId":"mis-msd-banding-001"}]'::jsonb, 'A', null, null, null, 'A', false, null, null),
  ('msd-banding-003', 'sub-matematika-sd', 'top-matematika-sd-bilangan', 'st-matematika-sd-bilangan-rasional', 'con-matematika-sd-banding-urut-pecahan', 'single', 'Mengaplikasikan perbandingan pecahan pada capaian target', 'menengah', 'penerapan', 'html', '<p>Dua kelas mengumpulkan botol bekas untuk didaur ulang. Kelas A sudah mencapai 5/8 dari targetnya, sedangkan Kelas B sudah mencapai 7/12 dari targetnya. Target kedua kelas sama banyak.</p>', '<p>Kelas yang capaiannya lebih tinggi beserta alasannya adalah ....</p>', 'Pilih satu jawaban.', '<p>Kelipatan persekutuan terkecil dari 8 dan 12 adalah 24.</p><p>5/8 = 15/24 dan 7/12 = 14/24. Karena 15/24 lebih dari 14/24, capaian Kelas A lebih tinggi.</p><p>Selisih 15 dan 14 hanya 1/24 dari target, jadi keduanya memang berdekatan — tetapi tetap tidak sama.</p>', '[{"key":"A","text":"<p>Kelas A, karena 5/8 = 15/24 dan 7/12 = 14/24</p>"},{"key":"B","text":"<p>Kelas B, karena penyebut 12 lebih besar daripada 8</p>","misconceptionId":"mis-msd-banding-001"},{"key":"C","text":"<p>Kelas B, karena pembilang 7 lebih besar daripada 5</p>","misconceptionId":"mis-msd-banding-002"},{"key":"D","text":"<p>sama tinggi, karena selisih pembilang dan penyebutnya sama-sama 3 dan 5</p>","misconceptionId":"mis-msd-banding-003"}]'::jsonb, 'A', null, null, null, 'A', false, null, null),
  ('msd-banding-004', 'sub-matematika-sd', 'top-matematika-sd-bilangan', 'st-matematika-sd-bilangan-rasional', 'con-matematika-sd-banding-urut-pecahan', 'single', 'Mengaplikasikan pengurutan empat pecahan dari yang terbesar', 'menengah', 'penerapan', 'html', '<p>Empat pekerja melaporkan bagian pekerjaan yang sudah selesai: Ardi 3/4 bagian, Bayu 5/6 bagian, Cinta 7/12 bagian, dan Dewa 2/3 bagian.</p>', '<p>Urutan pekerja dari yang paling banyak menyelesaikan pekerjaan adalah ....</p>', 'Pilih satu jawaban.', '<p>Samakan penyebut dengan 12: 3/4 = 9/12, 5/6 = 10/12, 7/12 = 7/12, dan 2/3 = 8/12.</p><p>Urutan pembilang dari besar: 10, 9, 8, 7. Jadi urutannya Bayu, Ardi, Dewa, Cinta.</p>', '[{"key":"A","text":"<p>Bayu, Ardi, Dewa, Cinta</p>"},{"key":"B","text":"<p>Cinta, Dewa, Ardi, Bayu</p>","misconceptionId":"mis-msd-banding-002"},{"key":"C","text":"<p>Ardi, Bayu, Cinta, Dewa</p>","misconceptionId":"mis-msd-banding-004"},{"key":"D","text":"<p>Cinta, Bayu, Ardi, Dewa</p>","misconceptionId":"mis-msd-banding-001"}]'::jsonb, 'A', null, null, null, 'A', false, null, null),
  ('msd-banding-005', 'sub-matematika-sd', 'top-matematika-sd-bilangan', 'st-matematika-sd-bilangan-rasional', 'con-matematika-sd-banding-urut-pecahan', 'single', 'Mengaplikasikan perbandingan untuk mencari pecahan di antara dua pecahan', 'menengah', 'penerapan', 'html', '<p>Pada garis bilangan, Bu Wati menandai dua titik: 1/3 dan 1/2. Siswa diminta menempelkan satu kartu pecahan tepat di antara kedua tanda itu.</p>', '<p>Kartu yang tepat ditempel di antara 1/3 dan 1/2 adalah ....</p>', 'Pilih satu jawaban.', '<p>Samakan penyebut dengan 30: 1/3 = 10/30 dan 1/2 = 15/30.</p><p>Periksa tiap kartu: 1/4 = 7,5/30 (terlalu kecil), 2/5 = 12/30 (berada di antara), 3/5 = 18/30 (terlalu besar), dan 1/6 = 5/30 (terlalu kecil).</p><p>Jadi kartu 2/5 yang tepat.</p>', '[{"key":"A","text":"<p>1/4</p>","misconceptionId":"mis-msd-banding-001"},{"key":"B","text":"<p>2/5</p>"},{"key":"C","text":"<p>3/5</p>","misconceptionId":"mis-msd-banding-002"},{"key":"D","text":"<p>1/6</p>","misconceptionId":"mis-msd-banding-001"}]'::jsonb, 'B', null, null, null, 'B', false, null, null),
  ('msd-banding-006', 'sub-matematika-sd', 'top-matematika-sd-bilangan', 'st-matematika-sd-bilangan-rasional', 'con-matematika-sd-banding-urut-pecahan', 'single', 'Bernalar dengan patokan setengah untuk memilih pecahan terdekat', 'lanjut', 'penalaran', 'html', '<p>Empat regu mengisi tangki air sampai bagian tertentu: Regu I 5/9 bagian, Regu II 4/7 bagian, Regu III 7/15 bagian, dan Regu IV 3/8 bagian. Panitia mencari regu yang isinya paling dekat dengan setengah tangki.</p>', '<p>Regu yang isinya paling dekat dengan 1/2 adalah ....</p>', 'Pilih satu jawaban.', '<p>Setengah dari penyebut menjadi patokan pembilang. Hitung jarak setiap pecahan ke 1/2:</p><ul><li>5/9: setengah dari 9 adalah 4,5, selisih pembilang 0,5 bagian dari 9, yaitu 1/18</li><li>4/7: setengah dari 7 adalah 3,5, selisihnya 1/14</li><li>7/15: setengah dari 15 adalah 7,5, selisihnya 1/30</li><li>3/8: setengah dari 8 adalah 4, selisihnya 1/8</li></ul><p>Jarak terkecil adalah 1/30, yaitu Regu III. Perhatikan bahwa Regu III berada sedikit di bawah setengah, sedangkan Regu I dan II sedikit di atasnya — yang ditanyakan jaraknya, bukan besarnya.</p>', '[{"key":"A","text":"<p>Regu I</p>","misconceptionId":"mis-msd-banding-003"},{"key":"B","text":"<p>Regu II</p>","misconceptionId":"mis-msd-banding-002"},{"key":"C","text":"<p>Regu III</p>"},{"key":"D","text":"<p>Regu IV</p>","misconceptionId":"mis-msd-banding-001"}]'::jsonb, 'C', null, null, null, 'C', false, null, null),
  ('msd-banding-007', 'sub-matematika-sd', 'top-matematika-sd-bilangan', 'st-matematika-sd-bilangan-rasional', 'con-matematika-sd-banding-urut-pecahan', 'single', 'Bernalar menilai alasan yang dipakai saat membandingkan pecahan', 'lanjut', 'penalaran', 'html', '<p>Dinda berkata, “3/5 lebih besar daripada 5/8, sebab selisih pembilang dan penyebut 3/5 hanya 2, sedangkan pada 5/8 selisihnya 3.”</p>', '<p>Tanggapan yang tepat terhadap pendapat Dinda adalah ....</p>', 'Pilih satu jawaban.', '<p>Samakan penyebut dengan 40: 3/5 = 24/40 dan 5/8 = 25/40. Ternyata 5/8 lebih besar, jadi kesimpulan Dinda salah.</p><p>Selisih pembilang dan penyebut bukan ukuran nilai pecahan. Contoh penyangkal lain: 1/2 dan 8/9 sama-sama berselisih ganjil, tetapi nilainya jauh berbeda.</p><p>Pilihan C juga tidak dapat dibenarkan sebagai aturan umum, sebab 7/8 berpenyebut lebih besar daripada 1/2 namun nilainya lebih besar.</p>', '[{"key":"A","text":"<p>Benar, karena selisih yang lebih kecil menandakan pecahan yang lebih besar.</p>","misconceptionId":"mis-msd-banding-003"},{"key":"B","text":"<p>Salah, karena 3/5 = 24/40 dan 5/8 = 25/40 sehingga 5/8 justru lebih besar.</p>"},{"key":"C","text":"<p>Salah, karena pecahan berpenyebut lebih besar selalu lebih kecil nilainya.</p>","misconceptionId":"mis-msd-banding-001"},{"key":"D","text":"<p>Benar, karena pembilang 3 dan 5 lebih kecil daripada 5 dan 8.</p>","misconceptionId":"mis-msd-banding-004"}]'::jsonb, 'B', null, null, null, 'B', false, null, null),
  ('msd-banding-008', 'sub-matematika-sd', 'top-matematika-sd-bilangan', 'st-matematika-sd-bilangan-rasional', 'con-matematika-sd-banding-urut-pecahan', 'mcma', 'Mengaplikasikan perbandingan untuk menyaring pecahan lebih dari 2/3', 'menengah', 'penerapan', 'html', '<p>Sebuah lomba menetapkan syarat kelulusan: bagian soal yang dijawab benar harus lebih dari 2/3. Berikut capaian beberapa peserta.</p>', '<p>Capaian yang memenuhi syarat kelulusan adalah ....</p>', 'Pilih semua jawaban yang benar.', '<p>Bandingkan tiap pecahan dengan 2/3 memakai penyebut yang sama:</p><ul><li>5/6 dan 2/3 = 4/6 → 5/6 lebih besar</li><li>3/5 dan 2/3: penyebut 15 → 9/15 dan 10/15 → 3/5 lebih kecil</li><li>7/9 dan 2/3 = 6/9 → 7/9 lebih besar</li><li>5/8 dan 2/3: penyebut 24 → 15/24 dan 16/24 → 5/8 lebih kecil</li><li>11/15 dan 2/3 = 10/15 → 11/15 lebih besar</li></ul><p>Jadi yang lulus adalah 5/6, 7/9, dan 11/15.</p>', '[{"key":"A","text":"<p>5/6</p>"},{"key":"B","text":"<p>3/5</p>","misconceptionId":"mis-msd-banding-004"},{"key":"C","text":"<p>7/9</p>"},{"key":"D","text":"<p>5/8</p>","misconceptionId":"mis-msd-banding-003"},{"key":"E","text":"<p>11/15</p>"}]'::jsonb, null, array['A', 'C', 'E'], null, null, 'A, C, E', false, null, null),
  ('msd-banding-009', 'sub-matematika-sd', 'top-matematika-sd-bilangan', 'st-matematika-sd-bilangan-rasional', 'con-matematika-sd-banding-urut-pecahan', 'mcma', 'Bernalar tentang aturan membandingkan dan mengurutkan pecahan', 'lanjut', 'penalaran', 'html', '<p>Sekelompok siswa menuliskan kesimpulan mereka setelah belajar membandingkan pecahan. Guru meminta mereka menandai kesimpulan yang dapat dipertanggungjawabkan.</p>', '<p>Kesimpulan yang benar adalah ....</p>', 'Pilih semua jawaban yang benar.', '<p>A benar: dengan pembilang sama, penyebut terkecil memberi potongan terbesar, jadi 1/4 paling besar.</p><p>B salah, justru sebaliknya — inilah kekeliruan yang sering terjadi. Contoh: 1/8 lebih kecil daripada 1/3.</p><p>C benar: setengah dari 9 adalah 4,5 sedangkan pembilangnya 4, jadi 4/9 kurang dari 1/2.</p><p>D benar: 10/16 dibagi 2 pada kedua bagiannya menjadi 5/8.</p><p>E salah: 3/10 berpembilang lebih besar daripada 2/3, tetapi nilainya jauh lebih kecil.</p>', '[{"key":"A","text":"<p>Di antara 1/4, 1/5, dan 1/6, yang terbesar adalah 1/4.</p>"},{"key":"B","text":"<p>Bila pembilangnya sama, semakin besar penyebutnya semakin besar nilai pecahannya.</p>","misconceptionId":"mis-msd-banding-001"},{"key":"C","text":"<p>4/9 lebih kecil daripada 1/2.</p>"},{"key":"D","text":"<p>5/8 dan 10/16 bernilai sama karena 10/16 disederhanakan menjadi 5/8.</p>"},{"key":"E","text":"<p>Pecahan yang pembilangnya lebih besar selalu bernilai lebih besar.</p>","misconceptionId":"mis-msd-banding-002"}]'::jsonb, null, array['A', 'C', 'D'], null, null, 'A, C, D', false, null, null),
  ('msd-banding-010', 'sub-matematika-sd', 'top-matematika-sd-bilangan', 'st-matematika-sd-bilangan-rasional', 'con-matematika-sd-banding-urut-pecahan', 'category', 'Bernalar menilai kebenaran pernyataan perbandingan pecahan', 'lanjut', 'penalaran', 'html', '<p>Lima pernyataan hasil diskusi kelas ditulis di papan untuk diperiksa bersama.</p>', '<p>Tentukan benar atau salah setiap pernyataan berikut.</p>', 'Tentukan kategori setiap pernyataan.', '<p>P1 salah: dengan penyebut 72, 7/8 = 63/72 dan 8/9 = 64/72, jadi 8/9 yang lebih besar.</p><p>P2 benar: dengan penyebut 70, 2/7 = 20/70 dan 3/10 = 21/70.</p><p>P3 benar: dengan penyebut 40, 3/8 = 15/40, 2/5 = 16/40, dan 1/2 = 20/40.</p><p>P4 benar: 9/12 dibagi 3 menjadi 3/4 dan 6/8 dibagi 2 juga menjadi 3/4.</p><p>P5 salah: 5/6 berjarak 1/6 dari 1, sedangkan 7/8 hanya berjarak 1/8. Karena 1/8 lebih kecil daripada 1/6, justru 7/8 yang lebih dekat ke 1.</p>', null, null, null, '[{"key":"B","label":"Benar"},{"key":"S","label":"Salah"}]'::jsonb, '[{"id":"p1","text":"<p>7/8 lebih besar daripada 8/9.</p>","correctCategoryKey":"S","misconceptionId":"mis-msd-banding-003"},{"id":"p2","text":"<p>2/7 lebih kecil daripada 3/10.</p>","correctCategoryKey":"B"},{"id":"p3","text":"<p>Urutan naik yang benar adalah 3/8, 2/5, 1/2.</p>","correctCategoryKey":"B"},{"id":"p4","text":"<p>9/12 dan 6/8 bernilai sama.</p>","correctCategoryKey":"B"},{"id":"p5","text":"<p>Di antara 5/6 dan 7/8, yang lebih dekat ke 1 adalah 5/6.</p>","correctCategoryKey":"S","misconceptionId":"mis-msd-banding-001"}]'::jsonb, 'p1: S; p2: B; p3: B; p4: B; p5: S', false, null, null),
  ('msd-relasi-001', 'sub-matematika-sd', 'top-matematika-sd-bilangan', 'st-matematika-sd-bilangan-rasional', 'con-matematika-sd-relasi-bentuk-pecahan', 'single', 'Memahami bentuk desimal dan persen dari suatu pecahan', 'dasar', 'pemahaman', 'html', '<p>Pada laporan panen, tertulis bahwa 3/4 bagian lahan sudah dipanen. Petugas ingin menuliskan angka itu dalam bentuk desimal dan persen pada papan pengumuman.</p>', '<p>Bentuk desimal dan persen dari 3/4 adalah ....</p>', 'Pilih satu jawaban.', '<p>3/4 dikalikan 25 pada pembilang dan penyebut menjadi 75/100, yaitu 0,75.</p><p>Karena persen berarti per seratus, 75/100 sama dengan 75%.</p><p>Pilihan C adalah bagian yang belum dipanen, bukan yang sudah.</p>', '[{"key":"A","text":"<p>0,34 dan 34%</p>","misconceptionId":"mis-msd-relasi-001"},{"key":"B","text":"<p>7,5 dan 75%</p>","misconceptionId":"mis-msd-relasi-002"},{"key":"C","text":"<p>0,25 dan 25%</p>","misconceptionId":"mis-msd-relasi-004"},{"key":"D","text":"<p>0,75 dan 75%</p>"}]'::jsonb, 'D', null, null, null, 'D', false, null, null),
  ('msd-relasi-002', 'sub-matematika-sd', 'top-matematika-sd-bilangan', 'st-matematika-sd-bilangan-rasional', 'con-matematika-sd-relasi-bentuk-pecahan', 'single', 'Memahami bentuk pecahan sederhana dan persen dari suatu desimal', 'dasar', 'pemahaman', 'html', '<p>Alat ukur digital menunjukkan bahwa 0,4 bagian tangki sudah terisi. Angka itu akan ditulis ulang sebagai pecahan paling sederhana dan sebagai persen.</p>', '<p>Bentuk pecahan paling sederhana dan persen dari 0,4 adalah ....</p>', 'Pilih satu jawaban.', '<p>0,4 berarti 4 persepuluhan, yaitu 4/10. Pembilang dan penyebut dibagi 2 menjadi 2/5.</p><p>Untuk persen: 4/10 = 40/100 = 40%.</p><p>Pilihan B muncul bila koma sekadar dihapus tanpa mengalikan 100.</p>', '[{"key":"A","text":"<p>1/4 dan 25%</p>","misconceptionId":"mis-msd-relasi-004"},{"key":"B","text":"<p>1/40 dan 4%</p>","misconceptionId":"mis-msd-relasi-002"},{"key":"C","text":"<p>4/5 dan 80%</p>","misconceptionId":"mis-msd-relasi-005"},{"key":"D","text":"<p>2/5 dan 40%</p>"}]'::jsonb, 'D', null, null, null, 'D', false, null, null),
  ('msd-relasi-003', 'sub-matematika-sd', 'top-matematika-sd-bilangan', 'st-matematika-sd-bilangan-rasional', 'con-matematika-sd-relasi-bentuk-pecahan', 'single', 'Mengaplikasikan perubahan pecahan menjadi persen berkoma', 'menengah', 'penerapan', 'html', '<p>Sebuah toko menuliskan potongan harga sebagai pecahan, yaitu 3/8 dari harga semula. Pemilik toko ingin memasang spanduk dengan angka persen agar lebih mudah dibaca pembeli.</p>', '<p>Potongan harga itu setara dengan ....</p>', 'Pilih satu jawaban.', '<p>3 dibagi 8 sama dengan 0,375. Dikalikan 100 menjadi 37,5%.</p><p>Cara lain: 3/8 dikalikan 12,5 pada pembilang dan penyebut menghasilkan 37,5/100, yaitu 37,5%.</p><p>Pilihan D didapat dengan menempelkan angka 3 dan 8, yang tidak ada kaitannya dengan nilai pecahannya.</p>', '[{"key":"A","text":"<p>3,8%</p>","misconceptionId":"mis-msd-relasi-002"},{"key":"B","text":"<p>24%</p>","misconceptionId":"mis-msd-relasi-004"},{"key":"C","text":"<p>37,5%</p>"},{"key":"D","text":"<p>38%</p>","misconceptionId":"mis-msd-relasi-001"}]'::jsonb, 'C', null, null, null, 'C', false, null, null),
  ('msd-relasi-004', 'sub-matematika-sd', 'top-matematika-sd-bilangan', 'st-matematika-sd-bilangan-rasional', 'con-matematika-sd-relasi-bentuk-pecahan', 'single', 'Mengaplikasikan penyeragaman bentuk untuk mengurutkan besaran', 'menengah', 'penerapan', 'html', '<p>Tiga sekolah melaporkan bagian siswa yang mengikuti kegiatan literasi dengan bentuk penulisan yang berbeda:</p><ul><li>Sekolah Melati: 0,7 bagian</li><li>Sekolah Nusa: 3/5 bagian</li><li>Sekolah Oryza: 65% bagian</li></ul>', '<p>Urutan sekolah dari bagian peserta yang paling sedikit adalah ....</p>', 'Pilih satu jawaban.', '<p>Ubah semuanya menjadi desimal: 0,7 tetap 0,7; 3/5 = 0,6; dan 65% = 0,65.</p><p>Urutan dari kecil: 0,6 lalu 0,65 lalu 0,7, yaitu Nusa, Oryza, Melati.</p><p>Pilihan D keliru karena angka 65 tampak besar padahal nilainya 0,65.</p>', '[{"key":"A","text":"<p>Nusa, Oryza, Melati</p>"},{"key":"B","text":"<p>Melati, Nusa, Oryza</p>","misconceptionId":"mis-msd-relasi-004"},{"key":"C","text":"<p>Nusa, Melati, Oryza</p>","misconceptionId":"mis-msd-relasi-005"},{"key":"D","text":"<p>Oryza, Nusa, Melati</p>","misconceptionId":"mis-msd-relasi-004"}]'::jsonb, 'A', null, null, null, 'A', false, null, null),
  ('msd-relasi-005', 'sub-matematika-sd', 'top-matematika-sd-bilangan', 'st-matematika-sd-bilangan-rasional', 'con-matematika-sd-relasi-bentuk-pecahan', 'single', 'Mengaplikasikan perubahan hasil pekerjaan menjadi persen', 'menengah', 'penerapan', 'html', '<p>Ulangan matematika berisi 24 soal. Nadia menjawab benar 18 soal. Guru menuliskan hasilnya dalam bentuk persen di buku nilai.</p>', '<p>Persentase jawaban benar Nadia adalah ....</p>', 'Pilih satu jawaban.', '<p>Bagian jawaban benar = 18/24. Pembilang dan penyebut dibagi 6 menjadi 3/4.</p><p>3/4 = 75/100 = 75%.</p><p>Pilihan A adalah 15/24, bukan 18/24, dan pilihan D adalah 19,2 dari 24 soal.</p>', '[{"key":"A","text":"<p>62,5%</p>","misconceptionId":"mis-msd-relasi-004"},{"key":"B","text":"<p>70%</p>","misconceptionId":"mis-msd-relasi-001"},{"key":"C","text":"<p>75%</p>"},{"key":"D","text":"<p>80%</p>","misconceptionId":"mis-msd-relasi-005"}]'::jsonb, 'C', null, null, null, 'C', false, null, null),
  ('msd-relasi-006', 'sub-matematika-sd', 'top-matematika-sd-bilangan', 'st-matematika-sd-bilangan-rasional', 'con-matematika-sd-relasi-bentuk-pecahan', 'single', 'Bernalar memilih besaran terbesar dari bentuk yang berbeda-beda', 'lanjut', 'penalaran', 'html', '<p>Empat pedagang memasang potongan harga dengan bentuk penulisan yang berbeda:</p><ul><li>Pedagang I: 5/8 dari harga</li><li>Pedagang II: 0,62 dari harga</li><li>Pedagang III: 63% dari harga</li><li>Pedagang IV: 3/5 dari harga</li></ul>', '<p>Potongan harga terbesar diberikan oleh ....</p>', 'Pilih satu jawaban.', '<p>Ubah semuanya menjadi desimal: 5/8 = 0,625; 0,62 tetap 0,62; 63% = 0,63; dan 3/5 = 0,6.</p><p>Nilai terbesar adalah 0,63, yaitu Pedagang III.</p><p>Perhatikan bahwa 5/8 dan 63% hanya berselisih 0,005, sehingga menebak tanpa menyeragamkan bentuk mudah keliru.</p>', '[{"key":"A","text":"<p>Pedagang I</p>","misconceptionId":"mis-msd-relasi-004"},{"key":"B","text":"<p>Pedagang II</p>","misconceptionId":"mis-msd-relasi-003"},{"key":"C","text":"<p>Pedagang III</p>"},{"key":"D","text":"<p>Pedagang IV</p>","misconceptionId":"mis-msd-relasi-005"}]'::jsonb, 'C', null, null, null, 'C', false, null, null),
  ('msd-relasi-007', 'sub-matematika-sd', 'top-matematika-sd-bilangan', 'st-matematika-sd-bilangan-rasional', 'con-matematika-sd-relasi-bentuk-pecahan', 'single', 'Bernalar menilai kekeliruan mengubah desimal menjadi persen', 'lanjut', 'penalaran', 'html', '<p>Rani menulis di buku catatannya, “0,5 sama dengan 5%, karena tanda komanya cukup dihilangkan.”</p>', '<p>Tanggapan yang tepat terhadap catatan Rani adalah ....</p>', 'Pilih satu jawaban.', '<p>0,5 berarti 5 persepuluhan, yaitu 5/10 = 50/100 = 50%.</p><p>Sedangkan 5% berarti 5/100 = 0,05, sepuluh kali lebih kecil. Jadi catatan Rani salah.</p><p>Aturan yang benar: desimal dikalikan 100 untuk menjadi persen, dan persen dibagi 100 untuk menjadi desimal.</p>', '[{"key":"A","text":"<p>Benar, karena angka di belakang koma langsung menjadi angka persen.</p>","misconceptionId":"mis-msd-relasi-002"},{"key":"B","text":"<p>Benar, karena 5% dan 0,5 sama-sama bernilai setengah.</p>","misconceptionId":"mis-msd-relasi-003"},{"key":"C","text":"<p>Salah, karena 0,5 tidak dapat dinyatakan dalam bentuk persen.</p>","misconceptionId":"mis-msd-relasi-005"},{"key":"D","text":"<p>Salah, karena 0,5 sama dengan 50/100 sehingga setara 50%.</p>"}]'::jsonb, 'D', null, null, null, 'D', false, null, null),
  ('msd-relasi-008', 'sub-matematika-sd', 'top-matematika-sd-bilangan', 'st-matematika-sd-bilangan-rasional', 'con-matematika-sd-relasi-bentuk-pecahan', 'mcma', 'Mengaplikasikan kesetaraan bentuk untuk menyaring nilai yang sama', 'menengah', 'penerapan', 'html', '<p>Guru menempel beberapa kartu bilangan di papan. Kartu yang nilainya sama dengan 0,25 akan dikumpulkan dalam satu kotak.</p>', '<p>Kartu yang masuk kotak itu adalah ....</p>', 'Pilih semua jawaban yang benar.', '<p>0,25 berarti 25 perseratusan, yaitu 25/100. Disederhanakan menjadi 1/4, dan dalam bentuk persen menjadi 25%. Ketiganya senilai.</p><p>2,5% = 0,025, sepuluh kali lebih kecil daripada 0,25.</p><p>1/25 = 4/100 = 0,04, jadi bukan pasangan yang sama.</p>', '[{"key":"A","text":"<p>1/4</p>"},{"key":"B","text":"<p>25%</p>"},{"key":"C","text":"<p>25/100</p>"},{"key":"D","text":"<p>2,5%</p>","misconceptionId":"mis-msd-relasi-002"},{"key":"E","text":"<p>1/25</p>","misconceptionId":"mis-msd-relasi-001"}]'::jsonb, null, array['A', 'B', 'C'], null, null, 'A, B, C', false, null, null),
  ('msd-relasi-009', 'sub-matematika-sd', 'top-matematika-sd-bilangan', 'st-matematika-sd-bilangan-rasional', 'con-matematika-sd-relasi-bentuk-pecahan', 'mcma', 'Bernalar tentang kesetaraan antarbentuk bilangan', 'lanjut', 'penalaran', 'html', '<p>Lima pernyataan hasil kerja kelompok dikumpulkan untuk diperiksa ketepatannya.</p>', '<p>Pernyataan yang benar adalah ....</p>', 'Pilih semua jawaban yang benar.', '<p>A benar: 7/10 = 70/100 = 70%.</p><p>B salah: 1 dibagi 3 menghasilkan 0,333… sehingga persennya 33,33…%, bukan tepat 33%.</p><p>C benar: 0,05 = 5/100 = 5%.</p><p>D benar: 0,8 = 8/10, dibagi 2 menjadi 4/5.</p><p>E salah: 3/4 = 75%, bukan 34%. Angka 34 hanya menempelkan pembilang dan penyebut.</p>', '[{"key":"A","text":"<p>7/10 setara dengan 70%.</p>"},{"key":"B","text":"<p>1/3 setara dengan tepat 33%.</p>","misconceptionId":"mis-msd-relasi-001"},{"key":"C","text":"<p>0,05 setara dengan 5%.</p>"},{"key":"D","text":"<p>0,8 setara dengan 4/5.</p>"},{"key":"E","text":"<p>3/4 setara dengan 34%.</p>","misconceptionId":"mis-msd-relasi-001"}]'::jsonb, null, array['A', 'C', 'D'], null, null, 'A, C, D', false, null, null),
  ('msd-relasi-010', 'sub-matematika-sd', 'top-matematika-sd-bilangan', 'st-matematika-sd-bilangan-rasional', 'con-matematika-sd-relasi-bentuk-pecahan', 'category', 'Bernalar menilai pernyataan tentang relasi pecahan, desimal, dan persen', 'lanjut', 'penalaran', 'html', '<p>Papan pengumuman kelas memuat lima catatan tentang bentuk bilangan. Kelas diminta memeriksa satu per satu.</p>', '<p>Tentukan benar atau salah setiap pernyataan berikut.</p>', 'Tentukan kategori setiap pernyataan.', '<p>P1 benar: 9/20 dikalikan 5 pada kedua bagian menjadi 45/100 = 45%.</p><p>P2 salah: 0,08 berarti 8 perseratusan, yaitu 8/100 = 2/25. Sedangkan 8/10 sama dengan 0,8.</p><p>P3 benar: 1 dibagi 8 sama dengan 0,125, yaitu 12,5%.</p><p>P4 salah: bentuk penulisan tidak mengubah nilai. Misalnya 45% dan 9/20 adalah bilangan yang sama.</p><p>P5 benar: 2/25 dikalikan 4 pada kedua bagian menjadi 8/100 = 0,08.</p>', null, null, null, '[{"key":"B","label":"Benar"},{"key":"S","label":"Salah"}]'::jsonb, '[{"id":"p1","text":"<p>9/20 setara dengan 45%.</p>","correctCategoryKey":"B"},{"id":"p2","text":"<p>0,08 setara dengan 8/10.</p>","correctCategoryKey":"S","misconceptionId":"mis-msd-relasi-003"},{"id":"p3","text":"<p>1/8 setara dengan 12,5%.</p>","correctCategoryKey":"B"},{"id":"p4","text":"<p>Bentuk persen selalu bernilai lebih besar daripada bentuk pecahan yang setara, karena angkanya lebih besar.</p>","correctCategoryKey":"S","misconceptionId":"mis-msd-relasi-005"},{"id":"p5","text":"<p>2/25 setara dengan 0,08.</p>","correctCategoryKey":"B"}]'::jsonb, 'p1: B; p2: S; p3: B; p4: S; p5: B', false, null, null),
  ('msd-cacah-001', 'sub-matematika-sd', 'top-matematika-sd-bilangan', 'st-matematika-sd-bilangan-rasional', 'con-matematika-sd-operasi-bilangan-cacah', 'single', 'Memahami pengurangan bilangan cacah empat angka', 'dasar', 'pemahaman', 'html', '<p>Perpustakaan sekolah mencatat 4.083 buku di daftar induk. Pada akhir semester, 1.756 buku sedang dipinjam siswa.</p>', '<p>Banyak buku yang masih berada di rak adalah ....</p>', 'Pilih satu jawaban.', '<p>Buku di rak = 4.083 − 1.756 = 2.327.</p><p>Periksa dengan penjumlahan: 2.327 + 1.756 = 4.083, jadi hasilnya benar.</p><p>Pilihan D didapat dengan menjumlahkan, padahal buku yang dipinjam justru mengurangi isi rak.</p>', '[{"key":"A","text":"<p>2.227 buku</p>","misconceptionId":"mis-msd-cacah-003"},{"key":"B","text":"<p>2.327 buku</p>"},{"key":"C","text":"<p>2.337 buku</p>","misconceptionId":"mis-msd-cacah-003"},{"key":"D","text":"<p>5.839 buku</p>","misconceptionId":"mis-msd-cacah-005"}]'::jsonb, 'B', null, null, null, 'B', false, null, null),
  ('msd-cacah-002', 'sub-matematika-sd', 'top-matematika-sd-bilangan', 'st-matematika-sd-bilangan-rasional', 'con-matematika-sd-operasi-bilangan-cacah', 'single', 'Memahami urutan pengerjaan operasi hitung', 'dasar', 'pemahaman', 'html', '<p>Ali membeli 1 buku tulis berharga Rp18.000 dan 6 pulpen yang masing-masing berharga Rp4.000.</p>', '<p>Uang yang harus dibayar Ali dihitung dengan 18.000 + 6 × 4.000, yaitu ....</p>', 'Pilih satu jawaban.', '<p>Perkalian dikerjakan lebih dahulu: 6 × 4.000 = 24.000.</p><p>Lalu dijumlahkan: 18.000 + 24.000 = 42.000.</p><p>Pilihan B muncul bila dikerjakan dari kiri, yaitu (18.000 + 6) × 4.000 — hasilnya tidak masuk akal untuk harga tujuh barang.</p>', '[{"key":"A","text":"<p>Rp42.000</p>"},{"key":"B","text":"<p>Rp96.000</p>","misconceptionId":"mis-msd-cacah-001"},{"key":"C","text":"<p>Rp28.000</p>","misconceptionId":"mis-msd-cacah-005"},{"key":"D","text":"<p>Rp72.000</p>","misconceptionId":"mis-msd-cacah-005"}]'::jsonb, 'A', null, null, null, 'A', false, null, null),
  ('msd-cacah-003', 'sub-matematika-sd', 'top-matematika-sd-bilangan', 'st-matematika-sd-bilangan-rasional', 'con-matematika-sd-operasi-bilangan-cacah', 'single', 'Mengaplikasikan perkalian dan pembagian pada masalah dua langkah', 'menengah', 'penerapan', 'html', '<p>Panitia kegiatan membeli 8 dus air mineral gelas. Setiap dus berisi 48 gelas. Seluruh gelas itu dibagikan rata kepada 12 kelas.</p>', '<p>Banyak gelas yang diterima setiap kelas adalah ....</p>', 'Pilih satu jawaban.', '<p>Seluruh gelas = 8 × 48 = 384.</p><p>Dibagi 12 kelas: 384 : 12 = 32.</p><p>Periksa: 32 × 12 = 384, sesuai. Pilihan D adalah jumlah seluruh gelas, belum dibagi ke kelas.</p>', '[{"key":"A","text":"<p>28 gelas</p>","misconceptionId":"mis-msd-cacah-003"},{"key":"B","text":"<p>32 gelas</p>"},{"key":"C","text":"<p>36 gelas</p>","misconceptionId":"mis-msd-cacah-005"},{"key":"D","text":"<p>384 gelas</p>","misconceptionId":"mis-msd-cacah-005"}]'::jsonb, 'B', null, null, null, 'B', false, null, null),
  ('msd-cacah-004', 'sub-matematika-sd', 'top-matematika-sd-bilangan', 'st-matematika-sd-bilangan-rasional', 'con-matematika-sd-operasi-bilangan-cacah', 'single', 'Mengaplikasikan penafsiran sisa pada pembagian', 'menengah', 'penerapan', 'html', '<p>Sebanyak 250 siswa akan berangkat studi wisata. Setiap bus hanya boleh mengangkut 40 siswa. Semua siswa harus terangkut dalam satu kali perjalanan.</p>', '<p>Banyak bus paling sedikit yang harus disewa adalah ....</p>', 'Pilih satu jawaban.', '<p>250 : 40 = 6 sisa 10. Enam bus hanya memuat 6 × 40 = 240 siswa.</p><p>Masih ada 10 siswa yang harus terangkut, sehingga diperlukan satu bus tambahan. Jadi 7 bus.</p><p>Sisa pembagian tidak boleh dibuang pada masalah seperti ini, karena setiap siswa tetap harus mendapat tempat.</p>', '[{"key":"A","text":"<p>6 bus</p>","misconceptionId":"mis-msd-cacah-002"},{"key":"B","text":"<p>6 bus dan 10 siswa berjalan kaki</p>","misconceptionId":"mis-msd-cacah-002"},{"key":"C","text":"<p>7 bus</p>"},{"key":"D","text":"<p>10 bus</p>","misconceptionId":"mis-msd-cacah-005"}]'::jsonb, 'C', null, null, null, 'C', false, null, null),
  ('msd-cacah-005', 'sub-matematika-sd', 'top-matematika-sd-bilangan', 'st-matematika-sd-bilangan-rasional', 'con-matematika-sd-operasi-bilangan-cacah', 'single', 'Mengaplikasikan pengurangan berturut pada masalah uang', 'menengah', 'penerapan', 'html', '<p>Tabungan Rio berisi Rp1.500.000. Ia membeli sepeda berharga Rp875.000 dan sebuah helm berharga Rp135.000 dari tabungan itu.</p>', '<p>Sisa tabungan Rio adalah ....</p>', 'Pilih satu jawaban.', '<p>Seluruh pengeluaran = 875.000 + 135.000 = 1.010.000.</p><p>Sisa tabungan = 1.500.000 − 1.010.000 = 490.000.</p><p>Pilihan D adalah jumlah pengeluarannya, bukan sisa tabungan.</p>', '[{"key":"A","text":"<p>Rp490.000</p>"},{"key":"B","text":"<p>Rp500.000</p>","misconceptionId":"mis-msd-cacah-003"},{"key":"C","text":"<p>Rp590.000</p>","misconceptionId":"mis-msd-cacah-003"},{"key":"D","text":"<p>Rp1.010.000</p>","misconceptionId":"mis-msd-cacah-005"}]'::jsonb, 'A', null, null, null, 'A', false, null, null),
  ('msd-cacah-006', 'sub-matematika-sd', 'top-matematika-sd-bilangan', 'st-matematika-sd-bilangan-rasional', 'con-matematika-sd-operasi-bilangan-cacah', 'single', 'Bernalar menaksir hasil perkalian tanpa menghitung tepat', 'lanjut', 'penalaran', 'html', '<p>Bu Guru menuliskan 47 × 29 di papan, lalu meminta siswa menyimpulkan sesuatu tentang hasilnya tanpa menghitung sampai selesai.</p>', '<p>Pernyataan yang pasti benar tentang hasil 47 × 29 adalah ....</p>', 'Pilih satu jawaban.', '<p>Karena 47 kurang dari 50 dan 29 kurang dari 30, maka 47 × 29 pasti kurang dari 50 × 30 = 1.500.</p><p>Sekaligus, 47 × 29 lebih dari 40 × 20 = 800, jadi hasilnya berada antara 800 dan 1.500 — pilihan D tersingkir.</p><p>Hasil tepatnya 1.363, yang memang berada di antara kedua taksiran itu.</p>', '[{"key":"A","text":"<p>hasilnya lebih dari 1.500</p>","misconceptionId":"mis-msd-cacah-001"},{"key":"B","text":"<p>hasilnya kurang dari 1.500</p>"},{"key":"C","text":"<p>hasilnya lebih dari 2.000</p>","misconceptionId":"mis-msd-cacah-005"},{"key":"D","text":"<p>hasilnya kurang dari 1.000</p>","misconceptionId":"mis-msd-cacah-003"}]'::jsonb, 'B', null, null, null, 'B', false, null, null),
  ('msd-cacah-007', 'sub-matematika-sd', 'top-matematika-sd-bilangan', 'st-matematika-sd-bilangan-rasional', 'con-matematika-sd-operasi-bilangan-cacah', 'single', 'Bernalar menilai sifat urutan pada pembagian berturut', 'lanjut', 'penalaran', 'html', '<p>Dito berpendapat, “Pembagian boleh dikerjakan dari mana saja, jadi 120 : 6 : 2 sama nilainya dengan 120 : (6 : 2).”</p>', '<p>Tanggapan yang tepat terhadap pendapat Dito adalah ....</p>', 'Pilih satu jawaban.', '<p>Tanpa tanda kurung, pembagian dikerjakan dari kiri: 120 : 6 = 20, lalu 20 : 2 = 10.</p><p>Dengan tanda kurung: 6 : 2 = 3, lalu 120 : 3 = 40.</p><p>Hasilnya berbeda, jadi pembagian tidak dapat ditukar urutannya. Sifat itu hanya berlaku pada penjumlahan dan perkalian.</p>', '[{"key":"A","text":"<p>Benar, karena bilangan yang dibagi tetap 120.</p>","misconceptionId":"mis-msd-cacah-004"},{"key":"B","text":"<p>Salah, karena 120 : 6 : 2 = 10 sedangkan 120 : (6 : 2) = 40.</p>"},{"key":"C","text":"<p>Salah, karena pembagian harus selalu dikerjakan dari kanan ke kiri.</p>","misconceptionId":"mis-msd-cacah-004"},{"key":"D","text":"<p>Benar, karena tanda kurung tidak memengaruhi hasil pembagian.</p>","misconceptionId":"mis-msd-cacah-001"}]'::jsonb, 'B', null, null, null, 'B', false, null, null),
  ('msd-cacah-008', 'sub-matematika-sd', 'top-matematika-sd-bilangan', 'st-matematika-sd-bilangan-rasional', 'con-matematika-sd-operasi-bilangan-cacah', 'mcma', 'Mengaplikasikan perkalian dan pembagian untuk memeriksa hasil hitungan', 'menengah', 'penerapan', 'html', '<p>Lima hasil hitungan siswa dikumpulkan untuk diperiksa. Guru meminta kelas menandai hitungan yang sudah benar.</p>', '<p>Hitungan yang benar adalah ....</p>', 'Pilih semua jawaban yang benar.', '<p>36 × 25 = 36 × 100 : 4 = 900, benar.</p><p>504 : 7 = 72, benar karena 7 × 72 = 504.</p><p>1.008 : 12 = 84, bukan 86, karena 12 × 84 = 1.008.</p><p>125 × 8 = 1.000, benar.</p><p>96 : 4 = 24, bukan 26, karena 4 × 24 = 96.</p>', '[{"key":"A","text":"<p>36 × 25 = 900</p>"},{"key":"B","text":"<p>504 : 7 = 72</p>"},{"key":"C","text":"<p>1.008 : 12 = 86</p>","misconceptionId":"mis-msd-cacah-003"},{"key":"D","text":"<p>125 × 8 = 1.000</p>"},{"key":"E","text":"<p>96 : 4 = 26</p>","misconceptionId":"mis-msd-cacah-003"}]'::jsonb, null, array['A', 'B', 'D'], null, null, 'A, B, D', false, null, null),
  ('msd-cacah-009', 'sub-matematika-sd', 'top-matematika-sd-bilangan', 'st-matematika-sd-bilangan-rasional', 'con-matematika-sd-operasi-bilangan-cacah', 'mcma', 'Bernalar tentang hubungan antar-langkah pada pengemasan bertingkat', 'lanjut', 'penalaran', 'html', '<p>Gudang berisi 1.440 batang pensil. Pensil dikemas 12 batang per bungkus, kemudian setiap dus diisi 10 bungkus.</p>', '<p>Pernyataan yang benar tentang pengemasan itu adalah ....</p>', 'Pilih semua jawaban yang benar.', '<p>Banyak bungkus = 1.440 : 12 = 120, jadi A benar.</p><p>Banyak dus = 120 : 10 = 12, jadi B benar.</p><p>Isi tiap dus = 10 × 12 = 120 batang, jadi C benar.</p><p>D salah: bila tiap dus berisi 12 bungkus, dus yang diperlukan 120 : 12 = 10 dus, yaitu lebih sedikit — wadah yang lebih besar selalu membutuhkan lebih sedikit wadah.</p><p>E salah: cara pengemasan hanya mengubah pengelompokan, bukan banyak pensilnya yang tetap 1.440.</p>', '[{"key":"A","text":"<p>Seluruh pensil menjadi 120 bungkus.</p>"},{"key":"B","text":"<p>Seluruh bungkus memenuhi tepat 12 dus.</p>"},{"key":"C","text":"<p>Setiap dus berisi 120 batang pensil.</p>"},{"key":"D","text":"<p>Bila setiap dus diisi 12 bungkus, dus yang diperlukan menjadi lebih banyak.</p>","misconceptionId":"mis-msd-cacah-005"},{"key":"E","text":"<p>Banyak pensil seluruhnya berubah bila cara pengemasannya diubah.</p>","misconceptionId":"mis-msd-cacah-005"}]'::jsonb, null, array['A', 'B', 'C'], null, null, 'A, B, C', false, null, null),
  ('msd-cacah-010', 'sub-matematika-sd', 'top-matematika-sd-bilangan', 'st-matematika-sd-bilangan-rasional', 'con-matematika-sd-operasi-bilangan-cacah', 'category', 'Bernalar menilai sifat-sifat operasi hitung bilangan cacah', 'lanjut', 'penalaran', 'html', '<p>Kelas menyusun lima pernyataan tentang sifat operasi hitung untuk diperiksa bersama.</p>', '<p>Tentukan benar atau salah setiap pernyataan berikut.</p>', 'Tentukan kategori setiap pernyataan.', '<p>P1 benar: perkalian dapat ditukar urutannya, keduanya bernilai 800.</p><p>P2 salah: pengurangan tidak dapat ditukar. 100 − 45 = 55, sedangkan 45 − 100 bukan bilangan cacah.</p><p>P3 benar: pembagian dan perkalian saling berkebalikan, jadi hasil pembagian dapat diperiksa dengan mengalikannya kembali.</p><p>P4 benar: 100 : 5 = 20, dan 12 + 8 = 20. Pembagian dapat disebar ke setiap suku penjumlahan.</p><p>P5 salah: 200 : (4 × 5) = 200 : 20 = 10, sedangkan 200 : 4 × 5 = 50 × 5 = 250.</p>', null, null, null, '[{"key":"B","label":"Benar"},{"key":"S","label":"Salah"}]'::jsonb, '[{"id":"p1","text":"<p>25 × 32 menghasilkan bilangan yang sama dengan 32 × 25.</p>","correctCategoryKey":"B"},{"id":"p2","text":"<p>100 − 45 menghasilkan bilangan yang sama dengan 45 − 100.</p>","correctCategoryKey":"S","misconceptionId":"mis-msd-cacah-004"},{"id":"p3","text":"<p>Karena 144 : 12 = 12, maka 12 × 12 = 144.</p>","correctCategoryKey":"B"},{"id":"p4","text":"<p>(60 + 40) : 5 menghasilkan bilangan yang sama dengan 60 : 5 + 40 : 5.</p>","correctCategoryKey":"B"},{"id":"p5","text":"<p>200 : (4 × 5) menghasilkan bilangan yang sama dengan 200 : 4 × 5.</p>","correctCategoryKey":"S","misconceptionId":"mis-msd-cacah-001"}]'::jsonb, 'p1: B; p2: S; p3: B; p4: B; p5: S', false, null, null),
  ('msd-oppec-001', 'sub-matematika-sd', 'top-matematika-sd-bilangan', 'st-matematika-sd-bilangan-rasional', 'con-matematika-sd-operasi-pecahan', 'single', 'Memahami penjumlahan pecahan berpenyebut sama', 'dasar', 'pemahaman', 'html', '<p>Sebuah semangka dipotong menjadi 7 bagian sama besar. Doni memakan 2 bagian dan Endah memakan 3 bagian.</p>', '<p>Bagian semangka yang dimakan keduanya adalah ....</p>', 'Pilih satu jawaban.', '<p>2/7 + 3/7 = 5/7 karena potongannya sama besar, sehingga cukup pembilangnya dijumlahkan.</p><p>Penyebut 7 tetap, sebab semangkanya tetap dipotong menjadi 7 bagian — jumlah potongannya tidak berubah menjadi 14.</p>', '[{"key":"A","text":"<p>5/7</p>"},{"key":"B","text":"<p>5/14</p>","misconceptionId":"mis-msd-oppec-001"},{"key":"C","text":"<p>6/7</p>","misconceptionId":"mis-msd-oppec-004"},{"key":"D","text":"<p>5/49</p>","misconceptionId":"mis-msd-oppec-001"}]'::jsonb, 'A', null, null, null, 'A', false, null, null),
  ('msd-oppec-002', 'sub-matematika-sd', 'top-matematika-sd-bilangan', 'st-matematika-sd-bilangan-rasional', 'con-matematika-sd-operasi-pecahan', 'single', 'Memahami perkalian pecahan dengan bilangan asli', 'dasar', 'pemahaman', 'html', '<p>Sebuah wadah berisi 8 liter air. Sebanyak 3/4 bagian air itu dipakai untuk menyiram tanaman.</p>', '<p>Banyak air yang dipakai untuk menyiram adalah ....</p>', 'Pilih satu jawaban.', '<p>3/4 × 8 = (3 × 8) : 4 = 24 : 4 = 6 liter.</p><p>Cara lain: 1/4 dari 8 liter adalah 2 liter, jadi 3/4 adalah 3 × 2 = 6 liter.</p><p>Pilihan B adalah sisa airnya, bukan air yang dipakai.</p>', '[{"key":"A","text":"<p>6 liter</p>"},{"key":"B","text":"<p>2 liter</p>","misconceptionId":"mis-msd-oppec-003"},{"key":"C","text":"<p>24 liter</p>","misconceptionId":"mis-msd-oppec-004"},{"key":"D","text":"<p>3/32 liter</p>","misconceptionId":"mis-msd-oppec-004"}]'::jsonb, 'A', null, null, null, 'A', false, null, null),
  ('msd-oppec-003', 'sub-matematika-sd', 'top-matematika-sd-bilangan', 'st-matematika-sd-bilangan-rasional', 'con-matematika-sd-operasi-pecahan', 'single', 'Mengaplikasikan pengurangan pecahan berpenyebut berbeda', 'menengah', 'penerapan', 'html', '<p>Sebuah pita panjangnya 5/6 meter. Sebanyak 1/4 meter dipotong untuk hiasan buku.</p>', '<p>Panjang pita yang tersisa adalah ....</p>', 'Pilih satu jawaban.', '<p>Kelipatan persekutuan terkecil 6 dan 4 adalah 12. Ubah kedua pecahan: 5/6 = 10/12 dan 1/4 = 3/12.</p><p>10/12 − 3/12 = 7/12 meter.</p><p>Pilihan C muncul bila penyebut diubah menjadi 12 tetapi pembilangnya dibiarkan 5 dan 1.</p>', '[{"key":"A","text":"<p>7/12 meter</p>"},{"key":"B","text":"<p>4/2 meter</p>","misconceptionId":"mis-msd-oppec-001"},{"key":"C","text":"<p>4/12 meter</p>","misconceptionId":"mis-msd-oppec-005"},{"key":"D","text":"<p>2/3 meter</p>","misconceptionId":"mis-msd-oppec-002"}]'::jsonb, 'A', null, null, null, 'A', false, null, null),
  ('msd-oppec-004', 'sub-matematika-sd', 'top-matematika-sd-bilangan', 'st-matematika-sd-bilangan-rasional', 'con-matematika-sd-operasi-pecahan', 'single', 'Mengaplikasikan pembagian pecahan dengan bilangan asli', 'menengah', 'penerapan', 'html', '<p>Gula sebanyak 2/3 kilogram dibagi rata ke dalam 4 wadah kecil.</p>', '<p>Berat gula pada setiap wadah adalah ....</p>', 'Pilih satu jawaban.', '<p>2/3 : 4 berarti 2/3 dipecah menjadi 4 bagian sama, sehingga penyebutnya dikalikan 4: 2/(3 × 4) = 2/12 = 1/6 kilogram.</p><p>Periksa kewajaran: 1/6 kg lebih kecil daripada 2/3 kg, dan 4 × 1/6 = 4/6 = 2/3 kg, sesuai dengan gula semula.</p><p>Pilihan B lebih besar daripada gula semula, jadi tidak mungkin benar.</p>', '[{"key":"A","text":"<p>1/6 kilogram</p>"},{"key":"B","text":"<p>8/3 kilogram</p>","misconceptionId":"mis-msd-oppec-003"},{"key":"C","text":"<p>1/12 kilogram</p>","misconceptionId":"mis-msd-oppec-005"},{"key":"D","text":"<p>6 kilogram</p>","misconceptionId":"mis-msd-oppec-003"}]'::jsonb, 'A', null, null, null, 'A', false, null, null),
  ('msd-oppec-005', 'sub-matematika-sd', 'top-matematika-sd-bilangan', 'st-matematika-sd-bilangan-rasional', 'con-matematika-sd-operasi-pecahan', 'single', 'Mengaplikasikan penjumlahan pecahan untuk mencari sisa dari satu keseluruhan', 'menengah', 'penerapan', 'html', '<p>Ayah mengecat dinding ruang tamu. Pada pagi hari selesai 1/2 bagian dinding, dan pada siang hari selesai 1/3 bagian dinding.</p>', '<p>Bagian dinding yang belum dicat adalah ....</p>', 'Pilih satu jawaban.', '<p>Bagian yang sudah dicat = 1/2 + 1/3. Dengan penyebut 6: 3/6 + 2/6 = 5/6.</p><p>Bagian yang belum dicat = 1 − 5/6 = 6/6 − 5/6 = 1/6.</p><p>Pilihan D adalah bagian yang sudah dicat, bukan yang belum.</p>', '[{"key":"A","text":"<p>1/6 bagian</p>"},{"key":"B","text":"<p>2/5 bagian</p>","misconceptionId":"mis-msd-oppec-002"},{"key":"C","text":"<p>1/5 bagian</p>","misconceptionId":"mis-msd-oppec-002"},{"key":"D","text":"<p>5/6 bagian</p>","misconceptionId":"mis-msd-oppec-005"}]'::jsonb, 'A', null, null, null, 'A', false, null, null),
  ('msd-oppec-006', 'sub-matematika-sd', 'top-matematika-sd-bilangan', 'st-matematika-sd-bilangan-rasional', 'con-matematika-sd-operasi-pecahan', 'single', 'Bernalar dengan perkalian pecahan untuk memeriksa kecukupan bahan', 'lanjut', 'penalaran', 'html', '<p>Satu loyang kue membutuhkan 3/4 kilogram tepung. Bu Hana akan membuat 6 loyang dan di dapurnya tersedia 5 kilogram tepung.</p>', '<p>Kesimpulan yang tepat tentang persediaan tepung Bu Hana adalah ....</p>', 'Pilih satu jawaban.', '<p>Tepung yang dibutuhkan = 3/4 × 6 = 18/4 = 4 1/2 kilogram.</p><p>Persediaan 5 kilogram, jadi cukup. Sisanya = 5 − 4 1/2 = 1/2 kilogram.</p><p>Pilihan B muncul bila kebutuhan ditaksir hanya 3 kilogram, misalnya karena 3/4 dibulatkan menjadi 1/2.</p>', '[{"key":"A","text":"<p>cukup, dan tersisa 1/2 kilogram</p>"},{"key":"B","text":"<p>cukup, dan tersisa 2 kilogram</p>","misconceptionId":"mis-msd-oppec-004"},{"key":"C","text":"<p>tidak cukup, karena kurang 1/2 kilogram</p>","misconceptionId":"mis-msd-oppec-003"},{"key":"D","text":"<p>cukup, dan tepung terpakai habis tanpa sisa</p>","misconceptionId":"mis-msd-oppec-005"}]'::jsonb, 'A', null, null, null, 'A', false, null, null),
  ('msd-oppec-007', 'sub-matematika-sd', 'top-matematika-sd-bilangan', 'st-matematika-sd-bilangan-rasional', 'con-matematika-sd-operasi-pecahan', 'single', 'Bernalar menilai kekeliruan menjumlahkan pecahan', 'lanjut', 'penalaran', 'html', '<p>Tio menulis di bukunya, “1/2 + 1/3 = 2/5, karena pembilang dijumlahkan dengan pembilang dan penyebut dijumlahkan dengan penyebut.”</p>', '<p>Tanggapan yang tepat terhadap pekerjaan Tio adalah ....</p>', 'Pilih satu jawaban.', '<p>Dengan penyebut 6: 1/2 + 1/3 = 3/6 + 2/6 = 5/6.</p><p>Pemeriksaan cepat menunjukkan cara Tio pasti salah: menambahkan sesuatu pada 1/2 tidak mungkin menghasilkan bilangan yang lebih kecil daripada 1/2, sedangkan 2/5 kurang dari 1/2.</p><p>Pecahan berpenyebut berbeda tetap dapat dijumlahkan setelah penyebutnya disamakan, jadi pilihan C tidak tepat.</p>', '[{"key":"A","text":"<p>Benar, karena pembilang dan penyebut sama-sama dijumlahkan sehingga caranya taat aturan.</p>","misconceptionId":"mis-msd-oppec-001"},{"key":"B","text":"<p>Benar, karena 2/5 dan 5/6 sebenarnya dua pecahan senilai yang hanya berbeda bentuknya.</p>","misconceptionId":"mis-msd-oppec-005"},{"key":"C","text":"<p>Salah, karena pecahan yang penyebutnya berbeda memang tidak dapat dijumlahkan sama sekali.</p>","misconceptionId":"mis-msd-oppec-002"},{"key":"D","text":"<p>Salah, karena hasilnya seharusnya 5/6; selain itu 2/5 justru lebih kecil daripada 1/2.</p>"}]'::jsonb, 'D', null, null, null, 'D', false, null, null),
  ('msd-oppec-008', 'sub-matematika-sd', 'top-matematika-sd-bilangan', 'st-matematika-sd-bilangan-rasional', 'con-matematika-sd-operasi-pecahan', 'mcma', 'Mengaplikasikan operasi pecahan untuk memeriksa hasil hitungan', 'menengah', 'penerapan', 'html', '<p>Lima hasil hitungan pecahan dikumpulkan dari buku latihan siswa untuk diperiksa bersama.</p>', '<p>Hitungan yang benar adalah ....</p>', 'Pilih semua jawaban yang benar.', '<p>A benar: 3/8 + 1/8 = 4/8 = 1/2.</p><p>B benar: 5/6 − 3/6 = 2/6 = 1/3.</p><p>C benar: 2/5 × 10 = 20/5 = 4.</p><p>D salah: 3/4 : 3 = 3/(4 × 3) = 3/12 = 1/4. Hasil 9/4 justru lebih besar daripada 3/4, padahal membagi seharusnya memperkecil.</p><p>E salah: 1/3 + 1/6 = 2/6 + 1/6 = 3/6 = 1/2, bukan 2/9.</p>', '[{"key":"A","text":"<p>3/8 + 1/8 = 1/2</p>"},{"key":"B","text":"<p>5/6 − 1/2 = 1/3</p>"},{"key":"C","text":"<p>2/5 × 10 = 4</p>"},{"key":"D","text":"<p>3/4 : 3 = 9/4</p>","misconceptionId":"mis-msd-oppec-003"},{"key":"E","text":"<p>1/3 + 1/6 = 2/9</p>","misconceptionId":"mis-msd-oppec-001"}]'::jsonb, null, array['A', 'B', 'C'], null, null, 'A, B, C', false, null, null),
  ('msd-oppec-009', 'sub-matematika-sd', 'top-matematika-sd-bilangan', 'st-matematika-sd-bilangan-rasional', 'con-matematika-sd-operasi-pecahan', 'mcma', 'Bernalar tentang pembagian satu keseluruhan menjadi beberapa bagian pecahan', 'lanjut', 'penalaran', 'html', '<p>Sebuah kue dibagi tiga. Andi mendapat 1/4 bagian, Bina mendapat 1/3 bagian, dan sisanya untuk Cita.</p>', '<p>Pernyataan yang benar tentang pembagian kue itu adalah ....</p>', 'Pilih semua jawaban yang benar.', '<p>Dengan penyebut 12: Andi 3/12, Bina 4/12, dan keduanya 7/12. Bagian Cita = 12/12 − 7/12 = 5/12, jadi A benar dan D salah (2/7 diperoleh dengan menjumlahkan penyebut).</p><p>B benar karena 4/12 lebih dari 3/12. C benar karena 5/12 paling besar di antara 3/12, 4/12, dan 5/12.</p><p>E salah: setelah pemberian itu Andi menjadi 3/12 + 1/12 = 4/12 dan Cita menjadi 5/12 − 1/12 = 4/12, jadi bagian keduanya sama, bukan Andi lebih banyak.</p>', '[{"key":"A","text":"<p>Bagian Cita adalah 5/12 bagian.</p>"},{"key":"B","text":"<p>Bagian Bina lebih banyak daripada bagian Andi.</p>"},{"key":"C","text":"<p>Cita mendapat bagian paling banyak.</p>"},{"key":"D","text":"<p>Andi dan Bina bersama-sama mendapat 2/7 bagian.</p>","misconceptionId":"mis-msd-oppec-001"},{"key":"E","text":"<p>Bila Cita memberikan 1/12 bagiannya kepada Andi, bagian Andi menjadi lebih banyak daripada bagian Cita.</p>","misconceptionId":"mis-msd-oppec-005"}]'::jsonb, null, array['A', 'B', 'C'], null, null, 'A, B, C', false, null, null),
  ('msd-oppec-010', 'sub-matematika-sd', 'top-matematika-sd-bilangan', 'st-matematika-sd-bilangan-rasional', 'con-matematika-sd-operasi-pecahan', 'category', 'Bernalar menilai pernyataan tentang operasi bilangan pecahan', 'lanjut', 'penalaran', 'html', '<p>Kelompok belajar menuliskan lima pernyataan tentang operasi pecahan untuk saling diperiksa.</p>', '<p>Tentukan benar atau salah setiap pernyataan berikut.</p>', 'Tentukan kategori setiap pernyataan.', '<p>P1 benar: penyebutnya sudah sama, jadi 2/5 + 1/5 = 3/5.</p><p>P2 benar: 2/5 = 4/10, sehingga 7/10 − 4/10 = 3/10.</p><p>P3 benar: 5/6 × 3 = 15/6 = 5/2 = 2 1/2.</p><p>P4 salah: 4/5 : 2 = 4/(5 × 2) = 4/10 = 2/5. Hasil 8/5 diperoleh dengan mengalikan, bukan membagi.</p><p>P5 salah: 3/4 × 4 = 3, yang jauh lebih besar daripada 3/4. Mengalikan dengan bilangan asli lebih dari 1 justru memperbesar.</p>', null, null, null, '[{"key":"B","label":"Benar"},{"key":"S","label":"Salah"}]'::jsonb, '[{"id":"p1","text":"<p>2/5 + 1/5 = 3/5</p>","correctCategoryKey":"B"},{"id":"p2","text":"<p>7/10 − 2/5 = 3/10</p>","correctCategoryKey":"B"},{"id":"p3","text":"<p>5/6 × 3 = 2 1/2</p>","correctCategoryKey":"B"},{"id":"p4","text":"<p>4/5 : 2 = 8/5</p>","correctCategoryKey":"S","misconceptionId":"mis-msd-oppec-003"},{"id":"p5","text":"<p>Mengalikan pecahan dengan bilangan asli yang lebih dari 1 selalu menghasilkan bilangan yang lebih kecil daripada pecahan semula.</p>","correctCategoryKey":"S","misconceptionId":"mis-msd-oppec-004"}]'::jsonb, 'p1: B; p2: B; p3: B; p4: S; p5: S', false, null, null),
  ('msd-kpkfpb-001', 'sub-matematika-sd', 'top-matematika-sd-bilangan', 'st-matematika-sd-bilangan-rasional', 'con-matematika-sd-kpk-fpb', 'single', 'Memahami daftar faktor suatu bilangan', 'dasar', 'pemahaman', 'html', '<p>Bu Nita mempunyai 24 bunga yang akan ditata dalam beberapa vas dengan isi sama banyak, tanpa ada bunga yang tersisa. Banyak bunga per vas haruslah faktor dari 24.</p>', '<p>Daftar faktor 24 yang lengkap adalah ....</p>', 'Pilih satu jawaban.', '<p>Daftar faktor secara berpasangan: 1 × 24, 2 × 12, 3 × 8, dan 4 × 6.</p><p>Jadi faktornya 1, 2, 3, 4, 6, 8, 12, dan 24 — seluruhnya 8 faktor.</p><p>Pilihan B melewatkan 8, pilihan C melewatkan 1 dan 24, dan pilihan D justru daftar kelipatan 24.</p>', '[{"key":"A","text":"<p>1, 2, 3, 4, 6, 8, 12, 24</p>"},{"key":"B","text":"<p>1, 2, 3, 4, 6, 12, 24</p>","misconceptionId":"mis-msd-kpkfpb-003"},{"key":"C","text":"<p>2, 3, 4, 6, 8, 12</p>","misconceptionId":"mis-msd-kpkfpb-003"},{"key":"D","text":"<p>24, 48, 72, 96</p>","misconceptionId":"mis-msd-kpkfpb-005"}]'::jsonb, 'A', null, null, null, 'A', false, null, null),
  ('msd-kpkfpb-002', 'sub-matematika-sd', 'top-matematika-sd-bilangan', 'st-matematika-sd-bilangan-rasional', 'con-matematika-sd-kpk-fpb', 'single', 'Memahami kelipatan persekutuan terkecil dua bilangan', 'dasar', 'pemahaman', 'html', '<p>Kelipatan 4 adalah 4, 8, 12, 16, 20, 24, … dan kelipatan 6 adalah 6, 12, 18, 24, 30, …</p>', '<p>Kelipatan persekutuan terkecil dari 4 dan 6 adalah ....</p>', 'Pilih satu jawaban.', '<p>Kelipatan persekutuan 4 dan 6 adalah 12, 24, 36, … Yang terkecil adalah 12.</p><p>Pilihan A adalah FPB 4 dan 6, bukan KPK-nya. Pilihan C adalah hasil kali 4 × 6, yang memang kelipatan persekutuan tetapi bukan yang terkecil.</p>', '[{"key":"A","text":"<p>2</p>","misconceptionId":"mis-msd-kpkfpb-001"},{"key":"B","text":"<p>12</p>"},{"key":"C","text":"<p>24</p>","misconceptionId":"mis-msd-kpkfpb-002"},{"key":"D","text":"<p>10</p>","misconceptionId":"mis-msd-kpkfpb-005"}]'::jsonb, 'B', null, null, null, 'B', false, null, null),
  ('msd-kpkfpb-003', 'sub-matematika-sd', 'top-matematika-sd-bilangan', 'st-matematika-sd-bilangan-rasional', 'con-matematika-sd-kpk-fpb', 'single', 'Mengaplikasikan KPK pada masalah kejadian berulang', 'menengah', 'penerapan', 'html', '<p>Dua lampu hias dinyalakan bersama pada pukul 19.00. Lampu merah berkedip setiap 12 detik dan lampu kuning berkedip setiap 18 detik.</p>', '<p>Kedua lampu berkedip bersamaan lagi setelah ....</p>', 'Pilih satu jawaban.', '<p>Masalah “berulang bersama lagi” diselesaikan dengan KPK.</p><p>Faktorisasi: 12 = 2 × 2 × 3 dan 18 = 2 × 3 × 3, sehingga KPK = 2 × 2 × 3 × 3 = 36.</p><p>Periksa: 36 : 12 = 3 kedipan lampu merah dan 36 : 18 = 2 kedipan lampu kuning — keduanya bulat. Pilihan A adalah FPB dan pilihan D adalah hasil kali 12 × 18.</p>', '[{"key":"A","text":"<p>6 detik</p>","misconceptionId":"mis-msd-kpkfpb-001"},{"key":"B","text":"<p>30 detik</p>","misconceptionId":"mis-msd-kpkfpb-005"},{"key":"C","text":"<p>36 detik</p>"},{"key":"D","text":"<p>216 detik</p>","misconceptionId":"mis-msd-kpkfpb-002"}]'::jsonb, 'C', null, null, null, 'C', false, null, null),
  ('msd-kpkfpb-004', 'sub-matematika-sd', 'top-matematika-sd-bilangan', 'st-matematika-sd-bilangan-rasional', 'con-matematika-sd-kpk-fpb', 'single', 'Mengaplikasikan FPB pada masalah pembagian rata', 'menengah', 'penerapan', 'html', '<p>Panitia bakti sosial mempunyai 36 buku tulis dan 48 pensil. Semuanya akan dimasukkan ke dalam paket dengan isi sama, dan tidak boleh ada barang yang tersisa.</p>', '<p>Banyak paket terbanyak yang dapat dibuat adalah ....</p>', 'Pilih satu jawaban.', '<p>Masalah “dibagi rata sebanyak mungkin kelompok” diselesaikan dengan FPB.</p><p>Faktorisasi: 36 = 2 × 2 × 3 × 3 dan 48 = 2 × 2 × 2 × 2 × 3, sehingga FPB = 2 × 2 × 3 = 12.</p><p>Periksa: 36 : 12 = 3 buku dan 48 : 12 = 4 pensil per paket, tanpa sisa. Pilihan A dan B juga membagi habis, tetapi paketnya lebih sedikit daripada yang terbanyak.</p>', '[{"key":"A","text":"<p>4 paket</p>","misconceptionId":"mis-msd-kpkfpb-003"},{"key":"B","text":"<p>6 paket</p>","misconceptionId":"mis-msd-kpkfpb-003"},{"key":"C","text":"<p>12 paket</p>"},{"key":"D","text":"<p>144 paket</p>","misconceptionId":"mis-msd-kpkfpb-001"}]'::jsonb, 'C', null, null, null, 'C', false, null, null),
  ('msd-kpkfpb-005', 'sub-matematika-sd', 'top-matematika-sd-bilangan', 'st-matematika-sd-bilangan-rasional', 'con-matematika-sd-kpk-fpb', 'single', 'Mengaplikasikan FPB untuk menentukan isi setiap kelompok', 'menengah', 'penerapan', 'html', '<p>Ibu mempunyai 60 kue dan 45 permen. Semuanya dibagikan rata kepada anak-anak sebanyak mungkin, tanpa ada yang tersisa.</p>', '<p>Setiap anak menerima ....</p>', 'Pilih satu jawaban.', '<p>Banyak anak terbanyak = FPB 60 dan 45. Faktorisasi: 60 = 2 × 2 × 3 × 5 dan 45 = 3 × 3 × 5, sehingga FPB = 3 × 5 = 15 anak.</p><p>Setiap anak menerima 60 : 15 = 4 kue dan 45 : 15 = 3 permen.</p><p>Pilihan D adalah pembagian untuk 5 anak, yang bukan jumlah anak terbanyak.</p>', '[{"key":"A","text":"<p>4 kue dan 3 permen</p>"},{"key":"B","text":"<p>3 kue dan 4 permen</p>","misconceptionId":"mis-msd-kpkfpb-005"},{"key":"C","text":"<p>5 kue dan 4 permen</p>","misconceptionId":"mis-msd-kpkfpb-003"},{"key":"D","text":"<p>12 kue dan 9 permen</p>","misconceptionId":"mis-msd-kpkfpb-001"}]'::jsonb, 'A', null, null, null, 'A', false, null, null),
  ('msd-kpkfpb-006', 'sub-matematika-sd', 'top-matematika-sd-bilangan', 'st-matematika-sd-bilangan-rasional', 'con-matematika-sd-kpk-fpb', 'single', 'Bernalar dengan KPK tiga bilangan beserta penanggalannya', 'lanjut', 'penalaran', 'html', '<p>Tiga anggota keluarga mendapat jadwal piket berbeda: Ayah setiap 4 hari, Ibu setiap 6 hari, dan Kakak setiap 8 hari. Hari ini, hari Senin, ketiganya piket bersama.</p>', '<p>Ketiganya piket bersama lagi setelah ... dan jatuh pada hari ....</p>', 'Pilih satu jawaban.', '<p>Faktorisasi: 4 = 2 × 2, 6 = 2 × 3, dan 8 = 2 × 2 × 2. KPK = 2 × 2 × 2 × 3 = 24 hari.</p><p>Untuk harinya, 24 hari sama dengan 3 pekan lebih 3 hari, karena 24 = 3 × 7 + 3. Tiga pekan kembali ke hari Senin, lalu maju 3 hari menjadi Kamis.</p><p>Pilihan C keliru karena 12 bukan kelipatan 8, dan pilihan D memakai hasil kali 4 × 6 × 8.</p>', '[{"key":"A","text":"<p>24 hari, hari Kamis</p>"},{"key":"B","text":"<p>24 hari, hari Selasa</p>","misconceptionId":"mis-msd-kpkfpb-003"},{"key":"C","text":"<p>12 hari, hari Sabtu</p>","misconceptionId":"mis-msd-kpkfpb-001"},{"key":"D","text":"<p>192 hari, hari Kamis</p>","misconceptionId":"mis-msd-kpkfpb-002"}]'::jsonb, 'A', null, null, null, 'A', false, null, null),
  ('msd-kpkfpb-007', 'sub-matematika-sd', 'top-matematika-sd-bilangan', 'st-matematika-sd-bilangan-rasional', 'con-matematika-sd-kpk-fpb', 'single', 'Bernalar menilai pernyataan umum tentang KPK', 'lanjut', 'penalaran', 'html', '<p>Rudi berpendapat, “KPK dua bilangan selalu sama dengan hasil kali kedua bilangan itu.”</p>', '<p>Tanggapan yang tepat terhadap pendapat Rudi adalah ....</p>', 'Pilih satu jawaban.', '<p>Hasil kali dua bilangan memang selalu merupakan kelipatan persekutuan, tetapi tidak selalu yang terkecil. Contoh penyangkalnya: KPK 4 dan 6 adalah 12, bukan 24.</p><p>Hasil kali baru sama dengan KPK bila kedua bilangan tidak punya faktor bersama selain 1, misalnya 5 dan 7 yang KPK-nya 35.</p><p>Pilihan C jelas salah karena KPK selalu paling sedikit sebesar bilangan terbesarnya, dan kelipatan persekutuan ada tak terhingga banyaknya sehingga pilihan D juga keliru.</p>', '[{"key":"A","text":"<p>Benar, karena hasil kali dua bilangan pasti dapat dibagi keduanya.</p>","misconceptionId":"mis-msd-kpkfpb-002"},{"key":"B","text":"<p>Salah, karena KPK 4 dan 6 adalah 12 sedangkan hasil kalinya 24; keduanya hanya sama bila FPB kedua bilangan adalah 1.</p>"},{"key":"C","text":"<p>Salah, karena KPK dua bilangan selalu lebih kecil daripada kedua bilangan itu.</p>","misconceptionId":"mis-msd-kpkfpb-001"},{"key":"D","text":"<p>Benar, karena kelipatan persekutuan hanya ada satu untuk setiap pasangan bilangan.</p>","misconceptionId":"mis-msd-kpkfpb-005"}]'::jsonb, 'B', null, null, null, 'B', false, null, null),
  ('msd-kpkfpb-008', 'sub-matematika-sd', 'top-matematika-sd-bilangan', 'st-matematika-sd-bilangan-rasional', 'con-matematika-sd-kpk-fpb', 'mcma', 'Mengaplikasikan faktor, kelipatan, KPK, dan FPB untuk memeriksa pernyataan', 'menengah', 'penerapan', 'html', '<p>Lima pernyataan tentang faktor dan kelipatan ditulis di papan tulis untuk diperiksa kebenarannya.</p>', '<p>Pernyataan yang benar adalah ....</p>', 'Pilih semua jawaban yang benar.', '<p>A benar: 18 = 2 × 3 × 3 dan 27 = 3 × 3 × 3, sehingga FPB = 3 × 3 = 9.</p><p>B benar: 15 sudah kelipatan 5, jadi KPK-nya 15 — hasil kali 75 bukan yang terkecil.</p><p>C benar: 7 × 8 = 56, jadi 7 membagi habis 56.</p><p>D salah: kelipatan 6 di sekitar 45 adalah 42 dan 48, sedangkan 45 : 6 bersisa 3.</p><p>E salah: FPB selalu paling besar sebesar bilangan terkecilnya, sedangkan KPK paling kecil sebesar bilangan terbesarnya, jadi FPB tidak pernah melebihi KPK.</p>', '[{"key":"A","text":"<p>FPB dari 18 dan 27 adalah 9.</p>"},{"key":"B","text":"<p>KPK dari 5 dan 15 adalah 15.</p>"},{"key":"C","text":"<p>7 adalah faktor dari 56.</p>"},{"key":"D","text":"<p>45 adalah kelipatan 6.</p>","misconceptionId":"mis-msd-kpkfpb-005"},{"key":"E","text":"<p>FPB dua bilangan selalu lebih besar daripada KPK-nya.</p>","misconceptionId":"mis-msd-kpkfpb-001"}]'::jsonb, null, array['A', 'B', 'C'], null, null, 'A, B, C', false, null, null),
  ('msd-kpkfpb-009', 'sub-matematika-sd', 'top-matematika-sd-bilangan', 'st-matematika-sd-bilangan-rasional', 'con-matematika-sd-kpk-fpb', 'mcma', 'Bernalar tentang faktorisasi dan keterbagian satu bilangan', 'lanjut', 'penalaran', 'html', '<p>Bilangan 84 dituliskan di papan. Kelas diminta memeriksa beberapa pernyataan tentang bilangan itu.</p>', '<p>Pernyataan yang benar tentang 84 adalah ....</p>', 'Pilih semua jawaban yang benar.', '<p>A benar: 2 × 2 × 3 × 7 = 84.</p><p>B benar: 84 : 6 = 14. Bilangan itu habis dibagi 2 dan habis dibagi 3, jadi habis dibagi 6.</p><p>C salah: 84 hanya memuat dua faktor 2, sedangkan 8 memerlukan tiga faktor 2. Memang 84 habis dibagi 4, tetapi tidak habis dibagi 8.</p><p>D benar: 84 : 2 = 42, dan tidak ada faktor lain yang lebih besar selain 84 sendiri.</p><p>E salah: jumlah angka 8 + 4 = 12 tidak habis dibagi 9, dan 84 : 9 bersisa 3. Bilangan ini habis dibagi 3 tetapi tidak habis dibagi 9.</p>', '[{"key":"A","text":"<p>84 = 2 × 2 × 3 × 7</p>"},{"key":"B","text":"<p>84 habis dibagi 6.</p>"},{"key":"C","text":"<p>84 habis dibagi 8.</p>","misconceptionId":"mis-msd-kpkfpb-004"},{"key":"D","text":"<p>Faktor terbesar 84 selain 84 sendiri adalah 42.</p>"},{"key":"E","text":"<p>84 adalah kelipatan 9.</p>","misconceptionId":"mis-msd-kpkfpb-004"}]'::jsonb, null, array['A', 'B', 'D'], null, null, 'A, B, D', false, null, null),
  ('msd-kpkfpb-010', 'sub-matematika-sd', 'top-matematika-sd-bilangan', 'st-matematika-sd-bilangan-rasional', 'con-matematika-sd-kpk-fpb', 'category', 'Bernalar menilai pernyataan tentang KPK, FPB, dan keterbagian', 'lanjut', 'penalaran', 'html', '<p>Lima pernyataan hasil diskusi kelompok dikumpulkan untuk diperiksa bersama.</p>', '<p>Tentukan benar atau salah setiap pernyataan berikut.</p>', 'Tentukan kategori setiap pernyataan.', '<p>P1 benar: 24 = 2 × 2 × 2 × 3 dan 36 = 2 × 2 × 3 × 3, sehingga FPB = 2 × 2 × 3 = 12.</p><p>P2 benar: KPK = 2 × 2 × 2 × 3 × 3 = 72. Periksa: 72 : 24 = 3 dan 72 : 36 = 2.</p><p>P3 benar: 9 memuat dua faktor 3, jadi bilangan yang habis dibagi 9 sudah pasti memuat faktor 3.</p><p>P4 salah: 12 habis dibagi 3 tetapi tidak habis dibagi 9. Hubungannya hanya berlaku satu arah.</p><p>P5 salah: setiap pasangan bilangan asli selalu punya KPK. Bila FPB-nya 1, KPK-nya justru tepat sama dengan hasil kali kedua bilangan, misalnya KPK 5 dan 7 adalah 35.</p>', null, null, null, '[{"key":"B","label":"Benar"},{"key":"S","label":"Salah"}]'::jsonb, '[{"id":"p1","text":"<p>FPB dari 24 dan 36 adalah 12.</p>","correctCategoryKey":"B"},{"id":"p2","text":"<p>KPK dari 24 dan 36 adalah 72.</p>","correctCategoryKey":"B"},{"id":"p3","text":"<p>Setiap bilangan yang habis dibagi 9 pasti habis dibagi 3.</p>","correctCategoryKey":"B"},{"id":"p4","text":"<p>Setiap bilangan yang habis dibagi 3 pasti habis dibagi 9.</p>","correctCategoryKey":"S","misconceptionId":"mis-msd-kpkfpb-004"},{"id":"p5","text":"<p>Dua bilangan yang FPB-nya 1 tidak mempunyai KPK.</p>","correctCategoryKey":"S","misconceptionId":"mis-msd-kpkfpb-002"}]'::jsonb, 'p1: B; p2: B; p3: B; p4: S; p5: S', false, null, null),
  ('msd-bangdat-001', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-objek-geometri', 'con-matematika-sd-bangun-datar', 'single', 'Memahami ciri bangun datar dari sisi dan sudutnya', 'dasar', 'pemahaman', 'html', '<p>Sebuah ubin lantai mempunyai empat sisi yang sama panjang dan keempat sudutnya berbentuk siku-siku.</p>', '<p>Bentuk ubin itu adalah ....</p>', 'Pilih satu jawaban.', '<p>Bangun bersisi empat dengan keempat sisi sama panjang sekaligus keempat sudut siku-siku disebut persegi.</p><p>Persegi panjang memenuhi syarat sudut siku-siku tetapi tidak menuntut sisinya sama panjang; belah ketupat memenuhi syarat sisi sama panjang tetapi tidak menuntut sudut siku-siku. Persegi memenuhi keduanya.</p>', '[{"key":"A","text":"<p>persegi</p>"},{"key":"B","text":"<p>persegi panjang</p>","misconceptionId":"mis-msd-bangdat-001"},{"key":"C","text":"<p>belah ketupat</p>","misconceptionId":"mis-msd-bangdat-002"},{"key":"D","text":"<p>jajar genjang</p>","misconceptionId":"mis-msd-bangdat-005"}]'::jsonb, 'A', null, null, null, 'A', false, null, null),
  ('msd-bangdat-002', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-objek-geometri', 'con-matematika-sd-bangun-datar', 'single', 'Memahami penggolongan segitiga menurut panjang sisinya', 'dasar', 'pemahaman', 'html', '<p>Rangka hiasan dinding berbentuk segitiga. Dua sisinya diukur sama panjang, yaitu 15 cm, sedangkan sisi ketiganya 20 cm.</p>', '<p>Segitiga pada rangka itu tergolong ....</p>', 'Pilih satu jawaban.', '<p>Segitiga dengan tepat dua sisi sama panjang disebut segitiga sama kaki.</p><p>Segitiga sama sisi menuntut ketiga sisinya sama panjang, sedangkan segitiga sembarang tidak punya sisi yang sama panjang. Penggolongan siku-siku ditentukan oleh sudutnya, bukan sisinya, dan tidak ada keterangan sudut pada soal.</p>', '[{"key":"A","text":"<p>segitiga sama sisi</p>","misconceptionId":"mis-msd-bangdat-002"},{"key":"B","text":"<p>segitiga siku-siku</p>","misconceptionId":"mis-msd-bangdat-001"},{"key":"C","text":"<p>segitiga sembarang</p>","misconceptionId":"mis-msd-bangdat-004"},{"key":"D","text":"<p>segitiga sama kaki</p>"}]'::jsonb, 'D', null, null, null, 'D', false, null, null),
  ('msd-bangdat-003', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-objek-geometri', 'con-matematika-sd-bangun-datar', 'single', 'Mengaplikasikan sifat segiempat untuk mengenali bangunnya', 'menengah', 'penerapan', 'html', '<p>Bangun ABCD mempunyai sifat berikut:</p><ul><li>dua pasang sisi berhadapan sejajar;</li><li>sisi yang berhadapan sama panjang;</li><li>keempat sudutnya tidak siku-siku;</li><li>keempat sisinya tidak sama panjang.</li></ul>', '<p>Bangun ABCD adalah ....</p>', 'Pilih satu jawaban.', '<p>Dua pasang sisi sejajar dengan sisi berhadapan sama panjang adalah ciri jajar genjang.</p><p>Persegi panjang tersingkir karena sudutnya harus siku-siku, dan belah ketupat tersingkir karena keempat sisinya harus sama panjang. Trapesium hanya dijamin mempunyai satu pasang sisi sejajar, sehingga syarat pertama tidak terpenuhi sebagai penciri trapesium.</p>', '[{"key":"A","text":"<p>persegi panjang</p>","misconceptionId":"mis-msd-bangdat-001"},{"key":"B","text":"<p>belah ketupat</p>","misconceptionId":"mis-msd-bangdat-002"},{"key":"C","text":"<p>trapesium</p>","misconceptionId":"mis-msd-bangdat-005"},{"key":"D","text":"<p>jajar genjang</p>"}]'::jsonb, 'D', null, null, null, 'D', false, null, null),
  ('msd-bangdat-004', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-objek-geometri', 'con-matematika-sd-bangun-datar', 'single', 'Mengaplikasikan penamaan segi banyak pada bangun gabungan', 'menengah', 'penerapan', 'html', '<p>Lantai ruang serbaguna berbentuk seperti huruf L. Bentuk itu dibuat dari sebuah persegi panjang besar yang salah satu sudutnya dipotong oleh persegi panjang yang lebih kecil. Seluruh tepinya berupa garis lurus.</p>', '<p>Lantai ruang itu berbentuk ....</p>', 'Pilih satu jawaban.', '<p>Ikuti tepi bangun berbentuk huruf L satu per satu sampai kembali ke titik awal. Ternyata ada 6 sisi lurus, jadi bangunnya segi enam.</p><p>Bangun ini mempunyai 5 sudut yang menonjol ke luar dan 1 sudut yang menjorok ke dalam. Bila hanya sudut menonjol yang dihitung, hasilnya keliru menjadi segi lima.</p><p>Nama segi banyak ditentukan oleh banyak sisinya, bukan oleh sudut yang tampak menonjol saja.</p>', '[{"key":"A","text":"<p>segi empat</p>","misconceptionId":"mis-msd-bangdat-004"},{"key":"B","text":"<p>segi lima</p>","misconceptionId":"mis-msd-bangdat-004"},{"key":"C","text":"<p>segi enam</p>"},{"key":"D","text":"<p>segi delapan</p>","misconceptionId":"mis-msd-bangdat-004"}]'::jsonb, 'C', null, null, null, 'C', true, 'Denah lantai berbentuk huruf L dilihat dari atas, bergaris tepi tebal dan berlatar abu muda. Bentuknya dibuat dari persegi panjang besar 6 satuan × 4 satuan yang salah satu sudut kanan atasnya dipotong oleh persegi panjang 3 satuan × 2 satuan. Tandai setiap sisi lurus dengan huruf a sampai f mengikuti tepinya searah jarum jam, tanpa menuliskan nama bangunnya.', 'svg'),
  ('msd-bangdat-005', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-objek-geometri', 'con-matematika-sd-bangun-datar', 'single', 'Mengaplikasikan sumbu simetri pada bangun datar', 'menengah', 'penerapan', 'html', '<p>Selembar kertas berbentuk persegi panjang berukuran 20 cm × 12 cm dilipat dengan berbagai cara. Lipatan disebut sumbu simetri bila kedua bagian kertas saling menutup tepat.</p>', '<p>Banyak sumbu simetri persegi panjang itu adalah ....</p>', 'Pilih satu jawaban.', '<p>Lipatan mendatar di tengah dan lipatan tegak di tengah keduanya menghasilkan dua bagian yang saling menutup, jadi ada 2 sumbu simetri.</p><p>Lipatan sepanjang diagonal tidak menghasilkan dua bagian yang saling menutup pada persegi panjang, karena sisi 20 cm tidak akan jatuh tepat di atas sisi 12 cm.</p><p>Persegi memang mempunyai 4 sumbu simetri, tetapi itu berlaku hanya bila keempat sisinya sama panjang.</p>', '[{"key":"A","text":"<p>1</p>","misconceptionId":"mis-msd-bangdat-004"},{"key":"B","text":"<p>tak terhingga</p>","misconceptionId":"mis-msd-bangdat-001"},{"key":"C","text":"<p>4</p>","misconceptionId":"mis-msd-bangdat-003"},{"key":"D","text":"<p>2</p>"}]'::jsonb, 'D', null, null, null, 'D', false, null, null),
  ('msd-bangdat-006', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-objek-geometri', 'con-matematika-sd-bangun-datar', 'single', 'Bernalar tentang hubungan antargolongan segiempat', 'lanjut', 'penalaran', 'html', '<p>Dua siswa berdebat. Sari berkata, “Persegi itu juga persegi panjang.” Beni membalas, “Kalau begitu, persegi panjang juga persegi.”</p>', '<p>Penilaian yang tepat terhadap kedua pendapat itu adalah ....</p>', 'Pilih satu jawaban.', '<p>Syarat persegi panjang adalah bersisi empat dengan keempat sudut siku-siku. Persegi memenuhi syarat itu, jadi setiap persegi adalah persegi panjang — pendapat Sari benar.</p><p>Sebaliknya tidak berlaku: persegi panjang berukuran 20 cm × 12 cm bersudut siku-siku semua tetapi sisinya tidak sama panjang, sehingga bukan persegi. Pendapat Beni salah.</p><p>Hubungan seperti ini searah, mirip dengan “setiap kucing adalah hewan, tetapi tidak setiap hewan adalah kucing”.</p>', '[{"key":"A","text":"<p>Keduanya benar, karena persegi dan persegi panjang sama-sama bersisi empat.</p>","misconceptionId":"mis-msd-bangdat-001"},{"key":"B","text":"<p>Keduanya salah, karena persegi dan persegi panjang adalah dua golongan yang tidak berhubungan.</p>","misconceptionId":"mis-msd-bangdat-001"},{"key":"C","text":"<p>Hanya Beni yang benar, karena persegi panjang mempunyai lebih banyak sifat.</p>","misconceptionId":"mis-msd-bangdat-003"},{"key":"D","text":"<p>Hanya Sari yang benar, karena persegi memenuhi semua syarat persegi panjang, sedangkan persegi panjang belum tentu bersisi empat sama panjang.</p>"}]'::jsonb, 'D', null, null, null, 'D', false, null, null),
  ('msd-bangdat-007', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-objek-geometri', 'con-matematika-sd-bangun-datar', 'single', 'Bernalar tentang kedudukan belah ketupat dalam golongan segiempat', 'lanjut', 'penalaran', 'html', '<p>Guru menggambar belah ketupat yang keempat sisinya 8 cm dan tidak satu pun sudutnya siku-siku. Kelas ditanya apakah bangun itu termasuk jajar genjang.</p>', '<p>Jawaban beserta alasan yang tepat adalah ....</p>', 'Pilih satu jawaban.', '<p>Syarat jajar genjang adalah dua pasang sisi berhadapan yang sejajar. Pada belah ketupat, syarat itu terpenuhi, jadi belah ketupat termasuk jajar genjang.</p><p>Jajar genjang tidak menuntut sudut siku-siku maupun sisi yang berbeda panjang, sehingga alasan pada pilihan B dan C tidak berlaku.</p><p>Pilihan D terlalu luas: trapesium bersisi empat tetapi hanya satu pasang sisinya yang sejajar, sehingga bukan jajar genjang.</p>', '[{"key":"A","text":"<p>Termasuk, karena kedua pasang sisi berhadapannya sejajar dan sama panjang.</p>"},{"key":"B","text":"<p>Tidak termasuk, karena jajar genjang harus mempunyai sisi yang tidak sama panjang.</p>","misconceptionId":"mis-msd-bangdat-001"},{"key":"C","text":"<p>Tidak termasuk, karena jajar genjang harus mempunyai sudut siku-siku.</p>","misconceptionId":"mis-msd-bangdat-002"},{"key":"D","text":"<p>Termasuk, karena setiap bangun bersisi empat adalah jajar genjang.</p>","misconceptionId":"mis-msd-bangdat-005"}]'::jsonb, 'A', null, null, null, 'A', false, null, null),
  ('msd-bangdat-008', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-objek-geometri', 'con-matematika-sd-bangun-datar', 'mcma', 'Mengaplikasikan sifat persegi panjang untuk menyaring pernyataan', 'menengah', 'penerapan', 'html', '<p>Kelas mendaftar sifat-sifat persegi panjang di papan tulis. Beberapa di antaranya perlu diperiksa kembali.</p>', '<p>Sifat yang pasti dimiliki setiap persegi panjang adalah ....</p>', 'Pilih semua jawaban yang benar.', '<p>A, B, dan C adalah sifat yang berlaku pada setiap persegi panjang, termasuk persegi.</p><p>D salah sebagai sifat umum: persegi panjang 20 cm × 12 cm tidak bersisi sama panjang. Sifat itu hanya milik persegi.</p><p>E salah: persegi panjang yang bukan persegi hanya mempunyai 2 sumbu simetri.</p>', '[{"key":"A","text":"<p>Keempat sudutnya siku-siku.</p>"},{"key":"B","text":"<p>Sisi yang berhadapan sama panjang dan sejajar.</p>"},{"key":"C","text":"<p>Kedua diagonalnya sama panjang.</p>"},{"key":"D","text":"<p>Keempat sisinya sama panjang.</p>","misconceptionId":"mis-msd-bangdat-001"},{"key":"E","text":"<p>Mempunyai 4 sumbu simetri.</p>","misconceptionId":"mis-msd-bangdat-003"}]'::jsonb, null, array['A', 'B', 'C'], null, null, 'A, B, C', false, null, null),
  ('msd-bangdat-009', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-objek-geometri', 'con-matematika-sd-bangun-datar', 'mcma', 'Bernalar tentang sifat segitiga, segiempat, dan segi banyak beraturan', 'lanjut', 'penalaran', 'html', '<p>Beberapa kesimpulan hasil kerja kelompok tentang bangun datar dikumpulkan untuk diperiksa.</p>', '<p>Kesimpulan yang benar adalah ....</p>', 'Pilih semua jawaban yang benar.', '<p>A benar: pada segi banyak beraturan, banyak sumbu simetri sama dengan banyak sisinya.</p><p>B benar: belah ketupat mempunyai empat sisi, jadi termasuk segi empat.</p><p>C salah: trapesium hanya dijamin satu pasang sisi sejajar. Bila dua pasang sisinya sejajar, bangun itu sudah menjadi jajar genjang.</p><p>D benar: sumbu simetrinya melewati setiap titik sudut menuju tengah sisi di hadapannya.</p><p>E salah: pada jajar genjang biasa maupun belah ketupat, kedua diagonalnya berbeda panjang.</p>', '[{"key":"A","text":"<p>Segi enam beraturan mempunyai 6 sumbu simetri.</p>"},{"key":"B","text":"<p>Belah ketupat termasuk bangun segi empat.</p>"},{"key":"C","text":"<p>Setiap trapesium mempunyai dua pasang sisi sejajar.</p>","misconceptionId":"mis-msd-bangdat-005"},{"key":"D","text":"<p>Segitiga sama sisi mempunyai 3 sumbu simetri.</p>"},{"key":"E","text":"<p>Setiap bangun segi empat mempunyai dua diagonal yang sama panjang.</p>","misconceptionId":"mis-msd-bangdat-003"}]'::jsonb, null, array['A', 'B', 'D'], null, null, 'A, B, D', false, null, null),
  ('msd-bangdat-010', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-objek-geometri', 'con-matematika-sd-bangun-datar', 'category', 'Bernalar menilai pernyataan tentang golongan bangun datar', 'lanjut', 'penalaran', 'html', '<p>Lima pernyataan tentang bangun datar ditempel di papan pengumuman kelas untuk diperiksa bersama.</p>', '<p>Tentukan benar atau salah setiap pernyataan berikut.</p>', 'Tentukan kategori setiap pernyataan.', '<p>P1 benar: persegi bersisi empat sama panjang, yang merupakan syarat belah ketupat.</p><p>P2 salah: belah ketupat bersudut 60° dan 120° tetap bersisi sama panjang, tetapi bukan persegi karena sudutnya tidak siku-siku.</p><p>P3 benar: segitiga sama kaki menuntut paling sedikit dua sisi sama panjang, dan segitiga sama sisi memenuhinya.</p><p>P4 salah: jajar genjang yang bukan persegi panjang tidak mempunyai sumbu simetri sama sekali. Bangun itu hanya setangkup bila diputar setengah putaran.</p><p>P5 benar: pada segi banyak beraturan, semua sisinya sama panjang dan semua sudutnya sama besar.</p>', null, null, null, '[{"key":"B","label":"Benar"},{"key":"S","label":"Salah"}]'::jsonb, '[{"id":"p1","text":"<p>Setiap persegi adalah belah ketupat.</p>","correctCategoryKey":"B"},{"id":"p2","text":"<p>Setiap belah ketupat adalah persegi.</p>","correctCategoryKey":"S","misconceptionId":"mis-msd-bangdat-002"},{"id":"p3","text":"<p>Segitiga sama sisi juga merupakan segitiga sama kaki.</p>","correctCategoryKey":"B"},{"id":"p4","text":"<p>Jajar genjang yang bukan persegi panjang mempunyai satu sumbu simetri.</p>","correctCategoryKey":"S","misconceptionId":"mis-msd-bangdat-003"},{"id":"p5","text":"<p>Segi delapan beraturan mempunyai 8 sisi yang sama panjang.</p>","correctCategoryKey":"B"}]'::jsonb, 'p1: B; p2: S; p3: B; p4: S; p5: B', false, null, null),
  ('msd-ruang-001', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-objek-geometri', 'con-matematika-sd-bangun-ruang-spasial', 'single', 'Memahami unsur-unsur balok', 'dasar', 'pemahaman', 'html', '<p>Sebuah kotak kado berbentuk balok akan dihias dengan pita di sepanjang setiap garis pertemuan dua sisinya.</p>', '<p>Banyak rusuk yang harus dilapisi pita adalah ....</p>', 'Pilih satu jawaban.', '<p>Balok mempunyai 12 rusuk: 4 rusuk panjang, 4 rusuk lebar, dan 4 rusuk tinggi.</p><p>Angka 6 adalah banyak sisinya dan angka 8 adalah banyak titik sudutnya, sehingga keduanya bukan jawaban yang diminta.</p>', '[{"key":"A","text":"<p>6 rusuk</p>","misconceptionId":"mis-msd-ruang-001"},{"key":"B","text":"<p>8 rusuk</p>","misconceptionId":"mis-msd-ruang-001"},{"key":"C","text":"<p>12 rusuk</p>"},{"key":"D","text":"<p>18 rusuk</p>","misconceptionId":"mis-msd-ruang-003"}]'::jsonb, 'C', null, null, null, 'C', false, null, null),
  ('msd-ruang-002', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-objek-geometri', 'con-matematika-sd-bangun-ruang-spasial', 'single', 'Memahami jaring-jaring kubus', 'dasar', 'pemahaman', 'html', '<p>Sebuah kubus dari karton dibuka pada beberapa rusuknya lalu dibentangkan mendatar sehingga menjadi jaring-jaring.</p>', '<p>Jaring-jaring kubus itu terdiri atas ....</p>', 'Pilih satu jawaban.', '<p>Kubus mempunyai 6 sisi berbentuk persegi yang sama besar, sehingga jaring-jaringnya juga terdiri atas 6 persegi yang sama besar.</p><p>Jawaban 5 persegi sering muncul karena sisi bawah terlewat saat dibentangkan, dan jawaban 8 tertukar dengan banyak titik sudut.</p>', '[{"key":"A","text":"<p>4 persegi yang sama besar</p>","misconceptionId":"mis-msd-ruang-001"},{"key":"B","text":"<p>5 persegi yang sama besar</p>","misconceptionId":"mis-msd-ruang-003"},{"key":"C","text":"<p>6 persegi yang sama besar</p>"},{"key":"D","text":"<p>8 persegi yang sama besar</p>","misconceptionId":"mis-msd-ruang-001"}]'::jsonb, 'C', null, null, null, 'C', false, null, null),
  ('msd-ruang-003', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-objek-geometri', 'con-matematika-sd-bangun-ruang-spasial', 'single', 'Mengaplikasikan penghitungan kubus satuan pada bangun gabungan', 'menengah', 'penerapan', 'html', '<p>Sebuah bangun disusun dari kubus satuan. Lapisan bawahnya berupa susunan 3 kubus ke arah kanan dan 2 kubus ke arah belakang, sehingga membentuk satu lapisan penuh. Di atas salah satu kubus sudut pada lapisan itu diletakkan 1 kubus lagi.</p>', '<p>Banyak kubus satuan yang menyusun bangun tersebut adalah ....</p>', 'Pilih satu jawaban.', '<p>Lapisan bawah berisi 3 × 2 = 6 kubus satuan.</p><p>Ditambah 1 kubus di atasnya, seluruhnya menjadi 6 + 1 = 7 kubus satuan.</p><p>Pilihan A muncul bila kubus di atas terlewat, sedangkan pilihan D muncul bila seluruh bangun dianggap balok penuh 3 × 2 × 2.</p>', '[{"key":"A","text":"<p>6 kubus</p>","misconceptionId":"mis-msd-ruang-003"},{"key":"B","text":"<p>7 kubus</p>"},{"key":"C","text":"<p>9 kubus</p>","misconceptionId":"mis-msd-ruang-002"},{"key":"D","text":"<p>12 kubus</p>","misconceptionId":"mis-msd-ruang-002"}]'::jsonb, 'B', null, null, null, 'B', true, 'Gambar isometrik tumpukan kubus satuan. Lapisan bawah berupa balok 3 kubus (ke kanan) × 2 kubus (ke belakang) × 1 kubus tinggi. Di atas kubus sudut kanan depan lapisan bawah diletakkan tepat 1 kubus satuan lagi. Semua kubus digambar sama besar dengan rusuk bergaris tegas, wajah atas lebih terang daripada wajah samping agar tumpukannya terbaca.', 'svg'),
  ('msd-ruang-004', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-objek-geometri', 'con-matematika-sd-bangun-ruang-spasial', 'single', 'Mengaplikasikan pembacaan pandangan samping suatu balok', 'menengah', 'penerapan', 'html', '<p>Sebuah balok disusun dari kubus satuan dengan panjang 4 satuan, lebar 2 satuan, dan tinggi 3 satuan. Pandangan depan menghadap sisi yang panjangnya 4 satuan.</p>', '<p>Banyak persegi satuan yang tampak pada pandangan samping balok itu adalah ....</p>', 'Pilih satu jawaban.', '<p>Pandangan samping memperlihatkan lebar dan tinggi, yaitu 2 satuan × 3 satuan = 6 persegi satuan.</p><p>Pandangan depan memperlihatkan panjang dan tinggi, yaitu 4 × 3 = 12 persegi satuan. Pandangan atas memperlihatkan panjang dan lebar, yaitu 4 × 2 = 8 persegi satuan.</p><p>Angka 24 adalah banyak kubus satuan seluruhnya, bukan banyak persegi pada satu pandangan.</p>', '[{"key":"A","text":"<p>6 persegi satuan</p>"},{"key":"B","text":"<p>8 persegi satuan</p>","misconceptionId":"mis-msd-ruang-002"},{"key":"C","text":"<p>12 persegi satuan</p>","misconceptionId":"mis-msd-ruang-002"},{"key":"D","text":"<p>24 persegi satuan</p>","misconceptionId":"mis-msd-ruang-003"}]'::jsonb, 'A', null, null, null, 'A', true, 'Gambar isometrik balok yang tersusun dari kubus satuan berukuran 4 kubus (panjang, ke kanan) × 2 kubus (lebar, ke belakang) × 3 kubus (tinggi). Beri tanda panah berlabel ''depan'' menghadap sisi panjang 4 dan panah berlabel ''samping'' menghadap sisi lebar 2. Kisi kubus satuan tampak pada setiap wajah yang terlihat.', 'svg'),
  ('msd-ruang-005', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-objek-geometri', 'con-matematika-sd-bangun-ruang-spasial', 'single', 'Mengaplikasikan penghitungan kubus satuan pada gabungan dua balok', 'menengah', 'penerapan', 'html', '<p>Sebuah tangga hiasan disusun dari kubus satuan. Balok bagian bawah berukuran 4 satuan × 2 satuan × 1 satuan, dan di atasnya diletakkan balok kedua berukuran 2 satuan × 2 satuan × 1 satuan.</p>', '<p>Banyak kubus satuan yang diperlukan untuk menyusun bangun itu adalah ....</p>', 'Pilih satu jawaban.', '<p>Balok bawah: 4 × 2 × 1 = 8 kubus satuan.</p><p>Balok atas: 2 × 2 × 1 = 4 kubus satuan.</p><p>Seluruhnya 8 + 4 = 12 kubus satuan. Pilihan D muncul bila bangunnya dianggap balok penuh 4 × 2 × 2.</p>', '[{"key":"A","text":"<p>10 kubus</p>","misconceptionId":"mis-msd-ruang-003"},{"key":"B","text":"<p>12 kubus</p>"},{"key":"C","text":"<p>14 kubus</p>","misconceptionId":"mis-msd-ruang-002"},{"key":"D","text":"<p>16 kubus</p>","misconceptionId":"mis-msd-ruang-002"}]'::jsonb, 'B', null, null, null, 'B', true, 'Gambar isometrik bangun gabungan dari kubus satuan. Balok bawah berukuran 4 kubus (ke kanan) × 2 kubus (ke belakang) × 1 kubus tinggi. Di atasnya, rata dengan tepi kiri dan tepi belakang, diletakkan balok kedua berukuran 2 kubus × 2 kubus × 1 kubus tinggi. Kisi kubus satuan tampak pada wajah-wajah yang terlihat.', 'svg'),
  ('msd-ruang-006', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-objek-geometri', 'con-matematika-sd-bangun-ruang-spasial', 'single', 'Bernalar tentang kubus bagian dalam yang tidak tampak', 'lanjut', 'penalaran', 'html', '<p>Sebuah kubus besar disusun dari 27 kubus satuan sehingga berukuran 3 satuan × 3 satuan × 3 satuan. Seluruh permukaan luar kubus besar itu dicelup cat. Setelah kering, kubus besar dibongkar kembali menjadi 27 kubus satuan.</p>', '<p>Banyak kubus satuan yang tidak terkena cat sama sekali adalah ....</p>', 'Pilih satu jawaban.', '<p>Kubus satuan tidak terkena cat hanya bila seluruh sisinya tidak menyentuh permukaan luar, yaitu kubus yang berada di bagian paling dalam.</p><p>Bagian dalam kubus 3 × 3 × 3 adalah kubus berukuran 1 × 1 × 1, karena satu lapisan terluar terkelupas dari setiap arah. Jadi ada 1 kubus satuan.</p><p>Angka 8 adalah banyak kubus di titik sudut, yang justru terkena cat pada tiga sisinya, dan angka 6 adalah banyak kubus di tengah setiap sisi.</p>', '[{"key":"A","text":"<p>0 kubus</p>","misconceptionId":"mis-msd-ruang-003"},{"key":"B","text":"<p>1 kubus</p>"},{"key":"C","text":"<p>6 kubus</p>","misconceptionId":"mis-msd-ruang-002"},{"key":"D","text":"<p>8 kubus</p>","misconceptionId":"mis-msd-ruang-001"}]'::jsonb, 'B', null, null, null, 'B', false, null, null),
  ('msd-ruang-007', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-objek-geometri', 'con-matematika-sd-bangun-ruang-spasial', 'single', 'Bernalar menyusun bangun dari tiga pandangan yang diketahui', 'lanjut', 'penalaran', 'html', '<p>Sebuah balok disusun dari kubus satuan. Hasil pengamatan mencatat bahwa pandangan depannya berupa 3 satuan × 2 satuan, pandangan sampingnya 2 satuan × 2 satuan, dan pandangan atasnya 3 satuan × 2 satuan.</p>', '<p>Banyak kubus satuan yang menyusun balok itu adalah ....</p>', 'Pilih satu jawaban.', '<p>Pandangan depan memperlihatkan panjang dan tinggi, jadi panjang 3 satuan dan tinggi 2 satuan.</p><p>Pandangan samping memperlihatkan lebar dan tinggi. Karena tingginya sudah 2 satuan, lebarnya 2 satuan.</p><p>Periksa dengan pandangan atas: panjang × lebar = 3 × 2, dan itu memang sesuai. Jadi banyak kubus satuan = 3 × 2 × 2 = 12.</p>', '[{"key":"A","text":"<p>7 kubus</p>","misconceptionId":"mis-msd-ruang-001"},{"key":"B","text":"<p>10 kubus</p>","misconceptionId":"mis-msd-ruang-002"},{"key":"C","text":"<p>12 kubus</p>"},{"key":"D","text":"<p>18 kubus</p>","misconceptionId":"mis-msd-ruang-003"}]'::jsonb, 'C', null, null, null, 'C', false, null, null),
  ('msd-ruang-008', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-objek-geometri', 'con-matematika-sd-bangun-ruang-spasial', 'mcma', 'Mengaplikasikan pengetahuan unsur kubus dan balok', 'menengah', 'penerapan', 'html', '<p>Kelas mendaftar pernyataan tentang kubus dan balok, lalu memeriksa mana yang benar.</p>', '<p>Pernyataan yang benar adalah ....</p>', 'Pilih semua jawaban yang benar.', '<p>A benar: seluruh rusuk kubus sama panjang, dan banyaknya 12.</p><p>B benar: keenam sisi balok berbentuk persegi panjang. Pada kubus, persegi panjang itu berupa persegi — persegi tetap termasuk persegi panjang.</p><p>C benar: kubus dan balok sama-sama mempunyai 8 titik sudut.</p><p>D salah: rusuk balok yang panjangnya, lebarnya, dan tingginya berbeda tidak sama panjang. Hanya kubus yang seluruh rusuknya sama.</p><p>E salah: kubus mempunyai 6 sisi, bukan 4.</p>', '[{"key":"A","text":"<p>Kubus mempunyai 12 rusuk yang sama panjang.</p>"},{"key":"B","text":"<p>Balok mempunyai 6 sisi yang berbentuk persegi panjang.</p>"},{"key":"C","text":"<p>Kubus mempunyai 8 titik sudut.</p>"},{"key":"D","text":"<p>Setiap balok mempunyai 12 rusuk yang sama panjang.</p>","misconceptionId":"mis-msd-ruang-004"},{"key":"E","text":"<p>Kubus mempunyai 4 sisi.</p>","misconceptionId":"mis-msd-ruang-001"}]'::jsonb, null, array['A', 'B', 'C'], null, null, 'A, B, C', false, null, null),
  ('msd-ruang-009', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-objek-geometri', 'con-matematika-sd-bangun-ruang-spasial', 'mcma', 'Bernalar tentang pandangan depan, atas, dan samping bangun gabungan', 'lanjut', 'penalaran', 'html', '<p>Sebuah bangun disusun dari 5 kubus satuan. Pada lapisan bawah, 3 kubus berjajar ke arah kanan dengan kedalaman 1 kubus. Di atas kubus paling kiri ditumpuk 2 kubus lagi, sehingga kolom paling kiri setinggi 3 kubus.</p>', '<p>Pernyataan yang benar tentang bangun itu adalah ....</p>', 'Pilih semua jawaban yang benar.', '<p>A benar: dilihat dari atas hanya panjang dan lebar yang tampak, yaitu 3 satuan × 1 satuan, berupa tiga persegi berjajar.</p><p>B benar: dari samping, lebarnya 1 satuan dan tinggi tertingginya 3 satuan, jadi tampak 1 × 3 = 3 persegi satuan.</p><p>C benar: dari depan tampak kolom kiri setinggi 3 persegi ditambah 1 persegi pada masing-masing kolom tengah dan kanan, yaitu 3 + 1 + 1 = 5 persegi satuan.</p><p>D salah: pada bangun ini pandangan depan berbentuk tangga sedangkan pandangan atas berupa deretan lurus.</p><p>E salah: kubus penyusunnya 3 di lapisan bawah dan 2 tumpukan tambahan, seluruhnya 5 kubus.</p>', '[{"key":"A","text":"<p>Pandangan atasnya berupa tiga persegi satuan yang berjajar.</p>"},{"key":"B","text":"<p>Pandangan sampingnya terdiri atas 3 persegi satuan.</p>"},{"key":"C","text":"<p>Pandangan depannya terdiri atas 5 persegi satuan.</p>"},{"key":"D","text":"<p>Pandangan depan dan pandangan atas suatu bangun selalu sama bentuknya.</p>","misconceptionId":"mis-msd-ruang-002"},{"key":"E","text":"<p>Banyak kubus satuan penyusunnya adalah 6.</p>","misconceptionId":"mis-msd-ruang-003"}]'::jsonb, null, array['A', 'B', 'C'], null, null, 'A, B, C', true, 'Gambar isometrik bangun dari 5 kubus satuan. Di lapisan bawah, 3 kubus berjajar ke arah kanan dengan kedalaman hanya 1 kubus. Di atas kubus paling kiri, ditumpuk 2 kubus lagi sehingga kolom kiri setinggi 3 kubus. Beri panah berlabel ''depan'' menghadap deretan 3 kubus tersebut.', 'svg'),
  ('msd-ruang-010', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-objek-geometri', 'con-matematika-sd-bangun-ruang-spasial', 'category', 'Bernalar menilai pernyataan tentang bangun ruang dan pandangannya', 'lanjut', 'penalaran', 'html', '<p>Lima pernyataan hasil diskusi tentang bangun ruang dan pandangannya dikumpulkan untuk diperiksa.</p>', '<p>Tentukan benar atau salah setiap pernyataan berikut.</p>', 'Tentukan kategori setiap pernyataan.', '<p>P1 benar: kubus memenuhi seluruh syarat balok, dengan tambahan semua rusuknya sama panjang.</p><p>P2 salah: balok berukuran 5 × 3 × 2 tidak mempunyai sisi berbentuk persegi sama sekali, karena tidak ada dua ukuran yang sama.</p><p>P3 benar: keenam sisi kubus berupa persegi yang sama besar, jadi bentangannya pun demikian.</p><p>P4 salah: dari atas hanya panjang dan lebar yang tampak. Tumpukan setinggi 1 kubus dan setinggi 5 kubus dapat memberi pandangan atas yang sama.</p><p>P5 salah: kedalaman bangun tidak tampak dari depan. Satu deret kubus dan dua deret kubus yang bertumpuk ke belakang memberi pandangan depan yang sama persis.</p>', null, null, null, '[{"key":"B","label":"Benar"},{"key":"S","label":"Salah"}]'::jsonb, '[{"id":"p1","text":"<p>Kubus adalah balok yang seluruh rusuknya sama panjang.</p>","correctCategoryKey":"B"},{"id":"p2","text":"<p>Setiap balok mempunyai paling sedikit dua sisi berbentuk persegi.</p>","correctCategoryKey":"S","misconceptionId":"mis-msd-ruang-004"},{"id":"p3","text":"<p>Jaring-jaring kubus selalu terdiri atas 6 persegi yang sama besar.</p>","correctCategoryKey":"B"},{"id":"p4","text":"<p>Pandangan atas suatu bangun memperlihatkan banyak lapisan tumpukan kubusnya.</p>","correctCategoryKey":"S","misconceptionId":"mis-msd-ruang-002"},{"id":"p5","text":"<p>Dua bangun yang pandangan depannya sama pasti tersusun dari kubus satuan sebanyak sama.</p>","correctCategoryKey":"S","misconceptionId":"mis-msd-ruang-005"}]'::jsonb, 'p1: B; p2: S; p3: B; p4: S; p5: S', false, null, null),
  ('msd-panjang-001', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-pengukuran', 'con-matematika-sd-panjang-satuan-baku', 'single', 'Memahami pemilihan satuan baku yang sesuai', 'dasar', 'pemahaman', 'html', '<p>Andi hendak mencatat panjang pensilnya di buku catatan. Pensil itu masih baru dan panjangnya sekitar sejengkal tangan anak.</p>', '<p>Satuan baku yang paling sesuai untuk menyatakan panjang pensil adalah ....</p>', 'Pilih satu jawaban.', '<p>Panjang pensil sekitar 17 cm, angka yang wajar dan mudah dibaca.</p><p>Dalam milimeter angkanya menjadi 170 mm yang terlalu rinci, sedangkan dalam meter menjadi 0,17 m dan dalam kilometer 0,00017 km yang jauh terlalu kecil untuk dicatat.</p>', '[{"key":"A","text":"<p>milimeter</p>","misconceptionId":"mis-msd-panjang-002"},{"key":"B","text":"<p>sentimeter</p>"},{"key":"C","text":"<p>meter</p>","misconceptionId":"mis-msd-panjang-002"},{"key":"D","text":"<p>kilometer</p>","misconceptionId":"mis-msd-panjang-002"}]'::jsonb, 'B', null, null, null, 'B', false, null, null),
  ('msd-panjang-002', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-pengukuran', 'con-matematika-sd-panjang-satuan-baku', 'single', 'Memahami pembacaan penggaris yang tidak dimulai dari nol', 'dasar', 'pemahaman', 'html', '<p>Sebuah pita diukur dengan penggaris. Ujung kiri pita berada tepat di angka 2 cm dan ujung kanannya tepat di angka 9,5 cm.</p>', '<p>Panjang pita itu adalah ....</p>', 'Pilih satu jawaban.', '<p>Panjang benda adalah selisih angka kedua ujungnya: 9,5 − 2 = 7,5 cm.</p><p>Pilihan C adalah angka di ujung kanan saja, yang hanya benar bila pita dimulai dari angka 0. Pilihan D didapat dengan menjumlahkan kedua angka.</p>', '[{"key":"A","text":"<p>7 cm</p>","misconceptionId":"mis-msd-panjang-004"},{"key":"B","text":"<p>7,5 cm</p>"},{"key":"C","text":"<p>9,5 cm</p>","misconceptionId":"mis-msd-panjang-001"},{"key":"D","text":"<p>11,5 cm</p>","misconceptionId":"mis-msd-panjang-001"}]'::jsonb, 'B', null, null, null, 'B', true, 'Penggaris mendatar berskala 0 sampai 15 cm dengan garis panjang tiap 1 cm dan garis pendek tiap 1 mm, angka tercetak jelas. Di atas penggaris tergambar sebuah pita berwarna hijau yang ujung kirinya tepat di angka 2 dan ujung kanannya tepat di angka 9,5. Jangan menuliskan panjang pita pada gambar.', 'svg'),
  ('msd-panjang-003', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-pengukuran', 'con-matematika-sd-panjang-satuan-baku', 'single', 'Mengaplikasikan penulisan hasil ukur gabungan cm dan mm', 'menengah', 'penerapan', 'html', '<p>Sebuah paku diukur dengan penggaris berskala milimeter. Hasilnya tercatat 4 cm lebih 6 mm.</p>', '<p>Panjang paku itu bila dinyatakan seluruhnya dalam milimeter adalah ....</p>', 'Pilih satu jawaban.', '<p>Ubah bagian sentimeternya lebih dahulu: 4 cm = 40 mm.</p><p>Lalu tambahkan sisanya: 40 + 6 = 46 mm. Panjang itu sama dengan 4,6 cm.</p><p>Pilihan A muncul bila 4 dan 6 dijumlahkan tanpa mengubah satuan, dan pilihan C keliru menuliskan bentuk sentimeter dengan satuan milimeter.</p>', '[{"key":"A","text":"<p>10 mm</p>","misconceptionId":"mis-msd-panjang-004"},{"key":"B","text":"<p>46 mm</p>"},{"key":"C","text":"<p>4,6 mm</p>","misconceptionId":"mis-msd-panjang-004"},{"key":"D","text":"<p>406 mm</p>","misconceptionId":"mis-msd-panjang-003"}]'::jsonb, 'B', null, null, null, 'B', false, null, null),
  ('msd-panjang-004', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-pengukuran', 'con-matematika-sd-panjang-satuan-baku', 'single', 'Mengaplikasikan pengukuran berulang dengan alat yang lebih pendek', 'menengah', 'penerapan', 'html', '<p>Panjang sebuah meja diukur memakai pensil yang panjangnya 15 cm. Pensil itu dapat diletakkan berturut-turut sebanyak 8 kali penuh, dan masih tersisa bagian meja sepanjang 6 cm.</p>', '<p>Panjang meja itu adalah ....</p>', 'Pilih satu jawaban.', '<p>Delapan kali panjang pensil = 8 × 15 = 120 cm.</p><p>Ditambah sisa 6 cm, panjang meja = 120 + 6 = 126 cm.</p><p>Pilihan A muncul bila sisanya dibuang, dan pilihan D bila sisanya dihitung sebagai satu pensil penuh.</p>', '[{"key":"A","text":"<p>120 cm</p>","misconceptionId":"mis-msd-panjang-005"},{"key":"B","text":"<p>121 cm</p>","misconceptionId":"mis-msd-panjang-004"},{"key":"C","text":"<p>126 cm</p>"},{"key":"D","text":"<p>138 cm</p>","misconceptionId":"mis-msd-panjang-005"}]'::jsonb, 'C', null, null, null, 'C', false, null, null),
  ('msd-panjang-005', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-pengukuran', 'con-matematika-sd-panjang-satuan-baku', 'single', 'Mengaplikasikan pembandingan hasil ukur yang satuannya berbeda', 'menengah', 'penerapan', 'html', '<p>Tiga potong tali diukur oleh tiga anak dengan cara pencatatan yang berbeda:</p><ul><li>Tali P: 1.250 mm</li><li>Tali Q: 1 m 30 cm</li><li>Tali R: 125 cm</li></ul>', '<p>Tali yang paling panjang adalah ....</p>', 'Pilih satu jawaban.', '<p>Seragamkan satuannya menjadi sentimeter: Tali P = 1.250 mm = 125 cm, Tali Q = 1 m 30 cm = 130 cm, dan Tali R = 125 cm.</p><p>Yang terpanjang adalah Tali Q, yaitu 130 cm.</p><p>Perhatikan bahwa Tali P dan Tali R sebenarnya sama panjang meski angkanya tampak jauh berbeda.</p>', '[{"key":"A","text":"<p>Tali P</p>","misconceptionId":"mis-msd-panjang-003"},{"key":"B","text":"<p>Tali Q</p>"},{"key":"C","text":"<p>Tali R</p>","misconceptionId":"mis-msd-panjang-004"},{"key":"D","text":"<p>ketiganya sama panjang</p>","misconceptionId":"mis-msd-panjang-003"}]'::jsonb, 'B', null, null, null, 'B', false, null, null),
  ('msd-panjang-006', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-pengukuran', 'con-matematika-sd-panjang-satuan-baku', 'single', 'Bernalar tentang sebab perbedaan hasil pengukuran', 'lanjut', 'penalaran', 'html', '<p>Dua siswa mengukur satu pita yang sama dengan penggaris yang sama. Nia melaporkan 24 cm, sedangkan Rio melaporkan 22 cm. Setelah diperiksa, penggarisnya tidak rusak dan pitanya tidak berubah.</p>', '<p>Penjelasan yang paling mungkin atas perbedaan itu adalah ....</p>', 'Pilih satu jawaban.', '<p>Beda 2 cm sama dengan pergeseran titik awal sebesar 2 cm. Bila pita diletakkan mulai dari angka 2 tetapi angka ujungnya dibaca apa adanya, hasilnya memang berbeda 2 cm dari pengukuran yang benar.</p><p>Justru itulah gunanya satuan baku: sentimeter bernilai sama bagi siapa pun, sehingga hasil ukur seharusnya dapat diperbandingkan — pilihan C bertentangan dengan gagasan satuan baku.</p><p>Panjang benda tidak berubah karena diukur, jadi pilihan B tidak mungkin.</p>', '[{"key":"A","text":"<p>Salah satu anak meletakkan ujung pita bukan di angka 0 lalu membaca angka ujung lainnya apa adanya.</p>"},{"key":"B","text":"<p>Panjang pita berubah karena diukur dua kali.</p>","misconceptionId":"mis-msd-panjang-003"},{"key":"C","text":"<p>Satuan sentimeter berbeda besarnya bagi setiap orang.</p>","misconceptionId":"mis-msd-panjang-002"},{"key":"D","text":"<p>Perbedaan itu wajar karena hasil pengukuran memang tidak dapat sama.</p>","misconceptionId":"mis-msd-panjang-001"}]'::jsonb, 'A', null, null, null, 'A', false, null, null),
  ('msd-panjang-007', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-pengukuran', 'con-matematika-sd-panjang-satuan-baku', 'single', 'Bernalar tentang hubungan besar satuan dan angka hasil ukur', 'lanjut', 'penalaran', 'html', '<p>Panjang sebuah meja tercatat 2 m. Guru menuliskannya ulang menjadi 200 cm. Seorang siswa berkata, “Berarti mejanya jadi jauh lebih panjang, karena angkanya bertambah besar.”</p>', '<p>Tanggapan yang tepat terhadap pendapat siswa itu adalah ....</p>', 'Pilih satu jawaban.', '<p>Satu meter memuat 100 sentimeter, sehingga 2 m memuat 200 cm. Kedua tulisan itu menyatakan panjang yang sama persis.</p><p>Semakin kecil satuan yang dipakai, semakin besar angkanya — tetapi bendanya tidak ikut berubah. Angka dan satuan harus selalu dibaca bersama-sama.</p>', '[{"key":"A","text":"<p>Benar, karena angka 200 lebih besar daripada 2 sehingga mejanya menjadi lebih panjang.</p>","misconceptionId":"mis-msd-panjang-003"},{"key":"B","text":"<p>Salah, karena sentimeter lebih kecil sehingga dibutuhkan lebih banyak; panjang mejanya tetap.</p>"},{"key":"C","text":"<p>Salah, karena 200 cm sebenarnya lebih pendek daripada 2 m bila diukur dengan penggaris.</p>","misconceptionId":"mis-msd-panjang-001"},{"key":"D","text":"<p>Benar, karena mengubah satuan berarti mengubah ukuran benda yang sedang diukur.</p>","misconceptionId":"mis-msd-panjang-002"}]'::jsonb, 'B', null, null, null, 'B', false, null, null),
  ('msd-panjang-008', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-pengukuran', 'con-matematika-sd-panjang-satuan-baku', 'mcma', 'Mengaplikasikan pemilihan satuan baku pada berbagai benda', 'menengah', 'penerapan', 'html', '<p>Kelas menyusun daftar satuan yang paling sesuai untuk mengukur berbagai benda dan jarak.</p>', '<p>Pilihan satuan yang sesuai adalah ....</p>', 'Pilih semua jawaban yang benar.', '<p>A sesuai: tinggi pintu sekitar 2 m.</p><p>B sesuai: tebal uang logam sekitar 2 mm, terlalu tipis untuk dinyatakan dalam sentimeter.</p><p>D sesuai: panjang buku tulis sekitar 25 cm.</p><p>C tidak sesuai: jarak antarkota puluhan kilometer, yang bila ditulis dalam sentimeter menjadi jutaan.</p><p>E tidak sesuai: panjang lapangan sekitar 100 m, yang menjadi 100.000 mm — angkanya terlalu besar untuk dibaca.</p>', '[{"key":"A","text":"<p>Tinggi pintu rumah dinyatakan dalam meter.</p>"},{"key":"B","text":"<p>Tebal uang logam dinyatakan dalam milimeter.</p>"},{"key":"C","text":"<p>Jarak antara dua kota dinyatakan dalam sentimeter.</p>","misconceptionId":"mis-msd-panjang-002"},{"key":"D","text":"<p>Panjang buku tulis dinyatakan dalam sentimeter.</p>"},{"key":"E","text":"<p>Panjang lapangan sepak bola dinyatakan dalam milimeter.</p>","misconceptionId":"mis-msd-panjang-002"}]'::jsonb, null, array['A', 'B', 'D'], null, null, 'A, B, D', false, null, null),
  ('msd-panjang-009', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-pengukuran', 'con-matematika-sd-panjang-satuan-baku', 'mcma', 'Bernalar tentang hasil pembacaan penggaris', 'lanjut', 'penalaran', 'html', '<p>Sebuah pita diletakkan di atas penggaris berskala sentimeter dan milimeter. Ujung kirinya berada di angka 3 dan ujung kanannya di angka 17,5.</p>', '<p>Pernyataan yang benar tentang pengukuran itu adalah ....</p>', 'Pilih semua jawaban yang benar.', '<p>A benar: 17,5 − 3 = 14,5 cm.</p><p>B benar: 14,5 cm = 145 mm, karena 1 cm = 10 mm.</p><p>C salah: 17,5 cm hanya benar bila pita dimulai dari angka 0.</p><p>D benar: menggeser benda tidak mengubah panjangnya, dan selisih kedua ujungnya tetap 14,5 cm.</p><p>E salah: 20,5 didapat dengan menjumlahkan 3 dan 17,5, bukan mengurangkannya.</p>', '[{"key":"A","text":"<p>Panjang pita 14,5 cm.</p>"},{"key":"B","text":"<p>Panjang pita 145 mm.</p>"},{"key":"C","text":"<p>Panjang pita 17,5 cm.</p>","misconceptionId":"mis-msd-panjang-001"},{"key":"D","text":"<p>Hasilnya tetap sama bila pita digeser sehingga ujung kirinya di angka 0 dan ujung kanannya di angka 14,5.</p>"},{"key":"E","text":"<p>Panjang pita 20,5 cm.</p>","misconceptionId":"mis-msd-panjang-001"}]'::jsonb, null, array['A', 'B', 'D'], null, null, 'A, B, D', false, null, null),
  ('msd-panjang-010', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-pengukuran', 'con-matematika-sd-panjang-satuan-baku', 'category', 'Bernalar menilai pernyataan tentang pengukuran panjang dengan satuan baku', 'lanjut', 'penalaran', 'html', '<p>Lima pernyataan tentang pengukuran panjang ditulis di papan tulis untuk diperiksa bersama.</p>', '<p>Tentukan benar atau salah setiap pernyataan berikut.</p>', 'Tentukan kategori setiap pernyataan.', '<p>P1 salah: benda boleh diletakkan mulai dari angka mana pun, asal panjangnya dihitung sebagai selisih kedua ujungnya. Memulai dari 0 hanya mempermudah pembacaan.</p><p>P2 benar: satu sentimeter dibagi menjadi 10 bagian milimeter pada penggaris.</p><p>P3 salah: yang bertambah hanya angkanya, bukan panjang bendanya.</p><p>P4 benar: 3 × 10 = 30, jadi keduanya panjang yang sama.</p><p>P5 benar: bila setiap orang memakai satuan sendiri seperti jengkal atau langkah, hasilnya tidak dapat diperbandingkan karena ukuran jengkal setiap orang berbeda.</p>', null, null, null, '[{"key":"B","label":"Benar"},{"key":"S","label":"Salah"}]'::jsonb, '[{"id":"p1","text":"<p>Pengukuran hanya sah bila benda diletakkan mulai dari angka 0 pada penggaris.</p>","correctCategoryKey":"S","misconceptionId":"mis-msd-panjang-001"},{"id":"p2","text":"<p>1 cm sama dengan 10 mm.</p>","correctCategoryKey":"B"},{"id":"p3","text":"<p>Benda yang diukur dengan satuan lebih kecil menjadi lebih panjang.</p>","correctCategoryKey":"S","misconceptionId":"mis-msd-panjang-003"},{"id":"p4","text":"<p>Hasil ukur 3 cm dan 30 mm menyatakan panjang yang sama.</p>","correctCategoryKey":"B"},{"id":"p5","text":"<p>Satuan baku dipakai agar hasil pengukuran orang yang berbeda tetap dapat diperbandingkan.</p>","correctCategoryKey":"B"}]'::jsonb, 'p1: S; p2: B; p3: S; p4: B; p5: B', false, null, null),
  ('msd-konvpanjang-001', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-pengukuran', 'con-matematika-sd-konversi-panjang', 'single', 'Memahami perubahan meter ke sentimeter', 'dasar', 'pemahaman', 'html', '<p>Panjang kain gorden tercatat 5 m pada nota pembelian. Penjahit ingin menuliskannya dalam sentimeter agar sesuai dengan alat ukurnya.</p>', '<p>Panjang kain itu sama dengan ....</p>', 'Pilih satu jawaban.', '<p>Dari m ke cm turun dua tangga, yaitu m ke dm lalu dm ke cm, sehingga dikali 10 × 10 = 100.</p><p>5 × 100 = 500 cm.</p><p>Pilihan A hanya turun satu tangga dan pilihan C turun tiga tangga.</p>', '[{"key":"A","text":"<p>50 cm</p>","misconceptionId":"mis-msd-konvpanjang-002"},{"key":"B","text":"<p>500 cm</p>"},{"key":"C","text":"<p>5.000 cm</p>","misconceptionId":"mis-msd-konvpanjang-003"},{"key":"D","text":"<p>0,05 cm</p>","misconceptionId":"mis-msd-konvpanjang-001"}]'::jsonb, 'B', null, null, null, 'B', false, null, null),
  ('msd-konvpanjang-002', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-pengukuran', 'con-matematika-sd-konversi-panjang', 'single', 'Memahami perubahan kilometer ke meter', 'dasar', 'pemahaman', 'html', '<p>Papan penunjuk di tepi jalan menyebutkan jarak ke pasar 3 km. Panitia jalan sehat ingin mencantumkannya dalam meter pada peta rute.</p>', '<p>Jarak itu sama dengan ....</p>', 'Pilih satu jawaban.', '<p>Dari km ke m turun tiga tangga: km ke hm, hm ke dam, dam ke m. Pengalinya 10 × 10 × 10 = 1.000.</p><p>3 × 1.000 = 3.000 m.</p><p>Pilihan B muncul bila tangga dam dilompati sehingga hanya dikali 100.</p>', '[{"key":"A","text":"<p>30 m</p>","misconceptionId":"mis-msd-konvpanjang-002"},{"key":"B","text":"<p>300 m</p>","misconceptionId":"mis-msd-konvpanjang-003"},{"key":"C","text":"<p>3.000 m</p>"},{"key":"D","text":"<p>30.000 m</p>","misconceptionId":"mis-msd-konvpanjang-004"}]'::jsonb, 'C', null, null, null, 'C', false, null, null),
  ('msd-konvpanjang-003', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-pengukuran', 'con-matematika-sd-konversi-panjang', 'single', 'Mengaplikasikan perubahan satuan naik tangga', 'menengah', 'penerapan', 'html', '<p>Sebuah gulungan benang layang-layang panjangnya tercatat 2.500 cm. Angka itu akan ditulis ulang dalam meter pada catatan lomba.</p>', '<p>Panjang benang itu sama dengan ....</p>', 'Pilih satu jawaban.', '<p>Dari cm ke m naik dua tangga, jadi dibagi 100.</p><p>2.500 : 100 = 25 m.</p><p>Pilihan A muncul bila komanya digeser tiga angka, dan pilihan D bila justru dikalikan.</p>', '[{"key":"A","text":"<p>2,5 m</p>","misconceptionId":"mis-msd-konvpanjang-004"},{"key":"B","text":"<p>25 m</p>"},{"key":"C","text":"<p>250 m</p>","misconceptionId":"mis-msd-konvpanjang-002"},{"key":"D","text":"<p>250.000 m</p>","misconceptionId":"mis-msd-konvpanjang-001"}]'::jsonb, 'B', null, null, null, 'B', false, null, null),
  ('msd-konvpanjang-004', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-pengukuran', 'con-matematika-sd-konversi-panjang', 'single', 'Mengaplikasikan penjumlahan panjang bersatuan berbeda', 'menengah', 'penerapan', 'html', '<p>Pak Rahmat menyambung dua batang bambu. Batang pertama panjangnya 4 dam dan batang kedua 6 m.</p>', '<p>Panjang bambu setelah disambung adalah ....</p>', 'Pilih satu jawaban.', '<p>Seragamkan satuannya lebih dahulu: 1 dam = 10 m, sehingga 4 dam = 40 m.</p><p>Panjang seluruhnya = 40 + 6 = 46 m.</p><p>Pilihan A muncul bila angka 4 dan 6 dijumlahkan tanpa mengubah satuan, dan pilihan D bila 1 dam dianggap 100 m.</p>', '[{"key":"A","text":"<p>10 m</p>","misconceptionId":"mis-msd-konvpanjang-005"},{"key":"B","text":"<p>46 m</p>"},{"key":"C","text":"<p>64 m</p>","misconceptionId":"mis-msd-konvpanjang-002"},{"key":"D","text":"<p>406 m</p>","misconceptionId":"mis-msd-konvpanjang-003"}]'::jsonb, 'B', null, null, null, 'B', false, null, null),
  ('msd-konvpanjang-005', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-pengukuran', 'con-matematika-sd-konversi-panjang', 'single', 'Mengaplikasikan penyeragaman tiga satuan panjang sekaligus', 'menengah', 'penerapan', 'html', '<p>Rute lari pagi terdiri atas tiga bagian: menyusuri jalan raya 1 km, memotong lapangan 250 m, dan melewati gang sepanjang 3.000 cm.</p>', '<p>Panjang seluruh rute itu adalah ....</p>', 'Pilih satu jawaban.', '<p>Ubah semuanya ke meter: 1 km = 1.000 m, 250 m tetap, dan 3.000 cm = 3.000 : 100 = 30 m.</p><p>Jumlahnya = 1.000 + 250 + 30 = 1.280 m.</p><p>Pilihan A muncul bila 3.000 cm dianggap 3 m, dan pilihan C bila dianggap 300 m.</p>', '[{"key":"A","text":"<p>1.253 m</p>","misconceptionId":"mis-msd-konvpanjang-005"},{"key":"B","text":"<p>1.280 m</p>"},{"key":"C","text":"<p>1.550 m</p>","misconceptionId":"mis-msd-konvpanjang-002"},{"key":"D","text":"<p>4.250 m</p>","misconceptionId":"mis-msd-konvpanjang-003"}]'::jsonb, 'B', null, null, null, 'B', false, null, null),
  ('msd-konvpanjang-006', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-pengukuran', 'con-matematika-sd-konversi-panjang', 'single', 'Bernalar mengurutkan panjang yang satuannya berbeda-beda', 'lanjut', 'penalaran', 'html', '<p>Empat jalur jalan sehat dicatat dengan satuan yang berbeda-beda:</p><ul><li>Jalur I: 0,5 km</li><li>Jalur II: 450 m</li><li>Jalur III: 48.000 cm</li><li>Jalur IV: 5.200 dm</li></ul>', '<p>Urutan jalur dari yang terpendek adalah ....</p>', 'Pilih satu jawaban.', '<p>Seragamkan semuanya ke meter:</p><ul><li>Jalur I: 0,5 km = 500 m</li><li>Jalur II: 450 m</li><li>Jalur III: 48.000 cm = 480 m</li><li>Jalur IV: 5.200 dm = 520 m</li></ul><p>Urutan dari terpendek: 450, 480, 500, 520, yaitu Jalur II, Jalur III, Jalur I, Jalur IV.</p><p>Bila hanya angkanya yang dibandingkan, jalur dengan satuan kecil seperti cm akan tampak paling panjang — padahal justru bukan.</p>', '[{"key":"A","text":"<p>Jalur II, Jalur III, Jalur I, Jalur IV</p>"},{"key":"B","text":"<p>Jalur I, Jalur II, Jalur III, Jalur IV</p>","misconceptionId":"mis-msd-konvpanjang-005"},{"key":"C","text":"<p>Jalur II, Jalur I, Jalur IV, Jalur III</p>","misconceptionId":"mis-msd-konvpanjang-001"},{"key":"D","text":"<p>Jalur IV, Jalur III, Jalur II, Jalur I</p>","misconceptionId":"mis-msd-konvpanjang-005"}]'::jsonb, 'A', null, null, null, 'A', false, null, null),
  ('msd-konvpanjang-007', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-pengukuran', 'con-matematika-sd-konversi-panjang', 'single', 'Bernalar tentang arah pengali pada tangga satuan', 'lanjut', 'penalaran', 'html', '<p>Untuk mengubah 7 km menjadi meter, Sinta membagi 7 dengan 1.000 dan memperoleh 0,007 m. Ia beralasan, “Angkanya harus dibagi karena satuannya berubah.”</p>', '<p>Tanggapan yang tepat terhadap pekerjaan Sinta adalah ....</p>', 'Pilih satu jawaban.', '<p>Satu kilometer sama dengan 1.000 meter, jadi 7 km jelas jauh lebih panjang daripada 7 m — hasil 0,007 m mustahil.</p><p>Karena satuan tujuannya lebih kecil, dibutuhkan lebih banyak satuan, sehingga angkanya dikali: 7 × 1.000 = 7.000 m.</p><p>Pengali 1.000 didapat dari tiga tangga km → hm → dam → m, jadi pilihan C juga keliru karena melompati satu tangga.</p>', '[{"key":"A","text":"<p>Benar, karena setiap perubahan satuan panjang selalu dikerjakan dengan pembagian.</p>","misconceptionId":"mis-msd-konvpanjang-001"},{"key":"B","text":"<p>Salah, karena meter lebih kecil daripada kilometer, jadi 7 × 1.000 = 7.000 m.</p>"},{"key":"C","text":"<p>Salah, karena pengalinya seharusnya 100 sehingga hasilnya menjadi 700 m.</p>","misconceptionId":"mis-msd-konvpanjang-002"},{"key":"D","text":"<p>Benar, tetapi hasil pembagiannya keliru sehingga seharusnya menjadi 0,7 m.</p>","misconceptionId":"mis-msd-konvpanjang-004"}]'::jsonb, 'B', null, null, null, 'B', false, null, null),
  ('msd-konvpanjang-008', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-pengukuran', 'con-matematika-sd-konversi-panjang', 'mcma', 'Mengaplikasikan kesetaraan antarsatuan panjang', 'menengah', 'penerapan', 'html', '<p>Kelas menuliskan beberapa kesetaraan satuan panjang di papan tulis untuk diperiksa.</p>', '<p>Kesetaraan yang benar adalah ....</p>', 'Pilih semua jawaban yang benar.', '<p>A benar: m ke dm turun satu tangga, jadi dikali 10.</p><p>B benar: hm ke m turun dua tangga, jadi dikali 100.</p><p>C salah: 1 cm = 10 mm, karena cm ke mm hanya turun satu tangga.</p><p>D benar: km ke hm turun satu tangga, jadi dikali 10.</p><p>E salah: 1 dam = 10 m, bukan 100 m.</p>', '[{"key":"A","text":"<p>1 m = 10 dm</p>"},{"key":"B","text":"<p>1 hm = 100 m</p>"},{"key":"C","text":"<p>1 cm = 100 mm</p>","misconceptionId":"mis-msd-konvpanjang-003"},{"key":"D","text":"<p>1 km = 10 hm</p>"},{"key":"E","text":"<p>1 dam = 100 m</p>","misconceptionId":"mis-msd-konvpanjang-003"}]'::jsonb, null, array['A', 'B', 'D'], null, null, 'A, B, D', false, null, null),
  ('msd-konvpanjang-009', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-pengukuran', 'con-matematika-sd-konversi-panjang', 'mcma', 'Bernalar tentang berbagai penulisan satu panjang yang sama', 'lanjut', 'penalaran', 'html', '<p>Panjang sebuah jalur sepeda adalah 2,4 km. Panitia menuliskannya dengan beberapa satuan berbeda untuk berbagai keperluan.</p>', '<p>Penulisan yang benar untuk panjang jalur itu adalah ....</p>', 'Pilih semua jawaban yang benar.', '<p>A benar: 2,4 × 1.000 = 2.400 m.</p><p>B benar: km ke hm turun satu tangga, jadi 2,4 × 10 = 24 hm.</p><p>C salah: km ke dam turun dua tangga, jadi 2,4 × 100 = 240 dam, bukan 2.400 dam.</p><p>D salah: 2.400 m = 240.000 cm. Angka 24.000 cm hanya sama dengan 240 m.</p><p>E benar: 2.400 m × 1.000 = 2.400.000 mm.</p>', '[{"key":"A","text":"<p>2.400 m</p>"},{"key":"B","text":"<p>24 hm</p>"},{"key":"C","text":"<p>2.400 dam</p>","misconceptionId":"mis-msd-konvpanjang-002"},{"key":"D","text":"<p>24.000 cm</p>","misconceptionId":"mis-msd-konvpanjang-004"},{"key":"E","text":"<p>2.400.000 mm</p>"}]'::jsonb, null, array['A', 'B', 'E'], null, null, 'A, B, E', false, null, null),
  ('msd-konvpanjang-010', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-pengukuran', 'con-matematika-sd-konversi-panjang', 'category', 'Bernalar menilai pernyataan tentang hubungan antar-satuan panjang', 'lanjut', 'penalaran', 'html', '<p>Lima pernyataan tentang satuan panjang dikumpulkan dari catatan siswa untuk diperiksa bersama.</p>', '<p>Tentukan benar atau salah setiap pernyataan berikut.</p>', 'Tentukan kategori setiap pernyataan.', '<p>P1 benar: dm ke cm turun satu tangga, jadi dikali 10.</p><p>P2 salah: 750 mm = 75 cm, karena mm ke cm naik satu tangga sehingga dibagi 10. Nilai 7,5 cm didapat bila dibagi 100.</p><p>P3 benar: 0,25 × 1.000 = 250 m.</p><p>P4 benar: 1 hm = 100 m sedangkan 1 dam = 10 m.</p><p>P5 salah: kilometer lebih besar daripada meter, jadi angkanya berkurang — meter dibagi 1.000 untuk menjadi kilometer.</p>', null, null, null, '[{"key":"B","label":"Benar"},{"key":"S","label":"Salah"}]'::jsonb, '[{"id":"p1","text":"<p>1 dm sama dengan 10 cm.</p>","correctCategoryKey":"B"},{"id":"p2","text":"<p>750 mm sama dengan 7,5 cm.</p>","correctCategoryKey":"S","misconceptionId":"mis-msd-konvpanjang-004"},{"id":"p3","text":"<p>0,25 km sama dengan 250 m.</p>","correctCategoryKey":"B"},{"id":"p4","text":"<p>1 hm lebih panjang daripada 1 dam.</p>","correctCategoryKey":"B"},{"id":"p5","text":"<p>Mengubah meter menjadi kilometer dilakukan dengan mengalikan 1.000.</p>","correctCategoryKey":"S","misconceptionId":"mis-msd-konvpanjang-001"}]'::jsonb, 'p1: B; p2: S; p3: B; p4: B; p5: S', false, null, null),
  ('msd-volbenda-001', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-pengukuran', 'con-matematika-sd-volume-satuan-baku', 'single', 'Memahami pemilihan satuan volume yang sesuai', 'dasar', 'pemahaman', 'html', '<p>Pada kemasan minuman kotak untuk anak, isi minuman perlu dicantumkan dengan satuan yang wajar. Isi satu kotak kira-kira sebanyak satu gelas minum.</p>', '<p>Satuan baku yang paling sesuai untuk mencantumkan isi minuman itu adalah ....</p>', 'Pilih satu jawaban.', '<p>Isi satu gelas minum kira-kira 200 ml, angka yang wajar dibaca.</p><p>Dalam liter angkanya menjadi 0,2 l, dalam hektoliter 0,002 hl, dan dalam kiloliter 0,0002 kl — semuanya terlalu kecil untuk dicantumkan pada kemasan.</p>', '[{"key":"A","text":"<p>mililiter</p>"},{"key":"B","text":"<p>liter</p>","misconceptionId":"mis-msd-volbenda-002"},{"key":"C","text":"<p>hektoliter</p>","misconceptionId":"mis-msd-volbenda-002"},{"key":"D","text":"<p>kiloliter</p>","misconceptionId":"mis-msd-volbenda-002"}]'::jsonb, 'A', null, null, null, 'A', false, null, null),
  ('msd-volbenda-002', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-pengukuran', 'con-matematika-sd-volume-satuan-baku', 'single', 'Memahami pembacaan skala gelas ukur', 'dasar', 'pemahaman', 'html', '<p>Sebuah gelas ukur mempunyai angka tercetak setiap 100 ml, dengan satu garis pendek tepat di tengah setiap dua angka. Permukaan air berada tepat pada garis pendek antara angka 300 dan 400.</p>', '<p>Volume air dalam gelas ukur itu adalah ....</p>', 'Pilih satu jawaban.', '<p>Selisih dua angka tercetak adalah 100 ml, dan di antaranya ada satu garis pendek yang membaginya menjadi dua bagian. Jadi satu garis pendek bernilai 50 ml.</p><p>Permukaan air pada garis di antara 300 dan 400 berarti 300 + 50 = 350 ml.</p>', '[{"key":"A","text":"<p>300 ml</p>","misconceptionId":"mis-msd-volbenda-003"},{"key":"B","text":"<p>3,5 ml</p>","misconceptionId":"mis-msd-volbenda-002"},{"key":"C","text":"<p>400 ml</p>","misconceptionId":"mis-msd-volbenda-003"},{"key":"D","text":"<p>350 ml</p>"}]'::jsonb, 'D', null, null, null, 'D', true, 'Gelas ukur tegak bening dengan skala di sisi kanan: angka tercetak 0, 100, 200, 300, 400, dan 500 ml, serta garis pendek tanpa angka tepat di tengah tiap dua angka (yaitu setiap 50 ml). Air berwarna biru muda mengisi gelas sampai garis pendek yang berada di antara angka 300 dan 400. Jangan menuliskan nilai volumenya pada gambar.', 'svg'),
  ('msd-volbenda-003', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-pengukuran', 'con-matematika-sd-volume-satuan-baku', 'single', 'Mengaplikasikan pembagian isi wadah besar ke wadah kecil', 'menengah', 'penerapan', 'html', '<p>Sebuah botol berisi penuh 600 ml sirop. Sirop itu dituang ke gelas-gelas kecil yang masing-masing berisi 150 ml sampai penuh.</p>', '<p>Banyak gelas penuh yang dapat diisi dari botol itu adalah ....</p>', 'Pilih satu jawaban.', '<p>Banyak gelas = 600 : 150 = 4 gelas.</p><p>Periksa: 4 × 150 = 600 ml, tepat habis tanpa sisa.</p>', '[{"key":"A","text":"<p>3 gelas</p>","misconceptionId":"mis-msd-volbenda-003"},{"key":"B","text":"<p>5 gelas</p>","misconceptionId":"mis-msd-volbenda-001"},{"key":"C","text":"<p>4 gelas</p>"},{"key":"D","text":"<p>45 gelas</p>","misconceptionId":"mis-msd-volbenda-002"}]'::jsonb, 'C', null, null, null, 'C', false, null, null),
  ('msd-volbenda-004', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-pengukuran', 'con-matematika-sd-volume-satuan-baku', 'single', 'Mengaplikasikan penambahan isi dengan satuan berbeda', 'menengah', 'penerapan', 'html', '<p>Sebuah ember sudah berisi 8 l air. Ke dalam ember itu dituangkan 3 botol air yang masing-masing berisi 750 ml.</p>', '<p>Isi ember sekarang adalah ....</p>', 'Pilih satu jawaban.', '<p>Air yang dituangkan = 3 × 750 = 2.250 ml = 2,25 l.</p><p>Isi ember = 8 + 2,25 = 10,25 l.</p><p>Pilihan A muncul bila hanya satu botol yang dihitung, dan pilihan B bila 750 ml dibulatkan menjadi 1 l.</p>', '[{"key":"A","text":"<p>8,75 l</p>","misconceptionId":"mis-msd-volbenda-003"},{"key":"B","text":"<p>11 l</p>","misconceptionId":"mis-msd-volbenda-005"},{"key":"C","text":"<p>10,75 l</p>","misconceptionId":"mis-msd-volbenda-001"},{"key":"D","text":"<p>10,25 l</p>"}]'::jsonb, 'D', null, null, null, 'D', false, null, null),
  ('msd-volbenda-005', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-pengukuran', 'con-matematika-sd-volume-satuan-baku', 'single', 'Mengaplikasikan pembagian volume secara merata', 'menengah', 'penerapan', 'html', '<p>Air sebanyak 2 l dituang rata ke dalam 8 gelas yang sama besar sampai seluruh air habis.</p>', '<p>Isi setiap gelas adalah ....</p>', 'Pilih satu jawaban.', '<p>Ubah lebih dahulu: 2 l = 2.000 ml.</p><p>Isi setiap gelas = 2.000 : 8 = 250 ml.</p><p>Periksa: 8 × 250 = 2.000 ml, sesuai. Pilihan D adalah pembagian untuk 5 gelas, bukan 8 gelas.</p>', '[{"key":"A","text":"<p>25 ml</p>","misconceptionId":"mis-msd-volbenda-002"},{"key":"B","text":"<p>160 ml</p>","misconceptionId":"mis-msd-volbenda-003"},{"key":"C","text":"<p>250 ml</p>"},{"key":"D","text":"<p>400 ml</p>","misconceptionId":"mis-msd-volbenda-001"}]'::jsonb, 'C', null, null, null, 'C', false, null, null),
  ('msd-volbenda-006', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-pengukuran', 'con-matematika-sd-volume-satuan-baku', 'single', 'Bernalar tentang tinggi permukaan air pada wadah berbeda bentuk', 'lanjut', 'penalaran', 'html', '<p>Air sebanyak 500 ml dituang ke Wadah P yang lebar dan pendek, lalu 500 ml lainnya dituang ke Wadah Q yang sempit dan tinggi. Ternyata permukaan air di Wadah Q jauh lebih tinggi daripada di Wadah P.</p>', '<p>Kesimpulan yang tepat tentang kedua wadah itu adalah ....</p>', 'Pilih satu jawaban.', '<p>Kedua wadah menerima 500 ml, jadi banyak airnya sama.</p><p>Pada wadah sempit, air yang sama harus menumpuk lebih tinggi karena luas dasarnya kecil. Pada wadah lebar, air itu menyebar sehingga permukaannya rendah.</p><p>Tinggi permukaan saja tidak dapat dipakai membandingkan volume, kecuali kedua wadah berukuran dasar sama.</p>', '[{"key":"A","text":"<p>Air di Wadah Q lebih banyak, karena permukaannya lebih tinggi.</p>","misconceptionId":"mis-msd-volbenda-001"},{"key":"B","text":"<p>Volume air berubah saat dituang ke wadah yang bentuknya berbeda.</p>","misconceptionId":"mis-msd-volbenda-005"},{"key":"C","text":"<p>Air di Wadah P lebih banyak, karena wadahnya lebih lebar.</p>","misconceptionId":"mis-msd-volbenda-001"},{"key":"D","text":"<p>Air di kedua wadah sama banyak; permukaan Wadah Q lebih tinggi karena dasarnya lebih sempit.</p>"}]'::jsonb, 'D', null, null, null, 'D', true, 'Dua wadah bening berdampingan di atas meja datar. Wadah kiri lebar dan pendek, wadah kanan sempit dan tinggi. Keduanya berisi air biru muda; permukaan air di wadah kanan jauh lebih tinggi daripada di wadah kiri, sedangkan luas daerah berisi air digambar sama besar. Beri label ''Wadah P'' pada yang lebar dan ''Wadah Q'' pada yang sempit, tanpa mencantumkan angka volume.', 'svg'),
  ('msd-volbenda-007', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-pengukuran', 'con-matematika-sd-volume-satuan-baku', 'single', 'Bernalar mengukur volume benda padat dari kenaikan air', 'lanjut', 'penalaran', 'html', '<p>Sebuah gelas ukur berisi air sampai angka 250 ml. Sebuah batu kecil dimasukkan sampai seluruhnya terbenam, dan permukaan air naik sampai angka 310 ml. Tidak ada air yang tercecer.</p>', '<p>Volume batu itu adalah ....</p>', 'Pilih satu jawaban.', '<p>Batu yang terbenam mendorong air ke atas sebanyak volume batu itu sendiri.</p><p>Volume batu = 310 − 250 = 60 ml.</p><p>Pilihan C adalah volume air dan batu bersama-sama, sedangkan pilihan D didapat dengan menjumlahkan kedua bacaan.</p>', '[{"key":"A","text":"<p>60 ml</p>"},{"key":"B","text":"<p>250 ml</p>","misconceptionId":"mis-msd-volbenda-004"},{"key":"C","text":"<p>310 ml</p>","misconceptionId":"mis-msd-volbenda-004"},{"key":"D","text":"<p>560 ml</p>","misconceptionId":"mis-msd-volbenda-005"}]'::jsonb, 'A', null, null, null, 'A', false, null, null),
  ('msd-volbenda-008', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-pengukuran', 'con-matematika-sd-volume-satuan-baku', 'mcma', 'Mengaplikasikan pemilihan satuan volume pada berbagai wadah', 'menengah', 'penerapan', 'html', '<p>Kelas menyusun daftar satuan yang wajar untuk menyatakan isi berbagai wadah.</p>', '<p>Pilihan satuan yang sesuai adalah ....</p>', 'Pilih semua jawaban yang benar.', '<p>A sesuai: isi satu sendok obat sekitar 5 ml.</p><p>B sesuai: isi bak mandi ratusan liter.</p><p>C sesuai: tangki kompleks perumahan bervolume puluhan kiloliter.</p><p>D tidak sesuai: isi gelas 200 ml sama dengan 0,0002 kl, angka yang tidak masuk akal untuk dicatat.</p><p>E tidak sesuai: satu tetes hanya sekitar 0,05 ml, jauh lebih kecil daripada satu hektoliter yang sama dengan 100 l.</p>', '[{"key":"A","text":"<p>Isi satu sendok obat dinyatakan dalam mililiter.</p>"},{"key":"B","text":"<p>Isi bak mandi dinyatakan dalam liter.</p>"},{"key":"C","text":"<p>Isi tangki air satu kompleks perumahan dinyatakan dalam kiloliter.</p>"},{"key":"D","text":"<p>Isi satu gelas minum dinyatakan dalam kiloliter.</p>","misconceptionId":"mis-msd-volbenda-002"},{"key":"E","text":"<p>Isi satu tetes obat mata dinyatakan dalam hektoliter.</p>","misconceptionId":"mis-msd-volbenda-002"}]'::jsonb, null, array['A', 'B', 'C'], null, null, 'A, B, C', false, null, null),
  ('msd-volbenda-009', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-pengukuran', 'con-matematika-sd-volume-satuan-baku', 'mcma', 'Bernalar tentang sisa isi setelah dituang berulang', 'lanjut', 'penalaran', 'html', '<p>Sebuah botol berisi penuh 1,5 l air. Air itu dituang ke 5 gelas, masing-masing berisi 200 ml sampai penuh.</p>', '<p>Pernyataan yang benar tentang keadaan air itu adalah ....</p>', 'Pilih semua jawaban yang benar.', '<p>Air yang dituang = 5 × 200 = 1.000 ml, jadi A benar.</p><p>Isi botol = 1,5 l = 1.500 ml, sehingga sisanya 1.500 − 1.000 = 500 ml, yaitu 0,5 l. B dan C benar dan menyatakan hal yang sama.</p><p>D salah karena masih ada sisa 500 ml.</p><p>E salah: 7 × 200 = 1.400 ml, masih kurang 100 ml dari 1.500 ml. Botol baru habis bila gelas terakhir tidak penuh.</p>', '[{"key":"A","text":"<p>Air yang dituang ke gelas seluruhnya 1.000 ml.</p>"},{"key":"B","text":"<p>Air yang tersisa di botol 500 ml.</p>"},{"key":"C","text":"<p>Air yang tersisa di botol 0,5 l.</p>"},{"key":"D","text":"<p>Air dalam botol tepat habis setelah kelima gelas terisi.</p>","misconceptionId":"mis-msd-volbenda-005"},{"key":"E","text":"<p>Air dalam botol tepat habis bila dituang ke 7 gelas berukuran 200 ml.</p>","misconceptionId":"mis-msd-volbenda-003"}]'::jsonb, null, array['A', 'B', 'C'], null, null, 'A, B, C', false, null, null),
  ('msd-volbenda-010', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-pengukuran', 'con-matematika-sd-volume-satuan-baku', 'category', 'Bernalar menilai pernyataan tentang pengukuran volume', 'lanjut', 'penalaran', 'html', '<p>Lima pernyataan tentang pengukuran volume dikumpulkan dari catatan kelas untuk diperiksa bersama.</p>', '<p>Tentukan benar atau salah setiap pernyataan berikut.</p>', 'Tentukan kategori setiap pernyataan.', '<p>P1 benar: l ke ml turun tiga tangga, jadi dikali 1.000.</p><p>P2 benar: menuang hanya mengubah bentuk permukaan air, bukan banyaknya.</p><p>P3 salah: pada wadah yang luas dasarnya berbeda, air sebanyak sama memberi tinggi permukaan yang berbeda.</p><p>P4 benar: kl ke l juga turun tiga tangga.</p><p>P5 salah: volumenya dapat diukur dari kenaikan permukaan air ketika benda itu dibenamkan ke dalam gelas ukur.</p>', null, null, null, '[{"key":"B","label":"Benar"},{"key":"S","label":"Salah"}]'::jsonb, '[{"id":"p1","text":"<p>1 liter sama dengan 1.000 mililiter.</p>","correctCategoryKey":"B"},{"id":"p2","text":"<p>Volume air tidak berubah meskipun dipindahkan ke wadah yang bentuknya berbeda.</p>","correctCategoryKey":"B"},{"id":"p3","text":"<p>Gelas yang permukaan airnya lebih tinggi selalu berisi air lebih banyak.</p>","correctCategoryKey":"S","misconceptionId":"mis-msd-volbenda-001"},{"id":"p4","text":"<p>1 kiloliter sama dengan 1.000 liter.</p>","correctCategoryKey":"B"},{"id":"p5","text":"<p>Volume benda padat yang bentuknya tidak beraturan tidak dapat diukur.</p>","correctCategoryKey":"S","misconceptionId":"mis-msd-volbenda-004"}]'::jsonb, 'p1: B; p2: B; p3: S; p4: B; p5: S', false, null, null),
  ('msd-konvvol-001', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-pengukuran', 'con-matematika-sd-konversi-volume', 'single', 'Memahami perubahan liter ke mililiter', 'dasar', 'pemahaman', 'html', '<p>Sebuah jeriken berisi 4 l minyak goreng. Penjual ingin menuliskan isinya dalam mililiter pada label kemasan kecil.</p>', '<p>Isi jeriken itu sama dengan ....</p>', 'Pilih satu jawaban.', '<p>Dari l ke ml turun tiga tangga: l ke dl, dl ke cl, cl ke ml. Pengalinya 10 × 10 × 10 = 1.000.</p><p>4 × 1.000 = 4.000 ml.</p><p>Pilihan B muncul bila satu tangga dilompati sehingga hanya dikali 100.</p>', '[{"key":"A","text":"<p>40 ml</p>","misconceptionId":"mis-msd-konvvol-002"},{"key":"B","text":"<p>400 ml</p>","misconceptionId":"mis-msd-konvvol-004"},{"key":"C","text":"<p>4.000 ml</p>"},{"key":"D","text":"<p>0,004 ml</p>","misconceptionId":"mis-msd-konvvol-001"}]'::jsonb, 'C', null, null, null, 'C', false, null, null),
  ('msd-konvvol-002', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-pengukuran', 'con-matematika-sd-konversi-volume', 'single', 'Memahami perubahan mililiter ke liter', 'dasar', 'pemahaman', 'html', '<p>Dua botol air masing-masing berisi 1.000 ml dituang ke dalam satu wadah, sehingga wadah itu berisi 2.000 ml air.</p>', '<p>Isi wadah itu sama dengan ....</p>', 'Pilih satu jawaban.', '<p>Dari ml ke l naik tiga tangga, jadi dibagi 1.000.</p><p>2.000 : 1.000 = 2 l.</p><p>Pilihan D muncul bila justru dikalikan 1.000; hasilnya jelas mustahil karena dua botol air tidak mungkin sebanyak dua juta liter.</p>', '[{"key":"A","text":"<p>0,2 l</p>","misconceptionId":"mis-msd-konvvol-002"},{"key":"B","text":"<p>2 l</p>"},{"key":"C","text":"<p>20 l</p>","misconceptionId":"mis-msd-konvvol-004"},{"key":"D","text":"<p>2.000.000 l</p>","misconceptionId":"mis-msd-konvvol-001"}]'::jsonb, 'B', null, null, null, 'B', false, null, null),
  ('msd-konvvol-003', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-pengukuran', 'con-matematika-sd-konversi-volume', 'single', 'Mengaplikasikan perubahan dekaliter ke liter', 'menengah', 'penerapan', 'html', '<p>Sebuah tandon air kecil berisi 5 dal air bersih. Petugas ingin mencatat isinya dalam liter di buku laporan.</p>', '<p>Isi tandon itu sama dengan ....</p>', 'Pilih satu jawaban.', '<p>Dari dal ke l turun satu tangga, jadi dikali 10.</p><p>5 × 10 = 50 l.</p><p>Pilihan C muncul bila dal dianggap berjarak dua tangga dari l, dan pilihan D bila dianggap tiga tangga.</p>', '[{"key":"A","text":"<p>0,5 l</p>","misconceptionId":"mis-msd-konvvol-001"},{"key":"B","text":"<p>50 l</p>"},{"key":"C","text":"<p>500 l</p>","misconceptionId":"mis-msd-konvvol-004"},{"key":"D","text":"<p>5.000 l</p>","misconceptionId":"mis-msd-konvvol-002"}]'::jsonb, 'B', null, null, null, 'B', false, null, null),
  ('msd-konvvol-004', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-pengukuran', 'con-matematika-sd-konversi-volume', 'single', 'Mengaplikasikan penjumlahan isi bersatuan berbeda', 'menengah', 'penerapan', 'html', '<p>Ke dalam sebuah teko dituangkan 3 l air panas, kemudian ditambah 250 ml air dingin.</p>', '<p>Isi teko itu bila dinyatakan seluruhnya dalam mililiter adalah ....</p>', 'Pilih satu jawaban.', '<p>Seragamkan satuannya: 3 l = 3.000 ml.</p><p>Isi teko = 3.000 + 250 = 3.250 ml, atau 3,25 l.</p><p>Pilihan A muncul bila angka 3 dan 250 langsung dijumlahkan tanpa mengubah satuan.</p>', '[{"key":"A","text":"<p>253 ml</p>","misconceptionId":"mis-msd-konvvol-005"},{"key":"B","text":"<p>550 ml</p>","misconceptionId":"mis-msd-konvvol-004"},{"key":"C","text":"<p>3.250 ml</p>"},{"key":"D","text":"<p>30.250 ml</p>","misconceptionId":"mis-msd-konvvol-002"}]'::jsonb, 'C', null, null, null, 'C', false, null, null),
  ('msd-konvvol-005', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-pengukuran', 'con-matematika-sd-konversi-volume', 'single', 'Mengaplikasikan penyeragaman tiga satuan volume sekaligus', 'menengah', 'penerapan', 'html', '<p>Persediaan air bersih di sebuah balai desa dicatat dalam tiga wadah: tandon utama 1 kl, tandon cadangan 5 hl, dan beberapa jeriken yang seluruhnya 20 l.</p>', '<p>Seluruh persediaan air itu adalah ....</p>', 'Pilih satu jawaban.', '<p>Ubah semuanya ke liter: 1 kl = 1.000 l, 5 hl = 5 × 100 = 500 l, dan 20 l tetap.</p><p>Jumlahnya = 1.000 + 500 + 20 = 1.520 l.</p><p>Pilihan B muncul bila 1 kl dianggap 100 l, dan pilihan C bila 5 hl dianggap 50 l.</p>', '[{"key":"A","text":"<p>1.520 l</p>"},{"key":"B","text":"<p>620 l</p>","misconceptionId":"mis-msd-konvvol-004"},{"key":"C","text":"<p>1.070 l</p>","misconceptionId":"mis-msd-konvvol-002"},{"key":"D","text":"<p>5.120 l</p>","misconceptionId":"mis-msd-konvvol-005"}]'::jsonb, 'A', null, null, null, 'A', false, null, null),
  ('msd-konvvol-006', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-pengukuran', 'con-matematika-sd-konversi-volume', 'single', 'Bernalar mengurutkan volume yang satuannya berbeda-beda', 'lanjut', 'penalaran', 'html', '<p>Empat tangki air dicatat dengan satuan yang berbeda-beda:</p><ul><li>Tangki I: 0,8 kl</li><li>Tangki II: 750 l</li><li>Tangki III: 85.000 cl</li><li>Tangki IV: 7.900 dl</li></ul>', '<p>Urutan tangki dari isi yang paling sedikit adalah ....</p>', 'Pilih satu jawaban.', '<p>Seragamkan semuanya ke liter:</p><ul><li>Tangki I: 0,8 kl = 800 l</li><li>Tangki II: 750 l</li><li>Tangki III: 85.000 cl = 85.000 : 100 = 850 l</li><li>Tangki IV: 7.900 dl = 7.900 : 10 = 790 l</li></ul><p>Urutan dari paling sedikit: 750, 790, 800, 850, yaitu Tangki II, Tangki IV, Tangki I, Tangki III.</p><p>Bila hanya angkanya yang dibandingkan, tangki bersatuan cl akan tampak paling banyak sekaligus paling menyesatkan.</p>', '[{"key":"A","text":"<p>Tangki II, Tangki IV, Tangki I, Tangki III</p>"},{"key":"B","text":"<p>Tangki I, Tangki II, Tangki IV, Tangki III</p>","misconceptionId":"mis-msd-konvvol-005"},{"key":"C","text":"<p>Tangki II, Tangki I, Tangki IV, Tangki III</p>","misconceptionId":"mis-msd-konvvol-002"},{"key":"D","text":"<p>Tangki III, Tangki IV, Tangki II, Tangki I</p>","misconceptionId":"mis-msd-konvvol-005"}]'::jsonb, 'A', null, null, null, 'A', false, null, null),
  ('msd-konvvol-007', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-pengukuran', 'con-matematika-sd-konversi-volume', 'single', 'Bernalar tentang hubungan sentiliter dan mililiter', 'lanjut', 'penalaran', 'html', '<p>Pada botol obat tertulis isi 20 cl. Andi berkata, “Berarti isinya 20 ml, karena cl dan ml sama saja.”</p>', '<p>Tanggapan yang tepat terhadap pendapat Andi adalah ....</p>', 'Pilih satu jawaban.', '<p>Pada tangga satuan volume, urutannya l, dl, cl, ml. Satuan cl berada satu tangga di atas ml, jadi 1 cl = 10 ml.</p><p>Isi botol = 20 × 10 = 200 ml, yaitu 0,2 l. Angka itu wajar untuk sebuah botol obat cair.</p><p>Pilihan C keliru karena memakai pengali dua tangga, padahal jaraknya hanya satu tangga.</p>', '[{"key":"A","text":"<p>Benar, karena keduanya satuan yang sangat kecil.</p>","misconceptionId":"mis-msd-konvvol-003"},{"key":"B","text":"<p>Salah, karena 1 cl sama dengan 10 ml sehingga isinya 200 ml.</p>"},{"key":"C","text":"<p>Salah, karena 1 cl sama dengan 100 ml sehingga isinya 2.000 ml.</p>","misconceptionId":"mis-msd-konvvol-002"},{"key":"D","text":"<p>Benar, tetapi isinya seharusnya ditulis 2 ml.</p>","misconceptionId":"mis-msd-konvvol-001"}]'::jsonb, 'B', null, null, null, 'B', false, null, null),
  ('msd-konvvol-008', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-pengukuran', 'con-matematika-sd-konversi-volume', 'mcma', 'Mengaplikasikan kesetaraan antarsatuan volume', 'menengah', 'penerapan', 'html', '<p>Beberapa kesetaraan satuan volume ditulis di papan tulis untuk diperiksa kebenarannya.</p>', '<p>Kesetaraan yang benar adalah ....</p>', 'Pilih semua jawaban yang benar.', '<p>A, B, dan C benar karena dl, cl, dan ml berturut-turut berjarak satu, dua, dan tiga tangga di bawah liter.</p><p>D salah: 1 dal = 10 l, karena dal hanya satu tangga di atas liter.</p><p>E salah: 1 hl = 100 l, karena hl berjarak dua tangga di atas liter.</p>', '[{"key":"A","text":"<p>1 l = 10 dl</p>"},{"key":"B","text":"<p>1 l = 100 cl</p>"},{"key":"C","text":"<p>1 l = 1.000 ml</p>"},{"key":"D","text":"<p>1 dal = 100 l</p>","misconceptionId":"mis-msd-konvvol-004"},{"key":"E","text":"<p>1 hl = 10 l</p>","misconceptionId":"mis-msd-konvvol-002"}]'::jsonb, null, array['A', 'B', 'C'], null, null, 'A, B, C', false, null, null),
  ('msd-konvvol-009', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-pengukuran', 'con-matematika-sd-konversi-volume', 'mcma', 'Bernalar tentang berbagai penulisan satu volume yang sama', 'lanjut', 'penalaran', 'html', '<p>Isi sebuah termos adalah 2,5 l. Isi itu akan dicatat dengan beberapa satuan berbeda untuk keperluan yang berbeda.</p>', '<p>Penulisan yang benar untuk isi termos itu adalah ....</p>', 'Pilih semua jawaban yang benar.', '<p>A benar: 2,5 × 1.000 = 2.500 ml.</p><p>B benar: 2,5 × 100 = 250 cl.</p><p>C benar: 2,5 × 10 = 25 dl.</p><p>D salah: l ke kl naik tiga tangga, jadi 2,5 : 1.000 = 0,0025 kl.</p><p>E salah: l ke dal naik satu tangga, jadi 2,5 : 10 = 0,25 dal. Angka 25 dal justru sama dengan 250 l.</p>', '[{"key":"A","text":"<p>2.500 ml</p>"},{"key":"B","text":"<p>250 cl</p>"},{"key":"C","text":"<p>25 dl</p>"},{"key":"D","text":"<p>0,025 kl</p>","misconceptionId":"mis-msd-konvvol-004"},{"key":"E","text":"<p>25 dal</p>","misconceptionId":"mis-msd-konvvol-001"}]'::jsonb, null, array['A', 'B', 'C'], null, null, 'A, B, C', false, null, null),
  ('msd-konvvol-010', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-pengukuran', 'con-matematika-sd-konversi-volume', 'category', 'Bernalar menilai pernyataan tentang hubungan antar-satuan volume', 'lanjut', 'penalaran', 'html', '<p>Lima pernyataan tentang satuan volume dikumpulkan untuk diperiksa bersama.</p>', '<p>Tentukan benar atau salah setiap pernyataan berikut.</p>', 'Tentukan kategori setiap pernyataan.', '<p>P1 benar: dl ke ml turun dua tangga, jadi dikali 100.</p><p>P2 benar: 500 : 1.000 = 0,5 l.</p><p>P3 salah: 1 kl = 1.000 l, karena kl berjarak tiga tangga di atas liter.</p><p>P4 benar: 6.000 : 100 = 60 l.</p><p>P5 salah: liter lebih besar daripada mililiter, jadi angkanya berkurang — mililiter dibagi 1.000 untuk menjadi liter.</p>', null, null, null, '[{"key":"B","label":"Benar"},{"key":"S","label":"Salah"}]'::jsonb, '[{"id":"p1","text":"<p>1 dl sama dengan 100 ml.</p>","correctCategoryKey":"B"},{"id":"p2","text":"<p>500 ml sama dengan 0,5 l.</p>","correctCategoryKey":"B"},{"id":"p3","text":"<p>1 kl sama dengan 100 l.</p>","correctCategoryKey":"S","misconceptionId":"mis-msd-konvvol-004"},{"id":"p4","text":"<p>6.000 cl sama dengan 60 l.</p>","correctCategoryKey":"B"},{"id":"p5","text":"<p>Mengubah mililiter menjadi liter dilakukan dengan mengalikan 1.000.</p>","correctCategoryKey":"S","misconceptionId":"mis-msd-konvvol-001"}]'::jsonb, 'p1: B; p2: B; p3: S; p4: B; p5: S', false, null, null),
  ('msd-berat-001', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-pengukuran', 'con-matematika-sd-berat-satuan-baku', 'single', 'Memahami pemilihan satuan berat yang sesuai', 'dasar', 'pemahaman', 'html', '<p>Petugas kesehatan sekolah mencatat berat badan siswa kelas lima pada kartu pemeriksaan. Berat badan siswa berkisar antara 25 sampai 40.</p>', '<p>Satuan baku yang paling sesuai untuk mencatat berat badan itu adalah ....</p>', 'Pilih satu jawaban.', '<p>Berat badan siswa sekitar 30 kg, angka yang wajar dicatat.</p><p>Dalam gram angkanya menjadi 30.000 g dan dalam miligram 30.000.000 mg — keduanya terlalu besar untuk kartu pemeriksaan. Dalam hektogram menjadi 300 hg, satuan yang tidak lazim untuk berat badan.</p>', '[{"key":"A","text":"<p>miligram</p>","misconceptionId":"mis-msd-berat-005"},{"key":"B","text":"<p>gram</p>","misconceptionId":"mis-msd-berat-005"},{"key":"C","text":"<p>kilogram</p>"},{"key":"D","text":"<p>hektogram</p>","misconceptionId":"mis-msd-berat-005"}]'::jsonb, 'C', null, null, null, 'C', false, null, null),
  ('msd-berat-002', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-pengukuran', 'con-matematika-sd-berat-satuan-baku', 'single', 'Memahami pembacaan skala timbangan', 'dasar', 'pemahaman', 'html', '<p>Sebuah timbangan mempunyai angka tercetak setiap 1 kg, dengan empat garis pendek di antara setiap dua angka. Jarum timbangan berhenti pada garis pendek kedua setelah angka 2.</p>', '<p>Berat benda yang ditimbang itu adalah ....</p>', 'Pilih satu jawaban.', '<p>Selisih dua angka tercetak adalah 1 kg = 1.000 g. Empat garis pendek membagi selang itu menjadi lima bagian, jadi satu garis pendek bernilai 1.000 : 5 = 200 g.</p><p>Garis kedua setelah angka 2 berarti 2 kg + 2 × 200 g = 2.000 + 400 = 2.400 g.</p><p>Pilihan A muncul bila garis dianggap bernilai 100 g, dan pilihan C bila banyak garis langsung ditulis sebagai gram.</p>', '[{"key":"A","text":"<p>2.200 g</p>","misconceptionId":"mis-msd-berat-003"},{"key":"B","text":"<p>2.400 g</p>"},{"key":"C","text":"<p>2.002 g</p>","misconceptionId":"mis-msd-berat-003"},{"key":"D","text":"<p>4.000 g</p>","misconceptionId":"mis-msd-berat-004"}]'::jsonb, 'B', null, null, null, 'B', true, 'Timbangan jarum berbentuk lingkaran dengan angka tercetak 0, 1, 2, 3, 4, dan 5 (satuan kg) searah jarum jam, serta empat garis pendek tanpa angka di antara setiap dua angka sehingga satu garis pendek bernilai 200 g. Jarum menunjuk pada garis pendek kedua setelah angka 2. Tambahkan tulisan ''kg'' kecil di tengah dial, tanpa menuliskan hasil pengukuran.', 'svg'),
  ('msd-berat-003', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-pengukuran', 'con-matematika-sd-berat-satuan-baku', 'single', 'Mengaplikasikan penjumlahan berat isi dan wadah', 'menengah', 'penerapan', 'html', '<p>Sebuah kotak kosong beratnya 400 g. Ke dalam kotak itu dimasukkan 12 bungkus biskuit yang masing-masing beratnya 250 g.</p>', '<p>Berat kotak beserta isinya adalah ....</p>', 'Pilih satu jawaban.', '<p>Berat seluruh biskuit = 12 × 250 = 3.000 g.</p><p>Berat kotak beserta isinya = 3.000 + 400 = 3.400 g = 3,4 kg.</p><p>Pilihan A muncul bila berat kotak diabaikan.</p>', '[{"key":"A","text":"<p>3 kg</p>","misconceptionId":"mis-msd-berat-002"},{"key":"B","text":"<p>3,4 kg</p>"},{"key":"C","text":"<p>3,25 kg</p>","misconceptionId":"mis-msd-berat-004"},{"key":"D","text":"<p>6,4 kg</p>","misconceptionId":"mis-msd-berat-003"}]'::jsonb, 'B', null, null, null, 'B', false, null, null),
  ('msd-berat-004', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-pengukuran', 'con-matematika-sd-berat-satuan-baku', 'single', 'Mengaplikasikan keadaan setimbang pada neraca dua lengan', 'menengah', 'penerapan', 'html', '<p>Sebuah neraca dua lengan berada dalam keadaan setimbang. Di piringan kiri terdapat benda X bersama anak timbangan 200 g, sedangkan di piringan kanan terdapat anak timbangan 500 g dan 250 g.</p>', '<p>Berat benda X adalah ....</p>', 'Pilih satu jawaban.', '<p>Karena setimbang, berat di kedua piringan sama: X + 200 = 500 + 250 = 750 g.</p><p>Jadi X = 750 − 200 = 550 g.</p><p>Pilihan D muncul bila anak timbangan 200 g ikut dijumlahkan, bukan dikurangkan.</p>', '[{"key":"A","text":"<p>350 g</p>","misconceptionId":"mis-msd-berat-004"},{"key":"B","text":"<p>450 g</p>","misconceptionId":"mis-msd-berat-003"},{"key":"C","text":"<p>550 g</p>"},{"key":"D","text":"<p>950 g</p>","misconceptionId":"mis-msd-berat-004"}]'::jsonb, 'C', null, null, null, 'C', true, 'Neraca dua lengan dalam keadaan setimbang, lengan mendatar rata. Di piringan kiri tergambar sebuah kotak berlabel ''X'' dan satu anak timbangan bertulis ''200 g''. Di piringan kanan tergambar dua anak timbangan bertulis ''500 g'' dan ''250 g''. Jangan menuliskan berat X pada gambar.', 'svg'),
  ('msd-berat-005', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-pengukuran', 'con-matematika-sd-berat-satuan-baku', 'single', 'Mengaplikasikan hubungan bruto, netto, dan tara', 'menengah', 'penerapan', 'html', '<p>Sekarung gula ditimbang beserta karungnya dan hasilnya 5 kg. Karung kosongnya sendiri beratnya 250 g.</p>', '<p>Berat bersih gula dalam karung itu adalah ....</p>', 'Pilih satu jawaban.', '<p>Berat kotor (bruto) 5 kg = 5.000 g, dan berat karung (tara) 250 g.</p><p>Berat bersih (netto) = 5.000 − 250 = 4.750 g = 4,75 kg.</p><p>Pilihan C keliru karena tara dijumlahkan; berat bersih tidak mungkin lebih besar daripada berat kotor.</p>', '[{"key":"A","text":"<p>4,5 kg</p>","misconceptionId":"mis-msd-berat-003"},{"key":"B","text":"<p>4,75 kg</p>"},{"key":"C","text":"<p>5,25 kg</p>","misconceptionId":"mis-msd-berat-004"},{"key":"D","text":"<p>2,5 kg</p>","misconceptionId":"mis-msd-berat-002"}]'::jsonb, 'B', null, null, null, 'B', false, null, null),
  ('msd-berat-006', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-pengukuran', 'con-matematika-sd-berat-satuan-baku', 'single', 'Bernalar tentang batas beban yang mencakup berat wadah', 'lanjut', 'penalaran', 'html', '<p>Sebuah tas hanya boleh menahan beban paling banyak 4 kg, terhitung tas beserta isinya. Tas kosong itu beratnya 500 g, dan setiap buku yang dimasukkan beratnya 250 g.</p>', '<p>Banyak buku terbanyak yang dapat dimasukkan ke tas itu adalah ....</p>', 'Pilih satu jawaban.', '<p>Batas beban 4 kg = 4.000 g sudah termasuk tasnya, jadi jatah untuk buku = 4.000 − 500 = 3.500 g.</p><p>Banyak buku = 3.500 : 250 = 14 buku.</p><p>Pilihan C muncul bila berat tas diabaikan, yaitu 4.000 : 250 = 16 buku — dan itu justru membuat beban menjadi 4.500 g, melampaui batas.</p>', '[{"key":"A","text":"<p>12 buku</p>","misconceptionId":"mis-msd-berat-003"},{"key":"B","text":"<p>14 buku</p>"},{"key":"C","text":"<p>16 buku</p>","misconceptionId":"mis-msd-berat-002"},{"key":"D","text":"<p>18 buku</p>","misconceptionId":"mis-msd-berat-002"}]'::jsonb, 'B', null, null, null, 'B', false, null, null),
  ('msd-berat-007', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-pengukuran', 'con-matematika-sd-berat-satuan-baku', 'single', 'Bernalar tentang hubungan besar benda dan beratnya', 'lanjut', 'penalaran', 'html', '<p>Di atas meja terdapat sekantong besar kapas dan sebuah paku besi kecil. Seorang siswa berkata, “Kantong kapasnya jauh lebih besar, jadi pasti lebih berat daripada pakunya.”</p>', '<p>Tanggapan yang tepat terhadap pendapat siswa itu adalah ....</p>', 'Pilih satu jawaban.', '<p>Besar benda dan beratnya adalah dua hal berbeda. Kapas ringan meski memakan banyak ruang, sedangkan besi berat meski kecil.</p><p>Karena itu kesimpulan hanya boleh diambil setelah keduanya ditimbang. Dalam hal ini kantong kapas memang bisa lebih berat atau lebih ringan, bergantung banyaknya kapas.</p><p>Pilihan C sama kelirunya dengan pilihan A, hanya berlawanan arah — keduanya membuat aturan umum yang tidak berlaku.</p>', '[{"key":"A","text":"<p>Benar, karena benda yang lebih besar sudah pasti lebih berat daripada benda kecil.</p>","misconceptionId":"mis-msd-berat-001"},{"key":"B","text":"<p>Belum tentu, karena berat bergantung pada bahannya sehingga keduanya harus ditimbang.</p>"},{"key":"C","text":"<p>Salah, karena benda yang lebih besar justru selalu lebih ringan daripada benda kecil.</p>","misconceptionId":"mis-msd-berat-001"},{"key":"D","text":"<p>Benar, karena satuan berat yang dipakai ditentukan oleh besar bendanya.</p>","misconceptionId":"mis-msd-berat-005"}]'::jsonb, 'B', null, null, null, 'B', false, null, null),
  ('msd-berat-008', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-pengukuran', 'con-matematika-sd-berat-satuan-baku', 'mcma', 'Mengaplikasikan pemilihan satuan berat pada berbagai benda', 'menengah', 'penerapan', 'html', '<p>Kelas menyusun daftar satuan yang wajar untuk menyatakan berat berbagai benda.</p>', '<p>Pilihan satuan yang sesuai adalah ....</p>', 'Pilih semua jawaban yang benar.', '<p>A sesuai: berat cincin beberapa gram.</p><p>B sesuai: berat sapi ratusan kilogram.</p><p>C sesuai: berat satu tablet beberapa ratus miligram.</p><p>D tidak sesuai: satu karung beras 25 kg sama dengan 25.000.000 mg.</p><p>E tidak sesuai: gajah seberat 4.000 kg menjadi 4.000.000 g — angkanya terlalu besar untuk dibaca.</p>', '[{"key":"A","text":"<p>Berat sebuah cincin dinyatakan dalam gram.</p>"},{"key":"B","text":"<p>Berat seekor sapi dinyatakan dalam kilogram.</p>"},{"key":"C","text":"<p>Berat satu butir tablet vitamin dinyatakan dalam miligram.</p>"},{"key":"D","text":"<p>Berat satu karung beras dinyatakan dalam miligram.</p>","misconceptionId":"mis-msd-berat-005"},{"key":"E","text":"<p>Berat seekor gajah dinyatakan dalam gram.</p>","misconceptionId":"mis-msd-berat-005"}]'::jsonb, null, array['A', 'B', 'C'], null, null, 'A, B, C', false, null, null),
  ('msd-berat-009', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-pengukuran', 'con-matematika-sd-berat-satuan-baku', 'mcma', 'Bernalar tentang berat gabungan beberapa barang belanjaan', 'lanjut', 'penalaran', 'html', '<p>Ibu membeli 1,5 kg gula, 750 g tepung, dan 2 bungkus mentega yang masing-masing beratnya 200 g.</p>', '<p>Pernyataan yang benar tentang belanjaan itu adalah ....</p>', 'Pilih semua jawaban yang benar.', '<p>Seragamkan ke gram: gula 1.500 g, tepung 750 g, dan mentega 2 × 200 = 400 g.</p><p>Jumlahnya 1.500 + 750 + 400 = 2.650 g = 2,65 kg, jadi A dan B benar dan E salah.</p><p>C benar karena 1.500 g paling besar di antara 1.500, 750, dan 400.</p><p>D salah: 400 g justru lebih ringan daripada 750 g.</p>', '[{"key":"A","text":"<p>Berat seluruh belanjaan 2.650 g.</p>"},{"key":"B","text":"<p>Berat seluruh belanjaan 2,65 kg.</p>"},{"key":"C","text":"<p>Gula adalah barang yang paling berat di antara ketiganya.</p>"},{"key":"D","text":"<p>Dua bungkus mentega lebih berat daripada tepungnya.</p>","misconceptionId":"mis-msd-berat-001"},{"key":"E","text":"<p>Berat seluruh belanjaan kurang dari 2 kg.</p>","misconceptionId":"mis-msd-berat-002"}]'::jsonb, null, array['A', 'B', 'C'], null, null, 'A, B, C', false, null, null),
  ('msd-berat-010', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-pengukuran', 'con-matematika-sd-berat-satuan-baku', 'category', 'Bernalar menilai pernyataan tentang pengukuran berat', 'lanjut', 'penalaran', 'html', '<p>Lima pernyataan tentang pengukuran berat dikumpulkan dari catatan kelas untuk diperiksa bersama.</p>', '<p>Tentukan benar atau salah setiap pernyataan berikut.</p>', 'Tentukan kategori setiap pernyataan.', '<p>P1 benar: kg ke g turun tiga tangga, jadi dikali 1.000.</p><p>P2 salah: wadah yang lebih besar hanya menambah berat wadahnya, sedangkan berat benda itu sendiri tidak berubah.</p><p>P3 benar: 2 kg = 2.000 g, dan 2.500 g lebih besar daripada 2.000 g.</p><p>P4 benar: berat bersih = berat kotor − tara, dan tara selalu bernilai lebih dari nol karena setiap wadah punya berat.</p><p>P5 salah: 1 hg = 100 g, karena hg hanya dua tangga di atas gram sedangkan kg tiga tangga.</p>', null, null, null, '[{"key":"B","label":"Benar"},{"key":"S","label":"Salah"}]'::jsonb, '[{"id":"p1","text":"<p>1 kg sama dengan 1.000 g.</p>","correctCategoryKey":"B"},{"id":"p2","text":"<p>Berat benda bertambah bila dipindahkan ke wadah yang lebih besar.</p>","correctCategoryKey":"S","misconceptionId":"mis-msd-berat-001"},{"id":"p3","text":"<p>Benda seberat 2.500 g lebih berat daripada benda seberat 2 kg.</p>","correctCategoryKey":"B"},{"id":"p4","text":"<p>Berat bersih suatu barang selalu lebih kecil daripada berat kotornya.</p>","correctCategoryKey":"B"},{"id":"p5","text":"<p>1 hg sama dengan 1.000 g.</p>","correctCategoryKey":"S","misconceptionId":"mis-msd-berat-004"}]'::jsonb, 'p1: B; p2: S; p3: B; p4: B; p5: S', false, null, null),
  ('msd-konvberat-001', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-pengukuran', 'con-matematika-sd-konversi-berat', 'single', 'Memahami perubahan kilogram ke gram', 'dasar', 'pemahaman', 'html', '<p>Sekantong tepung beratnya 3 kg. Penjual kue ingin menuliskan beratnya dalam gram supaya sesuai dengan takaran resepnya.</p>', '<p>Berat tepung itu sama dengan ....</p>', 'Pilih satu jawaban.', '<p>Dari kg ke g turun tiga tangga: kg ke hg, hg ke dag, dag ke g. Pengalinya 10 × 10 × 10 = 1.000.</p><p>3 × 1.000 = 3.000 g.</p><p>Pilihan B muncul bila satu tangga dilompati sehingga hanya dikali 100.</p>', '[{"key":"A","text":"<p>30 g</p>","misconceptionId":"mis-msd-konvberat-002"},{"key":"B","text":"<p>300 g</p>","misconceptionId":"mis-msd-konvberat-002"},{"key":"C","text":"<p>3.000 g</p>"},{"key":"D","text":"<p>30.000 g</p>","misconceptionId":"mis-msd-konvberat-004"}]'::jsonb, 'C', null, null, null, 'C', false, null, null),
  ('msd-konvberat-002', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-pengukuran', 'con-matematika-sd-konversi-berat', 'single', 'Memahami perubahan gram ke kilogram', 'dasar', 'pemahaman', 'html', '<p>Timbangan digital di pasar menunjukkan berat buah 5.000 g. Pembeli ingin mencatatnya dalam kilogram pada daftar belanjanya.</p>', '<p>Berat buah itu sama dengan ....</p>', 'Pilih satu jawaban.', '<p>Dari g ke kg naik tiga tangga, jadi dibagi 1.000.</p><p>5.000 : 1.000 = 5 kg.</p><p>Pilihan B muncul bila justru dikalikan; hasilnya mustahil karena sekantong buah tidak mungkin seberat lima juta kilogram.</p>', '[{"key":"A","text":"<p>0,5 kg</p>","misconceptionId":"mis-msd-konvberat-004"},{"key":"B","text":"<p>5.000.000 kg</p>","misconceptionId":"mis-msd-konvberat-001"},{"key":"C","text":"<p>50 kg</p>","misconceptionId":"mis-msd-konvberat-002"},{"key":"D","text":"<p>5 kg</p>"}]'::jsonb, 'D', null, null, null, 'D', false, null, null),
  ('msd-konvberat-003', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-pengukuran', 'con-matematika-sd-konversi-berat', 'single', 'Mengaplikasikan perubahan hektogram ke gram', 'menengah', 'penerapan', 'html', '<p>Pada bungkus kacang tertulis berat isi 4 hg. Pembeli ingin mengetahui berat itu dalam gram.</p>', '<p>Berat isi bungkus kacang itu sama dengan ....</p>', 'Pilih satu jawaban.', '<p>Dari hg ke g turun dua tangga: hg ke dag, dag ke g. Pengalinya 10 × 10 = 100.</p><p>4 × 100 = 400 g.</p><p>Pilihan C muncul bila hg dianggap sama jaraknya dengan kg terhadap gram, yaitu tiga tangga.</p>', '[{"key":"A","text":"<p>40 g</p>","misconceptionId":"mis-msd-konvberat-002"},{"key":"B","text":"<p>0,4 g</p>","misconceptionId":"mis-msd-konvberat-001"},{"key":"C","text":"<p>4.000 g</p>","misconceptionId":"mis-msd-konvberat-003"},{"key":"D","text":"<p>400 g</p>"}]'::jsonb, 'D', null, null, null, 'D', false, null, null),
  ('msd-konvberat-004', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-pengukuran', 'con-matematika-sd-konversi-berat', 'single', 'Mengaplikasikan penjumlahan berat bersatuan berbeda', 'menengah', 'penerapan', 'html', '<p>Sebuah keranjang belanja berisi 2 kg beras, 5 hg gula, dan 250 g garam.</p>', '<p>Berat seluruh isi keranjang itu adalah ....</p>', 'Pilih satu jawaban.', '<p>Seragamkan ke gram: 2 kg = 2.000 g, 5 hg = 5 × 100 = 500 g, dan 250 g tetap.</p><p>Jumlahnya = 2.000 + 500 + 250 = 2.750 g, atau 2,75 kg.</p><p>Pilihan B muncul bila 5 hg dianggap 50 g, dan pilihan D bila dianggap 5.000 g.</p>', '[{"key":"A","text":"<p>257 g</p>","misconceptionId":"mis-msd-konvberat-005"},{"key":"B","text":"<p>2.550 g</p>","misconceptionId":"mis-msd-konvberat-002"},{"key":"C","text":"<p>2.750 g</p>"},{"key":"D","text":"<p>7.250 g</p>","misconceptionId":"mis-msd-konvberat-003"}]'::jsonb, 'C', null, null, null, 'C', false, null, null),
  ('msd-konvberat-005', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-pengukuran', 'con-matematika-sd-konversi-berat', 'single', 'Mengaplikasikan perubahan miligram ke gram', 'menengah', 'penerapan', 'html', '<p>Pada kemasan obat tertulis bahwa satu bungkus mengandung 7.500 mg bahan aktif. Apoteker ingin mencatatnya dalam gram.</p>', '<p>Berat bahan aktif itu sama dengan ....</p>', 'Pilih satu jawaban.', '<p>Dari mg ke g naik tiga tangga: mg ke cg, cg ke dg, dg ke g. Jadi dibagi 1.000.</p><p>7.500 : 1.000 = 7,5 g.</p><p>Pilihan A muncul bila komanya digeser empat angka, dan pilihan C bila hanya digeser dua angka.</p>', '[{"key":"A","text":"<p>0,75 g</p>","misconceptionId":"mis-msd-konvberat-004"},{"key":"B","text":"<p>7.500.000 g</p>","misconceptionId":"mis-msd-konvberat-001"},{"key":"C","text":"<p>75 g</p>","misconceptionId":"mis-msd-konvberat-002"},{"key":"D","text":"<p>7,5 g</p>"}]'::jsonb, 'D', null, null, null, 'D', false, null, null),
  ('msd-konvberat-006', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-pengukuran', 'con-matematika-sd-konversi-berat', 'single', 'Bernalar mengurutkan berat yang satuannya berbeda-beda', 'lanjut', 'penalaran', 'html', '<p>Empat paket kiriman ditimbang dan dicatat dengan satuan yang berbeda-beda:</p><ul><li>Paket I: 0,4 kg</li><li>Paket II: 380 g</li><li>Paket III: 4.200 dg</li><li>Paket IV: 45.000 cg</li></ul>', '<p>Urutan paket dari yang paling ringan adalah ....</p>', 'Pilih satu jawaban.', '<p>Seragamkan semuanya ke gram:</p><ul><li>Paket I: 0,4 kg = 400 g</li><li>Paket II: 380 g</li><li>Paket III: 4.200 dg = 4.200 : 10 = 420 g</li><li>Paket IV: 45.000 cg = 45.000 : 100 = 450 g</li></ul><p>Urutan dari paling ringan: 380, 400, 420, 450, yaitu Paket II, Paket I, Paket III, Paket IV.</p><p>Paket bersatuan cg tampak berangka paling besar, padahal beratnya hanya 450 g.</p>', '[{"key":"A","text":"<p>Paket II, Paket I, Paket III, Paket IV</p>"},{"key":"B","text":"<p>Paket I, Paket II, Paket III, Paket IV</p>","misconceptionId":"mis-msd-konvberat-005"},{"key":"C","text":"<p>Paket II, Paket III, Paket I, Paket IV</p>","misconceptionId":"mis-msd-konvberat-002"},{"key":"D","text":"<p>Paket IV, Paket III, Paket II, Paket I</p>","misconceptionId":"mis-msd-konvberat-005"}]'::jsonb, 'A', null, null, null, 'A', false, null, null),
  ('msd-konvberat-007', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-pengukuran', 'con-matematika-sd-konversi-berat', 'single', 'Bernalar tentang kesetaraan dekagram dan gram', 'lanjut', 'penalaran', 'html', '<p>Rina menulis di bukunya, “1 dag sama dengan 100 g, karena setiap perpindahan satuan berat dikalikan 100.”</p>', '<p>Tanggapan yang tepat terhadap catatan Rina adalah ....</p>', 'Pilih satu jawaban.', '<p>Urutan tangga satuan berat adalah kg, hg, dag, g, dg, cg, mg, dan setiap tangga berkelipatan 10 — bukan 100.</p><p>Karena dag hanya satu tangga di atas gram, maka 1 dag = 10 g. Nilai 100 g diperoleh dari 1 hg, yang berjarak dua tangga.</p><p>Pengali 1.000 pada hubungan kg dan g muncul karena keduanya terpisah tiga tangga, bukan karena setiap tangga bernilai 1.000.</p>', '[{"key":"A","text":"<p>Benar, karena setiap tangga satuan berat memang berkelipatan 100.</p>","misconceptionId":"mis-msd-konvberat-003"},{"key":"B","text":"<p>Benar, karena dag dan hg sesungguhnya dua nama untuk satuan yang sama.</p>","misconceptionId":"mis-msd-konvberat-002"},{"key":"C","text":"<p>Salah, karena 1 dag sebenarnya sama dengan 1.000 g seperti hubungan kg dan g.</p>","misconceptionId":"mis-msd-konvberat-003"},{"key":"D","text":"<p>Salah, karena dag hanya satu tangga di atas gram, jadi 1 dag = 10 g.</p>"}]'::jsonb, 'D', null, null, null, 'D', false, null, null),
  ('msd-konvberat-008', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-pengukuran', 'con-matematika-sd-konversi-berat', 'mcma', 'Mengaplikasikan kesetaraan antarsatuan berat', 'menengah', 'penerapan', 'html', '<p>Beberapa kesetaraan satuan berat ditulis di papan tulis untuk diperiksa kebenarannya.</p>', '<p>Kesetaraan yang benar adalah ....</p>', 'Pilih semua jawaban yang benar.', '<p>A benar: kg ke hg turun satu tangga, jadi dikali 10.</p><p>B benar: g ke mg turun tiga tangga, jadi dikali 1.000.</p><p>C benar: dag ke g turun satu tangga, jadi dikali 10.</p><p>D salah: 1 hg = 100 g, karena hg dua tangga di atas gram.</p><p>E salah: 1 cg = 10 mg, karena cg hanya satu tangga di atas mg.</p>', '[{"key":"A","text":"<p>1 kg = 10 hg</p>"},{"key":"B","text":"<p>1 g = 1.000 mg</p>"},{"key":"C","text":"<p>1 dag = 10 g</p>"},{"key":"D","text":"<p>1 hg = 1.000 g</p>","misconceptionId":"mis-msd-konvberat-003"},{"key":"E","text":"<p>1 cg = 100 mg</p>","misconceptionId":"mis-msd-konvberat-003"}]'::jsonb, null, array['A', 'B', 'C'], null, null, 'A, B, C', false, null, null),
  ('msd-konvberat-009', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-pengukuran', 'con-matematika-sd-konversi-berat', 'mcma', 'Bernalar tentang berbagai penulisan satu berat yang sama', 'lanjut', 'penalaran', 'html', '<p>Berat sebuah paket adalah 1,25 kg. Berat itu akan dicatat dengan beberapa satuan berbeda pada formulir pengiriman.</p>', '<p>Penulisan yang benar untuk berat paket itu adalah ....</p>', 'Pilih semua jawaban yang benar.', '<p>A benar: 1,25 × 1.000 = 1.250 g.</p><p>B benar: kg ke hg turun satu tangga, jadi 1,25 × 10 = 12,5 hg.</p><p>C benar: kg ke dag turun dua tangga, jadi 1,25 × 100 = 125 dag.</p><p>D salah: 1.250 g = 1.250.000 mg. Angka 125.000 mg hanya sama dengan 125 g.</p><p>E salah: 12.500 g sama dengan 12,5 kg, sepuluh kali lebih berat daripada paket itu.</p>', '[{"key":"A","text":"<p>1.250 g</p>"},{"key":"B","text":"<p>12,5 hg</p>"},{"key":"C","text":"<p>125 dag</p>"},{"key":"D","text":"<p>125.000 mg</p>","misconceptionId":"mis-msd-konvberat-004"},{"key":"E","text":"<p>12.500 g</p>","misconceptionId":"mis-msd-konvberat-002"}]'::jsonb, null, array['A', 'B', 'C'], null, null, 'A, B, C', false, null, null),
  ('msd-konvberat-010', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-pengukuran', 'con-matematika-sd-konversi-berat', 'category', 'Bernalar menilai pernyataan tentang hubungan antar-satuan berat', 'lanjut', 'penalaran', 'html', '<p>Lima pernyataan tentang satuan berat dikumpulkan untuk diperiksa bersama.</p>', '<p>Tentukan benar atau salah setiap pernyataan berikut.</p>', 'Tentukan kategori setiap pernyataan.', '<p>P1 benar: hg ke g turun dua tangga, jadi dikali 100.</p><p>P2 salah: 250 mg = 0,25 g, karena mg ke g naik tiga tangga sehingga dibagi 1.000. Nilai 2,5 g sama dengan 2.500 mg.</p><p>P3 benar: 0,75 × 1.000 = 750 g.</p><p>P4 benar: dg berada satu tangga di atas cg, sehingga 1 dg = 10 cg.</p><p>P5 salah: gram lebih besar daripada miligram, jadi angkanya berkurang — miligram dibagi 1.000 untuk menjadi gram.</p>', null, null, null, '[{"key":"B","label":"Benar"},{"key":"S","label":"Salah"}]'::jsonb, '[{"id":"p1","text":"<p>1 hg sama dengan 100 g.</p>","correctCategoryKey":"B"},{"id":"p2","text":"<p>250 mg sama dengan 2,5 g.</p>","correctCategoryKey":"S","misconceptionId":"mis-msd-konvberat-004"},{"id":"p3","text":"<p>0,75 kg sama dengan 750 g.</p>","correctCategoryKey":"B"},{"id":"p4","text":"<p>1 dg lebih berat daripada 1 cg.</p>","correctCategoryKey":"B"},{"id":"p5","text":"<p>Mengubah miligram menjadi gram dilakukan dengan mengalikan 1.000.</p>","correctCategoryKey":"S","misconceptionId":"mis-msd-konvberat-001"}]'::jsonb, 'p1: B; p2: S; p3: B; p4: B; p5: S', false, null, null),
  ('msd-waktu-001', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-pengukuran', 'con-matematika-sd-waktu', 'single', 'Memahami pembacaan jam analog', 'dasar', 'pemahaman', 'html', '<p>Sebuah jam dinding di ruang kelas memperlihatkan jarum pendek berada di antara angka 7 dan 8, sedangkan jarum panjang menunjuk tepat pada angka 3.</p>', '<p>Waktu yang ditunjukkan jam itu adalah pukul ....</p>', 'Pilih satu jawaban.', '<p>Jarum pendek yang baru melewati angka 7 berarti jamnya masih 7, belum sampai 8.</p><p>Jarum panjang pada angka 3 berarti 3 × 5 = 15 menit.</p><p>Jadi waktunya pukul 07.15. Pilihan A muncul bila kedua jarum tertukar, dan pilihan B bila angka 3 langsung ditulis sebagai 3 menit.</p>', '[{"key":"A","text":"<p>03.35</p>","misconceptionId":"mis-msd-waktu-002"},{"key":"B","text":"<p>07.03</p>","misconceptionId":"mis-msd-waktu-002"},{"key":"C","text":"<p>07.15</p>"},{"key":"D","text":"<p>08.15</p>","misconceptionId":"mis-msd-waktu-003"}]'::jsonb, 'C', null, null, null, 'C', true, 'Jam analog bulat dengan angka 1 sampai 12 tercetak jelas dan garis menit kecil di tepinya. Jarum pendek berada di antara angka 7 dan 8, sedikit melewati angka 7. Jarum panjang menunjuk tepat pada angka 3. Bedakan tebal kedua jarum dengan jelas dan jangan menuliskan angka waktunya pada gambar.', 'svg'),
  ('msd-waktu-002', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-pengukuran', 'con-matematika-sd-waktu', 'single', 'Memahami hubungan penulisan 24 jam dan 12 jam', 'dasar', 'pemahaman', 'html', '<p>Jadwal keberangkatan kereta tertulis pukul 14.30 dengan penulisan 24 jam. Petugas ingin menyampaikannya secara lisan kepada penumpang dengan penulisan 12 jam.</p>', '<p>Pukul 14.30 sama dengan ....</p>', 'Pilih satu jawaban.', '<p>Setelah pukul 12.00, penulisan 24 jam dikurangi 12 untuk mendapatkan penulisan 12 jam: 14 − 12 = 2.</p><p>Karena masih di antara tengah hari dan senja, waktunya pukul 2.30 siang.</p><p>Pukul 2.30 malam ditulis 02.30 dalam penulisan 24 jam, jadi bukan pilihan D.</p>', '[{"key":"A","text":"<p>pukul 2.30 siang</p>"},{"key":"B","text":"<p>pukul 4.30 sore</p>","misconceptionId":"mis-msd-waktu-003"},{"key":"C","text":"<p>pukul 1.30 siang</p>","misconceptionId":"mis-msd-waktu-003"},{"key":"D","text":"<p>pukul 2.30 malam</p>","misconceptionId":"mis-msd-waktu-003"}]'::jsonb, 'A', null, null, null, 'A', false, null, null),
  ('msd-waktu-003', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-pengukuran', 'con-matematika-sd-waktu', 'single', 'Mengaplikasikan penghitungan lama perjalanan', 'menengah', 'penerapan', 'html', '<p>Sebuah bus berangkat dari terminal pukul 07.45 dan tiba di kota tujuan pukul 10.20 pada hari yang sama.</p>', '<p>Lama perjalanan bus itu adalah ....</p>', 'Pilih satu jawaban.', '<p>Dari pukul 07.45 sampai pukul 10.45 adalah 3 jam. Waktu tiba pukul 10.20 masih 25 menit sebelum itu.</p><p>Lama perjalanan = 3 jam − 25 menit = 2 jam 35 menit.</p><p>Pilihan B muncul bila 10,20 − 7,45 dihitung sebagai bilangan desimal. Perhatikan bahwa 75 menit sudah lebih dari satu jam, jadi penulisan itu tidak mungkin benar.</p>', '[{"key":"A","text":"<p>2 jam 35 menit</p>"},{"key":"B","text":"<p>2 jam 75 menit</p>","misconceptionId":"mis-msd-waktu-001"},{"key":"C","text":"<p>2 jam 45 menit</p>","misconceptionId":"mis-msd-waktu-001"},{"key":"D","text":"<p>3 jam 25 menit</p>","misconceptionId":"mis-msd-waktu-004"}]'::jsonb, 'A', null, null, null, 'A', false, null, null),
  ('msd-waktu-004', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-pengukuran', 'con-matematika-sd-waktu', 'single', 'Mengaplikasikan penentuan waktu mulai dari durasi', 'menengah', 'penerapan', 'html', '<p>Pemutaran film di aula berdurasi 1 jam 45 menit tanpa jeda, dan selesai tepat pukul 20.15.</p>', '<p>Pemutaran film itu dimulai pukul ....</p>', 'Pilih satu jawaban.', '<p>Kurangi jamnya lebih dahulu: 20.15 − 1 jam = 19.15.</p><p>Lalu kurangi 45 menit: 19.15 − 45 menit = 18.30, karena 15 menit dikurangi 45 menit perlu meminjam 60 menit dari jamnya.</p><p>Pilihan D muncul bila durasinya justru ditambahkan, bukan dikurangkan.</p>', '[{"key":"A","text":"<p>18.30</p>"},{"key":"B","text":"<p>18.70</p>","misconceptionId":"mis-msd-waktu-001"},{"key":"C","text":"<p>19.30</p>","misconceptionId":"mis-msd-waktu-001"},{"key":"D","text":"<p>22.00</p>","misconceptionId":"mis-msd-waktu-004"}]'::jsonb, 'A', null, null, null, 'A', false, null, null),
  ('msd-waktu-005', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-pengukuran', 'con-matematika-sd-waktu', 'single', 'Mengaplikasikan jadwal keberangkatan berulang', 'menengah', 'penerapan', 'html', '<p>Angkutan kota berangkat dari pangkalan setiap 25 menit. Keberangkatan pertama tepat pukul 06.00.</p>', '<p>Keberangkatan kelima terjadi pada pukul ....</p>', 'Pilih satu jawaban.', '<p>Keberangkatan pertama pukul 06.00 belum melewati satu selang, jadi sampai keberangkatan kelima hanya ada 4 selang.</p><p>4 × 25 menit = 100 menit = 1 jam 40 menit.</p><p>Pukul 06.00 + 1 jam 40 menit = 07.40. Pilihan D muncul bila selangnya dihitung 5 kali.</p>', '[{"key":"A","text":"<p>07.05</p>","misconceptionId":"mis-msd-waktu-004"},{"key":"B","text":"<p>07.25</p>","misconceptionId":"mis-msd-waktu-001"},{"key":"C","text":"<p>07.40</p>"},{"key":"D","text":"<p>08.05</p>","misconceptionId":"mis-msd-waktu-004"}]'::jsonb, 'C', null, null, null, 'C', false, null, null),
  ('msd-waktu-006', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-pengukuran', 'con-matematika-sd-waktu', 'single', 'Bernalar tentang penanggalan dan nama hari', 'lanjut', 'penalaran', 'html', '<p>Hari ini hari Rabu, tanggal 12 Maret. Sebuah kegiatan akan diadakan 25 hari setelah hari ini. Bulan Maret berisi 31 hari.</p>', '<p>Kegiatan itu jatuh pada ....</p>', 'Pilih satu jawaban.', '<p>Tanggal: 12 + 25 = 37. Karena Maret hanya 31 hari, maka 37 − 31 = 6, jadi tanggal 6 April.</p><p>Hari: 25 hari sama dengan 3 pekan lebih 4 hari, karena 25 = 3 × 7 + 4. Tiga pekan kembali ke hari Rabu, lalu maju 4 hari: Kamis, Jumat, Sabtu, Minggu.</p><p>Jadi kegiatan itu jatuh pada Minggu, 6 April.</p>', '[{"key":"A","text":"<p>6 April, hari Minggu</p>"},{"key":"B","text":"<p>6 April, hari Sabtu</p>","misconceptionId":"mis-msd-waktu-004"},{"key":"C","text":"<p>7 April, hari Minggu</p>","misconceptionId":"mis-msd-waktu-005"},{"key":"D","text":"<p>37 Maret, hari Minggu</p>","misconceptionId":"mis-msd-waktu-005"}]'::jsonb, 'A', null, null, null, 'A', false, null, null),
  ('msd-waktu-007', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-pengukuran', 'con-matematika-sd-waktu', 'single', 'Bernalar menilai cara menghitung selisih waktu', 'lanjut', 'penalaran', 'html', '<p>Doni menghitung lama kegiatan dari pukul 09.50 sampai pukul 12.20 dengan cara 12,20 − 9,50 = 2,70, lalu menulis hasilnya “2 jam 70 menit”.</p>', '<p>Tanggapan yang tepat terhadap pekerjaan Doni adalah ....</p>', 'Pilih satu jawaban.', '<p>Angka menit pada penulisan waktu bukan bilangan desimal, karena satu jam hanya memuat 60 menit — bukan 100.</p><p>Cara yang benar: dari 09.50 ke 12.50 adalah 3 jam, lalu dikurangi 30 menit karena kegiatannya berakhir pukul 12.20, sehingga hasilnya 2 jam 30 menit.</p><p>Penulisan “2 jam 70 menit” juga tidak mungkin benar karena 70 menit sudah melebihi satu jam dan seharusnya ditulis 3 jam 10 menit.</p>', '[{"key":"A","text":"<p>Benar, karena selisih waktu dihitung dengan mengurangkan angkanya.</p>","misconceptionId":"mis-msd-waktu-001"},{"key":"B","text":"<p>Salah, karena satu jam hanya 60 menit; lama kegiatan yang benar 2 jam 30 menit.</p>"},{"key":"C","text":"<p>Salah, karena lama kegiatan yang benar 3 jam 30 menit.</p>","misconceptionId":"mis-msd-waktu-004"},{"key":"D","text":"<p>Benar, tetapi hasilnya cukup ditulis 2,7 jam.</p>","misconceptionId":"mis-msd-waktu-001"}]'::jsonb, 'B', null, null, null, 'B', false, null, null),
  ('msd-waktu-008', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-pengukuran', 'con-matematika-sd-waktu', 'mcma', 'Mengaplikasikan penulisan waktu 12 jam dan 24 jam', 'menengah', 'penerapan', 'html', '<p>Kelas memeriksa beberapa pernyataan tentang penulisan waktu yang dipakai pada jadwal perjalanan.</p>', '<p>Pernyataan yang benar adalah ....</p>', 'Pilih semua jawaban yang benar.', '<p>A benar: 13 − 12 = 1, jadi pukul 1 siang.</p><p>B benar: penulisan 24 jam dimulai dari 00.00 pada tengah malam.</p><p>C benar: 19 − 12 = 7, jadi pukul 7.45 malam.</p><p>D salah: seperempat jam setelah tengah malam ditulis pukul 00.15, karena angka jam pada penulisan 24 jam hanya sampai 23.</p><p>E salah: tengah hari ditulis pukul 12.00, sedangkan pukul 24.00 sebenarnya sama dengan 00.00 pada hari berikutnya.</p>', '[{"key":"A","text":"<p>Pukul 13.00 sama dengan pukul 1 siang.</p>"},{"key":"B","text":"<p>Pukul 00.30 berarti setengah jam setelah tengah malam.</p>"},{"key":"C","text":"<p>Pukul 19.45 sama dengan pukul 7.45 malam.</p>"},{"key":"D","text":"<p>Seperempat jam setelah tengah malam ditulis pukul 24.15.</p>","misconceptionId":"mis-msd-waktu-003"},{"key":"E","text":"<p>Tengah hari ditulis pukul 24.00.</p>","misconceptionId":"mis-msd-waktu-003"}]'::jsonb, null, array['A', 'B', 'C'], null, null, 'A, B, C', false, null, null),
  ('msd-waktu-009', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-pengukuran', 'con-matematika-sd-waktu', 'mcma', 'Bernalar tentang lama kegiatan pada satu jadwal', 'lanjut', 'penalaran', 'html', '<p>Jadwal pagi di kelas lima tercatat sebagai berikut:</p><ul><li>Matematika: 07.00 sampai 08.20</li><li>Istirahat: 08.20 sampai 08.40</li><li>Bahasa Indonesia: 08.40 sampai 10.00</li></ul>', '<p>Pernyataan yang benar tentang jadwal itu adalah ....</p>', 'Pilih semua jawaban yang benar.', '<p>A benar: dari 07.00 ke 08.20 adalah 1 jam 20 menit.</p><p>B benar: dari 08.20 ke 08.40 adalah 20 menit.</p><p>C benar: dari 07.00 ke 10.00 adalah 3 jam.</p><p>D salah: Bahasa Indonesia dari 08.40 ke 10.00 juga 1 jam 20 menit, jadi sama lamanya.</p><p>E salah: ada dua pelajaran, sehingga tambahan seluruhnya 20 menit dan kegiatan berakhir pukul 10.20.</p>', '[{"key":"A","text":"<p>Pelajaran Matematika berlangsung 1 jam 20 menit.</p>"},{"key":"B","text":"<p>Istirahat berlangsung 20 menit.</p>"},{"key":"C","text":"<p>Seluruh kegiatan pagi itu berlangsung 3 jam.</p>"},{"key":"D","text":"<p>Bahasa Indonesia berlangsung lebih lama daripada Matematika.</p>","misconceptionId":"mis-msd-waktu-001"},{"key":"E","text":"<p>Bila setiap pelajaran ditambah 10 menit, kegiatan berakhir pukul 10.10.</p>","misconceptionId":"mis-msd-waktu-004"}]'::jsonb, null, array['A', 'B', 'C'], null, null, 'A, B, C', false, null, null),
  ('msd-waktu-010', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-pengukuran', 'con-matematika-sd-waktu', 'category', 'Bernalar menilai pernyataan tentang waktu', 'lanjut', 'penalaran', 'html', '<p>Lima pernyataan tentang waktu dikumpulkan dari catatan kelas untuk diperiksa bersama.</p>', '<p>Tentukan benar atau salah setiap pernyataan berikut.</p>', 'Tentukan kategori setiap pernyataan.', '<p>P1 benar: itulah dasar semua penghitungan waktu.</p><p>P2 benar: 15 − 12 = 3, jadi pukul 3 sore.</p><p>P3 benar: dari 08.40 ke 09.00 adalah 20 menit, ditambah 10 menit menjadi 30 menit.</p><p>P4 salah: karena satu jam bernilai 60 menit, bukan 100, pengurangan langsung memberi hasil keliru seperti “2 jam 70 menit”.</p><p>P5 salah: satu hari terdiri atas 24 jam. Angka 12 hanya banyak angka pada muka jam analog.</p>', null, null, null, '[{"key":"B","label":"Benar"},{"key":"S","label":"Salah"}]'::jsonb, '[{"id":"p1","text":"<p>1 jam sama dengan 60 menit.</p>","correctCategoryKey":"B"},{"id":"p2","text":"<p>Pukul 15.00 sama dengan pukul 3 sore.</p>","correctCategoryKey":"B"},{"id":"p3","text":"<p>Lama waktu dari pukul 08.40 sampai pukul 09.10 adalah 30 menit.</p>","correctCategoryKey":"B"},{"id":"p4","text":"<p>Selisih dua waktu dihitung dengan mengurangkan angkanya seperti bilangan biasa.</p>","correctCategoryKey":"S","misconceptionId":"mis-msd-waktu-001"},{"id":"p5","text":"<p>Satu hari terdiri atas 12 jam.</p>","correctCategoryKey":"S","misconceptionId":"mis-msd-waktu-003"}]'::jsonb, 'p1: B; p2: B; p3: B; p4: S; p5: S', false, null, null),
  ('msd-konvwaktu-001', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-pengukuran', 'con-matematika-sd-konversi-waktu', 'single', 'Memahami perubahan jam ke menit', 'dasar', 'pemahaman', 'html', '<p>Sebuah pelatihan berlangsung 3 jam tanpa jeda. Panitia ingin mencatat lamanya dalam menit pada laporan kegiatan.</p>', '<p>Lama pelatihan itu sama dengan ....</p>', 'Pilih satu jawaban.', '<p>Satu jam sama dengan 60 menit, jadi 3 jam = 3 × 60 = 180 menit.</p><p>Pilihan A dan C muncul bila pengalinya dianggap 10 atau 100 seperti pada satuan panjang.</p>', '[{"key":"A","text":"<p>30 menit</p>","misconceptionId":"mis-msd-konvwaktu-001"},{"key":"B","text":"<p>180 menit</p>"},{"key":"C","text":"<p>300 menit</p>","misconceptionId":"mis-msd-konvwaktu-001"},{"key":"D","text":"<p>0,05 menit</p>","misconceptionId":"mis-msd-konvwaktu-003"}]'::jsonb, 'B', null, null, null, 'B', false, null, null),
  ('msd-konvwaktu-002', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-pengukuran', 'con-matematika-sd-konversi-waktu', 'single', 'Memahami perubahan pekan ke hari', 'dasar', 'pemahaman', 'html', '<p>Libur sekolah berlangsung 2 pekan. Wali kelas ingin menuliskannya dalam hari pada surat pemberitahuan.</p>', '<p>Lama libur itu sama dengan ....</p>', 'Pilih satu jawaban.', '<p>Satu pekan sama dengan 7 hari, jadi 2 pekan = 2 × 7 = 14 hari.</p><p>Pilihan C dan D muncul bila pekan dianggap 10 atau 15 hari.</p>', '[{"key":"A","text":"<p>7 hari</p>","misconceptionId":"mis-msd-konvwaktu-003"},{"key":"B","text":"<p>14 hari</p>"},{"key":"C","text":"<p>20 hari</p>","misconceptionId":"mis-msd-konvwaktu-001"},{"key":"D","text":"<p>30 hari</p>","misconceptionId":"mis-msd-konvwaktu-001"}]'::jsonb, 'B', null, null, null, 'B', false, null, null),
  ('msd-konvwaktu-003', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-pengukuran', 'con-matematika-sd-konversi-waktu', 'single', 'Mengaplikasikan perubahan menit ke detik', 'menengah', 'penerapan', 'html', '<p>Waktu tempuh pelari terbaik pada lomba antarkelas tercatat 5 menit. Pencatat waktu ingin menuliskannya dalam detik pada papan hasil.</p>', '<p>Waktu tempuh itu sama dengan ....</p>', 'Pilih satu jawaban.', '<p>Satu menit sama dengan 60 detik, jadi 5 menit = 5 × 60 = 300 detik.</p><p>Pilihan D muncul bila justru dibagi 60; hasilnya mustahil karena 5 menit jelas jauh lebih lama daripada satu detik.</p>', '[{"key":"A","text":"<p>50 detik</p>","misconceptionId":"mis-msd-konvwaktu-001"},{"key":"B","text":"<p>300 detik</p>"},{"key":"C","text":"<p>500 detik</p>","misconceptionId":"mis-msd-konvwaktu-001"},{"key":"D","text":"<p>0,08 detik</p>","misconceptionId":"mis-msd-konvwaktu-003"}]'::jsonb, 'B', null, null, null, 'B', false, null, null),
  ('msd-konvwaktu-004', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-pengukuran', 'con-matematika-sd-konversi-waktu', 'single', 'Mengaplikasikan perubahan gabungan jam dan menit', 'menengah', 'penerapan', 'html', '<p>Ujian sekolah berlangsung 2 jam 15 menit. Pengawas ingin menuliskan seluruh waktunya dalam menit agar mudah dihitung dengan penghitung waktu.</p>', '<p>Lama ujian itu sama dengan ....</p>', 'Pilih satu jawaban.', '<p>Ubah bagian jamnya lebih dahulu: 2 jam = 2 × 60 = 120 menit.</p><p>Lalu tambahkan sisanya: 120 + 15 = 135 menit.</p><p>Pilihan C muncul bila angka 2 dan 15 langsung ditempelkan tanpa mengubah satuan.</p>', '[{"key":"A","text":"<p>75 menit</p>","misconceptionId":"mis-msd-konvwaktu-003"},{"key":"B","text":"<p>135 menit</p>"},{"key":"C","text":"<p>215 menit</p>","misconceptionId":"mis-msd-konvwaktu-001"},{"key":"D","text":"<p>230 menit</p>","misconceptionId":"mis-msd-konvwaktu-002"}]'::jsonb, 'B', null, null, null, 'B', false, null, null),
  ('msd-konvwaktu-005', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-pengukuran', 'con-matematika-sd-konversi-waktu', 'single', 'Mengaplikasikan penyeragaman tiga satuan waktu sekaligus', 'menengah', 'penerapan', 'html', '<p>Latihan drum band terdiri atas tiga bagian: pemanasan 1 jam, latihan pola 45 menit, dan penenangan 120 detik.</p>', '<p>Lama seluruh latihan itu bila dinyatakan dalam menit adalah ....</p>', 'Pilih satu jawaban.', '<p>Ubah semuanya ke menit: 1 jam = 60 menit, 45 menit tetap, dan 120 detik = 120 : 60 = 2 menit.</p><p>Jumlahnya = 60 + 45 + 2 = 107 menit.</p><p>Pilihan A muncul bila penenangan diabaikan, dan pilihan D bila 120 detik dianggap 120 menit.</p>', '[{"key":"A","text":"<p>105 menit</p>","misconceptionId":"mis-msd-konvwaktu-005"},{"key":"B","text":"<p>107 menit</p>"},{"key":"C","text":"<p>166 menit</p>","misconceptionId":"mis-msd-konvwaktu-001"},{"key":"D","text":"<p>225 menit</p>","misconceptionId":"mis-msd-konvwaktu-003"}]'::jsonb, 'B', null, null, null, 'B', false, null, null),
  ('msd-konvwaktu-006', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-pengukuran', 'con-matematika-sd-konversi-waktu', 'single', 'Bernalar mengurutkan lama waktu yang satuannya berbeda-beda', 'lanjut', 'penalaran', 'html', '<p>Empat kegiatan dicatat dengan satuan waktu yang berbeda-beda:</p><ul><li>Kegiatan I: 1/2 jam</li><li>Kegiatan II: 1.500 detik</li><li>Kegiatan III: 20 menit</li><li>Kegiatan IV: 0,6 jam</li></ul>', '<p>Urutan kegiatan dari yang paling singkat adalah ....</p>', 'Pilih satu jawaban.', '<p>Seragamkan semuanya ke menit:</p><ul><li>Kegiatan I: 1/2 jam = 30 menit</li><li>Kegiatan II: 1.500 detik = 1.500 : 60 = 25 menit</li><li>Kegiatan III: 20 menit</li><li>Kegiatan IV: 0,6 jam = 0,6 × 60 = 36 menit</li></ul><p>Urutan dari paling singkat: 20, 25, 30, 36, yaitu Kegiatan III, II, I, IV.</p><p>Kegiatan bersatuan detik berangka paling besar, padahal justru bukan yang paling lama.</p>', '[{"key":"A","text":"<p>Kegiatan III, Kegiatan II, Kegiatan I, Kegiatan IV</p>"},{"key":"B","text":"<p>Kegiatan I, Kegiatan II, Kegiatan III, Kegiatan IV</p>","misconceptionId":"mis-msd-konvwaktu-005"},{"key":"C","text":"<p>Kegiatan III, Kegiatan I, Kegiatan IV, Kegiatan II</p>","misconceptionId":"mis-msd-konvwaktu-005"},{"key":"D","text":"<p>Kegiatan IV, Kegiatan I, Kegiatan II, Kegiatan III</p>","misconceptionId":"mis-msd-konvwaktu-002"}]'::jsonb, 'A', null, null, null, 'A', false, null, null),
  ('msd-konvwaktu-007', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-pengukuran', 'con-matematika-sd-konversi-waktu', 'single', 'Bernalar tentang pengali antarsatuan waktu', 'lanjut', 'penalaran', 'html', '<p>Wira berpendapat, “Satu jam sama dengan 100 menit, sebab setiap perpindahan satuan pasti berkelipatan 10 atau 100 seperti pada satuan panjang.”</p>', '<p>Tanggapan yang tepat terhadap pendapat Wira adalah ....</p>', 'Pilih satu jawaban.', '<p>Satuan panjang, berat, dan volume memang berkelipatan 10 pada setiap tangganya, tetapi satuan waktu tidak.</p><p>Hubungan yang benar: 1 menit = 60 detik, 1 jam = 60 menit, 1 hari = 24 jam, 1 pekan = 7 hari, dan 1 tahun = 12 bulan. Angka 24 pada pilihan C adalah banyak jam dalam satu hari, bukan banyak menit dalam satu jam.</p>', '[{"key":"A","text":"<p>Benar, karena semua satuan ukur memakai tangga puluhan tanpa kecuali.</p>","misconceptionId":"mis-msd-konvwaktu-001"},{"key":"B","text":"<p>Salah, karena satuan waktu tidak bertangga puluhan: 1 jam = 60 menit.</p>"},{"key":"C","text":"<p>Salah, karena satu jam sebenarnya terdiri atas 24 menit, bukan 100 menit.</p>","misconceptionId":"mis-msd-konvwaktu-003"},{"key":"D","text":"<p>Benar, tetapi aturan itu hanya berlaku pada perubahan menit ke detik.</p>","misconceptionId":"mis-msd-konvwaktu-001"}]'::jsonb, 'B', null, null, null, 'B', false, null, null),
  ('msd-konvwaktu-008', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-pengukuran', 'con-matematika-sd-konversi-waktu', 'mcma', 'Mengaplikasikan kesetaraan antarsatuan waktu', 'menengah', 'penerapan', 'html', '<p>Beberapa kesetaraan satuan waktu ditulis di papan tulis untuk diperiksa kebenarannya.</p>', '<p>Kesetaraan yang benar adalah ....</p>', 'Pilih semua jawaban yang benar.', '<p>A, B, dan C adalah hubungan baku antarsatuan waktu.</p><p>D salah: 1 jam = 60 menit.</p><p>E salah: 1 tahun = 12 bulan. Angka 10 hanya berlaku pada tangga satuan panjang, berat, dan volume.</p>', '[{"key":"A","text":"<p>1 menit = 60 detik</p>"},{"key":"B","text":"<p>1 hari = 24 jam</p>"},{"key":"C","text":"<p>1 pekan = 7 hari</p>"},{"key":"D","text":"<p>1 jam = 100 menit</p>","misconceptionId":"mis-msd-konvwaktu-001"},{"key":"E","text":"<p>1 tahun = 10 bulan</p>","misconceptionId":"mis-msd-konvwaktu-001"}]'::jsonb, null, array['A', 'B', 'C'], null, null, 'A, B, C', false, null, null),
  ('msd-konvwaktu-009', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-pengukuran', 'con-matematika-sd-konversi-waktu', 'mcma', 'Bernalar tentang berbagai penulisan satu lama waktu yang sama', 'lanjut', 'penalaran', 'html', '<p>Latihan paduan suara berlangsung 2,5 jam. Lama itu dicatat dengan beberapa cara berbeda pada buku kegiatan.</p>', '<p>Penulisan yang benar untuk lama latihan itu adalah ....</p>', 'Pilih semua jawaban yang benar.', '<p>A benar: 2,5 × 60 = 150 menit.</p><p>B benar: 150 × 60 = 9.000 detik.</p><p>C salah: angka 250 muncul bila pengalinya dianggap 100.</p><p>D benar: 0,5 jam berarti setengah jam, yaitu 30 menit.</p><p>E salah: angka 5 di belakang koma bukan 5 menit, melainkan setengah jam.</p>', '[{"key":"A","text":"<p>150 menit</p>"},{"key":"B","text":"<p>9.000 detik</p>"},{"key":"C","text":"<p>250 menit</p>","misconceptionId":"mis-msd-konvwaktu-001"},{"key":"D","text":"<p>2 jam 30 menit</p>"},{"key":"E","text":"<p>2 jam 50 menit</p>","misconceptionId":"mis-msd-konvwaktu-002"}]'::jsonb, null, array['A', 'B', 'D'], null, null, 'A, B, D', false, null, null),
  ('msd-konvwaktu-010', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-pengukuran', 'con-matematika-sd-konversi-waktu', 'category', 'Bernalar menilai pernyataan tentang hubungan antar-satuan waktu', 'lanjut', 'penalaran', 'html', '<p>Lima pernyataan tentang satuan waktu dikumpulkan untuk diperiksa bersama.</p>', '<p>Tentukan benar atau salah setiap pernyataan berikut.</p>', 'Tentukan kategori setiap pernyataan.', '<p>P1 benar: itu hubungan baku antara tahun dan bulan.</p><p>P2 benar: 90 : 60 = 1,5 jam, yaitu 1 jam 30 menit.</p><p>P3 benar: 24 × 60 = 1.440 menit.</p><p>P4 salah: 200 : 60 = 3 sisa 20, jadi 200 detik sama dengan 3 menit 20 detik. Nilai 2 menit 20 detik hanya 140 detik.</p><p>P5 salah: 1 pekan sama dengan 7 hari.</p>', null, null, null, '[{"key":"B","label":"Benar"},{"key":"S","label":"Salah"}]'::jsonb, '[{"id":"p1","text":"<p>1 tahun sama dengan 12 bulan.</p>","correctCategoryKey":"B"},{"id":"p2","text":"<p>90 menit sama dengan 1,5 jam.</p>","correctCategoryKey":"B"},{"id":"p3","text":"<p>1 hari sama dengan 1.440 menit.</p>","correctCategoryKey":"B"},{"id":"p4","text":"<p>200 detik sama dengan 2 menit 20 detik.</p>","correctCategoryKey":"S","misconceptionId":"mis-msd-konvwaktu-004"},{"id":"p5","text":"<p>1 pekan sama dengan 10 hari.</p>","correctCategoryKey":"S","misconceptionId":"mis-msd-konvwaktu-001"}]'::jsonb, 'p1: B; p2: B; p3: B; p4: S; p5: S', false, null, null),
  ('msd-kecepatan-001', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-pengukuran', 'con-matematika-sd-kecepatan', 'single', 'Memahami penghitungan kecepatan dari jarak dan waktu', 'dasar', 'pemahaman', 'html', '<p>Seorang pesepeda menempuh jarak 60 km dari kota ke desa dalam waktu 3 jam dengan laju yang tetap.</p>', '<p>Kecepatan pesepeda itu adalah ....</p>', 'Pilih satu jawaban.', '<p>Kecepatan = jarak : waktu = 60 : 3 = 20 km/jam.</p><p>Pilihan D muncul bila jarak dikalikan waktu, dan pilihan C bila keduanya dijumlahkan. Periksa kewajaran: 20 km/jam memang laju sepeda yang masuk akal, sedangkan 180 km/jam laju kendaraan balap.</p>', '[{"key":"A","text":"<p>20 km/jam</p>"},{"key":"B","text":"<p>30 km/jam</p>","misconceptionId":"mis-msd-kecepatan-003"},{"key":"C","text":"<p>63 km/jam</p>","misconceptionId":"mis-msd-kecepatan-001"},{"key":"D","text":"<p>180 km/jam</p>","misconceptionId":"mis-msd-kecepatan-001"}]'::jsonb, 'A', null, null, null, 'A', false, null, null),
  ('msd-kecepatan-002', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-pengukuran', 'con-matematika-sd-kecepatan', 'single', 'Memahami arti satuan kecepatan', 'dasar', 'pemahaman', 'html', '<p>Pada papan petunjuk tertulis bahwa batas kecepatan di jalan itu 40 km/jam.</p>', '<p>Arti kecepatan 40 km/jam adalah ....</p>', 'Pilih satu jawaban.', '<p>Satuan km/jam dibaca “kilometer per jam”, yang berarti banyak kilometer yang ditempuh dalam waktu satu jam.</p><p>Jadi 40 km/jam berarti dalam 1 jam kendaraan menempuh 40 km. Pilihan D keliru karena mengganti jam dengan menit — kalau benar, kendaraan itu menempuh 2.400 km dalam sejam.</p>', '[{"key":"A","text":"<p>dalam 1 jam kendaraan menempuh 40 km</p>"},{"key":"B","text":"<p>dalam 1 km kendaraan memerlukan 40 jam</p>","misconceptionId":"mis-msd-kecepatan-001"},{"key":"C","text":"<p>dalam 40 jam kendaraan menempuh 1 km</p>","misconceptionId":"mis-msd-kecepatan-001"},{"key":"D","text":"<p>dalam 1 menit kendaraan menempuh 40 km</p>","misconceptionId":"mis-msd-kecepatan-002"}]'::jsonb, 'A', null, null, null, 'A', false, null, null),
  ('msd-kecepatan-003', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-pengukuran', 'con-matematika-sd-kecepatan', 'single', 'Mengaplikasikan penghitungan jarak dari kecepatan dan waktu', 'menengah', 'penerapan', 'html', '<p>Sebuah mobil melaju dengan kecepatan tetap 60 km/jam selama 2,5 jam tanpa berhenti.</p>', '<p>Jarak yang ditempuh mobil itu adalah ....</p>', 'Pilih satu jawaban.', '<p>Jarak = kecepatan × waktu = 60 × 2,5 = 150 km.</p><p>Cara lain: dalam 2 jam menempuh 120 km, ditambah setengah jam yang menempuh 30 km, seluruhnya 150 km.</p><p>Pilihan C muncul bila setengah jam terakhir diabaikan, dan pilihan A bila jarak dibagi bukan dikalikan.</p>', '[{"key":"A","text":"<p>24 km</p>","misconceptionId":"mis-msd-kecepatan-001"},{"key":"B","text":"<p>62,5 km</p>","misconceptionId":"mis-msd-kecepatan-001"},{"key":"C","text":"<p>120 km</p>","misconceptionId":"mis-msd-kecepatan-002"},{"key":"D","text":"<p>150 km</p>"}]'::jsonb, 'D', null, null, null, 'D', false, null, null),
  ('msd-kecepatan-004', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-pengukuran', 'con-matematika-sd-kecepatan', 'single', 'Mengaplikasikan penghitungan waktu tempuh', 'menengah', 'penerapan', 'html', '<p>Sebuah bus harus menempuh jarak 180 km. Bus itu melaju dengan kecepatan tetap 45 km/jam.</p>', '<p>Waktu tempuh bus itu adalah ....</p>', 'Pilih satu jawaban.', '<p>Waktu = jarak : kecepatan = 180 : 45 = 4 jam.</p><p>Periksa: 4 × 45 = 180 km, sesuai.</p><p>Pilihan D muncul bila jarak dikurangi kecepatan, yang jelas tidak menghasilkan satuan waktu.</p>', '[{"key":"A","text":"<p>3 jam</p>","misconceptionId":"mis-msd-kecepatan-003"},{"key":"B","text":"<p>4 jam</p>"},{"key":"C","text":"<p>5 jam</p>","misconceptionId":"mis-msd-kecepatan-004"},{"key":"D","text":"<p>135 jam</p>","misconceptionId":"mis-msd-kecepatan-001"}]'::jsonb, 'B', null, null, null, 'B', false, null, null),
  ('msd-kecepatan-005', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-pengukuran', 'con-matematika-sd-kecepatan', 'single', 'Mengaplikasikan perubahan menit menjadi jam pada perhitungan kecepatan', 'menengah', 'penerapan', 'html', '<p>Seorang pejalan kaki berjalan dengan kecepatan tetap 4 km/jam selama 45 menit.</p>', '<p>Jarak yang ditempuh pejalan kaki itu adalah ....</p>', 'Pilih satu jawaban.', '<p>Karena kecepatannya km/jam, ubah waktunya menjadi jam: 45 menit = 45 : 60 = 0,75 jam.</p><p>Jarak = 4 × 0,75 = 3 km.</p><p>Pilihan D muncul bila 45 menit dipakai apa adanya sebagai 45 jam. Periksa kewajaran: berjalan kaki 180 km dalam kurang dari sejam mustahil.</p>', '[{"key":"A","text":"<p>2,5 km</p>","misconceptionId":"mis-msd-kecepatan-002"},{"key":"B","text":"<p>3 km</p>"},{"key":"C","text":"<p>5,3 km</p>","misconceptionId":"mis-msd-kecepatan-001"},{"key":"D","text":"<p>180 km</p>","misconceptionId":"mis-msd-kecepatan-002"}]'::jsonb, 'B', null, null, null, 'B', false, null, null),
  ('msd-kecepatan-006', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-pengukuran', 'con-matematika-sd-kecepatan', 'single', 'Bernalar tentang kecepatan rata-rata perjalanan dua tahap', 'lanjut', 'penalaran', 'html', '<p>Sebuah kendaraan berangkat menempuh 60 km dalam waktu 1 jam. Saat kembali melalui jalan yang sama, kendaraan itu menempuh 60 km dalam waktu 2 jam karena jalanan padat.</p>', '<p>Kecepatan rata-rata seluruh perjalanan itu adalah ....</p>', 'Pilih satu jawaban.', '<p>Jarak seluruhnya = 60 + 60 = 120 km. Waktu seluruhnya = 1 + 2 = 3 jam.</p><p>Kecepatan rata-rata = 120 : 3 = 40 km/jam.</p><p>Pilihan C adalah rata-rata dari 60 km/jam dan 30 km/jam. Cara itu keliru karena kendaraan berjalan lebih lama pada tahap yang lambat, sehingga tahap lambat lebih berpengaruh dan hasilnya condong ke bawah 45.</p>', '[{"key":"A","text":"<p>30 km/jam</p>","misconceptionId":"mis-msd-kecepatan-001"},{"key":"B","text":"<p>40 km/jam</p>"},{"key":"C","text":"<p>45 km/jam</p>","misconceptionId":"mis-msd-kecepatan-003"},{"key":"D","text":"<p>60 km/jam</p>","misconceptionId":"mis-msd-kecepatan-004"}]'::jsonb, 'B', null, null, null, 'B', false, null, null),
  ('msd-kecepatan-007', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-pengukuran', 'con-matematika-sd-kecepatan', 'single', 'Bernalar tentang hubungan berbalik kecepatan dan waktu', 'lanjut', 'penalaran', 'html', '<p>Sebuah kendaraan menempuh jarak tertentu dalam 6 jam. Seorang siswa berkata, “Kalau kecepatannya digandakan, waktu tempuhnya juga menjadi dua kali, yaitu 12 jam.”</p>', '<p>Tanggapan yang tepat terhadap pendapat siswa itu adalah ....</p>', 'Pilih satu jawaban.', '<p>Untuk jarak yang tetap, kecepatan dan waktu berbanding berbalik. Bergerak lebih cepat pasti membuat perjalanan lebih singkat, bukan lebih lama.</p><p>Contoh angka: jarak 300 km dengan 50 km/jam memerlukan 6 jam; dengan 100 km/jam hanya 3 jam.</p><p>Pilihan D keliru karena yang digandakan hanya kecepatannya, sedangkan jaraknya tetap.</p>', '[{"key":"A","text":"<p>Benar, karena kecepatan dan waktu selalu berubah searah.</p>","misconceptionId":"mis-msd-kecepatan-004"},{"key":"B","text":"<p>Salah, karena untuk jarak yang tetap kecepatan dua kali membuat waktunya menjadi setengah, yaitu 3 jam.</p>"},{"key":"C","text":"<p>Salah, karena waktu tempuhnya tidak berubah meski kecepatannya berubah.</p>","misconceptionId":"mis-msd-kecepatan-001"},{"key":"D","text":"<p>Benar, karena jarak yang ditempuh ikut menjadi dua kali.</p>","misconceptionId":"mis-msd-kecepatan-003"}]'::jsonb, 'B', null, null, null, 'B', false, null, null),
  ('msd-kecepatan-008', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-pengukuran', 'con-matematika-sd-kecepatan', 'mcma', 'Mengaplikasikan hubungan jarak, waktu, dan kecepatan pada satu perjalanan', 'menengah', 'penerapan', 'html', '<p>Sebuah sepeda motor menempuh jarak 90 km dalam waktu 2 jam dengan kecepatan tetap.</p>', '<p>Pernyataan yang benar tentang perjalanan itu adalah ....</p>', 'Pilih semua jawaban yang benar.', '<p>A benar: 90 : 2 = 45 km/jam.</p><p>B benar: 45 × 4 = 180 km.</p><p>C benar: 30 menit = 0,5 jam, jadi 45 × 0,5 = 22,5 km.</p><p>D salah: 180 diperoleh dari 90 × 2, bukan 90 : 2.</p><p>E salah: 45 km ditempuh tepat dalam 1 jam, karena kecepatannya 45 km/jam.</p>', '[{"key":"A","text":"<p>Kecepatan sepeda motor itu 45 km/jam.</p>"},{"key":"B","text":"<p>Dalam 4 jam dengan kecepatan yang sama, jaraknya menjadi 180 km.</p>"},{"key":"C","text":"<p>Dalam 30 menit dengan kecepatan yang sama, jaraknya 22,5 km.</p>"},{"key":"D","text":"<p>Kecepatan sepeda motor itu 180 km/jam.</p>","misconceptionId":"mis-msd-kecepatan-001"},{"key":"E","text":"<p>Untuk menempuh 45 km diperlukan waktu 2 jam.</p>","misconceptionId":"mis-msd-kecepatan-004"}]'::jsonb, null, array['A', 'B', 'C'], null, null, 'A, B, C', false, null, null),
  ('msd-kecepatan-009', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-pengukuran', 'con-matematika-sd-kecepatan', 'mcma', 'Bernalar membandingkan kecepatan dua orang', 'lanjut', 'penalaran', 'html', '<p>Ana bersepeda menempuh 12 km dalam 40 menit. Budi berjalan kaki menempuh 3 km dalam 30 menit. Keduanya bergerak dengan laju tetap.</p>', '<p>Pernyataan yang benar tentang keduanya adalah ....</p>', 'Pilih semua jawaban yang benar.', '<p>A benar: 40 menit = 40 : 60 = 2/3 jam, jadi 12 : (2/3) = 18 km/jam.</p><p>B benar: 30 menit = 0,5 jam, jadi 3 : 0,5 = 6 km/jam.</p><p>C benar: 18 : 6 = 3.</p><p>D salah: Ana menempuh 12 km sedangkan Budi hanya 3 km.</p><p>E salah: dalam 1 jam Ana menempuh 18 km dan Budi 6 km, sehingga selisihnya 12 km.</p>', '[{"key":"A","text":"<p>Kecepatan Ana 18 km/jam.</p>"},{"key":"B","text":"<p>Kecepatan Budi 6 km/jam.</p>"},{"key":"C","text":"<p>Kecepatan Ana tiga kali kecepatan Budi.</p>"},{"key":"D","text":"<p>Budi menempuh jarak lebih jauh daripada Ana.</p>","misconceptionId":"mis-msd-kecepatan-005"},{"key":"E","text":"<p>Bila keduanya bergerak selama 1 jam, selisih jaraknya 9 km.</p>","misconceptionId":"mis-msd-kecepatan-002"}]'::jsonb, null, array['A', 'B', 'C'], null, null, 'A, B, C', false, null, null),
  ('msd-kecepatan-010', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-pengukuran', 'con-matematika-sd-kecepatan', 'category', 'Bernalar menilai pernyataan tentang kecepatan', 'lanjut', 'penalaran', 'html', '<p>Lima pernyataan tentang kecepatan dikumpulkan dari catatan kelas untuk diperiksa bersama.</p>', '<p>Tentukan benar atau salah setiap pernyataan berikut.</p>', 'Tentukan kategori setiap pernyataan.', '<p>P1 benar: itulah hubungan dasar kecepatan.</p><p>P2 benar: 5 m/detik berarti 5 × 60 × 60 = 18.000 m dalam satu jam, yaitu 18 km/jam — jauh lebih besar daripada 5 km/jam.</p><p>P3 benar: dengan waktu yang sama, jarak yang lebih besar memberi hasil bagi yang lebih besar.</p><p>P4 salah: cara itu hanya benar bila lama kedua tahap sama. Kecepatan rata-rata dihitung dari jarak seluruhnya dibagi waktu seluruhnya.</p><p>P5 salah: 100 : 2 = 50 km/jam dan 150 : 3 = 50 km/jam, jadi keduanya sama cepat.</p>', null, null, null, '[{"key":"B","label":"Benar"},{"key":"S","label":"Salah"}]'::jsonb, '[{"id":"p1","text":"<p>Kecepatan diperoleh dengan membagi jarak dengan waktu.</p>","correctCategoryKey":"B"},{"id":"p2","text":"<p>Kecepatan 5 m/detik lebih besar daripada kecepatan 5 km/jam.</p>","correctCategoryKey":"B"},{"id":"p3","text":"<p>Bila waktunya sama, yang menempuh jarak lebih jauh berarti berkecepatan lebih besar.</p>","correctCategoryKey":"B"},{"id":"p4","text":"<p>Kecepatan rata-rata dua tahap perjalanan selalu sama dengan rata-rata kedua kecepatannya.</p>","correctCategoryKey":"S","misconceptionId":"mis-msd-kecepatan-003"},{"id":"p5","text":"<p>Menempuh 100 km dalam 2 jam lebih cepat daripada menempuh 150 km dalam 3 jam.</p>","correctCategoryKey":"S","misconceptionId":"mis-msd-kecepatan-005"}]'::jsonb, 'p1: B; p2: B; p3: B; p4: S; p5: S', false, null, null),
  ('msd-luas-001', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-pengukuran', 'con-matematika-sd-keliling-luas', 'single', 'Memahami keliling persegi panjang', 'dasar', 'pemahaman', 'html', '<p>Sebuah papan mading berbentuk persegi panjang berukuran panjang 12 cm dan lebar 7 cm pada gambar rancangan. Seluruh tepinya akan dilapisi selotip berwarna.</p>', '<p>Panjang selotip yang diperlukan untuk melapisi seluruh tepi papan itu adalah ....</p>', 'Pilih satu jawaban.', '<p>Tepi papan adalah kelilingnya: 2 × (12 + 7) = 2 × 19 = 38 cm.</p><p>Pilihan A hanya menjumlahkan panjang dan lebar sekali, padahal ada dua sisi panjang dan dua sisi lebar.</p><p>Pilihan B adalah luasnya, yaitu 12 × 7 = 84 — dan satuannya pun seharusnya cm², bukan cm.</p>', '[{"key":"A","text":"<p>19 cm</p>","misconceptionId":"mis-msd-luas-004"},{"key":"B","text":"<p>84 cm</p>","misconceptionId":"mis-msd-luas-001"},{"key":"C","text":"<p>76 cm</p>","misconceptionId":"mis-msd-luas-004"},{"key":"D","text":"<p>38 cm</p>"}]'::jsonb, 'D', null, null, null, 'D', false, null, null),
  ('msd-luas-002', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-pengukuran', 'con-matematika-sd-keliling-luas', 'single', 'Memahami luas persegi', 'dasar', 'pemahaman', 'html', '<p>Sebuah ubin berbentuk persegi dengan panjang sisi 9 cm akan dihitung luas permukaannya untuk keperluan pemasangan.</p>', '<p>Luas ubin itu adalah ....</p>', 'Pilih satu jawaban.', '<p>Luas persegi = sisi × sisi = 9 × 9 = 81 cm².</p><p>Pilihan B adalah kelilingnya, yaitu 4 × 9 = 36 cm — bukan luasnya, dan satuannya pun cm.</p><p>Pilihan A hanya menjumlahkan dua sisi.</p>', '[{"key":"A","text":"<p>18 cm²</p>","misconceptionId":"mis-msd-luas-001"},{"key":"B","text":"<p>36 cm²</p>","misconceptionId":"mis-msd-luas-001"},{"key":"C","text":"<p>72 cm²</p>","misconceptionId":"mis-msd-luas-002"},{"key":"D","text":"<p>81 cm²</p>"}]'::jsonb, 'D', null, null, null, 'D', false, null, null),
  ('msd-luas-003', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-pengukuran', 'con-matematika-sd-keliling-luas', 'single', 'Mengaplikasikan luas segitiga', 'menengah', 'penerapan', 'html', '<p>Sebuah bendera hias berbentuk segitiga dengan panjang alas 14 cm dan tinggi 9 cm. Kain untuk membuat bendera dihitung berdasarkan luasnya.</p>', '<p>Luas satu bendera hias itu adalah ....</p>', 'Pilih satu jawaban.', '<p>Luas segitiga = 1/2 × alas × tinggi = 1/2 × 14 × 9 = 63 cm².</p><p>Pilihan D adalah 14 × 9 tanpa dibagi dua — itu luas persegi panjang beralas dan bertinggi sama, yaitu dua kali luas segitiganya.</p>', '[{"key":"A","text":"<p>23 cm²</p>","misconceptionId":"mis-msd-luas-001"},{"key":"B","text":"<p>46 cm²</p>","misconceptionId":"mis-msd-luas-001"},{"key":"C","text":"<p>63 cm²</p>"},{"key":"D","text":"<p>126 cm²</p>","misconceptionId":"mis-msd-luas-002"}]'::jsonb, 'C', null, null, null, 'C', false, null, null),
  ('msd-luas-004', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-pengukuran', 'con-matematika-sd-keliling-luas', 'single', 'Mengaplikasikan keliling bangun segi banyak gabungan', 'menengah', 'penerapan', 'html', '<p>Sebuah taman kecil berbentuk huruf L. Bentuk itu berasal dari persegi panjang berukuran 10 cm × 6 cm pada gambar rancangan, yang salah satu sudutnya dipotong oleh persegi panjang 4 cm × 3 cm. Panjang keenam sisinya berturut-turut 10 cm, 3 cm, 4 cm, 3 cm, 6 cm, dan 6 cm.</p>', '<p>Keliling taman itu adalah ....</p>', 'Pilih satu jawaban.', '<p>Keliling adalah jumlah panjang semua sisinya: 10 + 3 + 4 + 3 + 6 + 6 = 32 cm.</p><p>Menarik diperhatikan: kelilingnya persis sama dengan keliling persegi panjang utuh 10 cm × 6 cm, yaitu 2 × (10 + 6) = 32 cm. Potongan pada sudut memindahkan tepinya ke dalam tanpa mengubah panjang totalnya.</p><p>Pilihan B adalah luas bangun itu, bukan kelilingnya.</p>', '[{"key":"A","text":"<p>26 cm</p>","misconceptionId":"mis-msd-luas-004"},{"key":"B","text":"<p>48 cm</p>","misconceptionId":"mis-msd-luas-001"},{"key":"C","text":"<p>44 cm</p>","misconceptionId":"mis-msd-luas-003"},{"key":"D","text":"<p>32 cm</p>"}]'::jsonb, 'D', null, null, null, 'D', true, 'Bangun datar berbentuk huruf L dengan garis tepi tebal, berlatar abu muda. Bentuknya berasal dari persegi panjang 10 cm (mendatar) × 6 cm (tegak) yang sudut kanan atasnya dipotong persegi panjang 4 cm × 3 cm. Tuliskan ukuran pada setiap sisi mengikuti tepinya: 10 cm di sisi bawah, 3 cm di sisi kanan, 4 cm mendatar ke dalam, 3 cm tegak ke atas, 6 cm di sisi atas, dan 6 cm di sisi kiri.', 'svg'),
  ('msd-luas-005', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-pengukuran', 'con-matematika-sd-keliling-luas', 'single', 'Mengaplikasikan luas bangun gabungan', 'menengah', 'penerapan', 'html', '<p>Taman berbentuk huruf L pada rancangan yang sama berasal dari persegi panjang 10 cm × 6 cm dengan potongan persegi panjang 4 cm × 3 cm di salah satu sudutnya.</p>', '<p>Luas taman itu adalah ....</p>', 'Pilih satu jawaban.', '<p>Luas persegi panjang utuh = 10 × 6 = 60 cm². Luas potongan = 4 × 3 = 12 cm².</p><p>Luas taman = 60 − 12 = 48 cm².</p><p>Pilihan C adalah luas persegi panjang utuhnya, yang berarti potongannya lupa dikurangkan.</p>', '[{"key":"A","text":"<p>36 cm²</p>","misconceptionId":"mis-msd-luas-002"},{"key":"B","text":"<p>72 cm²</p>","misconceptionId":"mis-msd-luas-003"},{"key":"C","text":"<p>60 cm²</p>","misconceptionId":"mis-msd-luas-003"},{"key":"D","text":"<p>48 cm²</p>"}]'::jsonb, 'D', null, null, null, 'D', false, null, null),
  ('msd-luas-006', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-pengukuran', 'con-matematika-sd-keliling-luas', 'single', 'Bernalar tentang bangun berkeliling sama dengan luas berbeda', 'lanjut', 'penalaran', 'html', '<p>Dua bidang tanah berbentuk persegi panjang dipagari dengan kawat sepanjang 24 m, dan seluruh kawat terpakai pada masing-masing bidang.</p><ul><li>Bidang I berukuran 8 m × 4 m.</li><li>Bidang II berukuran 6 m × 6 m.</li></ul>', '<p>Kesimpulan yang tepat tentang kedua bidang itu adalah ....</p>', 'Pilih satu jawaban.', '<p>Periksa kelilingnya: Bidang I = 2 × (8 + 4) = 24 m dan Bidang II = 2 × (6 + 6) = 24 m — memang sama.</p><p>Periksa luasnya: Bidang I = 8 × 4 = 32 m² dan Bidang II = 6 × 6 = 36 m². Jadi bidang yang lebih mendekati bentuk persegi ternyata lebih luas.</p><p>Keliling sama tidak menjamin luas sama. Inilah sebabnya keliling dan luas harus dihitung terpisah.</p>', '[{"key":"A","text":"<p>Luas kedua bidang sama, karena kelilingnya sama.</p>","misconceptionId":"mis-msd-luas-001"},{"key":"B","text":"<p>Luas kedua bidang tidak dapat dibandingkan karena bentuknya berbeda.</p>","misconceptionId":"mis-msd-luas-003"},{"key":"C","text":"<p>Bidang I lebih luas, karena sisi terpanjangnya lebih besar.</p>","misconceptionId":"mis-msd-luas-004"},{"key":"D","text":"<p>Bidang II lebih luas, yaitu 36 m² dibanding 32 m², meskipun kelilingnya sama.</p>"}]'::jsonb, 'D', null, null, null, 'D', false, null, null),
  ('msd-luas-007', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-pengukuran', 'con-matematika-sd-keliling-luas', 'single', 'Bernalar tentang pengaruh pelipatan sisi terhadap luas', 'lanjut', 'penalaran', 'html', '<p>Sebuah kertas gambar berbentuk persegi panjang berukuran 5 cm × 3 cm. Kertas gambar baru dibuat dengan panjang dan lebar masing-masing dua kali ukuran itu.</p>', '<p>Luas kertas gambar baru dibandingkan luas kertas semula menjadi ....</p>', 'Pilih satu jawaban.', '<p>Luas semula = 5 × 3 = 15 cm². Ukuran baru 10 cm × 6 cm, sehingga luasnya 10 × 6 = 60 cm².</p><p>Perbandingannya 60 : 15 = 4 kali.</p><p>Luas dipengaruhi dua ukuran sekaligus, jadi bila keduanya menjadi dua kali, luasnya menjadi 2 × 2 = 4 kali. Kelilingnya sendiri hanya menjadi 2 kali, dari 16 cm menjadi 32 cm.</p>', '[{"key":"A","text":"<p>2 kali</p>","misconceptionId":"mis-msd-luas-005"},{"key":"B","text":"<p>6 kali</p>","misconceptionId":"mis-msd-luas-002"},{"key":"C","text":"<p>4 kali</p>"},{"key":"D","text":"<p>tetap sama</p>","misconceptionId":"mis-msd-luas-001"}]'::jsonb, 'C', null, null, null, 'C', false, null, null),
  ('msd-luas-008', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-pengukuran', 'con-matematika-sd-keliling-luas', 'mcma', 'Mengaplikasikan keliling dan luas pada satu persegi panjang', 'menengah', 'penerapan', 'html', '<p>Sebuah karton berbentuk persegi panjang berukuran panjang 15 cm dan lebar 8 cm.</p>', '<p>Pernyataan yang benar tentang karton itu adalah ....</p>', 'Pilih semua jawaban yang benar.', '<p>A benar: 2 × (15 + 8) = 2 × 23 = 46 cm.</p><p>B benar: 15 × 8 = 120 cm².</p><p>C dan E salah karena angka keliling dan luasnya tertukar.</p><p>D benar: panjang menjadi 20 cm, sehingga luasnya 20 × 8 = 160 cm².</p>', '[{"key":"A","text":"<p>Kelilingnya 46 cm.</p>"},{"key":"B","text":"<p>Luasnya 120 cm².</p>"},{"key":"C","text":"<p>Luasnya 46 cm².</p>","misconceptionId":"mis-msd-luas-001"},{"key":"D","text":"<p>Bila panjangnya ditambah 5 cm, luasnya menjadi 160 cm².</p>"},{"key":"E","text":"<p>Kelilingnya 120 cm.</p>","misconceptionId":"mis-msd-luas-001"}]'::jsonb, null, array['A', 'B', 'D'], null, null, 'A, B, D', false, null, null),
  ('msd-luas-009', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-pengukuran', 'con-matematika-sd-keliling-luas', 'mcma', 'Bernalar membandingkan luas segitiga dan trapesium', 'lanjut', 'penalaran', 'html', '<p>Dua potong kain dipotong menurut bentuk berikut:</p><ul><li>Kain P berbentuk segitiga dengan alas 12 cm dan tinggi 5 cm.</li><li>Kain Q berbentuk trapesium dengan sisi sejajar 8 cm dan 12 cm serta tinggi 6 cm.</li></ul>', '<p>Pernyataan yang benar tentang kedua kain itu adalah ....</p>', 'Pilih semua jawaban yang benar.', '<p>A benar: luas segitiga = 1/2 × 12 × 5 = 30 cm².</p><p>B benar: luas trapesium = 1/2 × (8 + 12) × 6 = 1/2 × 20 × 6 = 60 cm².</p><p>C benar: 60 : 30 = 2.</p><p>D salah: 60 diperoleh dari 12 × 5 tanpa dibagi dua.</p><p>E salah: 120 diperoleh dari (8 + 12) × 6 tanpa dibagi dua.</p>', '[{"key":"A","text":"<p>Luas Kain P adalah 30 cm².</p>"},{"key":"B","text":"<p>Luas Kain Q adalah 60 cm².</p>"},{"key":"C","text":"<p>Luas Kain Q dua kali luas Kain P.</p>"},{"key":"D","text":"<p>Luas Kain P adalah 60 cm².</p>","misconceptionId":"mis-msd-luas-002"},{"key":"E","text":"<p>Luas Kain Q adalah 120 cm².</p>","misconceptionId":"mis-msd-luas-002"}]'::jsonb, null, array['A', 'B', 'C'], null, null, 'A, B, C', false, null, null),
  ('msd-luas-010', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-pengukuran', 'con-matematika-sd-keliling-luas', 'category', 'Bernalar menilai pernyataan tentang keliling dan luas', 'lanjut', 'penalaran', 'html', '<p>Lima pernyataan tentang keliling dan luas ditulis di papan tulis untuk diperiksa bersama.</p>', '<p>Tentukan benar atau salah setiap pernyataan berikut.</p>', 'Tentukan kategori setiap pernyataan.', '<p>P1 benar: keliling mengukur panjang seluruh tepinya.</p><p>P2 salah: luasnya 6 × 6 = 36 cm². Angka 24 adalah kelilingnya, yaitu 4 × 6 cm.</p><p>P3 benar: segitiga adalah setengah persegi panjang beralas dan bertinggi sama.</p><p>P4 salah: persegi panjang 1 cm × 36 cm dan persegi 6 cm × 6 cm sama-sama berluas 36 cm², tetapi kelilingnya 74 cm dan 24 cm.</p><p>P5 benar: luas mengukur daerah sehingga satuannya persegi, sedangkan keliling mengukur panjang.</p>', null, null, null, '[{"key":"B","label":"Benar"},{"key":"S","label":"Salah"}]'::jsonb, '[{"id":"p1","text":"<p>Keliling suatu bangun datar adalah jumlah panjang semua sisinya.</p>","correctCategoryKey":"B"},{"id":"p2","text":"<p>Luas persegi yang panjang sisinya 6 cm adalah 24 cm².</p>","correctCategoryKey":"S","misconceptionId":"mis-msd-luas-001"},{"id":"p3","text":"<p>Luas segitiga dihitung dengan setengah alas kali tinggi.</p>","correctCategoryKey":"B"},{"id":"p4","text":"<p>Dua bangun datar yang luasnya sama pasti kelilingnya juga sama.</p>","correctCategoryKey":"S","misconceptionId":"mis-msd-luas-005"},{"id":"p5","text":"<p>Satuan luas ditulis cm², sedangkan satuan keliling ditulis cm.</p>","correctCategoryKey":"B"}]'::jsonb, 'p1: B; p2: S; p3: B; p4: S; p5: B', false, null, null),
  ('msd-volruang-001', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-pengukuran', 'con-matematika-sd-volume-bangun-ruang', 'single', 'Memahami volume kubus', 'dasar', 'pemahaman', 'html', '<p>Sebuah kotak mainan berbentuk kubus dengan panjang rusuk 5 cm akan diisi penuh kubus satuan berukuran 1 cm.</p>', '<p>Volume kotak mainan itu adalah ....</p>', 'Pilih satu jawaban.', '<p>Volume kubus = rusuk × rusuk × rusuk = 5 × 5 × 5 = 125 cm³.</p><p>Pilihan A muncul bila rusuk hanya dikalikan 3, dan pilihan B bila hanya dua ukuran yang dikalikan — itu luas satu sisinya, bukan volumenya.</p>', '[{"key":"A","text":"<p>15 cm³</p>","misconceptionId":"mis-msd-volruang-001"},{"key":"B","text":"<p>25 cm³</p>","misconceptionId":"mis-msd-volruang-002"},{"key":"C","text":"<p>125 cm³</p>"},{"key":"D","text":"<p>150 cm³</p>","misconceptionId":"mis-msd-volruang-002"}]'::jsonb, 'C', null, null, null, 'C', false, null, null),
  ('msd-volruang-002', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-pengukuran', 'con-matematika-sd-volume-bangun-ruang', 'single', 'Memahami volume balok', 'dasar', 'pemahaman', 'html', '<p>Sebuah kotak pensil berbentuk balok berukuran panjang 8 cm, lebar 5 cm, dan tinggi 3 cm.</p>', '<p>Volume kotak pensil itu adalah ....</p>', 'Pilih satu jawaban.', '<p>Volume balok = panjang × lebar × tinggi = 8 × 5 × 3 = 120 cm³.</p><p>Pilihan B adalah 8 × 5 saja, yaitu luas sisi bawahnya. Pilihan A adalah jumlah ketiga ukurannya.</p>', '[{"key":"A","text":"<p>16 cm³</p>","misconceptionId":"mis-msd-volruang-001"},{"key":"B","text":"<p>40 cm³</p>","misconceptionId":"mis-msd-volruang-002"},{"key":"C","text":"<p>120 cm³</p>"},{"key":"D","text":"<p>240 cm³</p>","misconceptionId":"mis-msd-volruang-005"}]'::jsonb, 'C', null, null, null, 'C', false, null, null),
  ('msd-volruang-003', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-pengukuran', 'con-matematika-sd-volume-bangun-ruang', 'single', 'Mengaplikasikan volume balok beserta perubahan ke liter', 'menengah', 'penerapan', 'html', '<p>Sebuah akuarium berbentuk balok berukuran panjang 60 cm, lebar 30 cm, dan tinggi 40 cm. Akuarium itu akan diisi air sampai penuh.</p>', '<p>Banyak air yang diperlukan untuk mengisi akuarium itu adalah ....</p>', 'Pilih satu jawaban.', '<p>Volume akuarium = 60 × 30 × 40 = 72.000 cm³.</p><p>Karena 1 liter = 1.000 cm³, maka 72.000 : 1.000 = 72 liter.</p><p>Pilihan B lupa mengubah satuannya, dan hasil sebesar itu jelas mustahil untuk akuarium meja.</p>', '[{"key":"A","text":"<p>7,2 liter</p>","misconceptionId":"mis-msd-volruang-003"},{"key":"B","text":"<p>72.000 liter</p>","misconceptionId":"mis-msd-volruang-003"},{"key":"C","text":"<p>720 liter</p>","misconceptionId":"mis-msd-volruang-003"},{"key":"D","text":"<p>72 liter</p>"}]'::jsonb, 'D', null, null, null, 'D', false, null, null),
  ('msd-volruang-004', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-pengukuran', 'con-matematika-sd-volume-bangun-ruang', 'single', 'Mengaplikasikan volume untuk mencari ukuran yang belum diketahui', 'menengah', 'penerapan', 'html', '<p>Sebuah kotak berbentuk balok bervolume 240 cm³. Panjangnya 10 cm dan lebarnya 6 cm.</p>', '<p>Tinggi kotak itu adalah ....</p>', 'Pilih satu jawaban.', '<p>Luas sisi bawah = 10 × 6 = 60 cm².</p><p>Tinggi = volume : luas sisi bawah = 240 : 60 = 4 cm.</p><p>Periksa: 10 × 6 × 4 = 240 cm³, sesuai. Pilihan C muncul bila volume hanya dibagi 10.</p>', '[{"key":"A","text":"<p>4 cm</p>"},{"key":"B","text":"<p>14 cm</p>","misconceptionId":"mis-msd-volruang-002"},{"key":"C","text":"<p>24 cm</p>","misconceptionId":"mis-msd-volruang-002"},{"key":"D","text":"<p>40 cm</p>","misconceptionId":"mis-msd-volruang-003"}]'::jsonb, 'A', null, null, null, 'A', false, null, null),
  ('msd-volruang-005', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-pengukuran', 'con-matematika-sd-volume-bangun-ruang', 'single', 'Mengaplikasikan volume bangun gabungan dua balok', 'menengah', 'penerapan', 'html', '<p>Sebuah bangun gabungan tersusun dari dua balok. Balok bawah berukuran 12 cm × 8 cm × 5 cm, dan di atasnya berdiri balok kedua berukuran 6 cm × 4 cm × 5 cm.</p>', '<p>Volume bangun gabungan itu adalah ....</p>', 'Pilih satu jawaban.', '<p>Volume balok bawah = 12 × 8 × 5 = 480 cm³.</p><p>Volume balok atas = 6 × 4 × 5 = 120 cm³.</p><p>Volume gabungan = 480 + 120 = 600 cm³. Pilihan B hanya menghitung balok bawahnya saja.</p>', '[{"key":"A","text":"<p>360 cm³</p>","misconceptionId":"mis-msd-volruang-002"},{"key":"B","text":"<p>480 cm³</p>","misconceptionId":"mis-msd-volruang-004"},{"key":"C","text":"<p>600 cm³</p>"},{"key":"D","text":"<p>720 cm³</p>","misconceptionId":"mis-msd-volruang-005"}]'::jsonb, 'C', null, null, null, 'C', true, 'Gambar isometrik bangun gabungan dua balok. Balok bawah berukuran panjang 12 cm, lebar 8 cm, tinggi 5 cm. Di atasnya, rata dengan tepi kiri dan tepi belakang, berdiri balok kedua berukuran panjang 6 cm, lebar 4 cm, tinggi 5 cm. Tuliskan ukuran setiap rusuk yang tampak beserta satuan cm, garis tepi tegas, wajah atas lebih terang.', 'svg'),
  ('msd-volruang-006', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-pengukuran', 'con-matematika-sd-volume-bangun-ruang', 'single', 'Bernalar tentang waktu pengisian bak dari volume dan laju air', 'lanjut', 'penalaran', 'html', '<p>Sebuah bak berbentuk balok berukuran 90 cm × 50 cm × 40 cm diisi air dari sebuah kran. Kran itu mengalirkan 15 liter air setiap menit dan bak diisi sampai penuh.</p>', '<p>Waktu yang diperlukan untuk mengisi bak itu sampai penuh adalah ....</p>', 'Pilih satu jawaban.', '<p>Volume bak = 90 × 50 × 40 = 180.000 cm³.</p><p>Ubah ke liter: 180.000 : 1.000 = 180 liter.</p><p>Waktu = 180 : 15 = 12 menit. Pilihan B muncul bila volumenya dibagi 15 tanpa lebih dahulu diubah ke liter.</p>', '[{"key":"A","text":"<p>9 menit</p>","misconceptionId":"mis-msd-volruang-004"},{"key":"B","text":"<p>120 menit</p>","misconceptionId":"mis-msd-volruang-003"},{"key":"C","text":"<p>15 menit</p>","misconceptionId":"mis-msd-volruang-002"},{"key":"D","text":"<p>12 menit</p>"}]'::jsonb, 'D', null, null, null, 'D', false, null, null),
  ('msd-volruang-007', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-pengukuran', 'con-matematika-sd-volume-bangun-ruang', 'single', 'Bernalar tentang pengaruh pelipatan rusuk terhadap volume', 'lanjut', 'penalaran', 'html', '<p>Sebuah kotak berbentuk kubus mempunyai rusuk 3 cm. Kotak baru dibuat dengan rusuk dua kali panjang rusuk kotak semula.</p>', '<p>Volume kotak baru dibandingkan volume kotak semula menjadi ....</p>', 'Pilih satu jawaban.', '<p>Volume semula = 3 × 3 × 3 = 27 cm³. Rusuk baru 6 cm, sehingga volumenya 6 × 6 × 6 = 216 cm³.</p><p>Perbandingannya 216 : 27 = 8 kali.</p><p>Volume dipengaruhi tiga ukuran sekaligus: 2 × 2 × 2 = 8. Perhatikan bahwa luas satu sisinya hanya menjadi 4 kali, dan panjang rusuknya sendiri 2 kali.</p>', '[{"key":"A","text":"<p>2 kali</p>","misconceptionId":"mis-msd-volruang-005"},{"key":"B","text":"<p>4 kali</p>","misconceptionId":"mis-msd-volruang-002"},{"key":"C","text":"<p>6 kali</p>","misconceptionId":"mis-msd-volruang-001"},{"key":"D","text":"<p>8 kali</p>"}]'::jsonb, 'D', null, null, null, 'D', false, null, null),
  ('msd-volruang-008', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-pengukuran', 'con-matematika-sd-volume-bangun-ruang', 'mcma', 'Mengaplikasikan volume balok pada beberapa pernyataan', 'menengah', 'penerapan', 'html', '<p>Sebuah kardus berbentuk balok berukuran panjang 10 cm, lebar 6 cm, dan tinggi 4 cm.</p>', '<p>Pernyataan yang benar tentang kardus itu adalah ....</p>', 'Pilih semua jawaban yang benar.', '<p>A benar: 10 × 6 × 4 = 240 cm³.</p><p>B benar: tinggi menjadi dua kali membuat volumenya dua kali, yaitu 480 cm³.</p><p>C salah: 20 hanya jumlah ketiga ukurannya.</p><p>D benar: satu kubus satuan bervolume 1 cm³, jadi 240 cm³ memuat 240 kubus satuan.</p><p>E salah: kubus berusuk 6 cm bervolume 6 × 6 × 6 = 216 cm³, bukan 240 cm³.</p>', '[{"key":"A","text":"<p>Volumenya 240 cm³.</p>"},{"key":"B","text":"<p>Bila tingginya menjadi 8 cm, volumenya menjadi 480 cm³.</p>"},{"key":"C","text":"<p>Volumenya 20 cm³.</p>","misconceptionId":"mis-msd-volruang-001"},{"key":"D","text":"<p>Kardus itu dapat diisi penuh oleh 240 kubus satuan berusuk 1 cm.</p>"},{"key":"E","text":"<p>Volumenya sama dengan volume kubus berusuk 6 cm.</p>","misconceptionId":"mis-msd-volruang-005"}]'::jsonb, null, array['A', 'B', 'D'], null, null, 'A, B, D', false, null, null),
  ('msd-volruang-009', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-pengukuran', 'con-matematika-sd-volume-bangun-ruang', 'mcma', 'Bernalar membandingkan volume kubus dan balok', 'lanjut', 'penalaran', 'html', '<p>Dua wadah dibandingkan isinya:</p><ul><li>Wadah P berbentuk kubus dengan rusuk 6 cm.</li><li>Wadah Q berbentuk balok berukuran 9 cm × 4 cm × 3 cm.</li></ul>', '<p>Pernyataan yang benar tentang kedua wadah itu adalah ....</p>', 'Pilih semua jawaban yang benar.', '<p>A benar: 6 × 6 × 6 = 216 cm³.</p><p>B benar: 9 × 4 × 3 = 108 cm³.</p><p>C benar: 216 : 108 = 2.</p><p>D salah: 108 cm³ justru lebih kecil daripada 216 cm³.</p><p>E salah: 36 adalah luas satu sisi kubus itu, yaitu 6 × 6, bukan volumenya.</p>', '[{"key":"A","text":"<p>Volume Wadah P adalah 216 cm³.</p>"},{"key":"B","text":"<p>Volume Wadah Q adalah 108 cm³.</p>"},{"key":"C","text":"<p>Volume Wadah P dua kali volume Wadah Q.</p>"},{"key":"D","text":"<p>Volume Wadah Q lebih besar daripada volume Wadah P.</p>","misconceptionId":"mis-msd-volruang-002"},{"key":"E","text":"<p>Volume Wadah P adalah 36 cm³.</p>","misconceptionId":"mis-msd-volruang-002"}]'::jsonb, null, array['A', 'B', 'C'], null, null, 'A, B, C', false, null, null),
  ('msd-volruang-010', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-pengukuran', 'con-matematika-sd-volume-bangun-ruang', 'category', 'Bernalar menilai pernyataan tentang volume bangun ruang', 'lanjut', 'penalaran', 'html', '<p>Lima pernyataan tentang volume bangun ruang ditulis di papan tulis untuk diperiksa bersama.</p>', '<p>Tentukan benar atau salah setiap pernyataan berikut.</p>', 'Tentukan kategori setiap pernyataan.', '<p>P1 benar: volume memerlukan tiga ukuran sekaligus.</p><p>P2 salah: volumenya 4 × 4 × 4 = 64 cm³. Angka 12 hanya 4 × 3.</p><p>P3 benar: itulah hubungan yang dipakai untuk mengubah volume wadah menjadi banyak air.</p><p>P4 salah: kubus berusuk 6 cm dan balok 12 cm × 6 cm × 3 cm sama-sama bervolume 216 cm³ dengan bentuk yang jelas berbeda.</p><p>P5 benar: volume mengukur ruang sehingga satuannya berpangkat tiga.</p>', null, null, null, '[{"key":"B","label":"Benar"},{"key":"S","label":"Salah"}]'::jsonb, '[{"id":"p1","text":"<p>Volume balok dihitung dengan panjang × lebar × tinggi.</p>","correctCategoryKey":"B"},{"id":"p2","text":"<p>Volume kubus yang panjang rusuknya 4 cm adalah 12 cm³.</p>","correctCategoryKey":"S","misconceptionId":"mis-msd-volruang-001"},{"id":"p3","text":"<p>1 liter sama dengan 1.000 cm³.</p>","correctCategoryKey":"B"},{"id":"p4","text":"<p>Dua bangun ruang yang volumenya sama pasti bentuknya sama.</p>","correctCategoryKey":"S","misconceptionId":"mis-msd-volruang-004"},{"id":"p5","text":"<p>Satuan volume ditulis dengan cm³.</p>","correctCategoryKey":"B"}]'::jsonb, 'p1: B; p2: S; p3: B; p4: S; p5: B', false, null, null),
  ('msd-sudut-001', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-pengukuran', 'con-matematika-sd-besar-sudut', 'single', 'Memahami penggolongan jenis sudut', 'dasar', 'pemahaman', 'html', '<p>Pada gambar rancangan atap rumah tercatat sebuah sudut yang besarnya 45°.</p>', '<p>Sudut itu tergolong ....</p>', 'Pilih satu jawaban.', '<p>Sudut lancip adalah sudut yang besarnya kurang dari 90°. Karena 45° kurang dari 90°, sudut itu lancip.</p><p>Sudut siku-siku tepat 90°, sudut tumpul antara 90° dan 180°, dan sudut lurus tepat 180°.</p>', '[{"key":"A","text":"<p>sudut lancip</p>"},{"key":"B","text":"<p>sudut siku-siku</p>","misconceptionId":"mis-msd-sudut-003"},{"key":"C","text":"<p>sudut tumpul</p>","misconceptionId":"mis-msd-sudut-003"},{"key":"D","text":"<p>sudut lurus</p>","misconceptionId":"mis-msd-sudut-003"}]'::jsonb, 'A', null, null, null, 'A', false, null, null),
  ('msd-sudut-002', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-pengukuran', 'con-matematika-sd-besar-sudut', 'single', 'Memahami pembacaan busur derajat', 'dasar', 'pemahaman', 'html', '<p>Sebuah sudut diukur dengan busur derajat. Salah satu kakinya berimpit dengan angka 0, dan kaki lainnya menunjuk angka 65 pada deretan skala yang sama.</p>', '<p>Besar dan jenis sudut itu adalah ....</p>', 'Pilih satu jawaban.', '<p>Karena pembacaan dimulai dari angka 0 dan diikuti pada deretan yang sama, besar sudutnya 65°.</p><p>Karena kurang dari 90°, sudut itu tergolong lancip.</p><p>Pilihan B muncul bila angka dibaca pada deretan skala yang berlawanan, yaitu 180 − 65 = 115.</p>', '[{"key":"A","text":"<p>65°, sudut lancip</p>"},{"key":"B","text":"<p>115°, sudut tumpul</p>","misconceptionId":"mis-msd-sudut-002"},{"key":"C","text":"<p>65°, sudut tumpul</p>","misconceptionId":"mis-msd-sudut-003"},{"key":"D","text":"<p>25°, sudut lancip</p>","misconceptionId":"mis-msd-sudut-002"}]'::jsonb, 'A', null, null, null, 'A', true, 'Busur derajat setengah lingkaran dengan dua deret angka: deret luar 0 sampai 180 dari kiri ke kanan, dan deret dalam 180 sampai 0 dari kiri ke kanan. Sebuah sudut digambar dengan titik sudut di pusat busur; kaki pertama mendatar ke kanan berimpit dengan angka 0 pada deret luar, kaki kedua menembus tepi busur tepat pada angka 65 deret luar. Jangan menuliskan besar sudutnya di luar skala busur.', 'svg'),
  ('msd-sudut-003', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-pengukuran', 'con-matematika-sd-besar-sudut', 'single', 'Mengaplikasikan besar sudut pada jarum jam tepat', 'menengah', 'penerapan', 'html', '<p>Sebuah jam dinding menunjukkan pukul 04.00 tepat. Muka jam dibagi menjadi 12 selang yang sama, sehingga setiap selang antara dua angka bernilai 30°.</p>', '<p>Sudut terkecil yang dibentuk kedua jarum jam itu adalah ....</p>', 'Pilih satu jawaban.', '<p>Pada pukul 04.00, jarum panjang di angka 12 dan jarum pendek di angka 4, sehingga terpisah 4 selang.</p><p>Besar sudutnya = 4 × 30° = 120°.</p><p>Sudut itu tergolong tumpul. Pilihan C adalah sudut pada pukul 03.00, yaitu 3 selang.</p>', '[{"key":"A","text":"<p>30°</p>","misconceptionId":"mis-msd-sudut-005"},{"key":"B","text":"<p>60°</p>","misconceptionId":"mis-msd-sudut-005"},{"key":"C","text":"<p>90°</p>","misconceptionId":"mis-msd-sudut-003"},{"key":"D","text":"<p>120°</p>"}]'::jsonb, 'D', null, null, null, 'D', false, null, null),
  ('msd-sudut-004', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-pengukuran', 'con-matematika-sd-besar-sudut', 'single', 'Mengaplikasikan hubungan sudut berpelurus', 'menengah', 'penerapan', 'html', '<p>Dua sudut terletak berdampingan pada satu garis lurus sehingga keduanya berpelurus. Salah satu sudut besarnya 115°.</p>', '<p>Besar sudut yang lainnya adalah ....</p>', 'Pilih satu jawaban.', '<p>Dua sudut yang berpelurus berjumlah 180°, karena bersama-sama membentuk sudut lurus.</p><p>Sudut lainnya = 180° − 115° = 65°.</p><p>Pilihan D muncul bila 115° ditambahkan ke 360° dan dikurangi, yaitu memakai satu putaran penuh sebagai patokan.</p>', '[{"key":"A","text":"<p>65°</p>"},{"key":"B","text":"<p>75°</p>","misconceptionId":"mis-msd-sudut-002"},{"key":"C","text":"<p>85°</p>","misconceptionId":"mis-msd-sudut-004"},{"key":"D","text":"<p>245°</p>","misconceptionId":"mis-msd-sudut-004"}]'::jsonb, 'A', null, null, null, 'A', false, null, null),
  ('msd-sudut-005', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-pengukuran', 'con-matematika-sd-besar-sudut', 'single', 'Mengaplikasikan jumlah sudut dalam segitiga', 'menengah', 'penerapan', 'html', '<p>Sebuah rangka layang-layang berbentuk segitiga. Dua sudut yang sudah diukur besarnya 55° dan 65°.</p>', '<p>Besar sudut yang ketiga adalah ....</p>', 'Pilih satu jawaban.', '<p>Jumlah sudut dalam segitiga adalah 180°.</p><p>Sudut ketiga = 180° − (55° + 65°) = 180° − 120° = 60°.</p><p>Pilihan B muncul bila jumlah sudut segitiga dianggap 360°. Perhatikan bahwa satu sudut sebesar 240° tidak mungkin ada dalam segitiga.</p>', '[{"key":"A","text":"<p>50°</p>","misconceptionId":"mis-msd-sudut-002"},{"key":"B","text":"<p>240°</p>","misconceptionId":"mis-msd-sudut-004"},{"key":"C","text":"<p>70°</p>","misconceptionId":"mis-msd-sudut-002"},{"key":"D","text":"<p>60°</p>"}]'::jsonb, 'D', null, null, null, 'D', false, null, null),
  ('msd-sudut-006', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-pengukuran', 'con-matematika-sd-besar-sudut', 'single', 'Bernalar tentang sudut jarum jam pada pukul setengah', 'lanjut', 'penalaran', 'html', '<p>Sebuah jam menunjukkan pukul 07.30. Setiap selang antara dua angka pada muka jam bernilai 30°, dan jarum pendek bergerak perlahan mengikuti perjalanan menit.</p>', '<p>Sudut terkecil yang dibentuk kedua jarum jam itu adalah ....</p>', 'Pilih satu jawaban.', '<p>Jarum panjang pada 30 menit berada di angka 6.</p><p>Jarum pendek tidak lagi tepat di angka 7. Dalam 30 menit ia sudah bergeser setengah selang, yaitu 15°, sehingga berada 15° setelah angka 7.</p><p>Jarak angka 6 ke angka 7 adalah 30°, ditambah geseran 15° menjadi 45°.</p><p>Pilihan C muncul bila jarum pendek dianggap masih tepat di angka 7, dan pilihan A bila geserannya dihitung dua kali.</p>', '[{"key":"A","text":"<p>30°</p>","misconceptionId":"mis-msd-sudut-005"},{"key":"B","text":"<p>75°</p>","misconceptionId":"mis-msd-sudut-002"},{"key":"C","text":"<p>60°</p>","misconceptionId":"mis-msd-sudut-005"},{"key":"D","text":"<p>45°</p>"}]'::jsonb, 'D', null, null, null, 'D', false, null, null),
  ('msd-sudut-007', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-pengukuran', 'con-matematika-sd-besar-sudut', 'single', 'Bernalar tentang apa yang menentukan besar sudut', 'lanjut', 'penalaran', 'html', '<p>Guru menggambar dua sudut yang bukaannya persis sama, tetapi kaki sudut pertama digambar 3 cm dan kaki sudut kedua digambar 8 cm. Seorang siswa berkata, “Sudut kedua lebih besar, karena kakinya lebih panjang.”</p>', '<p>Tanggapan yang tepat terhadap pendapat siswa itu adalah ....</p>', 'Pilih satu jawaban.', '<p>Sudut diukur dari bukaan antara kedua kakinya dengan busur derajat, bukan dengan penggaris.</p><p>Memperpanjang kaki sudut hanya memperpanjang garisnya; bukaannya tetap, jadi besar sudutnya tidak berubah. Kedua sudut pada gambar itu sama besar.</p><p>Pilihan C sama kelirunya dengan pilihan A, hanya berlawanan arah.</p>', '[{"key":"A","text":"<p>Benar, karena kaki yang lebih panjang membuat bukaan sudutnya ikut melebar.</p>","misconceptionId":"mis-msd-sudut-001"},{"key":"B","text":"<p>Benar, karena besar sudut diukur dengan penggaris pada panjang kakinya.</p>","misconceptionId":"mis-msd-sudut-002"},{"key":"C","text":"<p>Salah, karena kaki yang lebih panjang justru membuat sudutnya menjadi lebih kecil.</p>","misconceptionId":"mis-msd-sudut-001"},{"key":"D","text":"<p>Salah, karena besar sudut ditentukan bukaan kakinya, jadi keduanya sama besar.</p>"}]'::jsonb, 'D', null, null, null, 'D', false, null, null),
  ('msd-sudut-008', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-pengukuran', 'con-matematika-sd-besar-sudut', 'mcma', 'Mengaplikasikan penggolongan dan hubungan besar sudut', 'menengah', 'penerapan', 'html', '<p>Kelas mendaftar beberapa pernyataan tentang besar sudut untuk diperiksa kebenarannya.</p>', '<p>Pernyataan yang benar adalah ....</p>', 'Pilih semua jawaban yang benar.', '<p>A, B, dan C adalah batasan baku penggolongan sudut.</p><p>D salah: sudut 180° disebut sudut lurus.</p><p>E salah: jumlah sudut dalam segitiga 180°, sedangkan 360° adalah satu putaran penuh atau jumlah sudut dalam segi empat.</p>', '[{"key":"A","text":"<p>Sudut yang besarnya 90° disebut sudut siku-siku.</p>"},{"key":"B","text":"<p>Sudut yang besarnya kurang dari 90° disebut sudut lancip.</p>"},{"key":"C","text":"<p>Sudut yang besarnya antara 90° dan 180° disebut sudut tumpul.</p>"},{"key":"D","text":"<p>Sudut yang besarnya 180° disebut sudut lancip.</p>","misconceptionId":"mis-msd-sudut-003"},{"key":"E","text":"<p>Jumlah sudut dalam segitiga adalah 360°.</p>","misconceptionId":"mis-msd-sudut-004"}]'::jsonb, null, array['A', 'B', 'C'], null, null, 'A, B, C', false, null, null),
  ('msd-sudut-009', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-pengukuran', 'con-matematika-sd-besar-sudut', 'mcma', 'Bernalar tentang sudut-sudut dalam satu segitiga', 'lanjut', 'penalaran', 'html', '<p>Sebuah segitiga mempunyai satu sudut 90° dan satu sudut 35°.</p>', '<p>Pernyataan yang benar tentang segitiga itu adalah ....</p>', 'Pilih semua jawaban yang benar.', '<p>A benar: 180° − (90° + 35°) = 55°.</p><p>B benar: salah satu sudutnya tepat 90°.</p><p>C benar: 35° dan 55° keduanya kurang dari 90°.</p><p>D salah: tidak ada sudut yang lebih dari 90°. Segitiga bahkan tidak mungkin punya dua sudut tumpul, karena jumlahnya sudah melebihi 180°.</p><p>E salah: 145° diperoleh dari 180° − 35° dengan mengabaikan sudut 90°.</p>', '[{"key":"A","text":"<p>Sudut ketiganya 55°.</p>"},{"key":"B","text":"<p>Segitiga itu tergolong segitiga siku-siku.</p>"},{"key":"C","text":"<p>Kedua sudut selain sudut siku-siku sama-sama lancip.</p>"},{"key":"D","text":"<p>Segitiga itu mempunyai dua sudut tumpul.</p>","misconceptionId":"mis-msd-sudut-003"},{"key":"E","text":"<p>Sudut ketiganya 145°.</p>","misconceptionId":"mis-msd-sudut-004"}]'::jsonb, null, array['A', 'B', 'C'], null, null, 'A, B, C', false, null, null),
  ('msd-sudut-010', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-pengukuran', 'con-matematika-sd-besar-sudut', 'category', 'Bernalar menilai pernyataan tentang besar sudut', 'lanjut', 'penalaran', 'html', '<p>Lima pernyataan tentang besar sudut ditulis di papan tulis untuk diperiksa bersama.</p>', '<p>Tentukan benar atau salah setiap pernyataan berikut.</p>', 'Tentukan kategori setiap pernyataan.', '<p>P1 benar: satu putaran penuh dibagi menjadi 360 bagian yang sama.</p><p>P2 benar: sudut lurus adalah setengah putaran, yaitu 180°.</p><p>P3 salah: yang menentukan besar sudut adalah bukaan kedua kakinya.</p><p>P4 benar: berpenyiku berarti bersama-sama membentuk sudut siku-siku.</p><p>P5 salah: 95° lebih dari 90°, sehingga tergolong sudut tumpul.</p>', null, null, null, '[{"key":"B","label":"Benar"},{"key":"S","label":"Salah"}]'::jsonb, '[{"id":"p1","text":"<p>Satu putaran penuh sama dengan 360°.</p>","correctCategoryKey":"B"},{"id":"p2","text":"<p>Sudut lurus besarnya 180°.</p>","correctCategoryKey":"B"},{"id":"p3","text":"<p>Besar suatu sudut bergantung pada panjang kakinya.</p>","correctCategoryKey":"S","misconceptionId":"mis-msd-sudut-001"},{"id":"p4","text":"<p>Dua sudut yang berpenyiku berjumlah 90°.</p>","correctCategoryKey":"B"},{"id":"p5","text":"<p>Sudut yang besarnya 95° tergolong sudut lancip.</p>","correctCategoryKey":"S","misconceptionId":"mis-msd-sudut-003"}]'::jsonb, 'p1: B; p2: B; p3: S; p4: B; p5: S', false, null, null),
  ('msd-taksir-001', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-pengukuran', 'con-matematika-sd-penaksiran', 'single', 'Memahami penaksiran hasil perkalian dengan pembulatan', 'dasar', 'pemahaman', 'html', '<p>Panitia lomba ingin memperkirakan banyak kursi yang diperlukan bila ada 47 baris dengan 21 kursi setiap barisnya. Perkiraan dilakukan dengan membulatkan kedua bilangan ke puluhan terdekat.</p>', '<p>Taksiran banyak kursi seluruhnya adalah ....</p>', 'Pilih satu jawaban.', '<p>Bulatkan ke puluhan terdekat: 47 menjadi 50 dan 21 menjadi 20.</p><p>Taksirannya 50 × 20 = 1.000 kursi.</p><p>Hasil sebenarnya 47 × 21 = 987, jadi taksiran 1.000 memang mendekati.</p>', '[{"key":"A","text":"<p>800</p>","misconceptionId":"mis-msd-taksir-001"},{"key":"B","text":"<p>900</p>","misconceptionId":"mis-msd-taksir-002"},{"key":"C","text":"<p>1.000</p>"},{"key":"D","text":"<p>1.200</p>","misconceptionId":"mis-msd-taksir-001"}]'::jsonb, 'C', null, null, null, 'C', false, null, null),
  ('msd-taksir-002', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-pengukuran', 'con-matematika-sd-penaksiran', 'single', 'Memahami penaksiran ukuran benda dengan benda acuan', 'dasar', 'pemahaman', 'html', '<p>Seorang siswa diminta memperkirakan tinggi pintu ruang kelas tanpa mengukurnya, hanya dengan membandingkannya terhadap tinggi badannya sendiri yang sekitar 1,4 m.</p>', '<p>Taksiran tinggi pintu yang paling wajar adalah ....</p>', 'Pilih satu jawaban.', '<p>Tinggi pintu sedikit lebih tinggi daripada orang dewasa, jadi sekitar 2 m.</p><p>Ukuran 20 cm hanya sepanjang penggaris, sedangkan 20 m setinggi bangunan bertingkat enam dan 200 m jauh lebih tinggi lagi.</p><p>Membandingkan dengan benda acuan yang dikenal membuat taksiran tetap wajar.</p>', '[{"key":"A","text":"<p>20 cm</p>","misconceptionId":"mis-msd-taksir-005"},{"key":"B","text":"<p>200 m</p>","misconceptionId":"mis-msd-taksir-005"},{"key":"C","text":"<p>20 m</p>","misconceptionId":"mis-msd-taksir-005"},{"key":"D","text":"<p>2 m</p>"}]'::jsonb, 'D', null, null, null, 'D', false, null, null),
  ('msd-taksir-003', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-pengukuran', 'con-matematika-sd-penaksiran', 'single', 'Mengaplikasikan penaksiran penjumlahan harga', 'menengah', 'penerapan', 'html', '<p>Seorang pembeli mencatat tiga harga barang: Rp18.700, Rp24.300, dan Rp9.800. Ia ingin memperkirakan total harganya dengan membulatkan setiap harga ke ribuan terdekat.</p>', '<p>Taksiran total harga ketiga barang itu adalah ....</p>', 'Pilih satu jawaban.', '<p>Bulatkan ke ribuan terdekat: Rp18.700 menjadi Rp19.000, Rp24.300 menjadi Rp24.000, dan Rp9.800 menjadi Rp10.000.</p><p>Taksirannya 19.000 + 24.000 + 10.000 = Rp53.000.</p><p>Total sebenarnya Rp52.800, jadi taksirannya hanya berselisih Rp200.</p>', '[{"key":"A","text":"<p>Rp50.000</p>","misconceptionId":"mis-msd-taksir-001"},{"key":"B","text":"<p>Rp52.000</p>","misconceptionId":"mis-msd-taksir-002"},{"key":"C","text":"<p>Rp53.000</p>"},{"key":"D","text":"<p>Rp55.000</p>","misconceptionId":"mis-msd-taksir-001"}]'::jsonb, 'C', null, null, null, 'C', false, null, null),
  ('msd-taksir-004', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-pengukuran', 'con-matematika-sd-penaksiran', 'single', 'Mengaplikasikan penaksiran untuk memeriksa kecukupan uang', 'menengah', 'penerapan', 'html', '<p>Rani membawa uang Rp50.000 dan ingin membeli 4 buku tulis yang masing-masing berharga Rp11.500. Sebelum ke kasir, ia menaksir total harganya dengan membulatkan harga satuan ke ribuan terdekat.</p>', '<p>Taksiran total harga dan kesimpulannya adalah ....</p>', 'Pilih satu jawaban.', '<p>Harga Rp11.500 dibulatkan ke ribuan terdekat menjadi Rp12.000, karena angka ratusannya 5 sehingga dibulatkan ke atas.</p><p>Taksirannya 4 × 12.000 = Rp48.000, masih di bawah Rp50.000, jadi uangnya cukup.</p><p>Harga sebenarnya 4 × 11.500 = Rp46.000. Karena pembulatan dilakukan ke atas, taksirannya sedikit lebih besar — dan itu justru menguntungkan untuk memeriksa kecukupan uang.</p>', '[{"key":"A","text":"<p>Rp44.000, uang Rani cukup</p>","misconceptionId":"mis-msd-taksir-002"},{"key":"B","text":"<p>Rp56.000, uang Rani tidak cukup</p>","misconceptionId":"mis-msd-taksir-001"},{"key":"C","text":"<p>Rp48.000, uang Rani tidak cukup</p>","misconceptionId":"mis-msd-taksir-003"},{"key":"D","text":"<p>Rp48.000, uang Rani cukup</p>"}]'::jsonb, 'D', null, null, null, 'D', false, null, null),
  ('msd-taksir-005', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-pengukuran', 'con-matematika-sd-penaksiran', 'single', 'Mengaplikasikan penaksiran luas', 'menengah', 'penerapan', 'html', '<p>Sebuah taman berbentuk persegi panjang berukuran 19 m × 11 m. Petugas ingin memperkirakan luasnya dengan cepat dengan membulatkan kedua ukurannya ke puluhan terdekat.</p>', '<p>Taksiran luas taman itu adalah ....</p>', 'Pilih satu jawaban.', '<p>Bulatkan ke puluhan terdekat: 19 menjadi 20 dan 11 menjadi 10.</p><p>Taksirannya 20 × 10 = 200 m².</p><p>Luas sebenarnya 19 × 11 = 209 m², jadi taksirannya berselisih 9 m² saja.</p>', '[{"key":"A","text":"<p>190 m²</p>","misconceptionId":"mis-msd-taksir-001"},{"key":"B","text":"<p>300 m²</p>","misconceptionId":"mis-msd-taksir-001"},{"key":"C","text":"<p>220 m²</p>","misconceptionId":"mis-msd-taksir-003"},{"key":"D","text":"<p>200 m²</p>"}]'::jsonb, 'D', null, null, null, 'D', false, null, null),
  ('msd-taksir-006', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-pengukuran', 'con-matematika-sd-penaksiran', 'single', 'Bernalar tentang arah taksiran terhadap hasil sebenarnya', 'lanjut', 'penalaran', 'html', '<p>Untuk menaksir 47 × 21, kedua bilangan dibulatkan menjadi 50 × 20 sehingga diperoleh taksiran 1.000.</p>', '<p>Pernyataan yang tepat tentang taksiran itu adalah ....</p>', 'Pilih satu jawaban.', '<p>Hasil sebenarnya 47 × 21 = 987, sedangkan taksirannya 1.000. Jadi taksirannya memang lebih besar.</p><p>Satu bilangan dibulatkan naik 3 dan yang lain turun 1. Karena pengaruh kenaikan itu lebih besar, hasil akhirnya condong ke atas.</p><p>Arah taksiran dapat diperkirakan tanpa menghitung tepat, cukup dengan melihat arah pembulatan setiap bilangannya.</p>', '[{"key":"A","text":"<p>Taksirannya lebih kecil daripada hasil sebenarnya, karena hasil taksiran selalu lebih kecil.</p>","misconceptionId":"mis-msd-taksir-003"},{"key":"B","text":"<p>Taksirannya tepat sama dengan hasil sebenarnya.</p>","misconceptionId":"mis-msd-taksir-004"},{"key":"C","text":"<p>Taksirannya lebih besar daripada hasil sebenarnya, karena kenaikan 47 menjadi 50 lebih berpengaruh daripada penurunan 21 menjadi 20.</p>"},{"key":"D","text":"<p>Arah taksiran tidak dapat diketahui tanpa menghitung ulang seluruh perkaliannya.</p>","misconceptionId":"mis-msd-taksir-001"}]'::jsonb, 'C', null, null, null, 'C', false, null, null),
  ('msd-taksir-007', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-pengukuran', 'con-matematika-sd-penaksiran', 'single', 'Bernalar tentang batas penggunaan penaksiran', 'lanjut', 'penalaran', 'html', '<p>Kelas mendiskusikan situasi mana yang cocok diselesaikan dengan penaksiran dan mana yang menuntut hitungan tepat.</p>', '<p>Situasi yang <strong>tidak tepat</strong> diselesaikan dengan penaksiran adalah ....</p>', 'Pilih satu jawaban.', '<p>Uang kembalian menuntut hitungan tepat sampai satuan rupiahnya. Taksiran akan membuat pembeli atau penjual dirugikan meski selisihnya kecil.</p><p>Tiga situasi lainnya hanya memerlukan gambaran yang mendekati, sehingga penaksiran memang cara yang cepat dan memadai.</p><p>Jadi penaksiran berguna untuk mengambil keputusan cepat, tetapi bukan pengganti hitungan tepat pada urusan yang menuntut ketepatan.</p>', '[{"key":"A","text":"<p>memperkirakan banyak kursi yang dapat dimuat di aula</p>","misconceptionId":"mis-msd-taksir-005"},{"key":"B","text":"<p>memperkirakan lama perjalanan ke sekolah</p>","misconceptionId":"mis-msd-taksir-005"},{"key":"C","text":"<p>menghitung uang kembalian yang harus diterima pembeli</p>"},{"key":"D","text":"<p>memperkirakan berat sekarung buah sebelum ditimbang</p>","misconceptionId":"mis-msd-taksir-005"}]'::jsonb, 'C', null, null, null, 'C', false, null, null),
  ('msd-taksir-008', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-pengukuran', 'con-matematika-sd-penaksiran', 'mcma', 'Mengaplikasikan penaksiran ukuran benda sehari-hari', 'menengah', 'penerapan', 'html', '<p>Kelas menyusun daftar taksiran ukuran beberapa benda di sekitar sekolah.</p>', '<p>Taksiran yang wajar adalah ....</p>', 'Pilih semua jawaban yang benar.', '<p>A, B, dan C sesuai dengan ukuran benda yang biasa dijumpai.</p><p>D tidak wajar: panjang lapangan sepak bola sekitar 100 m, sedangkan 10 m hanya sepanjang satu ruang kelas.</p><p>E tidak wajar: 5 kg setara sekarung beras kecil, sedangkan pensil hanya beberapa gram.</p>', '[{"key":"A","text":"<p>Berat badan seorang siswa SD kira-kira 30 kg.</p>"},{"key":"B","text":"<p>Tinggi meja belajar kira-kira 75 cm.</p>"},{"key":"C","text":"<p>Isi satu gelas minum kira-kira 200 ml.</p>"},{"key":"D","text":"<p>Panjang lapangan sepak bola kira-kira 10 m.</p>","misconceptionId":"mis-msd-taksir-005"},{"key":"E","text":"<p>Berat sebuah pensil kira-kira 5 kg.</p>","misconceptionId":"mis-msd-taksir-005"}]'::jsonb, null, array['A', 'B', 'C'], null, null, 'A, B, C', false, null, null),
  ('msd-taksir-009', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-pengukuran', 'con-matematika-sd-penaksiran', 'mcma', 'Bernalar tentang taksiran dibandingkan hasil sebenarnya', 'lanjut', 'penalaran', 'html', '<p>Panitia menaksir banyak kursi di aula yang tersusun 24 baris dengan 19 kursi setiap barisnya. Taksiran dilakukan dengan membulatkan kedua bilangan ke puluhan terdekat.</p>', '<p>Pernyataan yang benar tentang penaksiran itu adalah ....</p>', 'Pilih semua jawaban yang benar.', '<p>A benar: 24 dibulatkan menjadi 20 dan 19 dibulatkan menjadi 20, sehingga taksirannya 400.</p><p>B benar: 24 × 19 = 456.</p><p>C benar: 400 kurang dari 456. Penurunan 24 menjadi 20 lebih berpengaruh daripada kenaikan 19 menjadi 20, sehingga taksirannya condong ke bawah.</p><p>D dan E salah karena bertentangan dengan hitungan itu. Perhatikan bahwa untuk menyiapkan kursi, taksiran yang terlalu kecil justru berisiko kekurangan.</p>', '[{"key":"A","text":"<p>Taksirannya 20 × 20 = 400 kursi.</p>"},{"key":"B","text":"<p>Banyak kursi sebenarnya 456.</p>"},{"key":"C","text":"<p>Taksirannya lebih kecil daripada banyak kursi sebenarnya.</p>"},{"key":"D","text":"<p>Taksirannya lebih besar daripada banyak kursi sebenarnya.</p>","misconceptionId":"mis-msd-taksir-003"},{"key":"E","text":"<p>Taksirannya tepat sama dengan banyak kursi sebenarnya.</p>","misconceptionId":"mis-msd-taksir-004"}]'::jsonb, null, array['A', 'B', 'C'], null, null, 'A, B, C', false, null, null),
  ('msd-taksir-010', 'sub-matematika-sd', 'top-matematika-sd-geometri-pengukuran', 'st-matematika-sd-pengukuran', 'con-matematika-sd-penaksiran', 'category', 'Bernalar menilai pernyataan tentang penaksiran dan pembulatan', 'lanjut', 'penalaran', 'html', '<p>Lima pernyataan tentang penaksiran dan pembulatan dikumpulkan untuk diperiksa bersama.</p>', '<p>Tentukan benar atau salah setiap pernyataan berikut.</p>', 'Tentukan kategori setiap pernyataan.', '<p>P1 benar: itulah gunanya penaksiran — cepat dan cukup mendekati.</p><p>P2 benar: angka satuannya 8, lebih dari 5, jadi dibulatkan ke atas.</p><p>P3 salah: angka puluhannya tepat 50, yaitu persis di tengah antara 4.300 dan 4.400. Aturan pembulatan mengambil yang lebih besar, jadi hasilnya 4.400.</p><p>P4 benar: kedua faktor bertambah, sehingga hasil kalinya pasti bertambah.</p><p>P5 salah: arah taksiran bergantung arah pembulatannya. Taksiran 50 × 20 = 1.000 untuk 47 × 21 = 987 justru lebih besar.</p>', null, null, null, '[{"key":"B","label":"Benar"},{"key":"S","label":"Salah"}]'::jsonb, '[{"id":"p1","text":"<p>Penaksiran dipakai untuk memperoleh hasil yang mendekati, bukan hasil yang tepat.</p>","correctCategoryKey":"B"},{"id":"p2","text":"<p>Bilangan 68 dibulatkan ke puluhan terdekat menjadi 70.</p>","correctCategoryKey":"B"},{"id":"p3","text":"<p>Bilangan 4.350 dibulatkan ke ratusan terdekat menjadi 4.300.</p>","correctCategoryKey":"S","misconceptionId":"mis-msd-taksir-002"},{"id":"p4","text":"<p>Membulatkan kedua faktor ke atas membuat taksiran perkaliannya lebih besar daripada hasil sebenarnya.</p>","correctCategoryKey":"B"},{"id":"p5","text":"<p>Hasil penaksiran selalu lebih kecil daripada hasil sebenarnya.</p>","correctCategoryKey":"S","misconceptionId":"mis-msd-taksir-003"}]'::jsonb, 'p1: B; p2: B; p3: S; p4: B; p5: S', false, null, null),
  ('msd-sajidata-001', 'sub-matematika-sd', 'top-matematika-sd-data', 'st-matematika-sd-penyajian-data', 'con-matematika-sd-penyajian-data', 'single', 'Memahami pembacaan piktogram', 'dasar', 'pemahaman', 'html', '<p>Sebuah piktogram menampilkan banyak buku yang terjual di koperasi sekolah. Satu gambar buku mewakili 5 buku. Pada baris Senin terdapat 4 gambar buku.</p>', '<p>Banyak buku yang terjual pada hari Senin adalah ....</p>', 'Pilih satu jawaban.', '<p>Banyak data = banyak gambar × nilai satu gambar = 4 × 5 = 20 buku.</p><p>Pilihan A hanya menyebut banyak gambarnya, dan pilihan B menjumlahkan 4 dengan 5 alih-alih mengalikannya.</p>', '[{"key":"A","text":"<p>4 buku</p>","misconceptionId":"mis-msd-sajidata-001"},{"key":"B","text":"<p>9 buku</p>","misconceptionId":"mis-msd-sajidata-003"},{"key":"C","text":"<p>20 buku</p>"},{"key":"D","text":"<p>25 buku</p>","misconceptionId":"mis-msd-sajidata-002"}]'::jsonb, 'C', null, null, null, 'C', true, 'Piktogram mendatar berjudul ''Buku Terjual''. Empat baris berlabel Senin, Selasa, Rabu, Kamis. Baris Senin memuat 4 ikon buku identik, Selasa 6 ikon, Rabu 3 ikon, Kamis 5 ikon, semuanya sama besar dan berjarak sama. Di bawah gambar tuliskan keterangan ''Satu gambar buku mewakili 5 buku''.', 'svg'),
  ('msd-sajidata-002', 'sub-matematika-sd', 'top-matematika-sd-data', 'st-matematika-sd-penyajian-data', 'con-matematika-sd-penyajian-data', 'single', 'Memahami pembacaan tabel frekuensi', 'dasar', 'pemahaman', 'html', '<p>Tabel frekuensi nilai ulangan matematika satu kelas tercatat sebagai berikut:</p><ul><li>Nilai 6: 5 siswa</li><li>Nilai 7: 8 siswa</li><li>Nilai 8: 6 siswa</li><li>Nilai 9: 3 siswa</li><li>Nilai 10: 2 siswa</li></ul>', '<p>Banyak siswa yang mengikuti ulangan itu adalah ....</p>', 'Pilih satu jawaban.', '<p>Banyak seluruh siswa adalah jumlah frekuensinya: 5 + 8 + 6 + 3 + 2 = 24 siswa.</p><p>Pilihan C menjumlahkan nilai ulangannya, yaitu 6 + 7 + 8 + 9 + 10 = 40 — itu bukan banyak siswa.</p><p>Pilihan B mengalikan setiap nilai dengan frekuensinya lalu menjumlahkannya; hasil itu jumlah seluruh nilai, bukan banyak siswa.</p>', '[{"key":"A","text":"<p>5 siswa</p>","misconceptionId":"mis-msd-sajidata-001"},{"key":"B","text":"<p>178 siswa</p>","misconceptionId":"mis-msd-sajidata-003"},{"key":"C","text":"<p>40 siswa</p>","misconceptionId":"mis-msd-sajidata-003"},{"key":"D","text":"<p>24 siswa</p>"}]'::jsonb, 'D', null, null, null, 'D', false, null, null),
  ('msd-sajidata-003', 'sub-matematika-sd', 'top-matematika-sd-data', 'st-matematika-sd-penyajian-data', 'con-matematika-sd-penyajian-data', 'single', 'Mengaplikasikan pembacaan tabel frekuensi untuk mencari banyak data pada beberapa kelompok', 'menengah', 'penerapan', 'html', '<p>Tabel frekuensi nilai ulangan yang sama memuat: nilai 6 sebanyak 5 siswa, nilai 7 sebanyak 8 siswa, nilai 8 sebanyak 6 siswa, nilai 9 sebanyak 3 siswa, dan nilai 10 sebanyak 2 siswa.</p>', '<p>Banyak siswa yang memperoleh nilai paling sedikit 8 adalah ....</p>', 'Pilih satu jawaban.', '<p>“Paling sedikit 8” berarti nilai 8, 9, dan 10 ikut dihitung.</p><p>Jumlahnya = 6 + 3 + 2 = 11 siswa.</p><p>Pilihan A hanya menghitung nilai 8, dan pilihan D ikut menghitung nilai 7 yang seharusnya tidak termasuk.</p>', '[{"key":"A","text":"<p>6 siswa</p>","misconceptionId":"mis-msd-sajidata-003"},{"key":"B","text":"<p>9 siswa</p>","misconceptionId":"mis-msd-sajidata-003"},{"key":"C","text":"<p>11 siswa</p>"},{"key":"D","text":"<p>13 siswa</p>","misconceptionId":"mis-msd-sajidata-002"}]'::jsonb, 'C', null, null, null, 'C', false, null, null),
  ('msd-sajidata-004', 'sub-matematika-sd', 'top-matematika-sd-data', 'st-matematika-sd-penyajian-data', 'con-matematika-sd-penyajian-data', 'single', 'Mengaplikasikan pembacaan piktogram dengan setengah gambar', 'menengah', 'penerapan', 'html', '<p>Sebuah piktogram menampilkan banyak pengunjung perpustakaan. Satu gambar orang mewakili 10 pengunjung. Pada baris Rabu terdapat 3 gambar penuh dan 1 gambar yang tampak separuh.</p>', '<p>Banyak pengunjung pada hari Rabu adalah ....</p>', 'Pilih satu jawaban.', '<p>Tiga gambar penuh bernilai 3 × 10 = 30 pengunjung, dan satu gambar separuh bernilai 10 : 2 = 5 pengunjung.</p><p>Jumlahnya = 30 + 5 = 35 pengunjung.</p><p>Pilihan B membuang gambar separuhnya dan pilihan D menghitungnya sebagai gambar penuh.</p>', '[{"key":"A","text":"<p>35 pengunjung</p>"},{"key":"B","text":"<p>30 pengunjung</p>","misconceptionId":"mis-msd-sajidata-002"},{"key":"C","text":"<p>3,5 pengunjung</p>","misconceptionId":"mis-msd-sajidata-001"},{"key":"D","text":"<p>40 pengunjung</p>","misconceptionId":"mis-msd-sajidata-002"}]'::jsonb, 'A', null, null, null, 'A', true, 'Piktogram mendatar berjudul ''Pengunjung Perpustakaan''. Tiga baris berlabel Senin, Selasa, Rabu. Baris Senin memuat 2 ikon orang penuh, Selasa 4 ikon penuh, dan Rabu 3 ikon penuh ditambah satu ikon yang digambar terpotong tepat separuhnya. Di bawah gambar tuliskan keterangan ''Satu gambar orang mewakili 10 pengunjung''.', 'svg'),
  ('msd-sajidata-005', 'sub-matematika-sd', 'top-matematika-sd-data', 'st-matematika-sd-penyajian-data', 'con-matematika-sd-penyajian-data', 'single', 'Mengaplikasikan pembacaan diagram batang', 'menengah', 'penerapan', 'html', '<p>Diagram batang banyak pengunjung perpustakaan selama lima hari mencatat: Senin 12 orang, Selasa 18 orang, Rabu 15 orang, Kamis 9 orang, dan Jumat 21 orang.</p>', '<p>Selisih banyak pengunjung pada hari terbanyak dan hari tersedikit adalah ....</p>', 'Pilih satu jawaban.', '<p>Hari terbanyak adalah Jumat dengan 21 orang, dan hari tersedikit adalah Kamis dengan 9 orang.</p><p>Selisihnya = 21 − 9 = 12 orang.</p><p>Pilihan B menjumlahkan keduanya, bukan mengurangkan.</p>', '[{"key":"A","text":"<p>9 orang</p>","misconceptionId":"mis-msd-sajidata-004"},{"key":"B","text":"<p>30 orang</p>","misconceptionId":"mis-msd-sajidata-003"},{"key":"C","text":"<p>21 orang</p>","misconceptionId":"mis-msd-sajidata-004"},{"key":"D","text":"<p>12 orang</p>"}]'::jsonb, 'D', null, null, null, 'D', true, 'Diagram batang tegak berjudul ''Pengunjung Perpustakaan per Hari''. Sumbu mendatar memuat lima label: Senin, Selasa, Rabu, Kamis, Jumat. Sumbu tegak bertulis ''Banyak pengunjung'' dengan angka 0, 3, 6, 9, 12, 15, 18, 21, 24 dan garis bantu mendatar tipis. Tinggi batang berturut-turut 12, 18, 15, 9, dan 21. Semua batang sama lebar dan berwarna sama.', 'svg'),
  ('msd-sajidata-006', 'sub-matematika-sd', 'top-matematika-sd-data', 'st-matematika-sd-penyajian-data', 'con-matematika-sd-penyajian-data', 'single', 'Bernalar tentang kelengkapan keterangan pada piktogram', 'lanjut', 'penalaran', 'html', '<p>Sebuah piktogram menampilkan banyak siswa yang mengikuti tiga jenis ekstrakurikuler. Gambarnya rapi dan mudah dibaca, tetapi tidak ada satu pun keterangan tentang berapa siswa yang diwakili setiap gambar.</p>', '<p>Kesimpulan yang tepat tentang piktogram itu adalah ....</p>', 'Pilih satu jawaban.', '<p>Nilai satu gambar adalah keterangan wajib pada piktogram. Tanpa keterangan itu, banyak data tidak dapat dihitung sebagai angka.</p><p>Meski begitu, piktogramnya tidak sepenuhnya tak berguna: urutan mana yang paling banyak dan paling sedikit masih terbaca dari banyak gambarnya, selama semua gambar sama besar.</p><p>Pilihan B dan C sama-sama menebak nilai gambar tanpa dasar apa pun.</p>', '[{"key":"A","text":"<p>Banyak siswa tidak dapat ditentukan; yang masih terbaca hanya urutan banyak-sedikitnya.</p>"},{"key":"B","text":"<p>Banyak siswa sama dengan banyak gambarnya, karena satu gambar mewakili satu siswa.</p>","misconceptionId":"mis-msd-sajidata-001"},{"key":"C","text":"<p>Banyak siswa dapat dihitung dengan menjumlahkan seluruh gambar lalu dikalikan 10.</p>","misconceptionId":"mis-msd-sajidata-005"},{"key":"D","text":"<p>Piktogram itu tidak berguna sama sekali sehingga seluruh datanya harus dibuang.</p>","misconceptionId":"mis-msd-sajidata-005"}]'::jsonb, 'A', null, null, null, 'A', false, null, null),
  ('msd-sajidata-007', 'sub-matematika-sd', 'top-matematika-sd-data', 'st-matematika-sd-penyajian-data', 'con-matematika-sd-penyajian-data', 'single', 'Bernalar mengubah tabel frekuensi menjadi piktogram', 'lanjut', 'penalaran', 'html', '<p>Data warna kesukaan siswa akan diubah dari tabel frekuensi menjadi piktogram. Salah satu warna dipilih oleh 10 siswa, dan pada piktogram itu satu gambar akan mewakili 4 siswa.</p>', '<p>Banyak gambar yang harus digambar untuk warna itu adalah ....</p>', 'Pilih satu jawaban.', '<p>Banyak gambar = banyak data : nilai satu gambar = 10 : 4 = 2 sisa 2.</p><p>Sisa 2 siswa sama dengan setengah dari nilai satu gambar, jadi digambar sebagai setengah gambar. Hasilnya 2 setengah gambar.</p><p>Pilihan A membuang sisanya dan pilihan C membulatkannya menjadi satu gambar penuh — keduanya membuat piktogram tidak lagi menyatakan data yang sebenarnya. Pilihan B mengalikan alih-alih membagi.</p>', '[{"key":"A","text":"<p>2 gambar</p>","misconceptionId":"mis-msd-sajidata-002"},{"key":"B","text":"<p>40 gambar</p>","misconceptionId":"mis-msd-sajidata-001"},{"key":"C","text":"<p>3 gambar</p>","misconceptionId":"mis-msd-sajidata-002"},{"key":"D","text":"<p>2 setengah gambar</p>"}]'::jsonb, 'D', null, null, null, 'D', false, null, null),
  ('msd-sajidata-008', 'sub-matematika-sd', 'top-matematika-sd-data', 'st-matematika-sd-penyajian-data', 'con-matematika-sd-penyajian-data', 'mcma', 'Mengaplikasikan pembacaan tabel frekuensi warna kesukaan', 'menengah', 'penerapan', 'html', '<p>Tabel frekuensi warna kesukaan siswa satu kelas tercatat sebagai berikut:</p><ul><li>Merah: 7 siswa</li><li>Biru: 10 siswa</li><li>Hijau: 5 siswa</li><li>Kuning: 3 siswa</li></ul>', '<p>Pernyataan yang benar tentang data itu adalah ....</p>', 'Pilih semua jawaban yang benar.', '<p>A benar: 7 + 10 + 5 + 3 = 25 siswa.</p><p>B benar: 10 adalah frekuensi terbesar.</p><p>C benar: 3 adalah frekuensi terkecil.</p><p>D salah: 7 kurang dari 10.</p><p>E salah: selisihnya 10 − 5 = 5 siswa, sedangkan 15 adalah jumlah keduanya.</p>', '[{"key":"A","text":"<p>Banyak siswa seluruhnya 25 orang.</p>"},{"key":"B","text":"<p>Biru adalah warna yang paling banyak dipilih.</p>"},{"key":"C","text":"<p>Kuning adalah warna yang paling sedikit dipilih.</p>"},{"key":"D","text":"<p>Merah dipilih lebih banyak daripada biru.</p>","misconceptionId":"mis-msd-sajidata-003"},{"key":"E","text":"<p>Selisih pemilih biru dan hijau adalah 15 siswa.</p>","misconceptionId":"mis-msd-sajidata-003"}]'::jsonb, null, array['A', 'B', 'C'], null, null, 'A, B, C', false, null, null),
  ('msd-sajidata-009', 'sub-matematika-sd', 'top-matematika-sd-data', 'st-matematika-sd-penyajian-data', 'con-matematika-sd-penyajian-data', 'mcma', 'Bernalar tentang data pada diagram batang', 'lanjut', 'penalaran', 'html', '<p>Diagram batang banyak pengunjung perpustakaan mencatat: Senin 12 orang, Selasa 18 orang, Rabu 15 orang, Kamis 9 orang, dan Jumat 21 orang.</p>', '<p>Pernyataan yang benar tentang data itu adalah ....</p>', 'Pilih semua jawaban yang benar.', '<p>A benar: 12 + 18 + 15 + 9 + 21 = 75 orang.</p><p>B benar: 21 adalah batang tertinggi.</p><p>C benar: 21 − 9 = 12 orang.</p><p>D salah: dua kali 9 adalah 18, sedangkan hari Rabu 15 orang. Yang dua kali pengunjung hari Kamis justru hari Selasa.</p><p>E salah: dari Rabu ke Kamis banyak pengunjung justru turun dari 15 menjadi 9.</p>', '[{"key":"A","text":"<p>Jumlah pengunjung selama lima hari itu 75 orang.</p>"},{"key":"B","text":"<p>Hari Jumat paling banyak dikunjungi.</p>"},{"key":"C","text":"<p>Selisih pengunjung hari Jumat dan hari Kamis 12 orang.</p>"},{"key":"D","text":"<p>Pengunjung hari Rabu dua kali pengunjung hari Kamis.</p>","misconceptionId":"mis-msd-sajidata-004"},{"key":"E","text":"<p>Banyak pengunjung selalu bertambah dari hari ke hari.</p>","misconceptionId":"mis-msd-sajidata-005"}]'::jsonb, null, array['A', 'B', 'C'], null, null, 'A, B, C', false, null, null),
  ('msd-sajidata-010', 'sub-matematika-sd', 'top-matematika-sd-data', 'st-matematika-sd-penyajian-data', 'con-matematika-sd-penyajian-data', 'category', 'Bernalar menilai pernyataan tentang penyajian data', 'lanjut', 'penalaran', 'html', '<p>Lima pernyataan tentang cara menyajikan data dikumpulkan untuk diperiksa bersama.</p>', '<p>Tentukan benar atau salah setiap pernyataan berikut.</p>', 'Tentukan kategori setiap pernyataan.', '<p>P1 benar: tanpa keterangan itu, banyak data tidak dapat dihitung.</p><p>P2 benar: itulah gunanya kolom frekuensi.</p><p>P3 benar: yang dibandingkan pada diagram batang adalah tingginya.</p><p>P4 salah: batang yang lebih lebar tampak lebih besar meski tingginya sama, sehingga pembacanya dapat tersesatkan. Lebar batang harus dibuat sama.</p><p>P5 salah: setengah gambar justru dipakai untuk menyatakan data yang bukan kelipatan nilai gambarnya, misalnya 35 pada piktogram bernilai 10 per gambar.</p>', null, null, null, '[{"key":"B","label":"Benar"},{"key":"S","label":"Salah"}]'::jsonb, '[{"id":"p1","text":"<p>Piktogram harus menyertakan keterangan nilai setiap gambarnya.</p>","correctCategoryKey":"B"},{"id":"p2","text":"<p>Tabel frekuensi menunjukkan banyak data pada setiap kelompok.</p>","correctCategoryKey":"B"},{"id":"p3","text":"<p>Tinggi batang pada diagram batang menyatakan banyak data.</p>","correctCategoryKey":"B"},{"id":"p4","text":"<p>Diagram batang dengan lebar batang yang berbeda-beda tetap adil untuk dibandingkan.</p>","correctCategoryKey":"S","misconceptionId":"mis-msd-sajidata-005"},{"id":"p5","text":"<p>Piktogram tidak dapat memuat setengah gambar.</p>","correctCategoryKey":"S","misconceptionId":"mis-msd-sajidata-002"}]'::jsonb, 'p1: B; p2: B; p3: B; p4: S; p5: S', false, null, null),
  ('msd-gunadata-001', 'sub-matematika-sd', 'top-matematika-sd-data', 'st-matematika-sd-penyajian-data', 'con-matematika-sd-penggunaan-data', 'single', 'Memahami pengambilan informasi langsung dari tabel', 'dasar', 'pemahaman', 'html', '<p>Perpustakaan sekolah mencatat peminjaman buku selama satu pekan:</p><ul><li>Cerita rakyat: 24 buku</li><li>Ensiklopedia: 15 buku</li><li>Komik edukasi: 32 buku</li><li>Biografi: 9 buku</li></ul>', '<p>Jenis buku yang paling banyak dipinjam adalah ....</p>', 'Pilih satu jawaban.', '<p>Bandingkan keempat angkanya: 24, 15, 32, dan 9.</p><p>Angka terbesar adalah 32, yaitu komik edukasi.</p><p>Perhatikan bahwa biografi dengan 9 buku adalah yang paling sedikit, bukan yang paling banyak.</p>', '[{"key":"A","text":"<p>cerita rakyat</p>","misconceptionId":"mis-msd-gunadata-005"},{"key":"B","text":"<p>ensiklopedia</p>","misconceptionId":"mis-msd-gunadata-005"},{"key":"C","text":"<p>komik edukasi</p>"},{"key":"D","text":"<p>biografi</p>","misconceptionId":"mis-msd-gunadata-005"}]'::jsonb, 'C', null, null, null, 'C', false, null, null),
  ('msd-gunadata-002', 'sub-matematika-sd', 'top-matematika-sd-data', 'st-matematika-sd-penyajian-data', 'con-matematika-sd-penggunaan-data', 'single', 'Memahami penjumlahan seluruh data', 'dasar', 'pemahaman', 'html', '<p>Catatan peminjaman yang sama memuat cerita rakyat 24 buku, ensiklopedia 15 buku, komik edukasi 32 buku, dan biografi 9 buku.</p>', '<p>Banyak buku yang dipinjam selama pekan itu seluruhnya adalah ....</p>', 'Pilih satu jawaban.', '<p>Jumlahkan seluruh frekuensinya: 24 + 15 + 32 + 9 = 80 buku.</p><p>Pilihan A hanya jenis yang terbanyak, dan pilihan D adalah banyak jenis bukunya, bukan banyak bukunya.</p>', '[{"key":"A","text":"<p>32 buku</p>","misconceptionId":"mis-msd-gunadata-005"},{"key":"B","text":"<p>71 buku</p>","misconceptionId":"mis-msd-gunadata-005"},{"key":"C","text":"<p>80 buku</p>"},{"key":"D","text":"<p>4 buku</p>","misconceptionId":"mis-msd-gunadata-003"}]'::jsonb, 'C', null, null, null, 'C', false, null, null),
  ('msd-gunadata-003', 'sub-matematika-sd', 'top-matematika-sd-data', 'st-matematika-sd-penyajian-data', 'con-matematika-sd-penggunaan-data', 'single', 'Mengaplikasikan data untuk mencari selisih', 'menengah', 'penerapan', 'html', '<p>Catatan peminjaman memuat cerita rakyat 24 buku, ensiklopedia 15 buku, komik edukasi 32 buku, dan biografi 9 buku.</p>', '<p>Selisih peminjaman antara jenis buku yang paling banyak dan yang paling sedikit adalah ....</p>', 'Pilih satu jawaban.', '<p>Paling banyak adalah komik edukasi 32 buku, dan paling sedikit adalah biografi 9 buku.</p><p>Selisihnya = 32 − 9 = 23 buku.</p><p>Pilihan C menjumlahkan keduanya, dan pilihan A memakai ensiklopedia yang bukan data paling sedikit.</p>', '[{"key":"A","text":"<p>17 buku</p>","misconceptionId":"mis-msd-gunadata-005"},{"key":"B","text":"<p>80 buku</p>","misconceptionId":"mis-msd-gunadata-005"},{"key":"C","text":"<p>41 buku</p>","misconceptionId":"mis-msd-gunadata-005"},{"key":"D","text":"<p>23 buku</p>"}]'::jsonb, 'D', null, null, null, 'D', false, null, null),
  ('msd-gunadata-004', 'sub-matematika-sd', 'top-matematika-sd-data', 'st-matematika-sd-penyajian-data', 'con-matematika-sd-penggunaan-data', 'single', 'Mengaplikasikan data untuk mengambil keputusan', 'menengah', 'penerapan', 'html', '<p>Kantin sekolah mencatat banyak pembeli pada empat waktu berbeda dalam sehari:</p><ul><li>Pukul 09.30: 45 pembeli</li><li>Pukul 10.00: 78 pembeli</li><li>Pukul 12.00: 95 pembeli</li><li>Pukul 12.30: 60 pembeli</li></ul><p>Pengelola kantin hanya mampu menambah satu petugas pada satu waktu saja.</p>', '<p>Berdasarkan data itu, petugas tambahan paling tepat ditempatkan pada pukul ....</p>', 'Pilih satu jawaban.', '<p>Petugas tambahan paling berguna pada waktu tersibuk, yaitu ketika pembelinya paling banyak.</p><p>Angka terbesar adalah 95 pembeli pada pukul 12.00.</p><p>Pilihan A justru waktu paling lengang dengan 45 pembeli.</p>', '[{"key":"A","text":"<p>09.30</p>","misconceptionId":"mis-msd-gunadata-001"},{"key":"B","text":"<p>10.00</p>","misconceptionId":"mis-msd-gunadata-005"},{"key":"C","text":"<p>12.00</p>"},{"key":"D","text":"<p>12.30</p>","misconceptionId":"mis-msd-gunadata-003"}]'::jsonb, 'C', null, null, null, 'C', false, null, null),
  ('msd-gunadata-005', 'sub-matematika-sd', 'top-matematika-sd-data', 'st-matematika-sd-penyajian-data', 'con-matematika-sd-penggunaan-data', 'single', 'Mengaplikasikan data untuk menghitung kebutuhan', 'menengah', 'penerapan', 'html', '<p>Berdasarkan catatan peminjaman satu pekan, komik edukasi dipinjam 32 kali. Sekolah memutuskan menambah koleksi komik edukasi sebanyak setengah dari banyak peminjaman itu.</p>', '<p>Banyak komik edukasi yang akan ditambahkan adalah ....</p>', 'Pilih satu jawaban.', '<p>Setengah dari 32 adalah 32 : 2 = 16 buku.</p><p>Pilihan C adalah banyak peminjamannya sendiri, dan pilihan D justru menggandakannya.</p>', '[{"key":"A","text":"<p>16 buku</p>"},{"key":"B","text":"<p>8 buku</p>","misconceptionId":"mis-msd-gunadata-005"},{"key":"C","text":"<p>32 buku</p>","misconceptionId":"mis-msd-gunadata-005"},{"key":"D","text":"<p>64 buku</p>","misconceptionId":"mis-msd-gunadata-002"}]'::jsonb, 'A', null, null, null, 'A', false, null, null),
  ('msd-gunadata-006', 'sub-matematika-sd', 'top-matematika-sd-data', 'st-matematika-sd-penyajian-data', 'con-matematika-sd-penggunaan-data', 'single', 'Bernalar menilai kesimpulan yang melampaui data', 'lanjut', 'penalaran', 'html', '<p>Melihat catatan bahwa biografi hanya dipinjam 9 kali sedangkan komik edukasi 32 kali, seorang siswa menyimpulkan, “Berarti siswa di sekolah ini tidak menyukai buku biografi.”</p>', '<p>Tanggapan yang tepat terhadap kesimpulan itu adalah ....</p>', 'Pilih satu jawaban.', '<p>Data itu mencatat banyak peminjaman, bukan kesukaan. Angka kecil bisa berasal dari sebab lain: koleksinya sedikit, letaknya di rak yang jarang dilewati, atau buku-bukunya sedang dipinjam lama.</p><p>Untuk menyimpulkan kesukaan, diperlukan data lain seperti hasil angket, bukan catatan peminjaman.</p><p>Data itu tetap berguna, misalnya untuk memutuskan penambahan koleksi — jadi pilihan B terlalu jauh.</p>', '[{"key":"A","text":"<p>Tepat, karena angka peminjaman biografi paling kecil di antara keempat jenis buku.</p>","misconceptionId":"mis-msd-gunadata-001"},{"key":"B","text":"<p>Tidak tepat, karena data peminjaman tidak dapat dipakai untuk keperluan apa pun.</p>","misconceptionId":"mis-msd-gunadata-004"},{"key":"C","text":"<p>Tepat, karena setiap siswa pasti memilih buku yang paling banyak dipinjam temannya.</p>","misconceptionId":"mis-msd-gunadata-003"},{"key":"D","text":"<p>Belum tentu tepat, karena data itu hanya mencatat peminjaman, bukan kesukaan siswa.</p>"}]'::jsonb, 'D', null, null, null, 'D', false, null, null),
  ('msd-gunadata-007', 'sub-matematika-sd', 'top-matematika-sd-data', 'st-matematika-sd-penyajian-data', 'con-matematika-sd-penggunaan-data', 'single', 'Bernalar tentang batas perkiraan berdasarkan data', 'lanjut', 'penalaran', 'html', '<p>Selama satu pekan, komik edukasi selalu menjadi buku yang paling banyak dipinjam. Panitia perpustakaan ingin menyimpulkan keadaan pekan depan.</p>', '<p>Pernyataan yang paling dapat dipertanggungjawabkan adalah ....</p>', 'Pilih satu jawaban.', '<p>Data satu pekan memberi dasar untuk memperkirakan, karena kebiasaan biasanya berulang. Karena itu kata yang tepat adalah “diperkirakan”.</p><p>Namun kepastian tidak dapat diklaim: pekan depan bisa ada buku baru, tugas dari guru, atau perubahan jadwal yang mengubah keadaan.</p><p>Pilihan D terlalu jauh ke arah sebaliknya — data tetap berguna sebagai dasar perkiraan, sekadar bukan jaminan.</p>', '[{"key":"A","text":"<p>Pekan depan komik edukasi diperkirakan tetap paling banyak dipinjam, tetapi hal itu belum dapat dipastikan.</p>"},{"key":"B","text":"<p>Pekan depan komik edukasi pasti kembali menjadi buku yang paling banyak dipinjam.</p>","misconceptionId":"mis-msd-gunadata-002"},{"key":"C","text":"<p>Pekan depan komik edukasi pasti tidak lagi paling banyak dipinjam.</p>","misconceptionId":"mis-msd-gunadata-002"},{"key":"D","text":"<p>Data satu pekan tidak dapat dipakai untuk memperkirakan apa pun.</p>","misconceptionId":"mis-msd-gunadata-004"}]'::jsonb, 'A', null, null, null, 'A', false, null, null),
  ('msd-gunadata-008', 'sub-matematika-sd', 'top-matematika-sd-data', 'st-matematika-sd-penyajian-data', 'con-matematika-sd-penggunaan-data', 'mcma', 'Mengaplikasikan pengambilan informasi dari satu kumpulan data', 'menengah', 'penerapan', 'html', '<p>Catatan peminjaman satu pekan: cerita rakyat 24 buku, ensiklopedia 15 buku, komik edukasi 32 buku, dan biografi 9 buku.</p>', '<p>Pernyataan yang benar tentang data itu adalah ....</p>', 'Pilih semua jawaban yang benar.', '<p>A benar: 32 lebih dari 24.</p><p>B benar: 24 + 15 + 32 + 9 = 80 buku.</p><p>C benar: 15 lebih dari 9.</p><p>D salah: 9 kurang dari 15.</p><p>E salah: 24 + 9 = 33, yang justru lebih banyak daripada 32. Selisihnya hanya 1 buku, jadi pernyataan ini harus benar-benar dihitung, tidak boleh ditebak.</p>', '[{"key":"A","text":"<p>Komik edukasi dipinjam lebih banyak daripada cerita rakyat.</p>"},{"key":"B","text":"<p>Jumlah seluruh peminjaman 80 buku.</p>"},{"key":"C","text":"<p>Ensiklopedia dipinjam lebih banyak daripada biografi.</p>"},{"key":"D","text":"<p>Biografi dipinjam lebih banyak daripada ensiklopedia.</p>","misconceptionId":"mis-msd-gunadata-005"},{"key":"E","text":"<p>Cerita rakyat dan biografi bersama-sama masih lebih sedikit daripada komik edukasi.</p>","misconceptionId":"mis-msd-gunadata-005"}]'::jsonb, null, array['A', 'B', 'C'], null, null, 'A, B, C', false, null, null),
  ('msd-gunadata-009', 'sub-matematika-sd', 'top-matematika-sd-data', 'st-matematika-sd-penyajian-data', 'con-matematika-sd-penggunaan-data', 'mcma', 'Bernalar tentang kesimpulan yang didukung data berpola', 'lanjut', 'penalaran', 'html', '<p>Hasil panen sayur di kebun sekolah selama tiga bulan tercatat sebagai berikut:</p><ul><li>Januari: 120 kg</li><li>Februari: 150 kg</li><li>Maret: 180 kg</li></ul>', '<p>Pernyataan yang didukung data itu adalah ....</p>', 'Pilih semua jawaban yang benar.', '<p>A benar: 150 − 120 = 30 dan 180 − 150 = 30.</p><p>B benar: 120 + 150 + 180 = 450 kg.</p><p>C benar: bila polanya berlanjut, 180 + 30 = 210 kg — dan kata “diperkirakan” sudah tepat.</p><p>D salah: panen bergantung cuaca, hama, dan perawatan, jadi tidak dapat dipastikan.</p><p>E salah: dua kali 120 adalah 240 kg, sedangkan panen Maret 180 kg.</p>', '[{"key":"A","text":"<p>Hasil panen bertambah 30 kg setiap bulan.</p>"},{"key":"B","text":"<p>Jumlah panen selama tiga bulan itu 450 kg.</p>"},{"key":"C","text":"<p>Bila pola itu berlanjut, panen April diperkirakan 210 kg.</p>"},{"key":"D","text":"<p>Panen April pasti 210 kg.</p>","misconceptionId":"mis-msd-gunadata-002"},{"key":"E","text":"<p>Panen Maret dua kali panen Januari.</p>","misconceptionId":"mis-msd-gunadata-005"}]'::jsonb, null, array['A', 'B', 'C'], null, null, 'A, B, C', false, null, null),
  ('msd-gunadata-010', 'sub-matematika-sd', 'top-matematika-sd-data', 'st-matematika-sd-penyajian-data', 'con-matematika-sd-penggunaan-data', 'category', 'Bernalar menilai pernyataan tentang penggunaan data', 'lanjut', 'penalaran', 'html', '<p>Lima pernyataan tentang cara memakai data dikumpulkan untuk diperiksa bersama.</p>', '<p>Tentukan benar atau salah setiap pernyataan berikut.</p>', 'Tentukan kategori setiap pernyataan.', '<p>P1 benar: data menunjukkan kecenderungan, bukan jaminan.</p><p>P2 benar: kesimpulan tanpa dukungan data hanyalah dugaan.</p><p>P3 benar: itulah cara menghitung banyak seluruh data pada tabel frekuensi.</p><p>P4 salah: frekuensi tertinggi hanya berarti paling banyak dipilih. Bila biru dipilih 10 dari 25 siswa, masih ada 15 siswa yang memilih warna lain.</p><p>P5 salah: satu kelas belum tentu mewakili seluruh sekolah, karena kelas lain dapat berbeda kebiasaan dan pilihannya.</p>', null, null, null, '[{"key":"B","label":"Benar"},{"key":"S","label":"Salah"}]'::jsonb, '[{"id":"p1","text":"<p>Data dapat dipakai untuk memperkirakan keadaan berikutnya, tetapi tidak untuk memastikannya.</p>","correctCategoryKey":"B"},{"id":"p2","text":"<p>Kesimpulan yang ditarik harus didukung oleh data yang tersedia.</p>","correctCategoryKey":"B"},{"id":"p3","text":"<p>Jumlah seluruh frekuensi pada tabel menyatakan banyak seluruh data.</p>","correctCategoryKey":"B"},{"id":"p4","text":"<p>Kategori dengan frekuensi tertinggi pasti menjadi kesukaan setiap orang dalam kelompok itu.</p>","correctCategoryKey":"S","misconceptionId":"mis-msd-gunadata-003"},{"id":"p5","text":"<p>Data yang dikumpulkan dari satu kelas dapat langsung dipakai menyimpulkan keadaan seluruh sekolah.</p>","correctCategoryKey":"S","misconceptionId":"mis-msd-gunadata-004"}]'::jsonb, 'p1: B; p2: B; p3: B; p4: S; p5: S', false, null, null)
insert into public.packages (id, kind, slug, title, subject_id, series_id, level, description, summary, variant, variant_label, estimated_minutes, difficulty_range, skills, instructions, is_premium, is_published, sort_order, source_id, source_file) values
  ('pkg-latihan-msd-pecahan-senilai', 'latihan', 'matematika-sd-pecahan-senilai', 'Pecahan Senilai lewat Gambar dan Simbol', 'sub-matematika-sd', 'series-latihan-tka-matematika-sd', 'SD', 'Mengenali pecahan senilai dari gambar bagian yang diwarnai maupun dari simbol matematika, menyederhanakan pecahan, dan menalar mengapa dua pecahan bernilai sama.', '10 soal diagnostik bergaya TKA untuk pecahan senilai menggunakan gambar dan simbol matematika.', 'adaptif', 'Latihan TKA', 25, 'dasar–lanjut', array['Membaca pecahan dari gambar bagian yang diwarnai', 'Menyederhanakan pecahan ke bentuk paling sederhana', 'Membuat pecahan senilai dengan pengali yang sama', 'Menalar sah tidaknya cara membuat pecahan senilai'], array['Baca stimulus dengan teliti.', 'Perhatikan satuan dan bentuk bilangan yang diminta.', 'Periksa kembali hasil hitunganmu sebelum lanjut.'], false, true, 1, 'authored-tka-matematika-sd-matematika-sd-pecahan-senilai', '01-pecahan-senilai.json'),
  ('pkg-latihan-msd-banding-urut-pecahan', 'latihan', 'matematika-sd-perbandingan-pengurutan-pecahan', 'Perbandingan dan Pengurutan Bilangan Pecahan', 'sub-matematika-sd', 'series-latihan-tka-matematika-sd', 'SD', 'Membandingkan dua pecahan dan mengurutkan beberapa pecahan, baik dengan menyamakan penyebut, memakai patokan setengah, maupun dengan menalar hubungan pembilang dan penyebut.', '10 soal diagnostik bergaya TKA untuk perbandingan dan pengurutan bilangan pecahan.', 'adaptif', 'Latihan TKA', 25, 'dasar–lanjut', array['Membandingkan pecahan berpembilang sama', 'Menyamakan penyebut untuk membandingkan', 'Memakai patokan setengah dan satu', 'Mengurutkan pecahan naik dan turun'], array['Baca stimulus dengan teliti.', 'Perhatikan satuan dan bentuk bilangan yang diminta.', 'Periksa kembali hasil hitunganmu sebelum lanjut.'], false, true, 2, 'authored-tka-matematika-sd-matematika-sd-perbandingan-pengurutan-pecahan', '02-banding-urut-pecahan.json'),
  ('pkg-latihan-msd-relasi-bentuk-pecahan', 'latihan', 'matematika-sd-relasi-pecahan-desimal-persen', 'Relasi Pecahan, Desimal, dan Persen', 'sub-matematika-sd', 'series-latihan-tka-matematika-sd', 'SD', 'Mengubah bentuk pecahan sederhana, desimal, dan persen satu ke yang lain, lalu memakainya untuk membandingkan besaran yang ditulis dalam bentuk berbeda.', '10 soal diagnostik bergaya TKA untuk relasi berbagai bentuk pecahan: pecahan sederhana, desimal, dan persen.', 'adaptif', 'Latihan TKA', 25, 'dasar–lanjut', array['Mengubah pecahan menjadi desimal dan persen', 'Mengubah desimal menjadi pecahan paling sederhana', 'Membandingkan besaran dalam bentuk yang berbeda', 'Menalar kekeliruan penulisan bentuk pecahan'], array['Baca stimulus dengan teliti.', 'Perhatikan satuan dan bentuk bilangan yang diminta.', 'Periksa kembali hasil hitunganmu sebelum lanjut.'], false, true, 3, 'authored-tka-matematika-sd-matematika-sd-relasi-pecahan-desimal-persen', '03-relasi-bentuk-pecahan.json'),
  ('pkg-latihan-msd-operasi-bilangan-cacah', 'latihan', 'matematika-sd-operasi-bilangan-cacah', 'Operasi Hitung Bilangan Cacah', 'sub-matematika-sd', 'series-latihan-tka-matematika-sd', 'SD', 'Penjumlahan, pengurangan, perkalian, dan pembagian bilangan cacah pada masalah sehari-hari, termasuk urutan pengerjaan operasi, pembagian bersisa, dan penaksiran hasil.', '10 soal diagnostik bergaya TKA untuk operasi penjumlahan, pengurangan, perkalian, dan pembagian bilangan cacah.', 'adaptif', 'Latihan TKA', 25, 'dasar–lanjut', array['Menjumlah dan mengurang bilangan cacah bersusun', 'Menerapkan urutan pengerjaan operasi hitung', 'Menafsirkan sisa pada pembagian', 'Menaksir hasil operasi tanpa menghitung tepat'], array['Baca stimulus dengan teliti.', 'Perhatikan satuan dan bentuk bilangan yang diminta.', 'Periksa kembali hasil hitunganmu sebelum lanjut.'], false, true, 4, 'authored-tka-matematika-sd-matematika-sd-operasi-bilangan-cacah', '04-operasi-bilangan-cacah.json'),
  ('pkg-latihan-msd-operasi-pecahan', 'latihan', 'matematika-sd-operasi-bilangan-pecahan', 'Operasi Hitung Bilangan Pecahan', 'sub-matematika-sd', 'series-latihan-tka-matematika-sd', 'SD', 'Penjumlahan dan pengurangan bilangan pecahan, serta perkalian dan pembagian bilangan pecahan dengan bilangan asli pada masalah sehari-hari.', '10 soal diagnostik bergaya TKA untuk operasi penjumlahan, pengurangan, perkalian, dan pembagian bilangan pecahan.', 'adaptif', 'Latihan TKA', 25, 'dasar–lanjut', array['Menjumlah dan mengurang pecahan berpenyebut sama dan berbeda', 'Mengalikan pecahan dengan bilangan asli', 'Membagi pecahan dengan bilangan asli', 'Menalar kewajaran hasil operasi pecahan'], array['Baca stimulus dengan teliti.', 'Perhatikan satuan dan bentuk bilangan yang diminta.', 'Periksa kembali hasil hitunganmu sebelum lanjut.'], false, true, 5, 'authored-tka-matematika-sd-matematika-sd-operasi-bilangan-pecahan', '05-operasi-pecahan.json'),
  ('pkg-latihan-msd-kpk-fpb', 'latihan', 'matematika-sd-kelipatan-faktor-kpk-fpb', 'Kelipatan, Faktor, KPK, dan FPB', 'sub-matematika-sd', 'series-latihan-tka-matematika-sd', 'SD', 'Mendaftar kelipatan dan faktor bilangan asli, menentukan KPK dan FPB, serta memilih di antara keduanya pada masalah jadwal berulang dan pembagian rata.', '10 soal diagnostik bergaya TKA untuk kelipatan, faktor, KPK, dan FPB bilangan asli.', 'adaptif', 'Latihan TKA', 25, 'dasar–lanjut', array['Mendaftar faktor dan kelipatan bilangan asli', 'Menentukan KPK pada masalah kejadian berulang', 'Menentukan FPB pada masalah pembagian rata', 'Membedakan kapan memakai KPK dan kapan memakai FPB'], array['Baca stimulus dengan teliti.', 'Perhatikan satuan dan bentuk bilangan yang diminta.', 'Periksa kembali hasil hitunganmu sebelum lanjut.'], false, true, 6, 'authored-tka-matematika-sd-matematika-sd-kelipatan-faktor-kpk-fpb', '06-kpk-fpb.json'),
  ('pkg-latihan-msd-bangun-datar', 'latihan', 'matematika-sd-bentuk-bangun-datar', 'Bentuk Bangun Datar', 'sub-matematika-sd', 'series-latihan-tka-matematika-sd', 'SD', 'Mengenali dan menggolongkan segitiga, segiempat, dan segi banyak dari sisi, sudut, diagonal, dan sumbu simetrinya, serta menalar hubungan antargolongan bangun.', '10 soal diagnostik bergaya TKA untuk bentuk bangun datar: segitiga, segiempat, dan segi banyak.', 'adaptif', 'Latihan TKA', 25, 'dasar–lanjut', array['Mengenali bangun datar dari sifat sisi dan sudutnya', 'Menghitung sumbu simetri bangun datar', 'Menentukan nama segi banyak dari banyak sisinya', 'Menalar hubungan antargolongan segiempat'], array['Baca stimulus dengan teliti.', 'Perhatikan satuan dan bentuk bilangan yang diminta.', 'Periksa kembali hasil hitunganmu sebelum lanjut.'], false, true, 7, 'authored-tka-matematika-sd-matematika-sd-bentuk-bangun-datar', '07-bangun-datar.json'),
  ('pkg-latihan-msd-bangun-ruang-spasial', 'latihan', 'matematika-sd-konstruksi-bangun-ruang-visualisasi-spasial', 'Konstruksi Bangun Ruang dan Visualisasi Spasial', 'sub-matematika-sd', 'series-latihan-tka-matematika-sd', 'SD', 'Menyusun dan membaca kubus, balok, dan gabungannya: unsur bangun ruang, jaring-jaring, banyak kubus satuan penyusun, serta pandangan depan, atas, dan samping.', '10 soal diagnostik bergaya TKA untuk konstruksi bangun ruang dan visualisasi spasial pada kubus, balok, dan gabungannya.', 'adaptif', 'Latihan TKA', 30, 'dasar–lanjut', array['Menyebut sisi, rusuk, dan titik sudut kubus dan balok', 'Menghitung kubus satuan penyusun bangun, termasuk yang tersembunyi', 'Membaca pandangan depan, atas, dan samping', 'Menyusun bangun dari tiga pandangan yang diketahui'], array['Baca stimulus dengan teliti.', 'Perhatikan satuan dan bentuk bilangan yang diminta.', 'Periksa kembali hasil hitunganmu sebelum lanjut.'], false, true, 8, 'authored-tka-matematika-sd-matematika-sd-konstruksi-bangun-ruang-visualisasi-spasial', '08-bangun-ruang-spasial.json'),
  ('pkg-latihan-msd-panjang-satuan-baku', 'latihan', 'matematika-sd-panjang-benda-satuan-baku', 'Panjang Benda dengan Satuan Baku', 'sub-matematika-sd', 'series-latihan-tka-matematika-sd', 'SD', 'Mengukur panjang benda dengan satuan baku: memilih satuan yang sesuai, membaca penggaris yang tidak dimulai dari angka nol, dan menalar mengapa satuan baku diperlukan.', '10 soal diagnostik bergaya TKA untuk pengukuran panjang benda menggunakan satuan baku.', 'adaptif', 'Latihan TKA', 25, 'dasar–lanjut', array['Memilih satuan baku yang sesuai dengan ukuran benda', 'Membaca hasil pengukuran pada penggaris', 'Menuliskan hasil ukur dalam gabungan satuan', 'Menalar sebab perbedaan hasil pengukuran'], array['Baca stimulus dengan teliti.', 'Perhatikan satuan dan bentuk bilangan yang diminta.', 'Periksa kembali hasil hitunganmu sebelum lanjut.'], false, true, 9, 'authored-tka-matematika-sd-matematika-sd-panjang-benda-satuan-baku', '09-panjang-satuan-baku.json'),
  ('pkg-latihan-msd-konversi-panjang', 'latihan', 'matematika-sd-hubungan-antar-satuan-panjang', 'Hubungan Antar-Satuan Baku Panjang', 'sub-matematika-sd', 'series-latihan-tka-matematika-sd', 'SD', 'Mengubah dan membandingkan satuan panjang mm, cm, dm, m, dam, hm, dan km, termasuk menjumlahkan besaran yang satuannya berbeda dan menalar arah naik-turun tangga satuan.', '10 soal diagnostik bergaya TKA untuk hubungan antar-satuan baku panjang (mm, dm, cm, m, dam, hm, km).', 'adaptif', 'Latihan TKA', 25, 'dasar–lanjut', array['Mengubah satuan panjang naik dan turun satu tangga', 'Menjumlahkan panjang yang satuannya berbeda', 'Mengurutkan panjang setelah menyeragamkan satuan', 'Menalar arah pengali pada tangga satuan'], array['Baca stimulus dengan teliti.', 'Perhatikan satuan dan bentuk bilangan yang diminta.', 'Periksa kembali hasil hitunganmu sebelum lanjut.'], false, true, 10, 'authored-tka-matematika-sd-matematika-sd-hubungan-antar-satuan-panjang', '10-konversi-panjang.json'),
  ('pkg-latihan-msd-volume-satuan-baku', 'latihan', 'matematika-sd-volume-benda-satuan-baku', 'Volume Benda dengan Satuan Baku', 'sub-matematika-sd', 'series-latihan-tka-matematika-sd', 'SD', 'Mengukur volume dan isi benda dengan satuan baku: memilih satuan yang sesuai, membaca gelas ukur, menuang antarwadah, dan mengukur volume benda padat lewat kenaikan air.', '10 soal diagnostik bergaya TKA untuk pengukuran volume benda menggunakan satuan baku.', 'adaptif', 'Latihan TKA', 25, 'dasar–lanjut', array['Memilih satuan volume yang sesuai dengan wadah', 'Membaca skala gelas ukur', 'Menghitung isi setelah dituang antarwadah', 'Mengukur volume benda padat dari kenaikan permukaan air'], array['Baca stimulus dengan teliti.', 'Perhatikan satuan dan bentuk bilangan yang diminta.', 'Periksa kembali hasil hitunganmu sebelum lanjut.'], false, true, 11, 'authored-tka-matematika-sd-matematika-sd-volume-benda-satuan-baku', '11-volume-satuan-baku.json'),
  ('pkg-latihan-msd-konversi-volume', 'latihan', 'matematika-sd-hubungan-antar-satuan-volume', 'Hubungan Antar-Satuan Baku Volume', 'sub-matematika-sd', 'series-latihan-tka-matematika-sd', 'SD', 'Mengubah dan membandingkan satuan volume ml, cl, dl, l, dal, hl, dan kl, termasuk menjumlahkan isi yang satuannya berbeda dan menalar arah tangga satuan.', '10 soal diagnostik bergaya TKA untuk hubungan antar-satuan baku volume (ml, dl, cl, l, dal, hl, kl).', 'adaptif', 'Latihan TKA', 25, 'dasar–lanjut', array['Mengubah satuan volume naik dan turun tangga', 'Menjumlahkan isi yang satuannya berbeda', 'Mengurutkan volume setelah menyeragamkan satuan', 'Membedakan mililiter dan sentiliter'], array['Baca stimulus dengan teliti.', 'Perhatikan satuan dan bentuk bilangan yang diminta.', 'Periksa kembali hasil hitunganmu sebelum lanjut.'], false, true, 12, 'authored-tka-matematika-sd-matematika-sd-hubungan-antar-satuan-volume', '12-konversi-volume.json'),
  ('pkg-latihan-msd-berat-satuan-baku', 'latihan', 'matematika-sd-berat-benda-satuan-baku', 'Berat Benda dengan Satuan Baku', 'sub-matematika-sd', 'series-latihan-tka-matematika-sd', 'SD', 'Mengukur berat benda dengan satuan baku: memilih satuan yang sesuai, membaca timbangan, menyetimbangkan neraca, serta membedakan berat kotor, berat bersih, dan tara.', '10 soal diagnostik bergaya TKA untuk pengukuran berat benda menggunakan satuan baku.', 'adaptif', 'Latihan TKA', 25, 'dasar–lanjut', array['Memilih satuan berat yang sesuai dengan benda', 'Membaca skala timbangan', 'Menghitung berat pada neraca yang setimbang', 'Membedakan bruto, netto, dan tara'], array['Baca stimulus dengan teliti.', 'Perhatikan satuan dan bentuk bilangan yang diminta.', 'Periksa kembali hasil hitunganmu sebelum lanjut.'], false, true, 13, 'authored-tka-matematika-sd-matematika-sd-berat-benda-satuan-baku', '13-berat-satuan-baku.json'),
  ('pkg-latihan-msd-konversi-berat', 'latihan', 'matematika-sd-hubungan-antar-satuan-berat', 'Hubungan Antar-Satuan Baku Berat', 'sub-matematika-sd', 'series-latihan-tka-matematika-sd', 'SD', 'Mengubah dan membandingkan satuan berat mg, cg, dg, g, dag, hg, dan kg, termasuk menjumlahkan berat bersatuan berbeda dan menalar arah tangga satuan.', '10 soal diagnostik bergaya TKA untuk hubungan antar-satuan baku berat (mg, dg, cg, g, dag, hg, kg).', 'adaptif', 'Latihan TKA', 25, 'dasar–lanjut', array['Mengubah satuan berat naik dan turun tangga', 'Menjumlahkan berat yang satuannya berbeda', 'Mengurutkan berat setelah menyeragamkan satuan', 'Membedakan dag, hg, dan kg'], array['Baca stimulus dengan teliti.', 'Perhatikan satuan dan bentuk bilangan yang diminta.', 'Periksa kembali hasil hitunganmu sebelum lanjut.'], false, true, 14, 'authored-tka-matematika-sd-matematika-sd-hubungan-antar-satuan-berat', '14-konversi-berat.json'),
  ('pkg-latihan-msd-waktu', 'latihan', 'matematika-sd-waktu', 'Waktu', 'sub-matematika-sd', 'series-latihan-tka-matematika-sd', 'SD', 'Membaca jam, memakai penulisan 12 jam dan 24 jam, menghitung lama kegiatan dan waktu mulai, serta menalar jadwal berulang dan pergantian tanggal.', '10 soal diagnostik bergaya TKA untuk pengukuran dan penggunaan waktu.', 'adaptif', 'Latihan TKA', 25, 'dasar–lanjut', array['Membaca jam analog dan penulisan 24 jam', 'Menghitung lama kegiatan antar dua waktu', 'Menentukan waktu mulai dari durasi dan waktu selesai', 'Menalar jadwal berulang dan pergantian tanggal'], array['Baca stimulus dengan teliti.', 'Perhatikan satuan dan bentuk bilangan yang diminta.', 'Periksa kembali hasil hitunganmu sebelum lanjut.'], false, true, 15, 'authored-tka-matematika-sd-matematika-sd-waktu', '15-waktu.json'),
  ('pkg-latihan-msd-konversi-waktu', 'latihan', 'matematika-sd-hubungan-antar-satuan-waktu', 'Hubungan Antar-Satuan Waktu', 'sub-matematika-sd', 'series-latihan-tka-matematika-sd', 'SD', 'Mengubah dan membandingkan satuan waktu detik, menit, jam, hari, pekan, bulan, dan tahun, termasuk menafsirkan bentuk desimal jam dan sisa pembagian detik.', '10 soal diagnostik bergaya TKA untuk hubungan antar-satuan waktu (detik, menit, jam, hari, pekan, bulan, tahun).', 'adaptif', 'Latihan TKA', 25, 'dasar–lanjut', array['Mengubah jam, menit, dan detik', 'Mengubah hari, pekan, bulan, dan tahun', 'Menafsirkan bentuk desimal pada satuan jam', 'Mengurutkan lama waktu setelah menyeragamkan satuan'], array['Baca stimulus dengan teliti.', 'Perhatikan satuan dan bentuk bilangan yang diminta.', 'Periksa kembali hasil hitunganmu sebelum lanjut.'], false, true, 16, 'authored-tka-matematika-sd-matematika-sd-hubungan-antar-satuan-waktu', '16-konversi-waktu.json'),
  ('pkg-latihan-msd-kecepatan', 'latihan', 'matematika-sd-laju-perubahan-kecepatan', 'Laju Perubahan (Kecepatan)', 'sub-matematika-sd', 'series-latihan-tka-matematika-sd', 'SD', 'Menghitung kecepatan, jarak, dan waktu tempuh, mengubah menit menjadi jam pada perhitungan kecepatan, serta menalar kecepatan rata-rata dan hubungan berbalik antara kecepatan dan waktu.', '10 soal diagnostik bergaya TKA untuk laju perubahan (kecepatan).', 'adaptif', 'Latihan TKA', 30, 'dasar–lanjut', array['Menghitung kecepatan dari jarak dan waktu', 'Menghitung jarak dan waktu tempuh', 'Mengubah menit menjadi jam pada perhitungan kecepatan', 'Menalar kecepatan rata-rata perjalanan bertahap'], array['Baca stimulus dengan teliti.', 'Perhatikan satuan dan bentuk bilangan yang diminta.', 'Periksa kembali hasil hitunganmu sebelum lanjut.'], false, true, 17, 'authored-tka-matematika-sd-matematika-sd-laju-perubahan-kecepatan', '17-kecepatan.json'),
  ('pkg-latihan-msd-keliling-luas', 'latihan', 'matematika-sd-keliling-dan-luas-bangun-datar', 'Keliling dan Luas Bangun Datar', 'sub-matematika-sd', 'series-latihan-tka-matematika-sd', 'SD', 'Menghitung keliling dan luas segitiga, segiempat, dan segi banyak termasuk bangun gabungan, serta menalar hubungan keliling, luas, dan perubahan ukuran sisinya.', '10 soal diagnostik bergaya TKA untuk keliling dan luas bangun datar (segitiga, segiempat, dan segi banyak).', 'adaptif', 'Latihan TKA', 30, 'dasar–lanjut', array['Menghitung keliling dan luas persegi serta persegi panjang', 'Menghitung luas segitiga dan trapesium', 'Menghitung keliling dan luas bangun gabungan', 'Menalar hubungan keliling, luas, dan perubahan ukuran'], array['Baca stimulus dengan teliti.', 'Perhatikan satuan dan bentuk bilangan yang diminta.', 'Periksa kembali hasil hitunganmu sebelum lanjut.'], false, true, 18, 'authored-tka-matematika-sd-matematika-sd-keliling-dan-luas-bangun-datar', '18-keliling-luas.json'),
  ('pkg-latihan-msd-volume-bangun-ruang', 'latihan', 'matematika-sd-volume-bangun-ruang', 'Volume Bangun Ruang', 'sub-matematika-sd', 'series-latihan-tka-matematika-sd', 'SD', 'Menghitung volume kubus, balok, dan bangun gabungannya, mengubah cm³ ke liter, mencari ukuran yang belum diketahui, serta menalar pengaruh pelipatan rusuk terhadap volume.', '10 soal diagnostik bergaya TKA untuk volume bangun ruang (kubus, balok, dan gabungannya).', 'adaptif', 'Latihan TKA', 30, 'dasar–lanjut', array['Menghitung volume kubus dan balok', 'Menghitung volume bangun gabungan', 'Mengubah cm³ menjadi liter', 'Menalar pengaruh perubahan ukuran terhadap volume'], array['Baca stimulus dengan teliti.', 'Perhatikan satuan dan bentuk bilangan yang diminta.', 'Periksa kembali hasil hitunganmu sebelum lanjut.'], false, true, 19, 'authored-tka-matematika-sd-matematika-sd-volume-bangun-ruang', '19-volume-bangun-ruang.json'),
  ('pkg-latihan-msd-besar-sudut', 'latihan', 'matematika-sd-besar-sudut', 'Besar Sudut', 'sub-matematika-sd', 'series-latihan-tka-matematika-sd', 'SD', 'Mengukur dan menggolongkan sudut, membaca busur derajat, memakai sudut pelurus dan penyiku, jumlah sudut segitiga, serta menalar sudut yang dibentuk jarum jam.', '10 soal diagnostik bergaya TKA untuk pengukuran besar sudut.', 'adaptif', 'Latihan TKA', 25, 'dasar–lanjut', array['Menggolongkan sudut lancip, siku-siku, dan tumpul', 'Membaca busur derajat dengan benar', 'Memakai sudut pelurus, penyiku, dan jumlah sudut segitiga', 'Menentukan sudut yang dibentuk jarum jam'], array['Baca stimulus dengan teliti.', 'Perhatikan satuan dan bentuk bilangan yang diminta.', 'Periksa kembali hasil hitunganmu sebelum lanjut.'], false, true, 20, 'authored-tka-matematika-sd-matematika-sd-besar-sudut', '20-besar-sudut.json'),
  ('pkg-latihan-msd-penaksiran', 'latihan', 'matematika-sd-penaksiran-ukuran', 'Penaksiran Ukuran', 'sub-matematika-sd', 'series-latihan-tka-matematika-sd', 'SD', 'Menaksir hasil operasi hitung dan ukuran benda dengan pembulatan, memperkirakan kecukupan uang dan bahan, serta menalar kapan penaksiran boleh dipakai dan kapan tidak.', '10 soal diagnostik bergaya TKA untuk penaksiran ukuran.', 'adaptif', 'Latihan TKA', 25, 'dasar–lanjut', array['Membulatkan bilangan ke puluhan, ratusan, dan ribuan terdekat', 'Menaksir hasil perkalian dan penjumlahan', 'Menaksir ukuran benda dengan benda acuan', 'Menalar arah taksiran dan batas penggunaannya'], array['Baca stimulus dengan teliti.', 'Perhatikan satuan dan bentuk bilangan yang diminta.', 'Periksa kembali hasil hitunganmu sebelum lanjut.'], false, true, 21, 'authored-tka-matematika-sd-matematika-sd-penaksiran-ukuran', '21-penaksiran.json'),
  ('pkg-latihan-msd-penyajian-data', 'latihan', 'matematika-sd-penyajian-data', 'Penyajian Data', 'sub-matematika-sd', 'series-latihan-tka-matematika-sd', 'SD', 'Membaca dan menilai penyajian data dalam bentuk gambar, piktogram, diagram batang, dan tabel frekuensi, termasuk mengubah satu bentuk penyajian menjadi bentuk lainnya.', '10 soal diagnostik bergaya TKA untuk penyajian data (gambar, piktogram, diagram batang, dan tabel frekuensi).', 'adaptif', 'Latihan TKA', 30, 'dasar–lanjut', array['Membaca piktogram beserta keterangan nilai gambarnya', 'Membaca tabel frekuensi dan diagram batang', 'Mengubah satu bentuk penyajian data menjadi bentuk lain', 'Menilai kelengkapan dan keadilan suatu penyajian data'], array['Baca stimulus dengan teliti.', 'Perhatikan satuan dan bentuk bilangan yang diminta.', 'Periksa kembali hasil hitunganmu sebelum lanjut.'], false, true, 22, 'authored-tka-matematika-sd-matematika-sd-penyajian-data', '22-penyajian-data.json'),
  ('pkg-latihan-msd-penggunaan-data', 'latihan', 'matematika-sd-pengambilan-informasi-penggunaan-data', 'Pengambilan Informasi dan Penggunaan Data', 'sub-matematika-sd', 'series-latihan-tka-matematika-sd', 'SD', 'Mengambil informasi dari data yang tersaji, memakainya untuk menghitung dan mengambil keputusan, serta menalar batas kesimpulan yang boleh ditarik dari suatu data.', '10 soal diagnostik bergaya TKA untuk pengambilan informasi dan penggunaan data.', 'adaptif', 'Latihan TKA', 30, 'dasar–lanjut', array['Mengambil informasi langsung dari tabel dan diagram', 'Memakai data untuk menghitung jumlah dan selisih', 'Memakai data untuk mengambil keputusan', 'Menilai kesimpulan yang melampaui dukungan data'], array['Baca stimulus dengan teliti.', 'Perhatikan satuan dan bentuk bilangan yang diminta.', 'Periksa kembali hasil hitunganmu sebelum lanjut.'], false, true, 23, 'authored-tka-matematika-sd-matematika-sd-pengambilan-informasi-penggunaan-data', '23-penggunaan-data.json')
